--
-- Name: claim_transactional_email_batch(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_transactional_email_batch(p_worker_ref text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_items jsonb;
begin
  if coalesce(length(trim(p_worker_ref)), 0) < 8 then
    raise exception using message = 'Worker inválido.', errcode = '22023';
  end if;

  with candidates as (
    select id
    from public.transactional_email_outbox
    where (
      status in ('pending','retry') and next_attempt_at <= now()
    ) or (
      status = 'processing' and claimed_at < now() - interval '10 minutes'
    )
    order by created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 10), 50))
  ), claimed as (
    update public.transactional_email_outbox o
    set
      status = 'processing',
      attempts = attempts + 1,
      claimed_at = now(),
      updated_at = now(),
      last_error_code = null
    from candidates c
    where o.id = c.id
    returning o.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'eventType', event_type,
    'entityType', entity_type,
    'entityId', entity_id,
    'template', template,
    'recipientAddress', recipient_address,
    'recipientRef', left(recipient_hash, 16),
    'payload', payload,
    'attempts', attempts,
    'maxAttempts', max_attempts,
    'requestId', request_id
  ) order by created_at), '[]'::jsonb)
  into v_items
  from claimed;

  return v_items;
end;
$$;


ALTER FUNCTION public.claim_transactional_email_batch(p_worker_ref text, p_limit integer) OWNER TO postgres;

--
-- Name: claim_transactional_email_batch_v2(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_transactional_email_batch_v2(p_worker_ref text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_items jsonb; v_limit integer := greatest(1, least(coalesce(p_limit, 10), 50));
begin
  if coalesce(length(trim(p_worker_ref)), 0) < 8 then
    raise exception using message = 'Worker inválido.', errcode = '22023';
  end if;
  with ready as (
    select o.id, o.created_at,
           row_number() over (partition by coalesce(o.organization_id::text, o.recipient_hash) order by o.created_at, o.id) as turn
      from public.transactional_email_outbox o
     where (o.status in ('pending','retry') and o.next_attempt_at <= now())
        or (o.status = 'processing' and o.lease_expires_at <= now())
  ), candidates as (
    select o.id from public.transactional_email_outbox o join ready r on r.id = o.id
     where (o.status in ('pending','retry') and o.next_attempt_at <= now())
        or (o.status = 'processing' and o.lease_expires_at <= now())
     order by r.turn, r.created_at, r.id
     for update of o skip locked
     limit v_limit
  ), claimed as (
    update public.transactional_email_outbox o
    set status = 'processing', attempts = attempts + 1, claimed_at = now(),
        worker_ref = left(trim(p_worker_ref), 120), claim_token = gen_random_uuid(),
        lease_expires_at = now() + interval '10 minutes', updated_at = now(),
        last_error_code = null
    from candidates c where o.id = c.id returning o.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'eventType', event_type, 'entityType', entity_type,
    'entityId', entity_id, 'template', template,
    'recipientAddress', recipient_address, 'recipientRef', left(recipient_hash, 16),
    'payload', payload, 'attempts', attempts, 'maxAttempts', max_attempts,
    'requestId', request_id, 'idempotencyKey', idempotency_key,
    'workerRef', worker_ref, 'claimToken', claim_token
  ) order by created_at), '[]'::jsonb) into v_items from claimed;
  return v_items;
end;
$$;


ALTER FUNCTION public.claim_transactional_email_batch_v2(p_worker_ref text, p_limit integer) OWNER TO postgres;

--
-- Name: complete_transactional_email(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_transactional_email(p_id uuid, p_provider text, p_provider_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.transactional_email_outbox%rowtype;
begin
  update public.transactional_email_outbox
  set
    status = 'delivered',
    delivered_at = now(),
    provider = nullif(left(trim(p_provider), 40), ''),
    provider_reference = nullif(left(trim(p_provider_reference), 180), ''),
    recipient_address = null,
    claimed_at = null,
    updated_at = now(),
    last_error_code = null
  where id = p_id and status = 'processing'
  returning * into v_row;

  if not found then
    raise exception using message = 'Evento de e-mail não está em processamento.', errcode = 'P0001';
  end if;

  return jsonb_build_object('ok', true, 'id', v_row.id, 'status', v_row.status);
end;
$$;


ALTER FUNCTION public.complete_transactional_email(p_id uuid, p_provider text, p_provider_reference text) OWNER TO postgres;

