--
-- Name: fail_transactional_email(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_transactional_email(p_id uuid, p_error_code text, p_retry_after_seconds integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.transactional_email_outbox%rowtype;
  v_dead boolean;
  v_delay integer;
begin
  select * into v_row
  from public.transactional_email_outbox
  where id = p_id
  for update;

  if not found or v_row.status <> 'processing' then
    raise exception using message = 'Evento de e-mail não está em processamento.', errcode = 'P0001';
  end if;

  v_dead := v_row.attempts >= v_row.max_attempts;
  v_delay := greatest(30, least(coalesce(p_retry_after_seconds, 60), 86400));

  update public.transactional_email_outbox
  set
    status = case when v_dead then 'dead' else 'retry' end,
    next_attempt_at = case when v_dead then next_attempt_at else now() + make_interval(secs => v_delay) end,
    claimed_at = null,
    recipient_address = case when v_dead then null else recipient_address end,
    last_error_code = left(coalesce(nullif(trim(p_error_code), ''), 'delivery_failed'), 120),
    updated_at = now()
  where id = p_id
  returning * into v_row;

  return jsonb_build_object('ok', true, 'id', v_row.id, 'status', v_row.status, 'attempts', v_row.attempts);
end;
$$;


ALTER FUNCTION public.fail_transactional_email(p_id uuid, p_error_code text, p_retry_after_seconds integer) OWNER TO postgres;

--
-- Name: fail_transactional_email_v2(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_transactional_email_v2(p_id uuid, p_claim_token uuid, p_error_code text, p_retry_after_seconds integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_row public.transactional_email_outbox%rowtype; v_dead boolean; v_delay integer;
begin
  select * into v_row from public.transactional_email_outbox
  where id = p_id and status = 'processing' and claim_token = p_claim_token
    and lease_expires_at > now() for update;
  if not found then raise exception using message = 'Lease da outbox inválida ou expirada.', errcode = 'P0001'; end if;
  v_dead := v_row.attempts >= v_row.max_attempts or (p_error_code ~ '^http_4[0-9]{2}$' and p_error_code not in ('http_408','http_429'));
  v_delay := greatest(30, least(coalesce(p_retry_after_seconds, 60), 86400));
  update public.transactional_email_outbox
  set status = case when v_dead then 'dead' else 'retry' end,
      next_attempt_at = case when v_dead then next_attempt_at else now() + make_interval(secs => v_delay) end,
      claimed_at = null, worker_ref = null, claim_token = null, lease_expires_at = null,
      recipient_address = case when v_dead then null else recipient_address end,
      last_error_code = left(coalesce(nullif(trim(p_error_code), ''), 'delivery_failed'), 120), updated_at = now()
  where id = p_id returning * into v_row;
  return jsonb_build_object('ok', true, 'id', v_row.id, 'status', v_row.status, 'attempts', v_row.attempts);
end;
$_$;


ALTER FUNCTION public.fail_transactional_email_v2(p_id uuid, p_claim_token uuid, p_error_code text, p_retry_after_seconds integer) OWNER TO postgres;

--
-- Name: fin_accept_implementation(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_accept_implementation(p_plan uuid, p_expected integer, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_implementation_plans%rowtype; v_id uuid; v_value uuid; v_doc uuid; v_date date;
begin
 p:=public.fin_implementation_require(p_plan,array['admin','finance_manager']);
 if p_expected is null or p.version<>p_expected then raise exception 'implementation conflict'; end if;
 if p.status<>'ready_for_acceptance' or exists(select 1 from public.fin_implementation_issues where plan_id=p.id and status='open') or exists(select 1 from public.fin_implementation_milestones where plan_id=p.id and status<>'completed') then raise exception 'implementation not ready'; end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or p_input->>'confirm'<>'true' or not(p_input ? 'confirm') or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('confirm','actual_go_live','evidence_reference','document_id','value_record_id')) then raise exception 'implementation confirmation required'; end if;
 v_date:=(p_input->>'actual_go_live')::date; v_value:=nullif(p_input->>'value_record_id','')::uuid; v_doc:=nullif(p_input->>'document_id','')::uuid;
 if v_date is null or v_date<p.starts_on or v_date>current_date then raise exception 'invalid implementation input'; end if;
 if v_value is not null and not exists(select 1 from public.fin_value_records v where v.id=v_value and v.organization_id=p.organization_id and v.contract_id=p.contract_id and v.legal_entity_id is not distinct from p.legal_entity_id) then raise exception 'invalid implementation evidence'; end if;
 if v_doc is not null and not(public.fin_can_read_document(v_doc) and exists(select 1 from public.fin_private_documents d where d.id=v_doc and d.buyer_organization_id=p.organization_id and d.entity_type='contract' and d.entity_id=p.contract_id)) then raise exception 'invalid implementation evidence'; end if;
 insert into public.fin_implementation_acceptances(organization_id,plan_id,actual_go_live,evidence_reference,document_id,accepted_by,plan_version,value_record_id) values(p.organization_id,p.id,v_date,trim(p_input->>'evidence_reference'),v_doc,auth.uid(),p.version,v_value) returning id into v_id;
 update public.fin_implementation_plans set status='accepted',actual_go_live=v_date,version=version+1,updated_at=now() where id=p.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'implementation_accepted',auth.uid(),p.legal_entity_id,jsonb_build_object('implementation_id',p.id,'acceptance_id',v_id));
 return v_id;
end $$;


ALTER FUNCTION public.fin_accept_implementation(p_plan uuid, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_accept_member_invitation(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_accept_member_invitation(p_token text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_inv public.fin_member_invitations%rowtype; v_email text; v_confirmed timestamptz;
begin
  if auth.uid() is null or coalesce(p_token,'') !~ '^[0-9a-f]{64}$' then raise exception 'invalid invitation'; end if;
  select nullif(lower(trim(coalesce(email, ''))), ''), email_confirmed_at into v_email, v_confirmed
    from auth.users where id = auth.uid();
  select * into v_inv from public.fin_member_invitations
    where token_hash = encode(sha256(convert_to(p_token,'UTF8')),'hex')
      and accepted_at is null and expires_at > now()
    for update;
  if not found or v_email is null or v_confirmed is null or v_inv.email is distinct from v_email then
    raise exception 'invalid invitation';
  end if;
  insert into public.fin_members (organization_id, user_id, role)
    values (v_inv.organization_id, auth.uid(), v_inv.role)
    on conflict (organization_id, user_id) do nothing;
  update public.fin_member_invitations set accepted_at = now() where id = v_inv.id;
  return v_inv.organization_id;
end $_$;


ALTER FUNCTION public.fin_accept_member_invitation(p_token text) OWNER TO postgres;

--
-- Name: fin_accept_provider_invite(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_accept_provider_invite(p_token text, p_provider_org uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_inv public.fin_rfq_invites%rowtype; v_email text; v_confirmed timestamptz; v_reason text;
begin
  if auth.uid() is null or coalesce(p_token,'') !~ '^[0-9a-f]{64}$' then raise exception 'invalid invitation'; end if;
  if not public.fin_has_role(p_provider_org, array['admin','provider_user']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_provider_org and o.kind = 'PROVIDER') then
    raise exception 'provider organization required';
  end if;
  select * into v_inv from public.fin_rfq_invites
    where token_hash = encode(sha256(convert_to(p_token,'UTF8')),'hex')
      and status = 'invited' and accepted_at is null and expires_at > now()
    for update;
  if not found then raise exception 'invalid invitation'; end if;
  if v_inv.buyer_organization_id = p_provider_org then raise exception 'invalid invitation'; end if;
  -- Recusas daqui em diante ficam registradas (motivo interno) e devolvem null:
  -- a API responde o mesmo erro genérico de convite inválido, sem dizer qual
  -- e-mail era esperado nem qual organização deveria aceitar.
  if v_inv.recipient_mode = 'exact_email' then
    select nullif(lower(trim(coalesce(u.email, ''))), ''), u.email_confirmed_at into v_email, v_confirmed
      from auth.users u where u.id = auth.uid();
    v_reason := case when v_email is null then 'no_email'
                     when v_confirmed is null then 'email_unconfirmed'
                     when v_email <> v_inv.recipient_email then 'recipient_mismatch' end;
  end if;
  -- Cadastro do comprador já vinculado a outra conta provedora (#73).
  if v_reason is null and exists (
    select 1 from public.fin_providers p
    where p.id = v_inv.provider_id and p.organization_id = v_inv.buyer_organization_id
      and p.provider_organization_id is not null and p.provider_organization_id <> p_provider_org
  ) then v_reason := 'provider_bound_elsewhere'; end if;
  -- A mesma conta já ocupa outra vaga aceita nesta RFQ (#73).
  if v_reason is null and exists (
    select 1 from public.fin_rfq_invites i
    where i.rfq_id = v_inv.rfq_id and i.id <> v_inv.id
      and i.status = 'accepted' and i.provider_organization_id = p_provider_org
  ) then v_reason := 'organization_already_in_rfq'; end if;
  if v_reason is not null then
    insert into public.fin_invite_acceptance_denials (invite_id, rfq_id, user_id, reason)
      values (v_inv.id, v_inv.rfq_id, auth.uid(), v_reason);
    return null;
  end if;
  update public.fin_rfq_invites
    set status = 'accepted', accepted_at = now(), provider_organization_id = p_provider_org
    where id = v_inv.id;
  -- O cadastro do comprador passa a apontar para a conta canônica do provedor.
  update public.fin_providers
    set provider_organization_id = p_provider_org, updated_at = now()
    where id = v_inv.provider_id and organization_id = v_inv.buyer_organization_id
      and provider_organization_id is null;
  insert into public.fin_proposals (invite_id, rfq_id, buyer_organization_id, provider_id, provider_organization_id, product)
    select v_inv.id, v_inv.rfq_id, v_inv.buyer_organization_id, v_inv.provider_id, p_provider_org, r.product
    from public.fin_rfqs r where r.id = v_inv.rfq_id
    on conflict (invite_id) do nothing;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (v_inv.buyer_organization_id, 'rfq', v_inv.rfq_id, 'invite_accepted', auth.uid());
  return v_inv.id;
end $_$;


ALTER FUNCTION public.fin_accept_provider_invite(p_token text, p_provider_org uuid) OWNER TO postgres;

--
-- Name: fin_accept_terms(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_accept_terms(p_org uuid, p_version text, p_context text DEFAULT 'pilot'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if not public.fin_has_role(p_org) then raise exception 'forbidden'; end if;
  if coalesce(p_version,'') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}(-[a-z0-9-]{1,40})?$' then raise exception 'invalid terms version'; end if;
  if p_context not in ('pilot','production','test') then raise exception 'invalid context'; end if;
  insert into public.fin_terms_acceptances (organization_id, user_id, terms_version, context)
    values (p_org, auth.uid(), p_version, p_context)
    on conflict (organization_id, user_id, terms_version) do nothing;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'terms_accepted', auth.uid(),
            jsonb_build_object('terms_version', p_version, 'context', p_context));
end $_$;


ALTER FUNCTION public.fin_accept_terms(p_org uuid, p_version text, p_context text) OWNER TO postgres;

