--
-- Name: fin_act_on_approval_v2(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_act_on_approval_v2(p_request uuid, p_action text, p_comment text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.fin_approval_requests%rowtype; v_step public.fin_approval_steps%rowtype; v_stage public.fin_approval_stages%rowtype;
  v_version integer; v_updated timestamptz; v_status text; v_entity uuid; v_delegation uuid; v_done integer; v_step_id uuid;
begin
  -- Mesma ordem de travas da decisão e do pedido: votos concorrentes serializam.
  select * into v_request from public.fin_approval_requests where id = p_request;
  if not found then raise exception 'approval not found'; end if;
  perform 1 from public.fin_rfqs where id = v_request.rfq_id for update;
  if v_request.external_proposal_id is not null then
    perform public.fin_external_lock_source(v_request.external_proposal_id,v_request.proposal_version,v_request.external_rfq_revision,array['admin','finance_manager','analyst','viewer']);
  end if;
  select * into v_request from public.fin_approval_requests where id = p_request for update;
  if not public.fin_has_role(v_request.organization_id) then raise exception 'forbidden'; end if;
  if v_request.status <> 'pending' then raise exception 'approval not pending'; end if;
  if v_request.expires_at is not null and v_request.expires_at < now() then raise exception 'approval expired'; end if;
  if p_action not in ('approved','rejected','changes_requested') then raise exception 'invalid approval action'; end if;
  if p_action <> 'approved' and length(trim(coalesce(p_comment,''))) < 3 then raise exception 'approval comment required'; end if;
  if p_reason_code is not null and p_reason_code not in ('insufficient_competition','terms_outside_policy','missing_documentation','pricing_review','risk_review','compliance_review','budget','other') then
    raise exception 'invalid approval action';
  end if;
  select updated_at, legal_entity_id into v_updated, v_entity from public.fin_rfqs where id = v_request.rfq_id;
  select current_version into v_version from public.fin_decision_sources where id = coalesce(v_request.proposal_id,v_request.external_proposal_id) and status in ('submitted','revised','reviewed');
  if v_updated is distinct from v_request.rfq_updated_at or v_version is distinct from v_request.proposal_version then raise exception 'approval stale'; end if;
  if v_request.requested_by = auth.uid() then raise exception 'forbidden'; end if;

  if v_request.policy_snapshot is null then
    -- Pedido v1: fila estritamente sequencial, só o aprovador da vez.
    select * into v_step from public.fin_approval_steps where request_id = p_request and status = 'pending' order by position limit 1 for update;
    if not found or v_step.approver_id <> auth.uid() then raise exception 'forbidden'; end if;
    update public.fin_approval_steps set status = p_action, comment = nullif(trim(coalesce(p_comment,'')),''), acted_at = now(), acted_by = auth.uid(), reason_code = p_reason_code
     where id = v_step.id;
    v_status := case when p_action = 'approved' and exists (select 1 from public.fin_approval_steps where request_id = p_request and status = 'pending') then 'pending' else p_action end;
    if v_status <> 'pending' then update public.fin_approval_requests set status = v_status, resolved_at = now() where id = p_request; end if;
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
      values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_' || p_action, auth.uid(), jsonb_build_object('request_id', p_request, 'step', v_step.position));
    return v_status;
  end if;

  -- Pedido com policy: voto próprio numa etapa ativa...
  select s.* into v_step from public.fin_approval_steps s join public.fin_approval_stages st on st.id = s.stage_id and st.status = 'active'
   where s.request_id = p_request and s.status = 'pending' and s.approver_id = auth.uid() order by s.position limit 1 for update of s;
  if found then
    select * into v_stage from public.fin_approval_stages where id = v_step.stage_id;
    -- Aprovador revogado (papel ou entidade) não vota mais, mesmo indicado.
    if not public.fin_approval_member_eligible(v_request.organization_id, v_entity, auth.uid(), v_stage.roles, v_stage.scope) then
      raise exception 'approver no longer eligible';
    end if;
  else
    -- ...ou como substituto: delegação ativa, etapa que admite delegação,
    -- substituto elegível por si mesmo e fora das demais etapas do pedido.
    select s.id, d.id into v_step_id, v_delegation
      from public.fin_approval_steps s
      join public.fin_approval_stages st on st.id = s.stage_id and st.status = 'active' and st.allow_delegation
      join public.fin_approval_delegations d on d.organization_id = v_request.organization_id and d.delegator_id = s.approver_id
           and d.delegate_id = auth.uid() and d.revoked_at is null and now() >= d.starts_at and now() < d.ends_at
     where s.request_id = p_request and s.status = 'pending'
     order by s.position, d.created_at limit 1;
    if v_step_id is null then raise exception 'forbidden'; end if;
    select * into v_step from public.fin_approval_steps where id = v_step_id for update;
    select * into v_stage from public.fin_approval_stages where id = v_step.stage_id;
    if exists (select 1 from public.fin_approval_steps x where x.request_id = p_request and (x.approver_id = auth.uid() or x.acted_by = auth.uid())) then
      raise exception 'segregation of duties';
    end if;
    if not public.fin_approval_member_eligible(v_request.organization_id, v_entity, auth.uid(), v_stage.roles, v_stage.scope) then
      raise exception 'approver no longer eligible';
    end if;
  end if;

  update public.fin_approval_steps set status = p_action, comment = nullif(trim(coalesce(p_comment,'')),''), acted_at = now(),
         acted_by = auth.uid(), delegation_id = v_delegation, reason_code = p_reason_code
   where id = v_step.id;
  if p_action = 'approved' then
    select count(*) into v_done from public.fin_approval_steps where stage_id = v_stage.id and status = 'approved';
    if v_done >= v_stage.min_approvals then
      update public.fin_approval_stages set status = 'approved', completed_at = now() where id = v_stage.id;
      update public.fin_approval_steps set status = 'not_required' where stage_id = v_stage.id and status = 'pending';
    end if;
    -- Andamento antes do evento: o aviso já encontra a próxima sequência aberta.
    v_status := public.fin_approval_refresh(p_request);
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
      values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_approved', auth.uid(),
              jsonb_build_object('request_id', p_request, 'step', v_step.position, 'stage', v_stage.stage_key, 'on_behalf_of', case when v_delegation is not null then v_step.approver_id end));
  else
    update public.fin_approval_stages set status = p_action, completed_at = now() where id = v_stage.id;
    update public.fin_approval_requests set status = p_action, resolved_at = now() where id = p_request;
    perform public.fin_approval_close_open(p_request, 'cancelled');
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
      values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_' || p_action, auth.uid(),
              jsonb_build_object('request_id', p_request, 'step', v_step.position, 'stage', v_stage.stage_key, 'reason_code', p_reason_code,
                                 'on_behalf_of', case when v_delegation is not null then v_step.approver_id end));
    v_status := p_action;
  end if;
  return v_status;
end $$;


ALTER FUNCTION public.fin_act_on_approval_v2(p_request uuid, p_action text, p_comment text, p_reason_code text) OWNER TO postgres;

--
-- Name: fin_activate_policy_version(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_activate_policy_version(p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_policy_versions%rowtype; p public.fin_policies%rowtype; v_previous uuid;
begin
  select * into v from public.fin_policy_versions where id = p_version;
  if not found or not public.fin_has_role(v.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  select * into p from public.fin_policies where id = v.policy_id for update;
  select * into v from public.fin_policy_versions where id = p_version for update;
  if v.status <> 'draft' then raise exception 'policy version not draft'; end if;
  if p.legal_entity_id is not null and not exists (select 1 from public.fin_legal_entities e where e.id = p.legal_entity_id and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  update public.fin_policy_versions set status = 'superseded', ended_at = now() where policy_id = v.policy_id and status = 'active'
    returning id into v_previous;
  update public.fin_policy_versions set status = 'active', activated_by = auth.uid(), activated_at = now() where id = p_version;
  update public.fin_policies set status = 'active', retired_at = null where id = v.policy_id and status = 'retired';
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'organization', v.organization_id, 'policy_activated', auth.uid(),
            jsonb_build_object('policy_id', v.policy_id, 'version_id', v.id, 'version', v.version, 'superseded_version_id', v_previous), p.legal_entity_id);
end $$;


ALTER FUNCTION public.fin_activate_policy_version(p_version uuid) OWNER TO postgres;

--
-- Name: fin_add_comment(text, uuid, text, text, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_add_comment(p_type text, p_id uuid, p_visibility text, p_body text, p_mention_ids uuid[] DEFAULT '{}'::uuid[], p_client_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid;v_id uuid;v_user uuid;v_owner uuid;v_provider_org uuid;v_text text;
begin
 v_org:=public.fin_comment_object_org(p_type,p_id);
 if v_org is null then raise exception 'object not found'; end if;
 if p_visibility not in ('internal','provider_visible') or p_type not in ('rfq','proposal','approval','decision','contract','task') then raise exception 'invalid visibility'; end if;
 v_text:=trim(coalesce(p_body,''));
 if length(v_text) not between 1 and 4000 or v_text ~ '[<>]' then raise exception 'invalid comment'; end if;
 if coalesce(array_length(p_mention_ids,1),0)>10 then raise exception 'invalid mentions'; end if;
 if public.fin_has_role(v_org,array['admin','finance_manager','analyst']) then
  if p_visibility='provider_visible' and p_type not in ('rfq','proposal') then raise exception 'invalid visibility'; end if;
 elsif public.fin_provider_can_comment(p_type,p_id) then
  if p_visibility<>'provider_visible' or cardinality(coalesce(p_mention_ids,'{}'::uuid[]))>0 then raise exception 'forbidden'; end if;
 else raise exception 'forbidden'; end if;
 if p_client_id is not null then
  select id into v_id from public.fin_comments where id=p_client_id;
  if v_id is not null then
   if exists(select 1 from public.fin_comments where id=v_id and author_id=auth.uid() and object_type=p_type and object_id=p_id and organization_id=v_org and body=v_text and visibility=p_visibility) then return v_id; end if;
   raise exception 'comment conflict';
  end if;
 end if;
 v_id:=coalesce(p_client_id,gen_random_uuid());
 insert into public.fin_comments(id,organization_id,object_type,object_id,author_id,visibility,body)
 values(v_id,v_org,p_type,p_id,auth.uid(),p_visibility,v_text);
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(v_org,p_type,p_id,'comment_added',auth.uid(),jsonb_build_object('comment_id',v_id,'visibility',p_visibility));
 if p_visibility='internal' then
  foreach v_user in array coalesce(p_mention_ids,'{}'::uuid[]) loop
   if not exists(select 1 from public.fin_members where organization_id=v_org and user_id=v_user) then raise exception 'invalid mention'; end if;
   if v_user<>auth.uid() then
    insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
    values(v_org,v_user,'mention',p_type,p_id,v_id,'Você foi mencionado','Há um comentário para revisar.')
    on conflict(user_id,event_type,event_id) do nothing;
   end if;
  end loop;
 end if;
 if p_type='rfq' then select owner_id into v_owner from public.fin_rfqs where id=p_id;
 elsif p_type='contract' then select owner_id into v_owner from public.fin_contracts where id=p_id;
 end if;
 if v_owner is not null and v_owner<>auth.uid() then
  insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
  values(v_org,v_owner,'comment',p_type,p_id,v_id,'Novo comentário','Há uma atualização no processo.')
  on conflict(user_id,event_type,event_id) do nothing;
 end if;
 return v_id;
end $$;


ALTER FUNCTION public.fin_add_comment(p_type text, p_id uuid, p_visibility text, p_body text, p_mention_ids uuid[], p_client_id uuid) OWNER TO postgres;

--
-- Name: fin_add_provider_contact(uuid, uuid, text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_add_provider_contact(p_org uuid, p_provider uuid, p_name text, p_title text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_primary boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  -- Contato de nível de grupo pode ser criado por qualquer membro de escrita;
  -- contato de entidade, só por quem alcança a entidade.
  if p_entity is null then
    if not public.fin_has_role(p_org, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  else
    perform public.fin_assert_portfolio_write(p_org, p_entity);
  end if;
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_primary then
    update public.fin_provider_contacts set is_primary = false
     where organization_id = p_org and provider_id = p_provider and legal_entity_id is not distinct from p_entity and archived_at is null;
  end if;
  insert into public.fin_provider_contacts(organization_id, provider_id, legal_entity_id, name, title, email, phone, is_primary, created_by)
    values (p_org, p_provider, p_entity, trim(p_name), nullif(trim(coalesce(p_title,'')),''), nullif(lower(trim(coalesce(p_email,''))),''),
      nullif(trim(coalesce(p_phone,'')),''), coalesce(p_primary, false), auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'provider', p_provider, 'provider_contact_added', auth.uid(), jsonb_build_object('contact_id', v_id), p_entity);
  return v_id;
exception when check_violation then raise exception 'invalid contact';
end $$;


ALTER FUNCTION public.fin_add_provider_contact(p_org uuid, p_provider uuid, p_name text, p_title text, p_email text, p_phone text, p_entity uuid, p_primary boolean) OWNER TO postgres;

--
-- Name: fin_api_context(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_context(p_key_hash text, p_scope text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare c public.fin_api_credentials%rowtype; a public.fin_service_accounts%rowtype;
begin
  if coalesce(p_key_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'api unauthorized'; end if;
  select * into c from public.fin_api_credentials where token_hash = p_key_hash;
  if not found or c.revoked_at is not null or c.expires_at <= now() then raise exception 'api unauthorized'; end if;
  select * into a from public.fin_service_accounts where id = c.service_account_id;
  if a.status <> 'active' or not exists (select 1 from public.fin_organizations o where o.id = a.organization_id and o.kind = 'BUYER') then
    raise exception 'api unauthorized';
  end if;
  if p_scope is not null and not (p_scope = any(a.scopes)) then raise exception 'api scope denied'; end if;
  -- Último uso: no máximo uma escrita por minuto por credencial.
  if c.last_used_at is null or c.last_used_at < now() - interval '1 minute' then
    update public.fin_api_credentials set last_used_at = now() where id = c.id;
    update public.fin_service_accounts set last_used_at = now() where id = a.id;
  end if;
  return jsonb_build_object('service_account_id', a.id, 'credential_id', c.id, 'organization_id', a.organization_id, 'scopes', to_jsonb(a.scopes),
    'entity_scope', a.entity_scope,
    'entities', coalesce((select jsonb_agg(g.entity_id) from public.fin_service_account_entities g where g.service_account_id = a.id), '[]'::jsonb));
end $_$;


ALTER FUNCTION public.fin_api_context(p_key_hash text, p_scope text) OWNER TO postgres;

--
-- Name: fin_api_create_rfq(text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_create_rfq(p_key_hash text, p_idempotency_key text, p_fingerprint text, p_payload jsonb, p_correlation text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v jsonb; s record; v_id uuid; v_org uuid; v_entity uuid; v_owner uuid; v_response jsonb;
begin
  v := public.fin_api_context(p_key_hash, 'rfqs:write');
  if coalesce(p_idempotency_key, '') !~ '^[A-Za-z0-9._:-]{8,200}$' or coalesce(p_fingerprint, '') !~ '^[0-9a-f]{64}$' then raise exception 'idempotency key required'; end if;
  -- Serializa a mesma chave (pedidos concorrentes esperam o primeiro).
  perform pg_advisory_xact_lock(hashtextextended((v->>'service_account_id') || ':' || p_idempotency_key, 0));
  select * into s from public.fin_api_idempotency where service_account_id = (v->>'service_account_id')::uuid and idempotency_key = p_idempotency_key and expires_at > now();
  if found then
    if s.request_fingerprint <> p_fingerprint or s.operation <> 'rfqs.create' then raise exception 'idempotency key reuse'; end if;
    return s.response_body || jsonb_build_object('idempotent_replay', true);
  end if;
  delete from public.fin_api_idempotency where service_account_id = (v->>'service_account_id')::uuid and idempotency_key = p_idempotency_key;
  v_org := (v->>'organization_id')::uuid;
  v_entity := nullif(p_payload->>'legal_entity_id', '')::uuid;
  v_owner := nullif(p_payload->>'owner_id', '')::uuid;
  if jsonb_typeof(p_payload) <> 'object' or coalesce(p_payload->>'product', '') not in ('credit','acquiring') or jsonb_typeof(p_payload->'demand') <> 'object'
     or length(trim(coalesce(p_payload->>'title', ''))) not between 3 and 160 or (p_payload->>'title') ~ '[<>]'
     or (p_payload ? 'description' and (length(coalesce(p_payload->>'description', '')) > 4000 or (p_payload->>'description') ~ '[<>]')) then
    raise exception 'invalid api payload';
  end if;
  if not public.fin_api_entity_allowed(v, v_entity) then raise exception 'api entity denied'; end if;
  if v_entity is not null and not exists (select 1 from public.fin_legal_entities e where e.organization_id = v_org and e.id = v_entity and e.status = 'active') then
    raise exception 'api entity denied';
  end if;
  if v_owner is null or not public.fin_approval_member_eligible(v_org, v_entity, v_owner, array['admin','finance_manager'], 'any') then
    raise exception 'invalid api owner';
  end if;
  insert into public.fin_rfqs(organization_id, product, title, description, demand, response_deadline, owner_id, legal_entity_id)
    values (v_org, p_payload->>'product', trim(p_payload->>'title'), nullif(trim(coalesce(p_payload->>'description', '')), ''), p_payload->'demand',
            nullif(p_payload->>'response_deadline', '')::date, v_owner, v_entity)
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_org, 'rfq', v_id, 'rfq_created', null, jsonb_build_object('product', p_payload->>'product', 'source', 'api_v1',
            'service_account_id', v->>'service_account_id', 'correlation_id', left(coalesce(p_correlation, ''), 80)));
  v_response := jsonb_build_object('id', v_id, 'status', 'draft', 'legal_entity_id', v_entity, 'owner_id', v_owner);
  insert into public.fin_api_idempotency(service_account_id, idempotency_key, request_fingerprint, operation, response_status, response_body)
    values ((v->>'service_account_id')::uuid, p_idempotency_key, p_fingerprint, 'rfqs.create', 201, v_response);
  return v_response;
exception when invalid_datetime_format or datetime_field_overflow or invalid_text_representation then raise exception 'invalid api payload';
end $_$;


ALTER FUNCTION public.fin_api_create_rfq(p_key_hash text, p_idempotency_key text, p_fingerprint text, p_payload jsonb, p_correlation text) OWNER TO postgres;

--
-- Name: fin_api_create_webhook(text, text, text[], text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_create_webhook(p_key_hash text, p_url text, p_events text[], p_secret_ciphertext text, p_description text, p_entities uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; v_id uuid; v_org uuid; x uuid;
begin
  v := public.fin_api_context(p_key_hash, 'webhooks:manage');
  v_org := (v->>'organization_id')::uuid;
  if v->>'entity_scope' = 'entities' then
    if p_entities is null or cardinality(p_entities) = 0 then raise exception 'api entity denied'; end if;
    foreach x in array p_entities loop
      if not public.fin_api_entity_allowed(v, x) then raise exception 'api entity denied'; end if;
    end loop;
  end if;
  if not public.fin_valid_webhook_url(coalesce(p_url, '')) or (p_entities is not null and not public.fin_api_valid_entities(v_org, 'entities', p_entities)) then
    raise exception 'invalid webhook';
  end if;
  if (select count(*) from public.fin_webhook_endpoints where organization_id = v_org and status <> 'disabled') >= 10 then raise exception 'too many webhooks'; end if;
  insert into public.fin_webhook_endpoints(organization_id, url, description, events, entity_ids, secret_ciphertext, created_by_service_account)
    values (v_org, p_url, nullif(trim(coalesce(p_description,'')),''), (select array_agg(distinct e order by e) from unnest(p_events) e), p_entities,
            p_secret_ciphertext, (v->>'service_account_id')::uuid)
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_org, 'webhook_endpoint', v_id, 'webhook_endpoint_created', null, jsonb_build_object('events', p_events, 'service_account_id', v->>'service_account_id'));
  return v_id;
exception when check_violation or not_null_violation then raise exception 'invalid webhook';
end $$;


ALTER FUNCTION public.fin_api_create_webhook(p_key_hash text, p_url text, p_events text[], p_secret_ciphertext text, p_description text, p_entities uuid[]) OWNER TO postgres;

--
-- Name: fin_api_disable_webhook(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_disable_webhook(p_key_hash text, p_endpoint uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; e public.fin_webhook_endpoints%rowtype;
begin
  v := public.fin_api_context(p_key_hash, 'webhooks:manage');
  select * into e from public.fin_webhook_endpoints where id = p_endpoint and organization_id = (v->>'organization_id')::uuid for update;
  if not found or not public.fin_api_endpoint_allowed(v, e.entity_ids) then raise exception 'api not found'; end if;
  update public.fin_webhook_endpoints set status = 'disabled', disabled_at = coalesce(disabled_at, now()), disabled_reason = 'manual', updated_at = now() where id = p_endpoint;
  update public.fin_webhook_deliveries set status = 'cancelled', lease_token = null, lease_expires_at = null where endpoint_id = p_endpoint and status in ('pending','failed');
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (e.organization_id, 'webhook_endpoint', p_endpoint, 'webhook_endpoint_disabled', null, jsonb_build_object('service_account_id', v->>'service_account_id'));
end $$;


ALTER FUNCTION public.fin_api_disable_webhook(p_key_hash text, p_endpoint uuid) OWNER TO postgres;

--
-- Name: fin_api_endpoint_allowed(jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_endpoint_allowed(p_ctx jsonb, p_entities uuid[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_ctx->>'entity_scope' = 'group' or (p_entities is not null and cardinality(p_entities) > 0
    and not exists (select 1 from unnest(p_entities) x where not public.fin_api_entity_allowed(p_ctx, x)));
$$;


ALTER FUNCTION public.fin_api_endpoint_allowed(p_ctx jsonb, p_entities uuid[]) OWNER TO postgres;

--
-- Name: fin_api_entity_allowed(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_entity_allowed(p_ctx jsonb, p_entity uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_ctx->>'entity_scope' = 'group' or (p_entity is not null and exists (
    select 1 from public.fin_legal_entities e
     where e.organization_id = (p_ctx->>'organization_id')::uuid and e.id = p_entity
       and ((p_ctx->'entities') ? e.id::text or (e.parent_id is not null and (p_ctx->'entities') ? e.parent_id::text))));
$$;


ALTER FUNCTION public.fin_api_entity_allowed(p_ctx jsonb, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_api_get_contract(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_get_contract(p_key_hash text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; c public.fin_contracts%rowtype;
begin
  v := public.fin_api_context(p_key_hash, 'contracts:read');
  select * into c from public.fin_contracts where id = p_id and organization_id = (v->>'organization_id')::uuid;
  if not found or not public.fin_api_entity_allowed(v, c.legal_entity_id) then raise exception 'api not found'; end if;
  return jsonb_build_object('id', c.id, 'provider_id', c.provider_id, 'product', c.product, 'status', c.status, 'legal_entity_id', c.legal_entity_id,
    'starts_on', c.starts_on, 'ends_on', c.ends_on, 'renewal_notice_days', c.renewal_notice_days, 'decision_id', c.decision_id,
    'created_at', c.created_at, 'updated_at', c.updated_at);
end $$;


ALTER FUNCTION public.fin_api_get_contract(p_key_hash text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_api_get_rfq(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_get_rfq(p_key_hash text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; r public.fin_rfqs%rowtype;
begin
  v := public.fin_api_context(p_key_hash, 'rfqs:read');
  select * into r from public.fin_rfqs where id = p_id and organization_id = (v->>'organization_id')::uuid;
  if not found or not public.fin_api_entity_allowed(v, r.legal_entity_id) then raise exception 'api not found'; end if;
  return jsonb_build_object('id', r.id, 'product', r.product, 'title', r.title, 'description', r.description, 'status', r.status, 'revision', r.revision,
    'legal_entity_id', r.legal_entity_id, 'demand', r.demand, 'response_deadline', r.response_deadline, 'owner_id', r.owner_id,
    'created_at', r.created_at, 'updated_at', r.updated_at,
    'proposals', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'provider_id', p.provider_id, 'status', p.status, 'version', p.current_version,
       'submitted_at', pv.submitted_at) order by p.created_at, p.id)
       from public.fin_proposals p left join public.fin_proposal_versions pv on pv.proposal_id = p.id and pv.version = p.current_version
      where p.rfq_id = r.id and p.current_version > 0), '[]'::jsonb),
    'decision', (select jsonb_build_object('id', d.id, 'proposal_id', d.proposal_id, 'decided_at', d.decided_at) from public.fin_decisions d where d.rfq_id = r.id));
end $$;


ALTER FUNCTION public.fin_api_get_rfq(p_key_hash text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_api_list_approvals(text, integer, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_list_approvals(p_key_hash text, p_limit integer DEFAULT 25, p_after_requested timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
begin
  v := public.fin_api_context(p_key_hash, 'approvals:read');
  if (p_after_requested is null) <> (p_after_id is null) then raise exception 'invalid api query'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.requested_at desc, x.id desc) from (
    select a.id, a.rfq_id, a.proposal_id, a.proposal_version, a.status, a.requested_at, a.resolved_at, a.expires_at,
           (a.policy_snapshot is not null) policy_driven, a.policy_version_ids,
           (select count(*) from public.fin_approval_stages s where s.request_id = a.id) stages_total,
           (select count(*) from public.fin_approval_stages s where s.request_id = a.id and s.status in ('approved','waived')) stages_done
      from public.fin_approval_requests a join public.fin_rfqs r on r.id = a.rfq_id
     where a.organization_id = (v->>'organization_id')::uuid and public.fin_api_entity_allowed(v, r.legal_entity_id)
       and (p_status is null or a.status = p_status)
       and (p_after_requested is null or (a.requested_at, a.id) < (p_after_requested, p_after_id))
     order by a.requested_at desc, a.id desc limit v_limit + 1) x), '[]'::jsonb);
end $$;


ALTER FUNCTION public.fin_api_list_approvals(p_key_hash text, p_limit integer, p_after_requested timestamp with time zone, p_after_id uuid, p_status text) OWNER TO postgres;

--
-- Name: fin_api_list_contracts(text, integer, timestamp with time zone, uuid, text, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_list_contracts(p_key_hash text, p_limit integer DEFAULT 25, p_after_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_ends_before date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
begin
  v := public.fin_api_context(p_key_hash, 'contracts:read');
  if (p_after_created is null) <> (p_after_id is null) then raise exception 'invalid api query'; end if;
  return coalesce((select jsonb_agg(row_to_json(x)::jsonb order by x.created_at desc, x.id desc) from (
    select c.id, c.provider_id, c.product, c.title, c.currency, c.status, c.legal_entity_id, c.starts_on, c.ends_on, c.renewal_notice_days, c.decision_id, c.created_at, c.updated_at
      from public.fin_contracts c
     where c.organization_id = (v->>'organization_id')::uuid and public.fin_api_entity_allowed(v, c.legal_entity_id)
       and (p_status is null or c.status = p_status) and (p_entity is null or c.legal_entity_id = p_entity)
       and (p_ends_before is null or c.ends_on < p_ends_before)
       and (p_after_created is null or (c.created_at, c.id) < (p_after_created, p_after_id))
     order by c.created_at desc, c.id desc limit v_limit + 1) x), '[]'::jsonb);
end $$;


ALTER FUNCTION public.fin_api_list_contracts(p_key_hash text, p_limit integer, p_after_created timestamp with time zone, p_after_id uuid, p_status text, p_entity uuid, p_ends_before date) OWNER TO postgres;

--
-- Name: fin_api_list_deliveries(text, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_api_list_deliveries(p_key_hash text, p_endpoint uuid, p_limit integer DEFAULT 25, p_after_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb; v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
begin
  v := public.fin_api_context(p_key_hash, 'webhooks:manage');
  if not exists (select 1 from public.fin_webhook_endpoints e where e.id = p_endpoint and e.organization_id = (v->>'organization_id')::uuid
                   and public.fin_api_endpoint_allowed(v, e.entity_ids)) then raise exception 'api not found'; end if;
  if (p_after_created is null) <> (p_after_id is null) then raise exception 'invalid api query'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc, x.id desc) from (
    select d.id, d.event_id, w.event_type, d.status, d.attempts, d.next_attempt_at, d.last_attempt_at, d.last_status_code, d.last_error_code, d.delivered_at, d.replay_of, d.created_at
      from public.fin_webhook_deliveries d join public.fin_webhook_events w on w.id = d.event_id
     where d.endpoint_id = p_endpoint and (p_after_created is null or (d.created_at, d.id) < (p_after_created, p_after_id))
     order by d.created_at desc, d.id desc limit v_limit + 1) x), '[]'::jsonb);
end $$;


ALTER FUNCTION public.fin_api_list_deliveries(p_key_hash text, p_endpoint uuid, p_limit integer, p_after_created timestamp with time zone, p_after_id uuid) OWNER TO postgres;

