--
-- Name: fin_apply_notification_preference(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_apply_notification_preference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if exists(select 1 from public.fin_notification_preferences p
   where p.organization_id=new.organization_id and p.user_id=new.user_id
   and p.event_type=new.event_type and not p.in_app) then return null; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_apply_notification_preference() OWNER TO postgres;

--
-- Name: fin_approval_close_open(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_close_open(p_request uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.fin_approval_stages set status = p_status, completed_at = now() where request_id = p_request and status in ('pending','active');
  update public.fin_approval_steps set status = case when p_status in ('expired','superseded') then p_status else 'cancelled' end
   where request_id = p_request and status = 'pending';
end $$;


ALTER FUNCTION public.fin_approval_close_open(p_request uuid, p_status text) OWNER TO postgres;

--
-- Name: fin_approval_live_actor_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_live_actor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_entity uuid; v_role text; v_stage public.fin_approval_stages%rowtype;
begin
  if old.status <> 'pending' or new.status not in ('approved','rejected','changes_requested')
    or old.status = new.status then return new; end if;
  select a.organization_id,r.legal_entity_id into v_org,v_entity
    from public.fin_approval_requests a join public.fin_rfqs r on r.id=a.rfq_id where a.id=new.request_id;
  select m.role into v_role from public.fin_members m
    where m.organization_id=v_org and m.user_id=auth.uid() for share;
  if not found or v_role not in ('admin','finance_manager','analyst','viewer') or new.acted_by is distinct from auth.uid() then raise exception 'forbidden'; end if;
  perform 1 from public.fin_member_entity_grants g where g.organization_id=v_org and g.user_id=auth.uid() for share;
  if not public.fin_entity_visible(v_org,v_entity) then raise exception 'forbidden'; end if;
  if new.stage_id is not null then
    select * into v_stage from public.fin_approval_stages where id=new.stage_id;
    if not public.fin_approval_member_eligible(v_org,v_entity,auth.uid(),v_stage.roles,v_stage.scope) then raise exception 'forbidden'; end if;
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_approval_live_actor_guard() OWNER TO postgres;

--
-- Name: fin_approval_member_eligible(uuid, uuid, uuid, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_member_eligible(p_org uuid, p_entity uuid, p_user uuid, p_roles text[], p_scope text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.fin_members m join public.fin_organizations o on o.id = m.organization_id and o.kind = 'BUYER'
     where m.organization_id = p_org and m.user_id = p_user and m.role = any(p_roles)
       and m.role in ('admin','finance_manager','analyst','viewer')
       and (m.entity_scope = 'group' or (p_entity is not null and exists (
             select 1 from public.fin_legal_entities e join public.fin_member_entity_grants g
               on g.organization_id = e.organization_id and g.user_id = m.user_id and (g.entity_id = e.id or g.entity_id = e.parent_id)
              where e.organization_id = p_org and e.id = p_entity)))
       and case p_scope when 'group' then m.entity_scope = 'group'
                        when 'entity' then m.entity_scope = 'entities' and p_entity is not null
                        else true end);
$$;


ALTER FUNCTION public.fin_approval_member_eligible(p_org uuid, p_entity uuid, p_user uuid, p_roles text[], p_scope text) OWNER TO postgres;

--
-- Name: fin_approval_refresh(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_refresh(p_request uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.fin_approval_requests%rowtype; v_seq integer; v_blocked boolean;
begin
  select * into v_request from public.fin_approval_requests where id = p_request;
  if v_request.status <> 'pending' or v_request.policy_snapshot is null then return v_request.status; end if;
  update public.fin_approval_stages st set status = 'waived', completed_at = now(),
         waived_by = (select e.id from public.fin_policy_exceptions e, jsonb_array_elements(st.sources) src
                       where e.request_id = p_request and e.status = 'approved' and e.policy_version_id = (src->>'policy_version_id')::uuid
                         and e.rule_id = src->>'rule_id' order by e.decided_at, e.id limit 1)
   where st.request_id = p_request and st.status in ('pending','active')
     and not exists (select 1 from jsonb_array_elements(st.sources) src
                      where not public.fin_policy_rule_excepted(p_request, (src->>'policy_version_id')::uuid, src->>'rule_id'));
  update public.fin_approval_steps s set status = 'waived' from public.fin_approval_stages st
   where st.id = s.stage_id and st.request_id = p_request and st.status = 'waived' and s.status = 'pending';
  select min(sequence) into v_seq from public.fin_approval_stages where request_id = p_request and status in ('pending','active');
  if v_seq is not null then
    update public.fin_approval_stages set status = 'active', opened_at = now(),
           due_at = case when due_hours is not null then now() + make_interval(hours => due_hours) end
     where request_id = p_request and sequence = v_seq and status = 'pending';
    return 'pending';
  end if;
  select exists (select 1 from jsonb_array_elements(v_request.policy_snapshot->'blockers') b
                  where not public.fin_policy_rule_excepted(p_request, (b->>'policy_version_id')::uuid, b->>'rule_id')) into v_blocked;
  if v_blocked then return 'pending'; end if;
  update public.fin_approval_requests set status = 'approved', resolved_at = now() where id = p_request;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_completed', auth.uid(), jsonb_build_object('request_id', p_request));
  return 'approved';
end $$;


ALTER FUNCTION public.fin_approval_refresh(p_request uuid) OWNER TO postgres;

--
-- Name: fin_approval_snapshot_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (new.proposal_id,new.external_proposal_id,new.external_rfq_revision,new.external_request_key,new.external_request_hash,new.proposal_version,new.snapshot,new.rfq_id,new.organization_id,new.requested_by) is distinct from (old.proposal_id,old.external_proposal_id,old.external_rfq_revision,old.external_request_key,old.external_request_hash,old.proposal_version,old.snapshot,old.rfq_id,old.organization_id,old.requested_by) then raise exception 'immutable record'; end if;
  if old.policy_snapshot is null and new.policy_snapshot is not null then raise exception 'immutable record'; end if;
  if old.policy_snapshot is not null and (new.policy_snapshot is distinct from old.policy_snapshot
     or new.policy_version_ids is distinct from old.policy_version_ids or new.evaluated_at is distinct from old.evaluated_at
     or new.declared_facts is distinct from old.declared_facts or new.justification is distinct from old.justification
     or new.expires_at is distinct from old.expires_at) then
    raise exception 'immutable record';
  end if;
  if old.status <> 'pending' and new.status is distinct from old.status then raise exception 'immutable record'; end if;
  return new;
end $$;


ALTER FUNCTION public.fin_approval_snapshot_guard() OWNER TO postgres;

--
-- Name: fin_approval_stage_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_stage_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.request_id is distinct from old.request_id or new.organization_id is distinct from old.organization_id
     or new.stage_key is distinct from old.stage_key or new.label is distinct from old.label or new.sequence is distinct from old.sequence
     or new.roles is distinct from old.roles or new.scope is distinct from old.scope or new.min_approvals is distinct from old.min_approvals
     or new.due_hours is distinct from old.due_hours or new.allow_delegation is distinct from old.allow_delegation or new.sources is distinct from old.sources then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_approval_stage_guard() OWNER TO postgres;

--
-- Name: fin_approval_step_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_approval_step_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_entity uuid; v_ok boolean;
begin
  select r.organization_id, r.legal_entity_id into v_org, v_entity
    from public.fin_approval_requests a join public.fin_rfqs r on r.id = a.rfq_id where a.id = new.request_id;
  if v_org is null then return new; end if;
  if tg_op = 'INSERT' then
    select m.entity_scope = 'group' or (v_entity is not null and exists (
             select 1 from public.fin_legal_entities e join public.fin_member_entity_grants g
               on g.organization_id = e.organization_id and g.user_id = m.user_id and (g.entity_id = e.id or g.entity_id = e.parent_id)
              where e.organization_id = v_org and e.id = v_entity))
      into v_ok from public.fin_members m where m.organization_id = v_org and m.user_id = new.approver_id;
    if not coalesce(v_ok, false) then raise exception 'invalid approver'; end if;
  else
    perform public.fin_assert_entity_write(v_org, v_entity);
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_approval_step_entity_guard() OWNER TO postgres;

--
-- Name: fin_archive_provider_contact(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_archive_provider_contact(p_contact uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_provider_contacts%rowtype;
begin
  select * into v from public.fin_provider_contacts where id = p_contact for update;
  if not found or not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager','analyst'])
     and not (v.legal_entity_id is null and public.fin_has_role(v.organization_id, array['admin','finance_manager','analyst'])) then
    raise exception 'contact not found';
  end if;
  update public.fin_provider_contacts set archived_at = coalesce(archived_at, now()), is_primary = false where id = p_contact;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'provider', v.provider_id, 'provider_contact_archived', auth.uid(), jsonb_build_object('contact_id', v.id), v.legal_entity_id);
end $$;


ALTER FUNCTION public.fin_archive_provider_contact(p_contact uuid) OWNER TO postgres;

--
-- Name: fin_assert_entity_write(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_assert_entity_write(p_org uuid, p_entity uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is not null and public.fin_has_role(p_org) and not public.fin_entity_visible(p_org, p_entity) then
    raise exception 'forbidden';
  end if;
end $$;


ALTER FUNCTION public.fin_assert_entity_write(p_org uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_assert_portfolio_write(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_assert_portfolio_write(p_org uuid, p_entity uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if not public.fin_entity_allows(p_org, p_entity, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  if p_entity is not null and not exists (select 1 from public.fin_legal_entities e where e.organization_id = p_org and e.id = p_entity and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
end $$;


ALTER FUNCTION public.fin_assert_portfolio_write(p_org uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_assign_contract_entity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_assign_contract_entity(p_contract uuid, p_entity uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_contracts%rowtype;
begin
  select * into v from public.fin_contracts where id = p_contract for update;
  if not found then raise exception 'contract not found'; end if;
  if not public.fin_has_role(v.organization_id, array['admin','finance_manager']) or public.fin_entity_scope(v.organization_id) <> 'group' then
    raise exception 'forbidden';
  end if;
  if v.legal_entity_id is not null then raise exception 'legal entity already assigned'; end if;
  if not exists (select 1 from public.fin_legal_entities e where e.organization_id = v.organization_id and e.id = p_entity and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  perform set_config('arandu.entity_change', 'on', true);
  update public.fin_contracts set legal_entity_id = p_entity, updated_at = now() where id = p_contract;
  update public.fin_tasks set legal_entity_id = p_entity where organization_id = v.organization_id and related_type = 'contract' and related_id = p_contract;
  perform set_config('arandu.entity_change', '', true);
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
  values (v.organization_id, 'contract', p_contract, 'contract_entity_assigned', auth.uid(), '{}'::jsonb, p_entity);
end $$;


ALTER FUNCTION public.fin_assign_contract_entity(p_contract uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_assign_contract_owner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_assign_contract_owner(p_contract uuid, p_expected_owner uuid, p_owner uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype;
begin
 select * into c from public.fin_contracts where id=p_contract;
 if c.id is null then raise exception 'forbidden'; end if;
 perform public.fin_contract_import_actor(c.organization_id,c.legal_entity_id,array['admin','finance_manager']);
 perform public.fin_contract_owner_eligible(c.organization_id,c.legal_entity_id,p_owner);
 select * into c from public.fin_contracts where id=p_contract for update;
 if not public.fin_entity_visible(c.organization_id,c.legal_entity_id) then raise exception 'forbidden'; end if;
 if c.owner_id=p_owner then return false; end if;
 if c.owner_id is distinct from p_expected_owner then raise exception 'contract version conflict'; end if;
 update public.fin_contracts set owner_id=p_owner,updated_at=now() where id=p_contract;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(c.organization_id,'contract',c.id,'contract_owner_assigned',auth.uid(),jsonb_build_object('previous_owner_id',c.owner_id,'owner_id',p_owner));
 return true;
end $$;


ALTER FUNCTION public.fin_assign_contract_owner(p_contract uuid, p_expected_owner uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_assignment_buyer_names(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_assignment_buyer_names(p_org uuid, p_rfqs uuid[]) RETURNS TABLE(rfq_id uuid, buyer_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.fin_has_role(p_org) or not exists (
    select 1 from public.fin_organizations o where o.id=p_org and o.kind='PROVIDER'
  ) then raise exception 'forbidden'; end if;
  if coalesce(cardinality(p_rfqs),0) > 200 then raise exception 'invalid assignment filters'; end if;
  return query
    select distinct r.id, coalesce(nullif(trim(o.trade_name),''), o.legal_name)
      from public.fin_rfqs r
      join public.fin_organizations o on o.id=r.organization_id
      join public.fin_rfq_invites i on i.rfq_id=r.id and i.buyer_organization_id=r.organization_id
        and i.provider_organization_id=p_org and i.status='accepted'
      join public.fin_proposals p on p.invite_id=i.id and p.rfq_id=r.id and p.provider_organization_id=p_org
     where r.id=any(p_rfqs);
end $$;


ALTER FUNCTION public.fin_assignment_buyer_names(p_org uuid, p_rfqs uuid[]) OWNER TO postgres;

--
-- Name: fin_can_read_document(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_can_read_document(p_document uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.fin_private_documents d
     where d.id = p_document and d.removed_at is null and (
       (public.fin_has_role(d.organization_id) and (d.organization_id <> d.buyer_organization_id
          or (d.entity_type = 'profile' and public.fin_entity_visible(d.organization_id,case when d.entity_id=d.organization_id then null else d.entity_id end)) or (d.entity_type <> 'profile' and public.fin_object_visible(d.organization_id, d.entity_type, d.entity_id))))
       or (d.visibility = 'shared' and d.organization_id = d.buyer_organization_id and d.rfq_id is not null
           and public.fin_provider_can_comment('rfq', d.rfq_id))
       or (d.visibility = 'shared' and d.organization_id <> d.buyer_organization_id and public.fin_has_role(d.buyer_organization_id)
           and (d.rfq_id is null or public.fin_rfq_visible(d.rfq_id)))
     ));
$$;


ALTER FUNCTION public.fin_can_read_document(p_document uuid) OWNER TO postgres;

--
-- Name: fin_cancel_approval(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_cancel_approval(p_request uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.fin_approval_requests%rowtype;
begin
  select * into v_request from public.fin_approval_requests where id = p_request;
  if not found then raise exception 'approval not found'; end if;
  perform 1 from public.fin_rfqs where id = v_request.rfq_id for update;
  select * into v_request from public.fin_approval_requests where id = p_request for update;
  if not public.fin_has_role(v_request.organization_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_request.status <> 'pending' then raise exception 'approval not pending'; end if;
  update public.fin_approval_requests set status = 'cancelled', resolved_at = now() where id = p_request;
  perform public.fin_approval_close_open(p_request, 'cancelled');
  update public.fin_policy_exceptions set status = 'cancelled' where request_id = p_request and status = 'requested';
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_cancelled', auth.uid(), jsonb_build_object('request_id', p_request));
end $$;


ALTER FUNCTION public.fin_cancel_approval(p_request uuid) OWNER TO postgres;

--
-- Name: fin_cancel_implementation(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_cancel_implementation(p_plan uuid, p_expected integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_implementation_plans%rowtype; begin
 p:=public.fin_implementation_require(p_plan,array['admin','finance_manager']);
 if p_expected is null or p.version<>p_expected then raise exception 'implementation conflict'; end if;
 if p.status in ('accepted','cancelled') then raise exception 'implementation closed'; end if;
 if p_reason is null or length(trim(p_reason)) not between 10 and 1000 or p_reason ~ '[<>]' then raise exception 'invalid implementation input'; end if;
 update public.fin_implementation_plans set status='cancelled',cancellation_reason=trim(p_reason),version=version+1,updated_at=now() where id=p.id;
 update public.fin_tasks set status='cancelled' where status='open' and id in(select task_id from public.fin_implementation_milestones where plan_id=p.id);
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'implementation_cancelled',auth.uid(),p.legal_entity_id,jsonb_build_object('implementation_id',p.id));
end $$;


ALTER FUNCTION public.fin_cancel_implementation(p_plan uuid, p_expected integer, p_reason text) OWNER TO postgres;

--
-- Name: fin_cancel_obligation(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_cancel_obligation(p_obligation uuid, p_expected integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype;v_period uuid;begin
 select id into v_period from public.fin_obligation_periods where obligation_id=p_obligation order by period_start limit 1;
 o:=public.fin_obligation_require(v_period,array['admin','finance_manager']);
 if p_expected is null or o.version<>p_expected then raise exception 'obligation conflict';end if;
 if p_reason is null or length(trim(p_reason)) not between 10 and 1000 or p_reason ~ '[<>]' then raise exception 'invalid obligation input';end if;
 update public.fin_obligations set status='cancelled',version=version+1,cancellation_reason=trim(p_reason) where id=o.id;
 update public.fin_tasks set status='cancelled' where id in(select task_id from public.fin_obligation_periods where obligation_id=o.id) and status='open';
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(o.organization_id,'contract',o.contract_id,'obligation_cancelled',auth.uid(),o.legal_entity_id,jsonb_build_object('obligation_id',o.id));
end $$;


ALTER FUNCTION public.fin_cancel_obligation(p_obligation uuid, p_expected integer, p_reason text) OWNER TO postgres;

--
-- Name: fin_cancel_policy_exception(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_cancel_policy_exception(p_exception uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.fin_policy_exceptions%rowtype; v_rfq uuid;
begin
  select * into e from public.fin_policy_exceptions where id = p_exception for update;
  if not found then raise exception 'policy exception not found'; end if;
  if not (e.requested_by = auth.uid() or public.fin_has_role(e.organization_id, array['admin'])) then raise exception 'forbidden'; end if;
  if e.status <> 'requested' then raise exception 'policy exception closed'; end if;
  update public.fin_policy_exceptions set status = 'cancelled' where id = p_exception;
  select rfq_id into v_rfq from public.fin_approval_requests where id = e.request_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (e.organization_id, 'rfq', v_rfq, 'policy_exception_cancelled', auth.uid(), jsonb_build_object('request_id', e.request_id, 'exception_id', e.id));
end $$;


ALTER FUNCTION public.fin_cancel_policy_exception(p_exception uuid) OWNER TO postgres;

--
-- Name: fin_capture_rfq_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_capture_rfq_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if (new.title,new.description,new.demand,new.response_deadline) is distinct from
    (old.title,old.description,old.demand,old.response_deadline) then
  new.revision:=old.revision+1;
 end if;
 return new;
end $$;


ALTER FUNCTION public.fin_capture_rfq_revision() OWNER TO postgres;

--
-- Name: fin_check_product_terms(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_check_product_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare category text; contract_currency text;
begin
 if not (new.terms ? 'product_terms') and exists(select 1 from public.fin_contract_versions v where v.contract_id=new.contract_id and v.organization_id=new.organization_id and v.version<new.version and v.terms ? 'product_terms') then raise exception 'specialized contract terms required'; end if;
 if new.terms ? 'product_terms' then
  select c.product,c.currency into category,contract_currency from public.fin_contracts c where c.id=new.contract_id and c.organization_id=new.organization_id;
  if not public.fin_valid_product_terms(category,new.terms->'product_terms') then raise exception 'invalid contract terms'; end if;
  if new.terms->'product_terms'->'values' ? 'currency' and coalesce(new.terms->>'currency',contract_currency) is distinct from new.terms->'product_terms'->'values'->>'currency' then raise exception 'currency mismatch'; end if;
 end if;
 return new;
end $$;


ALTER FUNCTION public.fin_check_product_terms() OWNER TO postgres;

--
-- Name: fin_clear_rfq_editor(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_clear_rfq_editor(p_org uuid, p_expected integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.fin_has_role(p_org,array['admin','finance_manager']) then raise exception 'forbidden'; end if;
 delete from public.fin_rfq_editor_drafts where organization_id=p_org and user_id=auth.uid() and revision=p_expected;
 if not found then raise exception 'rfq draft conflict'; end if;
end $$;


ALTER FUNCTION public.fin_clear_rfq_editor(p_org uuid, p_expected integer) OWNER TO postgres;

