ALTER FUNCTION public.fin_clear_submitted_draft() OWNER TO postgres;

--
-- Name: fin_close_performance(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_close_performance(p_period uuid, p_expected integer, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_provider_performance_periods%rowtype;begin
 p:=public.fin_performance_require(p_period,array['admin','finance_manager']);
 if p_expected is null or p.version<>p_expected then raise exception 'performance conflict';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or p_input->>'confirm' is distinct from 'true' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('confirm','reason')) or length(trim(p_input->>'reason')) not between 10 and 2000 or p_input->>'reason' is null then raise exception 'performance confirmation required';end if;
 if current_date<p.period_end or exists(select 1 from public.fin_provider_performance_targets t left join lateral(select x.* from public.fin_provider_performance_observations x where x.period_id=t.period_id and x.dimension_id=t.dimension_id order by revision desc limit 1)o on true left join public.fin_provider_performance_reviews r on r.observation_id=o.id where t.period_id=p.id and (r.status is null or r.status='rejected')) then raise exception 'performance review incomplete';end if;
 update public.fin_provider_performance_periods set status='closed',closed_by=auth.uid(),closed_at=now(),close_reason=trim(p_input->>'reason'),version=version+1 where id=p.id;
 update public.fin_tasks set status='done' where id=p.task_id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'performance_period_closed',auth.uid(),p.legal_entity_id,jsonb_build_object('period_id',p.id));return p.id;
end $$;


ALTER FUNCTION public.fin_close_performance(p_period uuid, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_comment_authors(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_comment_authors(p_type text, p_id uuid) RETURNS TABLE(author_id uuid, display_name text, organization_name text, organization_kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct on (c.author_id) c.author_id, m.display_name, o.legal_name, o.kind
    from public.fin_comments c
    join public.fin_members m on m.user_id = c.author_id
    join public.fin_organizations o on o.id = m.organization_id
   where c.object_type = p_type and c.object_id = p_id
     and ((public.fin_has_role(c.organization_id) and public.fin_object_visible(c.organization_id, c.object_type, c.object_id))
          or (c.visibility = 'provider_visible' and public.fin_provider_reads_comment(c.organization_id, c.author_id, c.object_type, c.object_id)))
   order by c.author_id, (m.organization_id = c.organization_id) desc, m.created_at;
$$;


ALTER FUNCTION public.fin_comment_authors(p_type text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_comment_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_comment_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is not null and public.fin_has_role(new.organization_id)
     and not public.fin_object_visible(new.organization_id, new.object_type, new.object_id) then
    raise exception 'forbidden';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_comment_entity_guard() OWNER TO postgres;

--
-- Name: fin_comment_object_org(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_comment_object_org(p_type text, p_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid;
begin
 case p_type
 when 'rfq' then select organization_id into v_org from public.fin_rfqs where id=p_id;
 when 'proposal' then select buyer_organization_id into v_org from public.fin_proposals where id=p_id;
 when 'approval' then select organization_id into v_org from public.fin_approval_requests where id=p_id;
 when 'decision' then select organization_id into v_org from public.fin_decisions where id=p_id;
 when 'contract' then select organization_id into v_org from public.fin_contracts where id=p_id;
 when 'task' then select organization_id into v_org from public.fin_tasks where id=p_id;
 else return null;
 end case;
 return v_org;
end $$;


ALTER FUNCTION public.fin_comment_object_org(p_type text, p_id uuid) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: fin_fee_observations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_fee_observations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    service text NOT NULL,
    service_key text GENERATED ALWAYS AS (lower(btrim(service))) STORED,
    charging_unit text NOT NULL,
    currency text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    volume numeric(24,6),
    base_amount numeric(20,2),
    observed_amount numeric(20,2) NOT NULL,
    source_type text NOT NULL,
    ingestion_channel text DEFAULT 'manual_entry'::text NOT NULL,
    source_reference text NOT NULL,
    source_object_id text,
    evidence_reference text NOT NULL,
    owner_id uuid NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    verification_status text DEFAULT 'unverified'::text NOT NULL,
    verified_by uuid,
    verified_at timestamp with time zone,
    verification_reason text,
    dedupe_key text NOT NULL,
    CONSTRAINT fin_fee_ingestion_channel_check CHECK ((ingestion_channel = ANY (ARRAY['manual_entry'::text, 'structured_file'::text, 'erp_adapter'::text]))),
    CONSTRAINT fin_fee_observations_base_amount_check CHECK (((base_amount IS NULL) OR ((base_amount >= (0)::numeric) AND (base_amount <= ('1000000000000'::bigint)::numeric)))),
    CONSTRAINT fin_fee_observations_charging_unit_check CHECK ((charging_unit = ANY (ARRAY['per_month'::text, 'per_year'::text, 'one_off'::text, 'per_transaction'::text, 'per_item'::text, 'percent_of_volume'::text, 'percent_of_amount'::text]))),
    CONSTRAINT fin_fee_observations_check CHECK (((period_end >= period_start) AND ((period_end - period_start) <= 366))),
    CONSTRAINT fin_fee_observations_check1 CHECK (((verification_status = 'unverified'::text) = ((verified_by IS NULL) AND (verified_at IS NULL) AND (verification_reason IS NULL)))),
    CONSTRAINT fin_fee_observations_currency_check CHECK ((currency = ANY (ARRAY['BRL'::text, 'USD'::text, 'EUR'::text, 'GBP'::text, 'CHF'::text, 'JPY'::text, 'CAD'::text, 'AUD'::text, 'CNY'::text, 'MXN'::text, 'ARS'::text, 'CLP'::text, 'COP'::text, 'PEN'::text]))),
    CONSTRAINT fin_fee_observations_evidence_reference_check CHECK ((((length(TRIM(BOTH FROM evidence_reference)) >= 3) AND (length(TRIM(BOTH FROM evidence_reference)) <= 200)) AND (evidence_reference !~ '[<>]'::text))),
    CONSTRAINT fin_fee_observations_observed_amount_check CHECK (((observed_amount >= (0)::numeric) AND (observed_amount <= ('1000000000000'::bigint)::numeric))),
    CONSTRAINT fin_fee_observations_service_check CHECK ((((length(TRIM(BOTH FROM service)) >= 2) AND (length(TRIM(BOTH FROM service)) <= 120)) AND (service !~ '[<>]'::text))),
    CONSTRAINT fin_fee_observations_source_object_id_check CHECK (((source_object_id IS NULL) OR (((length(TRIM(BOTH FROM source_object_id)) >= 1) AND (length(TRIM(BOTH FROM source_object_id)) <= 200)) AND (source_object_id !~ '[<>]'::text)))),
    CONSTRAINT fin_fee_observations_source_reference_check CHECK ((((length(TRIM(BOTH FROM source_reference)) >= 3) AND (length(TRIM(BOTH FROM source_reference)) <= 200)) AND (source_reference !~ '[<>]'::text))),
    CONSTRAINT fin_fee_observations_source_type_check CHECK ((source_type = ANY (ARRAY['manual'::text, 'bank_statement'::text, 'erp'::text, 'tms'::text, 'bank_file'::text, 'api'::text, 'confirmed_document_extraction'::text, 'other_import'::text]))),
    CONSTRAINT fin_fee_observations_verification_reason_check CHECK (((verification_reason IS NULL) OR (((length(TRIM(BOTH FROM verification_reason)) >= 3) AND (length(TRIM(BOTH FROM verification_reason)) <= 1000)) AND (verification_reason !~ '[<>]'::text)))),
    CONSTRAINT fin_fee_observations_verification_status_check CHECK ((verification_status = ANY (ARRAY['unverified'::text, 'verified'::text, 'rejected'::text]))),
    CONSTRAINT fin_fee_observations_volume_check CHECK (((volume IS NULL) OR ((volume >= (0)::numeric) AND (volume <= ('1000000000000'::bigint)::numeric))))
);

ALTER TABLE ONLY public.fin_fee_observations FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_fee_observations OWNER TO postgres;

--
-- Name: fin_fee_variances; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_fee_variances (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    schedule_id uuid,
    schedule_version integer,
    contract_id uuid NOT NULL,
    contract_version integer,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    category text,
    service text NOT NULL,
    currency text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    comparison_status text NOT NULL,
    reasons text[] DEFAULT '{}'::text[] NOT NULL,
    contracted_amount numeric(20,2),
    observed_amount numeric(20,2) NOT NULL,
    variance_amount numeric(20,2),
    direction text,
    methodology jsonb NOT NULL,
    reference_snapshot jsonb,
    review_status text NOT NULL,
    reviewer_id uuid,
    last_reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_fee_variances_check CHECK (((comparison_status = 'comparable'::text) = (contracted_amount IS NOT NULL))),
    CONSTRAINT fin_fee_variances_check1 CHECK (((comparison_status = 'comparable'::text) = (variance_amount IS NOT NULL))),
    CONSTRAINT fin_fee_variances_check2 CHECK (((comparison_status = 'comparable'::text) = (direction IS NOT NULL))),
    CONSTRAINT fin_fee_variances_check3 CHECK (((comparison_status <> 'missing_reference'::text) OR (schedule_id IS NULL))),
    CONSTRAINT fin_fee_variances_check4 CHECK (((comparison_status = 'comparable'::text) OR (cardinality(reasons) > 0))),
    CONSTRAINT fin_fee_variances_check5 CHECK (((review_status = 'not_required'::text) = (NOT (direction IS DISTINCT FROM 'equal'::text)))),
    CONSTRAINT fin_fee_variances_comparison_status_check CHECK ((comparison_status = ANY (ARRAY['comparable'::text, 'not_comparable'::text, 'missing_reference'::text]))),
    CONSTRAINT fin_fee_variances_direction_check CHECK ((direction = ANY (ARRAY['above'::text, 'below'::text, 'equal'::text]))),
    CONSTRAINT fin_fee_variances_review_status_check CHECK ((review_status = ANY (ARRAY['not_required'::text, 'new'::text, 'under_review'::text, 'confirmed'::text, 'explained'::text, 'dismissed'::text, 'resolved'::text])))
);

ALTER TABLE ONLY public.fin_fee_variances FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_fee_variances OWNER TO postgres;

--
-- Name: fin_compare_fee(public.fin_fee_observations); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_compare_fee(x public.fin_fee_observations) RETURNS public.fin_fee_variances
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare r public.fin_fee_variances; s public.fin_fee_schedules%rowtype; v public.fin_fee_schedule_versions%rowtype;
  v_reasons text[] := '{}'; v_expected numeric; v_months integer; v_formula text; v_left numeric; v_prev numeric := 0; t jsonb; v_band numeric;
begin
  r.id := gen_random_uuid(); r.organization_id := x.organization_id; r.observation_id := x.id; r.contract_id := x.contract_id;
  r.legal_entity_id := x.legal_entity_id; r.provider_id := x.provider_id; r.service := x.service; r.currency := x.currency;
  r.period_start := x.period_start; r.period_end := x.period_end; r.observed_amount := x.observed_amount; r.created_at := now(); r.reasons := '{}';
  select * into s from public.fin_fee_schedules where contract_id = x.contract_id and service_key = x.service_key and charging_unit = x.charging_unit;
  if s.id is null then
    select * into s from public.fin_fee_schedules where contract_id = x.contract_id and service_key = x.service_key order by created_at, id limit 1;
    if s.id is null then
      r.comparison_status := 'missing_reference'; r.reasons := array['missing_contracted_reference']; r.review_status := 'new';
      r.methodology := jsonb_build_object('version', 1, 'formula', null, 'note', 'No contracted fee reference for this contract and service');
      return r;
    end if;
    v_reasons := v_reasons || 'charging_unit_mismatch'::text;
  end if;
  r.schedule_id := s.id; r.category := s.category;
  select * into v from public.fin_fee_schedule_versions where schedule_id = s.id and effective_from <= x.period_start order by effective_from desc, version desc limit 1;
  if v.schedule_id is null then
    v_reasons := v_reasons || 'no_reference_for_period'::text;
  else
    r.schedule_version := v.version; r.contract_version := v.contract_version;
    r.reference_snapshot := jsonb_build_object('schedule_id', s.id, 'version', v.version, 'contract_version', v.contract_version, 'effective_from', v.effective_from,
      'pricing_model', v.pricing_model, 'charging_unit', s.charging_unit, 'currency', v.currency, 'rate', v.rate, 'tiers', v.tiers,
      'minimum_amount', v.minimum_amount, 'maximum_amount', v.maximum_amount, 'source', v.source, 'source_reference', v.source_reference);
    if exists (select 1 from public.fin_fee_schedule_versions w where w.schedule_id = s.id and w.effective_from > x.period_start and w.effective_from <= x.period_end) then
      v_reasons := v_reasons || 'reference_changed_in_period'::text;
    end if;
    if v.currency <> x.currency then v_reasons := v_reasons || 'currency_mismatch'::text; end if;
    if v.pricing_model in ('per_unit','tiered_per_unit') and x.volume is null then v_reasons := v_reasons || 'missing_volume'::text; end if;
    if v.pricing_model in ('percentage','basis_points') and x.base_amount is null then v_reasons := v_reasons || 'missing_base_amount'::text; end if;
    -- Calendar-month normalization only: no pro-rata by days is assumed.
    v_months := case when x.period_start = date_trunc('month', x.period_start)::date
                      and x.period_end = (date_trunc('month', x.period_end) + interval '1 month - 1 day')::date
                     then (extract(year from x.period_end)::integer * 12 + extract(month from x.period_end)::integer)
                        - (extract(year from x.period_start)::integer * 12 + extract(month from x.period_start)::integer) + 1 end;
    if v.pricing_model = 'fixed_amount' and ((s.charging_unit = 'per_month' and v_months is null) or (s.charging_unit = 'per_year' and (v_months is null or v_months % 12 <> 0))) then
      v_reasons := v_reasons || 'period_not_normalizable'::text;
    end if;
    if (v.minimum_amount is not null or v.maximum_amount is not null) and v_months is distinct from 1 then
      v_reasons := v_reasons || 'minimum_maximum_requires_single_month'::text;
    end if;
  end if;
  if cardinality(v_reasons) > 0 then
    r.comparison_status := 'not_comparable'; r.reasons := v_reasons; r.review_status := 'new';
    r.methodology := jsonb_build_object('version', 1, 'formula', null, 'note', 'Not economically comparable; no variance is computed');
    return r;
  end if;
  if v.pricing_model = 'fixed_amount' then
    v_expected := case s.charging_unit when 'one_off' then v.rate when 'per_month' then v.rate * v_months else v.rate * v_months / 12 end;
    v_formula := case s.charging_unit when 'one_off' then 'rate' when 'per_month' then 'rate * calendar_months' else 'rate * calendar_months / 12' end;
  elsif v.pricing_model = 'per_unit' then
    v_expected := v.rate * x.volume; v_formula := 'rate * volume';
  elsif v.pricing_model = 'percentage' then
    v_expected := v.rate / 100 * x.base_amount; v_formula := 'rate_percent / 100 * base_amount';
  elsif v.pricing_model = 'basis_points' then
    v_expected := v.rate / 10000 * x.base_amount; v_formula := 'rate_bps / 10000 * base_amount';
  else
    v_expected := 0; v_left := x.volume;
    for t in select value from jsonb_array_elements(v.tiers) loop
      v_band := case when t->'up_to' = 'null'::jsonb then v_left else least(v_left, (t->>'up_to')::numeric - v_prev) end;
      v_expected := v_expected + greatest(v_band, 0) * (t->>'rate')::numeric;
      v_left := v_left - greatest(v_band, 0);
      exit when t->'up_to' = 'null'::jsonb or v_left <= 0;
      v_prev := (t->>'up_to')::numeric;
    end loop;
    v_formula := 'sum(units_in_tier * tier_rate), graduated tiers';
  end if;
  if v.minimum_amount is not null then v_expected := greatest(v_expected, v.minimum_amount); v_formula := v_formula || ', floored at monthly minimum'; end if;
  if v.maximum_amount is not null then v_expected := least(v_expected, v.maximum_amount); v_formula := v_formula || ', capped at monthly maximum'; end if;
  r.comparison_status := 'comparable';
  r.contracted_amount := round(v_expected, 2);
  r.variance_amount := round(x.observed_amount - round(v_expected, 2), 2);
  r.direction := case when r.variance_amount > 0 then 'above' when r.variance_amount < 0 then 'below' else 'equal' end;
  r.review_status := case when r.direction = 'equal' then 'not_required' else 'new' end;
  r.methodology := jsonb_build_object('version', 1, 'formula', 'observed_amount - contracted_reference', 'reference_formula', v_formula,
    'rounding', '2 decimal places', 'inputs', jsonb_build_object('volume', x.volume, 'base_amount', x.base_amount, 'calendar_months', v_months, 'observed_amount', x.observed_amount),
    'note', 'Difference against the contracted reference; interpretation requires human review');
  return r;
end $$;


ALTER FUNCTION public.fin_compare_fee(x public.fin_fee_observations) OWNER TO postgres;

--
-- Name: fin_complete_opportunity_negotiation(uuid, text, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_complete_opportunity_negotiation(p_id uuid, p_expected text, p_decision uuid, p_confirmed boolean, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_opportunities%rowtype; d public.fin_decisions%rowtype;
begin
 select * into o from public.fin_opportunities where id=p_id for update;
 if o.id is null or auth.uid() is null then raise exception 'forbidden'; end if;
 perform public.fin_contract_import_actor(o.organization_id,o.legal_entity_id,array['admin','finance_manager']);
 if p_expected is null or p_expected not in ('acknowledged','under_review') or p_confirmed is not true or length(trim(coalesce(p_resolution,''))) not between 3 and 1000 or p_resolution ~ '[<>]' then raise exception 'opportunity result confirmation required'; end if;
 select * into d from public.fin_decisions where id=p_decision and organization_id=o.organization_id and rfq_id=o.linked_rfq_id;
 if d.id is null or not public.fin_rfq_visible(d.rfq_id) then raise exception 'opportunity result unavailable'; end if;
 if o.status='acted' and o.resolution=trim(p_resolution) and exists(select 1 from public.fin_events where organization_id=o.organization_id and entity_type='opportunity' and entity_id=o.id and event_type='opportunity_negotiation_completed' and metadata->>'decision_id'=d.id::text) then
   return jsonb_build_object('status','acted','decision_id',d.id,'replayed',true);
 end if;
 perform public.fin_transition_opportunity(o.id,p_expected,jsonb_build_object('to_status','acted','resolution',p_resolution));
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(o.organization_id,'opportunity',o.id,'opportunity_negotiation_completed',auth.uid(),jsonb_build_object('rfq_id',d.rfq_id,'decision_id',d.id));
 return jsonb_build_object('status','acted','decision_id',d.id,'replayed',false);
end $$;


ALTER FUNCTION public.fin_complete_opportunity_negotiation(p_id uuid, p_expected text, p_decision uuid, p_confirmed boolean, p_resolution text) OWNER TO postgres;

--
-- Name: fin_configure_fee_integration(uuid, uuid, uuid, integer, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_configure_fee_integration(p_org uuid, p_id uuid, p_contract uuid, p_expected integer, p_request uuid, p_settings jsonb, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare c public.fin_contracts%rowtype; previous jsonb; receipt jsonb; result jsonb; request_hash text; k text;
begin
 if p_org is null or p_id is null or p_contract is null or p_request is null or p_expected is null or p_expected<0 or p_status is null or p_status not in ('configured','suspended','revoked') then raise exception 'invalid fee integration';end if;
 select * into c from public.fin_contracts where organization_id=p_org and id=p_contract for share;
 if c.id is null or not public.fin_has_role(p_org,array['admin']) then raise exception 'forbidden';end if;
 perform public.fin_crm_actor(p_org,c.legal_entity_id,auth.uid());
 if not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden';end if;
 perform pg_advisory_xact_lock(hashtextextended('fee-ingestion:'||p_org::text,0));
 if not public.fin_has_role(p_org,array['admin']) then raise exception 'forbidden';end if;
 if jsonb_typeof(p_settings) is distinct from 'object' or length(p_settings::text)>2000 or p_settings::text ~ '[<>]' or exists(select 1 from jsonb_object_keys(p_settings) x where x not in ('tenant_id','environment','company_id','account_id','currency','service','charging_unit')) then raise exception 'invalid fee integration';end if;
 if exists(select 1 from jsonb_each(p_settings) x where jsonb_typeof(x.value) is distinct from 'string') or (p_settings->>'service') ~ '[[:cntrl:]]' then raise exception 'invalid fee integration';end if;
 foreach k in array array['tenant_id','company_id','account_id'] loop
  if jsonb_typeof(p_settings->k) is distinct from 'string' or (p_settings->>k) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'invalid fee integration';end if;
 end loop;
 if coalesce(p_settings->>'environment','') !~ '^[A-Za-z0-9_-]{1,60}$' or coalesce(p_settings->>'currency','') not in ('BRL','USD','EUR','GBP','CHF','JPY','CAD','AUD','CNY','MXN','ARS','CLP','COP','PEN') or length(trim(coalesce(p_settings->>'service',''))) not between 2 and 120
 or coalesce(p_settings->>'charging_unit','') not in ('per_transaction','per_item','per_month','per_year','percent_of_volume','percent_of_amount','one_off') then raise exception 'invalid fee integration';end if;
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_id,p_contract,p_expected,p_settings,p_status)::text,'UTF8')),'hex');
 select e.metadata into receipt from public.fin_events e where e.organization_id=p_org and e.actor_id=auth.uid() and e.event_type='fee_integration_configured' and e.metadata->>'request_key'=p_request::text limit 1;
 if receipt is not null then
  if receipt->>'input_hash' is distinct from request_hash then raise exception 'fee import request conflict';end if;
  return receipt||jsonb_build_object('replayed',true);
 end if;
 previous:=public.fin_fee_integration(p_org,p_id);
 if previous is null and (p_expected<>0 or p_status<>'configured') or previous is not null and ((previous->>'version')::integer<>p_expected or previous->>'contract_id'<>p_contract::text or previous->>'status'='revoked') then raise exception 'fee integration version conflict';end if;
 result:=jsonb_build_object('id',p_id,'contract_id',p_contract,'version',p_expected+1,'status',p_status,'settings',p_settings,'request_key',p_request,'input_hash',request_hash,'adapter','dynamics-business-central-v2','connection_state','not_tested');
 insert into public.fin_events(organization_id,legal_entity_id,entity_type,entity_id,event_type,actor_id,metadata,happened_at) values(p_org,c.legal_entity_id,'fee_integration',p_id,'fee_integration_configured',auth.uid(),result,clock_timestamp());
 return result||jsonb_build_object('replayed',false);
end $_$;


ALTER FUNCTION public.fin_configure_fee_integration(p_org uuid, p_id uuid, p_contract uuid, p_expected integer, p_request uuid, p_settings jsonb, p_status text) OWNER TO postgres;

--
-- Name: fin_confirm_facility(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_confirm_facility(p_facility uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_facilities%rowtype; v_now timestamptz := now();
begin
  select * into v from public.fin_facilities where id = p_facility for update;
  if not found or not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'facility not found'; end if;
  update public.fin_facilities set verified_at = v_now, updated_at = v_now where id = p_facility;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'facility', v.id, 'facility_confirmed', auth.uid(), '{}'::jsonb, v.legal_entity_id);
  return v_now;
end $$;


ALTER FUNCTION public.fin_confirm_facility(p_facility uuid) OWNER TO postgres;

--
-- Name: fin_contract_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    -- Contrato nasce na entidade da RFQ que o originou.
    if new.legal_entity_id is null then
      select r.legal_entity_id into new.legal_entity_id
        from public.fin_decisions d join public.fin_rfqs r on r.id = d.rfq_id where d.id = new.decision_id;
    end if;
    perform public.fin_assert_entity_write(new.organization_id, new.legal_entity_id);
  else
    perform public.fin_assert_entity_write(old.organization_id, old.legal_entity_id);
    if new.legal_entity_id is distinct from old.legal_entity_id then
      if coalesce(current_setting('arandu.entity_change', true), '') <> 'on' then raise exception 'legal entity change requires rpc'; end if;
      perform public.fin_assert_entity_write(new.organization_id, new.legal_entity_id);
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_contract_entity_guard() OWNER TO postgres;

--
-- Name: fin_contracts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    decision_id uuid,
    proposal_id uuid,
    provider_id uuid NOT NULL,
    product text NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    renewal_notice_days integer DEFAULT 60 NOT NULL,
    auto_renew boolean DEFAULT false NOT NULL,
    cost_summary text,
    main_conditions text,
    document_reference text,
    owner_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    legal_entity_id uuid,
    origin text DEFAULT 'sourcing'::text NOT NULL,
    parent_contract_id uuid,
    title text,
    currency text DEFAULT 'BRL'::text NOT NULL,
    current_version integer DEFAULT 0 NOT NULL,
    terms_updated_at timestamp with time zone,
    external_proposal_id uuid,
    external_proposal_version integer,
    external_request_key text,
    external_request_hash text,
    import_request_key uuid,
    import_request_hash text,
    import_actor_id uuid,
    CONSTRAINT contract_external_source CHECK ((((external_proposal_id IS NULL) AND (external_proposal_version IS NULL) AND (external_request_key IS NULL) AND (external_request_hash IS NULL)) OR ((origin = 'imported'::text) AND (proposal_id IS NULL) AND (decision_id IS NOT NULL) AND (external_proposal_id IS NOT NULL) AND (external_proposal_version IS NOT NULL) AND (external_proposal_version > 0) AND (external_request_key IS NOT NULL) AND (external_request_hash IS NOT NULL)))),
    CONSTRAINT fin_contracts_check CHECK ((ends_on >= starts_on)),
    CONSTRAINT fin_contracts_cost_summary_check CHECK (((cost_summary IS NULL) OR (length(cost_summary) <= 1000))),
    CONSTRAINT fin_contracts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fin_contracts_document_reference_check CHECK (((document_reference IS NULL) OR (document_reference ~ '^https://'::text))),
    CONSTRAINT fin_contracts_import_receipt CHECK ((((import_request_key IS NULL) AND (import_request_hash IS NULL) AND (import_actor_id IS NULL)) OR ((origin = 'imported'::text) AND (import_request_key IS NOT NULL) AND (import_request_hash IS NOT NULL) AND (import_request_hash ~ '^[a-f0-9]{64}$'::text) AND (import_actor_id IS NOT NULL)))),
    CONSTRAINT fin_contracts_main_conditions_check CHECK (((main_conditions IS NULL) OR (length(main_conditions) <= 4000))),
    CONSTRAINT fin_contracts_not_own_parent CHECK (((parent_contract_id IS NULL) OR (parent_contract_id <> id))),
    CONSTRAINT fin_contracts_origin_check CHECK ((origin = ANY (ARRAY['sourcing'::text, 'imported'::text]))),
    CONSTRAINT fin_contracts_product_check CHECK (((product = ANY (ARRAY['credit'::text, 'acquiring'::text])) OR ((origin = 'imported'::text) AND (product = ANY (ARRAY['cash_management'::text, 'guarantee'::text, 'fx'::text, 'insurance'::text, 'other'::text]))))),
    CONSTRAINT fin_contracts_renewal_notice_days_check CHECK (((renewal_notice_days >= 0) AND (renewal_notice_days <= 3650))),
    CONSTRAINT fin_contracts_sourcing_origin CHECK (((origin = 'imported'::text) OR ((decision_id IS NOT NULL) AND (proposal_id IS NOT NULL)))),
    CONSTRAINT fin_contracts_status_check CHECK ((status = ANY (ARRAY['active'::text, 'renewing'::text, 'expired'::text, 'terminated'::text]))),
    CONSTRAINT fin_contracts_title_check CHECK (((title IS NULL) OR (((length(TRIM(BOTH FROM title)) >= 2) AND (length(TRIM(BOTH FROM title)) <= 200)) AND (title !~ '[<>]'::text)))),
    CONSTRAINT fin_contracts_version_check CHECK ((current_version >= 0))
);

ALTER TABLE ONLY public.fin_contracts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_contracts OWNER TO postgres;

--
-- Name: fin_contract_for_write(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_for_write(p_contract uuid) RETURNS public.fin_contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_contracts%rowtype;
begin
  select * into v from public.fin_contracts where id = p_contract for update;
  if not found then raise exception 'contract not found'; end if;
  if not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  return v;
end $$;


ALTER FUNCTION public.fin_contract_for_write(p_contract uuid) OWNER TO postgres;

--
-- Name: fin_contract_import_actor(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_import_actor(p_org uuid, p_entity uuid, p_roles text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if auth.uid() is null then raise exception 'forbidden'; end if;
 perform 1 from public.fin_members where organization_id=p_org and user_id=auth.uid() for share;
 perform 1 from public.fin_member_entity_grants where organization_id=p_org and user_id=auth.uid() for share;
 if not public.fin_entity_allows(p_org,p_entity,p_roles) or not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden'; end if;
 if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
end $$;


ALTER FUNCTION public.fin_contract_import_actor(p_org uuid, p_entity uuid, p_roles text[]) OWNER TO postgres;

--
-- Name: fin_contract_import_receipt_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_import_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if old.import_request_key is not null and (new.import_request_key,new.import_request_hash,new.import_actor_id,new.organization_id)
 is distinct from (old.import_request_key,old.import_request_hash,old.import_actor_id,old.organization_id) then raise exception 'immutable record'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_contract_import_receipt_guard() OWNER TO postgres;

--
-- Name: fin_contract_import_result(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_import_result(p_org uuid, p_entity uuid, p_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype;
begin
 perform public.fin_contract_import_actor(p_org,p_entity,array['admin','finance_manager','analyst','viewer']);
 if p_key is null then raise exception 'invalid request key'; end if;
 if not pg_try_advisory_xact_lock(hashtextextended('contract-import:'||p_org||':'||auth.uid()||':'||p_key,0)) then return jsonb_build_object('state','pending','id',null); end if;
 select * into c from public.fin_contracts where organization_id=p_org and import_actor_id=auth.uid() and import_request_key=p_key
  and legal_entity_id is not distinct from p_entity and public.fin_entity_visible(p_org,legal_entity_id);
 if c.id is null then return jsonb_build_object('state','unconfirmed','id',null); end if;
 return jsonb_build_object('state','confirmed','id',c.id,'creation_version',1,'current_version',c.current_version,'owner_id',c.owner_id,
  'owner_eligible',public.fin_approval_member_eligible(p_org,c.legal_entity_id,c.owner_id,array['admin','finance_manager','analyst'],'any')
    and exists(select 1 from auth.users where id=c.owner_id and (banned_until is null or banned_until<=now())));
end $$;


ALTER FUNCTION public.fin_contract_import_result(p_org uuid, p_entity uuid, p_key uuid) OWNER TO postgres;

--
-- Name: fin_contract_owner_eligible(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_owner_eligible(p_org uuid, p_entity uuid, p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 perform 1 from public.fin_members where organization_id=p_org and user_id=p_owner for share;
 perform 1 from public.fin_member_entity_grants where organization_id=p_org and user_id=p_owner for share;
 perform 1 from auth.users where id=p_owner for share;
 if p_owner is null or not public.fin_approval_member_eligible(p_org,p_entity,p_owner,array['admin','finance_manager','analyst'],'any')
 or not exists(select 1 from auth.users where id=p_owner and (banned_until is null or banned_until<=now())) then raise exception 'invalid task assignee'; end if;
end $$;


ALTER FUNCTION public.fin_contract_owner_eligible(p_org uuid, p_entity uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_contract_visible(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_contract_visible(p_contract uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.fin_contracts c where c.id = p_contract and public.fin_entity_visible(c.organization_id, c.legal_entity_id));
$$;


ALTER FUNCTION public.fin_contract_visible(p_contract uuid) OWNER TO postgres;

--
-- Name: fin_covenant_waiver(uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_covenant_waiver(p_period uuid, p_waiver uuid, p_expected integer, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype;w public.fin_covenant_waivers%rowtype;v_id uuid;begin
 o:=public.fin_obligation_require(p_period,case when p_waiver is null then array['admin','finance_manager','analyst'] else array['admin','finance_manager'] end);
 if p_input is null or jsonb_typeof(p_input)<>'object' then raise exception 'invalid obligation input';end if;
 if p_waiver is null then
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('valid_until','reason','controls')) then raise exception 'invalid obligation input';end if;
 if (p_input->>'valid_until')::date<current_date or (p_input->>'valid_until')::date>current_date+366 then raise exception 'invalid waiver validity';end if;
 insert into public.fin_covenant_waivers(organization_id,period_id,valid_until,reason,controls,requested_by) values(o.organization_id,p_period,(p_input->>'valid_until')::date,trim(p_input->>'reason'),trim(p_input->>'controls'),auth.uid()) returning id into v_id;
 else
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('status','decision_reason')) or p_input->>'status' not in ('approved','rejected') then raise exception 'invalid obligation input';end if;
 select * into w from public.fin_covenant_waivers where id=p_waiver and period_id=p_period for update;
 if w.id is null then raise exception 'forbidden';end if;
 if p_expected is null or w.version<>p_expected then raise exception 'obligation conflict';end if;
 if w.status<>'requested' or w.valid_until<current_date then raise exception 'waiver closed';end if;
 if w.requested_by=auth.uid() then raise exception 'waiver independent reviewer required';end if;
 update public.fin_covenant_waivers set status=p_input->>'status',decision_reason=trim(p_input->>'decision_reason'),decided_by=auth.uid(),decided_at=clock_timestamp(),version=version+1 where id=w.id;v_id:=w.id;
 end if;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(o.organization_id,'contract',o.contract_id,'obligation_waiver_changed',auth.uid(),o.legal_entity_id,jsonb_build_object('period_id',p_period,'waiver_id',v_id));return v_id;
end $$;


ALTER FUNCTION public.fin_covenant_waiver(p_period uuid, p_waiver uuid, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_create_contract_milestone(uuid, text, text, date, integer, text, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_contract_milestone(p_contract uuid, p_kind text, p_title text, p_due_on date, p_lead_days integer DEFAULT 30, p_recurrence text DEFAULT 'none'::text, p_ends_after date DEFAULT NULL::date, p_owner uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_contracts%rowtype; v_id uuid;
begin
  v := public.fin_contract_for_write(p_contract);
  if p_owner is not null and not exists (select 1 from public.fin_members m where m.organization_id = v.organization_id and m.user_id = p_owner) then
    raise exception 'invalid owner';
  end if;
  if p_due_on is null or (p_ends_after is not null and p_ends_after < p_due_on) then raise exception 'invalid period'; end if;
  insert into public.fin_contract_milestones(organization_id, contract_id, kind, title, due_on, lead_days, recurrence, ends_after, owner_id, created_by)
    values (v.organization_id, v.id, p_kind, trim(p_title), p_due_on, coalesce(p_lead_days, 30), coalesce(p_recurrence, 'none'), p_ends_after,
      coalesce(p_owner, v.owner_id), auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v.organization_id, 'contract', v.id, 'contract_milestone_created', auth.uid(), jsonb_build_object('milestone_id', v_id, 'kind', p_kind, 'recurrence', p_recurrence));
  return v_id;
exception when check_violation then raise exception 'invalid milestone';
end $$;


ALTER FUNCTION public.fin_create_contract_milestone(p_contract uuid, p_kind text, p_title text, p_due_on date, p_lead_days integer, p_recurrence text, p_ends_after date, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_create_fee_schedule(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_fee_schedule(p_org uuid, p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype; s public.fin_fee_schedules%rowtype;
begin
  select * into c from public.fin_contracts where organization_id = p_org and id = p_contract for share;
  if c.id is null or auth.uid() is null or not public.fin_entity_allows(p_org, c.legal_entity_id, array['admin','finance_manager'])
     or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or length(p_input::text) > 6000 then raise exception 'invalid fee schedule'; end if;
  if exists (select 1 from public.fin_fee_schedules where contract_id = c.id and service_key = lower(btrim(coalesce(p_input->>'service', ''))) and charging_unit = p_input->>'charging_unit') then
    raise exception 'fee schedule already exists';
  end if;
  begin
    insert into public.fin_fee_schedules(organization_id, contract_id, legal_entity_id, provider_id, service, category, charging_unit, owner_id)
    values (p_org, c.id, c.legal_entity_id, c.provider_id, trim(p_input->>'service'), p_input->>'category', p_input->>'charging_unit', auth.uid())
    returning * into s;
  exception when check_violation or not_null_violation then raise exception 'invalid fee schedule';
  end;
  perform public.fin_insert_fee_version(s, p_input, 1);
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'contract', c.id, 'fee_schedule_created', auth.uid(), jsonb_build_object('schedule_id', s.id, 'version', 1, 'category', s.category));
  return s.id;
end $$;


ALTER FUNCTION public.fin_create_fee_schedule(p_org uuid, p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_create_legal_entity(uuid, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_legal_entity(p_org uuid, p_kind text, p_legal_name text, p_short_name text DEFAULT NULL::text, p_tax_identifier text DEFAULT NULL::text, p_country text DEFAULT 'BR'::text, p_currency text DEFAULT 'BRL'::text, p_parent uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if p_kind not in ('legal_entity','business_unit') then raise exception 'invalid legal entity'; end if;
  if p_kind = 'business_unit' and not exists (select 1 from public.fin_legal_entities e
       where e.organization_id = p_org and e.id = p_parent and e.kind = 'legal_entity' and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  if p_kind = 'legal_entity' and p_parent is not null then raise exception 'invalid legal entity'; end if;
  if p_tax_identifier is not null and p_tax_identifier !~ '^[0-9]{14}$' then raise exception 'invalid tax identifier'; end if;
  if exists (select 1 from public.fin_legal_entities e where e.organization_id = p_org and e.tax_identifier = p_tax_identifier) then
    raise exception 'legal entity conflict';
  end if;
  insert into public.fin_legal_entities(organization_id, kind, parent_id, legal_name, short_name, tax_identifier, country, currency, created_by)
  values (p_org, p_kind, p_parent, trim(p_legal_name), nullif(trim(coalesce(p_short_name,'')),''), p_tax_identifier,
          upper(coalesce(p_country,'BR')), upper(coalesce(p_currency,'BRL')), auth.uid())
  returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
  values (p_org, 'legal_entity', v_id, 'legal_entity_created', auth.uid(), jsonb_build_object('kind', p_kind), v_id);
  return v_id;
exception when check_violation then raise exception 'invalid legal entity';
end $_$;


ALTER FUNCTION public.fin_create_legal_entity(p_org uuid, p_kind text, p_legal_name text, p_short_name text, p_tax_identifier text, p_country text, p_currency text, p_parent uuid) OWNER TO postgres;

--
-- Name: fin_create_organization(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_organization(p_name text, p_kind text, p_country text DEFAULT 'BR'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid; v_email text;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select lower(email) into v_email from auth.users where id = auth.uid();
  if not public.fin_pilot_access_allowed(coalesce(v_email, '')) then
    raise exception 'pilot access not allowed';
  end if;
  if length(trim(coalesce(p_name,''))) not between 2 and 200
     or p_kind not in ('BUYER','PROVIDER')
     or coalesce(p_country,'') !~ '^[A-Z]{2}$' then
    raise exception 'invalid organization';
  end if;
  insert into public.fin_organizations (legal_name, kind, country, created_by)
    values (trim(p_name), p_kind, p_country, auth.uid()) returning id into v_id;
  insert into public.fin_members (organization_id, user_id, role) values (v_id, auth.uid(), 'admin');
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_id, 'organization', v_id, 'organization_created', auth.uid(), jsonb_build_object('kind', p_kind));
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (v_id, 'organization', v_id,
            case when p_kind = 'BUYER' then 'buyer_onboarded' else 'provider_onboarded' end, auth.uid());
  return v_id;
end $_$;


ALTER FUNCTION public.fin_create_organization(p_name text, p_kind text, p_country text) OWNER TO postgres;

--
-- Name: fin_create_provider_intent(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_provider_intent(p_org uuid, p_key uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v jsonb; h text; r public.fin_providers%rowtype; products text[]; k text;
begin
 if p_key is not null then
  perform pg_advisory_xact_lock(hashtextextended('provider-create:'||p_org||':'||auth.uid()||':'||p_key,0));
 end if;
 perform public.fin_provider_intent_actor(p_org,true);
 if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>20000
 or exists(select 1 from jsonb_object_keys(p_input) key where key not in
 ('name','kind','website','contact_name','contact_email','contact_phone','region','notes','products')) then raise exception 'invalid provider'; end if;
 if exists(select 1 from jsonb_each(p_input) e where e.key<>'products' and jsonb_typeof(e.value) not in ('string','null')) then raise exception 'invalid provider'; end if;
 v:=jsonb_build_object('name',btrim(p_input->>'name'),'kind',btrim(p_input->>'kind'));
 foreach k in array array['website','contact_name','contact_email','contact_phone','region','notes'] loop
  v:=v||jsonb_build_object(k,nullif(btrim(p_input->>k),''));
 end loop;
 v:=v||jsonb_build_object('contact_email',lower(v->>'contact_email'));
 if jsonb_typeof(coalesce(p_input->'products','[]'::jsonb))<>'array'
 or jsonb_array_length(coalesce(p_input->'products','[]'::jsonb))>10
 or exists(select 1 from jsonb_array_elements(coalesce(p_input->'products','[]'::jsonb)) e where jsonb_typeof(e)<>'string') then raise exception 'invalid provider'; end if;
 select coalesce(array_agg(btrim(x) order by ord),'{}') into products
 from jsonb_array_elements_text(coalesce(p_input->'products','[]'::jsonb)) with ordinality as a(x,ord) where btrim(x)<>'';
 if exists(select 1 from unnest(products) x where length(x)>60)
 or length(v->>'name') not between 2 and 200 or v->>'name' is null
 or coalesce(v->>'kind','') not in ('bank','fintech','acquirer','subacquirer','credit_provider','payment_provider','other')
 or (v->>'website' is not null and v->>'website' !~ '^https://')
 or length(v->>'contact_name')>200 or length(v->>'contact_email')>254
 or (v->>'contact_email' is not null and v->>'contact_email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')
 or length(v->>'contact_phone')>40 or length(v->>'region')>120 or length(v->>'notes')>1000 then raise exception 'invalid provider'; end if;
 v:=v||jsonb_build_object('products',to_jsonb(products));
 h:=encode(sha256(convert_to(jsonb_build_object('organization',p_org,'actor',auth.uid(),'input',v)::text,'UTF8')),'hex');
 if p_key is not null then
  select * into r from public.fin_providers where organization_id=p_org and created_by=auth.uid() and creation_request_key=p_key;
  if r.id is not null then
   if r.creation_request_hash is distinct from h then raise exception 'provider intent conflict'; end if;
   return jsonb_build_object('id',r.id,'replayed',true,'state','confirmed','row',to_jsonb(r)-'creation_request_hash'-'creation_request_key');
  end if;
 end if;
 insert into public.fin_providers(organization_id,name,kind,website,contact_name,contact_email,contact_phone,region,notes,products,created_by,creation_request_key,creation_request_hash)
 values(p_org,v->>'name',v->>'kind',v->>'website',v->>'contact_name',v->>'contact_email',v->>'contact_phone',v->>'region',v->>'notes',products,auth.uid(),p_key,case when p_key is null then null else h end) returning * into r;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(p_org,'provider',r.id,'provider_created',auth.uid(),jsonb_build_object('has_creation_receipt',p_key is not null));
 return jsonb_build_object('id',r.id,'replayed',false,'state','confirmed','row',to_jsonb(r)-'creation_request_hash'-'creation_request_key');
end $_$;


ALTER FUNCTION public.fin_create_provider_intent(p_org uuid, p_key uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_create_rfq(uuid, text, text, text, jsonb, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_rfq(p_org uuid, p_product text, p_title text, p_description text DEFAULT NULL::text, p_demand jsonb DEFAULT '{}'::jsonb, p_deadline date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if not public.fin_has_role(p_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if p_product not in ('credit','acquiring') then raise exception 'invalid product'; end if;
  if jsonb_typeof(coalesce(p_demand,'null'::jsonb)) is distinct from 'object' then raise exception 'invalid demand'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then
    raise exception 'buyer organization required';
  end if;
  insert into public.fin_rfqs (organization_id, product, title, description, demand, response_deadline, owner_id)
    values (p_org, p_product, trim(p_title), p_description, coalesce(p_demand,'{}'::jsonb), p_deadline, auth.uid())
    returning id into v_id;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'rfq', v_id, 'rfq_created', auth.uid(), jsonb_build_object('product', p_product));
  return v_id;
end $$;


ALTER FUNCTION public.fin_create_rfq(p_org uuid, p_product text, p_title text, p_description text, p_demand jsonb, p_deadline date) OWNER TO postgres;

--
-- Name: fin_create_rfq_from_passport(uuid, text, text, text, jsonb, date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_rfq_from_passport(p_org uuid, p_product text, p_title text, p_description text, p_demand jsonb, p_deadline date, p_usage jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_rfq uuid; v_item jsonb; v_key text; v_demand_key text; v_row public.fin_company_profiles%rowtype;
  v_entity uuid; v_org public.fin_organizations%rowtype; v_value text; v_source text; v_due date; v_given text;
begin
  if jsonb_typeof(coalesce(p_usage, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_usage, '[]'::jsonb)) > 10 then
    raise exception 'invalid passport usage';
  end if;
  -- Papel, produto, demanda e tipo de organização: as mesmas regras de fin_create_rfq.
  v_rfq := public.fin_create_rfq(p_org, p_product, p_title, p_description, p_demand, p_deadline);
  select legal_entity_id into v_entity from public.fin_rfqs where id=v_rfq;
  select * into v_org from public.fin_organizations where id = p_org;
  for v_item in select * from jsonb_array_elements(coalesce(p_usage, '[]'::jsonb)) loop
    v_key := v_item->>'field_key';
    v_demand_key := v_item->>'demand_key';
    if v_key is null or v_key !~ '^[a-z][a-z0-9_]{1,48}$' or v_demand_key is null or v_demand_key !~ '^[a-z][a-z0-9_]{1,48}$' then
      raise exception 'invalid passport usage';
    end if;
    if not ((p_product='credit' and (v_demand_key,v_key) in (('annual_revenue','receita_anual'),('sector','sector'),('operating_years','tempo_operacao_anos'),('collateral','garantias_disponiveis'))) or (p_product='acquiring' and (v_demand_key,v_key) in (('monthly_volume','volume_cartoes_mensal'),('average_ticket','ticket_medio'),('current_acquirer','adquirente_atual'),('current_anticipation','antecipacao_atual')))) then raise exception 'invalid passport usage'; end if;
    if v_key = 'sector' then
      -- Campo do cadastro da organização: sem período de revisão.
      if v_org.sector is null then raise exception 'invalid passport usage'; end if;
      v_value := v_org.sector; v_source := 'cadastro_organizacao'; v_due := null;
      v_row := null;
    else
      select * into v_row from public.fin_company_profiles where organization_id = p_org and field_key = v_key
        and (legal_entity_id is not distinct from v_entity or (legal_entity_id is null and public.fin_passport_inheritable(v_key)))
        order by (legal_entity_id is not null) desc limit 1;
      if not found then raise exception 'invalid passport usage'; end if;
      v_value := v_row.field_value; v_source := v_row.source;
      v_due := public.fin_passport_review_due(v_row.updated_at, v_row.verified_at, v_row.review_after_days, v_row.valid_until);
    end if;
    v_given := p_demand->>v_demand_key;
    insert into public.fin_rfq_profile_snapshots(organization_id, rfq_id, legal_entity_id, source_legal_entity_id, original_scope, vintage, field_key, demand_key, field_value, source,
      profile_updated_at, profile_updated_by, verified_at, document_id, review_due_on, freshness, used_as_is, captured_by)
    values (p_org, v_rfq, v_entity, v_row.legal_entity_id, case when v_row.legal_entity_id is null then 'group' else 'entity' end, v_row.updated_at, v_key, v_demand_key, v_value, v_source,
      v_row.updated_at, v_row.updated_by, v_row.verified_at, v_row.document_id, v_due,
      public.fin_passport_freshness(v_due, (now() at time zone 'UTC')::date),
      coalesce(v_given = v_value or public.fin_try_numeric(v_given) = public.fin_try_numeric(v_value), false),
      auth.uid());
  end loop;
  if jsonb_array_length(coalesce(p_usage, '[]'::jsonb)) > 0 then
    insert into public.fin_events(organization_id, legal_entity_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, v_entity, 'rfq', v_rfq, 'rfq_passport_snapshot', auth.uid(), jsonb_build_object('fields', jsonb_array_length(p_usage)));
  end if;
  return v_rfq;
end $_$;


ALTER FUNCTION public.fin_create_rfq_from_passport(p_org uuid, p_product text, p_title text, p_description text, p_demand jsonb, p_deadline date, p_usage jsonb) OWNER TO postgres;

--
-- Name: fin_create_rfq_in_entity(uuid, uuid, text, text, text, jsonb, date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_rfq_in_entity(p_org uuid, p_entity uuid, p_product text, p_title text, p_description text DEFAULT NULL::text, p_demand jsonb DEFAULT '{}'::jsonb, p_deadline date DEFAULT NULL::date, p_usage jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if p_entity is null then raise exception 'invalid legal entity'; end if;
  perform set_config('arandu.legal_entity', p_entity::text, true);
  if p_usage is not null and jsonb_typeof(p_usage) = 'array' and jsonb_array_length(p_usage) > 0 then
    v_id := public.fin_create_rfq_from_passport(p_org, p_product, p_title, p_description, p_demand, p_deadline, p_usage);
  else
    v_id := public.fin_create_rfq(p_org, p_product, p_title, p_description, p_demand, p_deadline);
  end if;
  perform set_config('arandu.legal_entity', '', true);
  return v_id;
end $$;


ALTER FUNCTION public.fin_create_rfq_in_entity(p_org uuid, p_entity uuid, p_product text, p_title text, p_description text, p_demand jsonb, p_deadline date, p_usage jsonb) OWNER TO postgres;

--
-- Name: fin_create_scorecard_template(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_scorecard_template(p_org uuid, p_key text, p_name text, p_criteria jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid; v_version integer; c jsonb; v_keys text[] := '{}';
begin
  if not public.fin_has_role(p_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if jsonb_typeof(p_criteria) <> 'array' or jsonb_array_length(p_criteria) not between 1 and 20 or p_criteria::text ~ '[<>]' then raise exception 'invalid scorecard'; end if;
  for c in select * from jsonb_array_elements(p_criteria) loop
    if coalesce(c->>'key','') !~ '^[a-z][a-z0-9_]{1,40}$' or length(coalesce(c->>'label','')) not between 2 and 120
       or jsonb_typeof(c->'weight') <> 'number' or (c->>'weight')::numeric <= 0 or (c->>'weight')::numeric > 100
       or jsonb_typeof(c->'scale_max') <> 'number' or (c->>'scale_max')::numeric not in (5, 10, 100)
       or (c->>'key') = any(v_keys) then
      raise exception 'invalid scorecard';
    end if;
    v_keys := v_keys || (c->>'key');
  end loop;
  select coalesce(max(version), 0) + 1 into v_version from public.fin_scorecard_templates where organization_id = p_org and template_key = p_key;
  update public.fin_scorecard_templates set status = 'retired' where organization_id = p_org and template_key = p_key and status = 'active';
  insert into public.fin_scorecard_templates(organization_id, template_key, version, name, criteria, created_by)
    values (p_org, p_key, v_version, trim(p_name), p_criteria, auth.uid()) returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'scorecard_template_created', auth.uid(), jsonb_build_object('template_id', v_id, 'version', v_version, 'criteria', jsonb_array_length(p_criteria)));
  return v_id;
exception when check_violation then raise exception 'invalid scorecard';
end $_$;


ALTER FUNCTION public.fin_create_scorecard_template(p_org uuid, p_key text, p_name text, p_criteria jsonb) OWNER TO postgres;

--
-- Name: fin_create_service_account(uuid, text, text, text[], text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_service_account(p_org uuid, p_name text, p_description text, p_scopes text[], p_entity_scope text, p_entities uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; x uuid;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if p_scopes is null or not (p_scopes <@ public.fin_api_scope_catalog()) or cardinality(p_scopes) = 0
     or not public.fin_api_valid_entities(p_org, coalesce(p_entity_scope, ''), p_entities) then
    raise exception 'invalid service account';
  end if;
  insert into public.fin_service_accounts(organization_id, name, description, scopes, entity_scope, created_by)
    values (p_org, trim(p_name), nullif(trim(coalesce(p_description,'')),''), (select array_agg(distinct s order by s) from unnest(p_scopes) s), p_entity_scope, auth.uid())
    returning id into v_id;
  foreach x in array coalesce(p_entities, '{}'::uuid[]) loop
    insert into public.fin_service_account_entities(organization_id, service_account_id, entity_id, granted_by) values (p_org, v_id, x, auth.uid());
  end loop;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'service_account', v_id, 'service_account_created', auth.uid(), jsonb_build_object('scopes', p_scopes, 'entity_scope', p_entity_scope,
            'entities', coalesce(cardinality(p_entities), 0)));
  return v_id;
exception when check_violation then raise exception 'invalid service account';
end $$;


ALTER FUNCTION public.fin_create_service_account(p_org uuid, p_name text, p_description text, p_scopes text[], p_entity_scope text, p_entities uuid[]) OWNER TO postgres;

--
-- Name: fin_create_webhook_endpoint(uuid, text, text[], text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_create_webhook_endpoint(p_org uuid, p_url text, p_events text[], p_secret_ciphertext text, p_description text, p_entities uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if not public.fin_valid_webhook_url(coalesce(p_url, '')) or (p_entities is not null and not public.fin_api_valid_entities(p_org, 'entities', p_entities)) then
    raise exception 'invalid webhook';
  end if;
  if (select count(*) from public.fin_webhook_endpoints where organization_id = p_org and status <> 'disabled') >= 10 then raise exception 'too many webhooks'; end if;
  insert into public.fin_webhook_endpoints(organization_id, url, description, events, entity_ids, secret_ciphertext, created_by_user)
    values (p_org, p_url, nullif(trim(coalesce(p_description,'')),''), (select array_agg(distinct e order by e) from unnest(p_events) e), p_entities, p_secret_ciphertext, auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'webhook_endpoint', v_id, 'webhook_endpoint_created', auth.uid(), jsonb_build_object('events', p_events));
  return v_id;
exception when check_violation or not_null_violation then raise exception 'invalid webhook';
end $$;


ALTER FUNCTION public.fin_create_webhook_endpoint(p_org uuid, p_url text, p_events text[], p_secret_ciphertext text, p_description text, p_entities uuid[]) OWNER TO postgres;

--
-- Name: fin_crm_actor(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_crm_actor(p_org uuid, p_entity uuid, p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k text; roles text[];
begin
 if auth.uid() is null then raise exception 'forbidden'; end if;
 -- Serialize membership/grant revocation with the entire command.
 perform 1 from public.fin_members where organization_id=p_org and user_id in(auth.uid(),p_owner) order by user_id for share;
 perform 1 from public.fin_member_entity_grants where organization_id=p_org and user_id in(auth.uid(),p_owner) order by user_id,entity_id for share;
 perform 1 from auth.users where id in(auth.uid(),p_owner) order by id for share;
 if not exists(select 1 from auth.users where id=auth.uid() and (banned_until is null or banned_until<=now())) then raise exception 'forbidden'; end if;
 select kind into k from public.fin_organizations where id=p_org;
 roles:=case when k='PROVIDER' then array['admin','provider_user'] else array['admin','finance_manager','analyst'] end;
 if not public.fin_entity_allows(p_org,p_entity,roles) or public.fin_governance_org_locked(p_org)
 or k not in ('BUYER','PROVIDER') or k='PROVIDER' and p_entity is not null then raise exception 'forbidden'; end if;
 if p_owner is null or not exists(select 1 from public.fin_members m where m.organization_id=p_org and m.user_id=p_owner and m.role=any(roles)
   and (m.entity_scope='group' or p_entity is not null and exists(select 1 from public.fin_member_entity_grants g join public.fin_legal_entities e on e.organization_id=g.organization_id and (e.id=g.entity_id or e.parent_id=g.entity_id) where g.organization_id=p_org and g.user_id=p_owner and e.id=p_entity)))
 or not exists(select 1 from auth.users where id=p_owner and (banned_until is null or banned_until<=now())) then raise exception 'invalid crm owner'; end if;
end $$;


ALTER FUNCTION public.fin_crm_actor(p_org uuid, p_entity uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_crm_command(uuid, text, uuid, integer, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_crm_command(p_org uuid, p_kind text, p_id uuid, p_expected integer, p_request uuid, p_scope jsonb, p_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare t text; b jsonb; v jsonb; scope jsonb; entity uuid; v_owner uuid; contact public.fin_provider_contacts%rowtype;
 process public.fin_crm_processes%rowtype; org_kind text; cmd_hash text; receipt public.fin_events%rowtype; result jsonb; record_id uuid; next_version integer; allowed text[];
begin
 if p_request is null or coalesce(p_kind,'') not in ('contact','activity','process') or jsonb_typeof(p_values) is distinct from 'object' or p_values='{}'::jsonb or jsonb_typeof(p_scope) is distinct from 'object' then raise exception 'invalid crm'; end if;
 t:=case p_kind when 'contact' then 'fin_provider_contacts' when 'activity' then 'fin_crm_activities' else 'fin_crm_processes' end;
 if p_id is not null then
  execute format('select to_jsonb(r) from public.%I r where r.id=$1 and r.organization_id=$2 for update',t) into b using p_id,p_org;
  if b is null then raise exception 'crm not found'; end if;
  entity:=(b->>'legal_entity_id')::uuid;
 else
  if p_expected is not null or p_scope-array['legal_entity_id','provider_id','counterparty_organization_id']<>'{}'::jsonb then raise exception 'invalid crm'; end if;
  entity:=(p_scope->>'legal_entity_id')::uuid;
 end if;
 v_owner:=coalesce((p_values->>'owner_id')::uuid,(b->>'owner_id')::uuid,auth.uid());
 perform public.fin_crm_actor(p_org,entity,v_owner);
 cmd_hash:=encode(sha256(convert_to(jsonb_build_object('kind',p_kind,'id',p_id,'expected',p_expected,'scope',p_scope,'values',p_values)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended(p_org::text||auth.uid()::text||p_request::text,0));
 select * into receipt from public.fin_events where organization_id=p_org and actor_id=auth.uid() and event_type='crm_command_recorded' and metadata->>'request_key'=p_request::text;
 if receipt.id is not null then
  if receipt.metadata->>'request_hash' is distinct from cmd_hash then raise exception 'crm request conflict'; end if;
  return (receipt.metadata->'result')||jsonb_build_object('replayed',true);
 end if;
 if p_id is not null and (p_expected is null or p_expected<>(b->>'version')::integer or p_scope<>'{}'::jsonb) then raise exception 'crm version conflict'; end if;
 allowed:=case p_kind
 when 'contact' then array['name','title','email','phone','owner_id','source_reference','status']
 when 'activity' then array['kind','subject','notes','occurred_at','due_on','owner_id','source_reference','status','contact_id','process_id','related_type','related_id']
 else array['title','stage','owner_id','due_on','next_action','outcome','source_reference','status','contact_id','related_type','related_id'] end;
 if exists(select 1 from jsonb_each(p_values) where jsonb_typeof(value) not in ('string','null')) then raise exception 'invalid crm'; end if;
 if p_kind<>'contact' and (p_scope->>'provider_id' is not null or p_scope->>'counterparty_organization_id' is not null) then raise exception 'invalid crm scope'; end if;
 if (p_values?'status' and p_values->>'status' is null) or (p_values?'owner_id' and p_values->>'owner_id' is null) then raise exception 'invalid crm'; end if;
 if p_values-allowed<>'{}'::jsonb then raise exception 'invalid crm'; end if;
 record_id:=coalesce(p_id,gen_random_uuid()); next_version:=coalesce((b->>'version')::integer,0)+1;
 v:=coalesce(b,'{}'::jsonb)||p_values||jsonb_build_object('id',record_id,'organization_id',p_org,'legal_entity_id',entity,'owner_id',v_owner,'version',next_version,'visibility','organization_private','updated_at',clock_timestamp());
 if p_id is null then v:=v||jsonb_build_object('created_by',auth.uid(),'created_at',clock_timestamp()); end if;
 if p_id is null and p_kind<>'contact' and not p_values?'status' then v:=v||jsonb_build_object('status',case p_kind when 'activity' then 'recorded' else 'active' end); end if;
 if coalesce(length(trim(v->>'source_reference')),0) not between 2 and 500 or (v->>'source_reference')~'[<>]' then raise exception 'invalid crm source'; end if;
 select kind into org_kind from public.fin_organizations where id=p_org;
 if p_kind='contact' then
  if p_id is null then
   if org_kind='BUYER' and not exists(select 1 from public.fin_providers where organization_id=p_org and id=(p_scope->>'provider_id')::uuid) then raise exception 'invalid crm provider'; end if;
   if org_kind='PROVIDER' and p_scope->>'provider_id' is not null then raise exception 'invalid crm provider'; end if;
   if p_scope->>'counterparty_organization_id' is not null and (org_kind<>'PROVIDER' or not exists(select 1 from public.fin_rfq_invites where provider_organization_id=p_org and buyer_organization_id=(p_scope->>'counterparty_organization_id')::uuid and status='accepted')) then raise exception 'invalid crm counterparty'; end if;
   v:=v||jsonb_build_object('provider_id',(p_scope->>'provider_id')::uuid,'counterparty_organization_id',(p_scope->>'counterparty_organization_id')::uuid,'is_primary',false);
  end if;
  if coalesce(v->>'status','active') not in ('active','archived') then raise exception 'invalid crm status'; end if;
  if p_values?'status' or p_id is null then v:=v||jsonb_build_object('archived_at',case when v->>'status'='archived' then to_jsonb(clock_timestamp()) else 'null'::jsonb end); end if;
  if v->>'archived_at' is not null then v:=v||jsonb_build_object('is_primary',false); end if;
  v:=v-'status';
 else
  if not public.fin_crm_reference_visible(p_org,entity,v->>'related_type',(v->>'related_id')::uuid) then raise exception 'invalid crm reference'; end if;
  if v->>'contact_id' is not null then
   select * into contact from public.fin_provider_contacts where id=(v->>'contact_id')::uuid and organization_id=p_org for share;
   if contact.id is null or contact.archived_at is not null or (contact.legal_entity_id is not null and contact.legal_entity_id is distinct from entity) then raise exception 'invalid crm contact'; end if;
  end if;
  if p_kind='activity' and v->>'process_id' is not null then
   select * into process from public.fin_crm_processes where id=(v->>'process_id')::uuid and organization_id=p_org for share;
   if process.id is null or process.status='archived' or process.legal_entity_id is distinct from entity then raise exception 'invalid crm process'; end if;
  end if;
 end if;
 -- Populate only a compile-time selected table; scope and audit fields were
 -- replaced above and cannot be supplied by the caller.
 if p_id is null then
  execute format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).*',t,t) using v;
 elsif p_kind='contact' then
  update public.fin_provider_contacts set name=v->>'name',title=v->>'title',email=v->>'email',phone=v->>'phone',owner_id=v_owner,source_reference=v->>'source_reference',archived_at=(v->>'archived_at')::timestamptz,is_primary=(v->>'is_primary')::boolean where id=p_id;
 elsif p_kind='process' then
  update public.fin_crm_processes set title=v->>'title',stage=v->>'stage',status=v->>'status',owner_id=(v->>'owner_id')::uuid,due_on=(v->>'due_on')::date,next_action=v->>'next_action',outcome=v->>'outcome',source_reference=v->>'source_reference',contact_id=(v->>'contact_id')::uuid,related_type=v->>'related_type',related_id=(v->>'related_id')::uuid,version=next_version,updated_at=clock_timestamp() where id=p_id;
 else
  update public.fin_crm_activities set kind=v->>'kind',subject=v->>'subject',notes=v->>'notes',status=v->>'status',occurred_at=(v->>'occurred_at')::timestamptz,due_on=(v->>'due_on')::date,owner_id=(v->>'owner_id')::uuid,source_reference=v->>'source_reference',contact_id=(v->>'contact_id')::uuid,process_id=(v->>'process_id')::uuid,related_type=v->>'related_type',related_id=(v->>'related_id')::uuid,version=next_version,updated_at=clock_timestamp() where id=p_id;
 end if;
 result:=jsonb_build_object('id',record_id,'object_type',p_kind,'version',next_version);
 -- Creation receipts contain no copy of user content. Updates preserve only
 -- changed fields, so authorized history can explain corrections. This audit
 -- evidence can contain personal data and follows the object's scope/hold.
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
 values(p_org,'crm_'||p_kind,record_id,'crm_command_recorded',auth.uid(),entity,jsonb_build_object('request_key',p_request,'request_hash',cmd_hash,'result',result,'changed_fields',(select jsonb_agg(key) from jsonb_object_keys(p_values) key),
 'changes',case when p_id is null then null else (select jsonb_object_agg(key,jsonb_build_object('before',case when p_kind='contact' and key='status' then to_jsonb(case when b->>'archived_at' is null then 'active'::text else 'archived'::text end) else b->key end,'after',case when p_kind='contact' and key='status' then to_jsonb(case when v->>'archived_at' is null then 'active'::text else 'archived'::text end) else v->key end)) from jsonb_object_keys(p_values) key) end,
 'previous_stage',b->>'stage','stage',v->>'stage','declaration',true));
 return result||jsonb_build_object('replayed',false);
exception when check_violation or not_null_violation or invalid_text_representation or datetime_field_overflow or foreign_key_violation then raise exception 'invalid crm';
end $_$;


ALTER FUNCTION public.fin_crm_command(p_org uuid, p_kind text, p_id uuid, p_expected integer, p_request uuid, p_scope jsonb, p_values jsonb) OWNER TO postgres;

--
-- Name: fin_crm_contact_version_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_crm_contact_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if (new.id,new.organization_id,new.provider_id,new.counterparty_organization_id,new.legal_entity_id,new.created_by,new.created_at)
 is distinct from (old.id,old.organization_id,old.provider_id,old.counterparty_organization_id,old.legal_entity_id,old.created_by,old.created_at) then raise exception 'immutable crm scope'; end if;
 new.version:=old.version+1; new.updated_at:=clock_timestamp(); return new;
end $$;


ALTER FUNCTION public.fin_crm_contact_version_guard() OWNER TO postgres;

--
-- Name: fin_crm_reference_visible(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_crm_reference_visible(p_org uuid, p_entity uuid, p_type text, p_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k text;
begin
 if p_type is null and p_id is null then return true; end if;
 if p_type is null or p_id is null or not public.fin_crm_scope_visible(p_org,p_entity) then return false; end if;
 select kind into k from public.fin_organizations where id=p_org;
 if k='PROVIDER' then
   -- A provider's CRM points only to its accepted demand or its own proposal.
   -- It never receives a buyer contract, competing proposal or private Radar.
   if p_entity is not null then return false; end if;
   if p_type='rfq' then return exists(select 1 from public.fin_rfq_invites where rfq_id=p_id and provider_organization_id=p_org and status='accepted'); end if;
   if p_type='proposal' then return exists(select 1 from public.fin_proposals p where p.id=p_id and p.provider_organization_id=p_org and exists(select 1 from public.fin_rfq_invites i where i.id=p.invite_id and i.status='accepted' and i.provider_organization_id=p_org)); end if;
   return false;
 end if;
 case p_type
 when 'provider' then return exists(select 1 from public.fin_providers where organization_id=p_org and id=p_id);
 when 'rfq' then return exists(select 1 from public.fin_rfqs where organization_id=p_org and id=p_id and legal_entity_id is not distinct from p_entity) and public.fin_rfq_visible(p_id);
 when 'contract' then return exists(select 1 from public.fin_contracts where organization_id=p_org and id=p_id and legal_entity_id is not distinct from p_entity) and public.fin_contract_visible(p_id);
 when 'proposal' then return exists(select 1 from public.fin_proposals p join public.fin_rfqs r on r.id=p.rfq_id where p.id=p_id and p.buyer_organization_id=p_org and r.legal_entity_id is not distinct from p_entity) and public.fin_object_visible(p_org,'proposal',p_id);
 when 'opportunity' then return exists(select 1 from public.fin_opportunities where organization_id=p_org and id=p_id and legal_entity_id is not distinct from p_entity);
 when 'task' then return exists(select 1 from public.fin_tasks where organization_id=p_org and id=p_id and legal_entity_id is not distinct from p_entity);
 else return false;
 end case;
end $$;


ALTER FUNCTION public.fin_crm_reference_visible(p_org uuid, p_entity uuid, p_type text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_crm_scope_visible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_crm_scope_visible(p_org uuid, p_entity uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and public.fin_has_role(p_org) and public.fin_entity_visible(p_org,p_entity)
 and exists(select 1 from public.fin_organizations where id=p_org and kind in ('BUYER','PROVIDER'));
$$;


ALTER FUNCTION public.fin_crm_scope_visible(p_org uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_current_session_alive(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_current_session_alive() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_claims jsonb; v_session uuid;
begin
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
    v_session := (v_claims->>'session_id')::uuid;
  exception when others then return false;
  end;
  return v_session is not null and exists (
    select 1 from auth.sessions s where s.id = v_session and (s.not_after is null or s.not_after > now()));
end $$;


ALTER FUNCTION public.fin_current_session_alive() OWNER TO postgres;

--
-- Name: fin_decide_policy_exception(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_decide_policy_exception(p_exception uuid, p_decision text, p_comment text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.fin_policy_exceptions%rowtype; v_request public.fin_approval_requests%rowtype; v_roles text[]; v_entity uuid; v_status text;
begin
  select * into e from public.fin_policy_exceptions where id = p_exception;
  if not found then raise exception 'policy exception not found'; end if;
  select * into v_request from public.fin_approval_requests where id = e.request_id;
  perform 1 from public.fin_rfqs where id = v_request.rfq_id for update;
  select * into v_request from public.fin_approval_requests where id = e.request_id for update;
  select * into e from public.fin_policy_exceptions where id = p_exception for update;
  if not public.fin_has_role(e.organization_id) then raise exception 'forbidden'; end if;
  if e.status <> 'requested' or v_request.status <> 'pending' then raise exception 'policy exception closed'; end if;
  if p_decision not in ('approved','rejected') or length(trim(coalesce(p_comment,''))) < 3 then raise exception 'invalid policy exception'; end if;
  if auth.uid() in (e.requested_by, v_request.requested_by) then raise exception 'segregation of duties'; end if;
  select array(select jsonb_array_elements_text(coalesce(v.document->'exception_approver_roles', '["admin"]'::jsonb))) into v_roles
    from public.fin_policy_versions v where v.id = e.policy_version_id;
  select legal_entity_id into v_entity from public.fin_rfqs where id = v_request.rfq_id;
  if not public.fin_approval_member_eligible(e.organization_id, v_entity, auth.uid(), v_roles, 'any') then raise exception 'forbidden'; end if;
  update public.fin_policy_exceptions set status = p_decision, decided_by = auth.uid(), decided_at = now(), decision_comment = trim(p_comment) where id = p_exception;
  v_status := public.fin_approval_refresh(e.request_id);
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (e.organization_id, 'rfq', v_request.rfq_id, 'policy_exception_' || p_decision, auth.uid(),
            jsonb_build_object('request_id', e.request_id, 'exception_id', e.id, 'rule_id', e.rule_id));
  return v_status;
end $$;


ALTER FUNCTION public.fin_decide_policy_exception(p_exception uuid, p_decision text, p_comment text) OWNER TO postgres;

--
-- Name: fin_decide_qualification_exception(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_decide_qualification_exception(p_exception uuid, p_input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_qualification_exceptions%rowtype; q public.fin_provider_qualifications%rowtype; v_status text := p_input->>'status'; v_reason text := nullif(trim(coalesce(p_input->>'reason', '')), '');
begin
  select * into x from public.fin_qualification_exceptions where id = p_exception for update;
  select * into q from public.fin_provider_qualifications where id = x.qualification_id;
  if x.id is null or auth.uid() is null or not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if x.status <> 'requested' then raise exception 'qualification exception closed'; end if;
  if x.requested_by = auth.uid() then raise exception 'segregation of duties'; end if;
  if v_status is null or v_status not in ('approved','rejected') or v_reason is null or length(v_reason) not between 3 and 1000 or v_reason ~ '[<>]' then raise exception 'invalid qualification exception'; end if;
  update public.fin_qualification_exceptions set status = v_status, decided_by = auth.uid(), decided_at = now(), decision_reason = v_reason where id = x.id;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, to_status, reason, object_id, actor_id) values (q.organization_id, q.id, 'exception_decided', v_status, v_reason, x.id, auth.uid());
end $$;


ALTER FUNCTION public.fin_decide_qualification_exception(p_exception uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_decision_external_context(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_decision_external_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 new.snapshot:=new.snapshot||jsonb_build_object('external_alternatives',coalesce((select jsonb_agg(jsonb_build_object(
 'id',p.id,'provider_id',p.provider_id,'origin','buyer_recorded_external','version',v.version,'terms',v.terms,'rfq_revision',v.rfq_revision,
 'currency',v.currency,'source_reference',v.source_reference,'channel',v.channel,'received_at',v.received_at,
 'document_id',v.document_id,'document_version',v.document_version,'document_sha256',v.document_sha256,
 'recorded_by',v.recorded_by,'recorded_at',v.recorded_at,'reviewed_by',q.reviewed_by,'reviewed_at',q.reviewed_at,
 'document_available_at_capture',case when v.document_id is null then null else exists(select 1 from public.fin_private_documents d where d.id=v.document_id and d.removed_at is null) end,
 'review_scope','transcription_correspondence_only','external_validation','not_recorded','institution_acceptance','not_recorded') order by p.id)
 from public.fin_external_proposals p join public.fin_external_proposal_versions v on v.proposal_id=p.id and v.version=p.current_version
 join public.fin_external_proposal_reviews q on q.proposal_id=p.id and q.version=v.version and q.action='confirm'
 where p.rfq_id=new.rfq_id and p.organization_id=new.organization_id and p.state='reviewed'),'[]'::jsonb));
 return new;
end $$;


ALTER FUNCTION public.fin_decision_external_context() OWNER TO postgres;

--
-- Name: fin_decision_live_actor_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_decision_live_actor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role text; v_entity uuid;
begin
  select role into v_role from public.fin_members
    where organization_id=new.organization_id and user_id=auth.uid() for share;
  if not found or v_role not in ('admin','finance_manager') or new.decided_by is distinct from auth.uid() then
    raise exception 'forbidden';
  end if;
  perform 1 from public.fin_member_entity_grants
    where organization_id=new.organization_id and user_id=auth.uid() for share;
  select legal_entity_id into v_entity from public.fin_rfqs where id=new.rfq_id and organization_id=new.organization_id;
  if not found or not public.fin_entity_visible(new.organization_id,v_entity) then raise exception 'forbidden'; end if;
  return new;
end $$;


ALTER FUNCTION public.fin_decision_live_actor_guard() OWNER TO postgres;

--
-- Name: fin_decline_provider_invite(text, uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_decline_provider_invite(p_token text, p_provider_org uuid, p_expected text, p_confirmed boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare i public.fin_rfq_invites%rowtype; v_email text; v_confirmed timestamptz; e public.fin_events%rowtype;
begin
 if auth.uid() is null or coalesce(p_token,'') !~ '^[0-9a-f]{64}$' or p_expected is distinct from 'invited' or p_confirmed is not true
 or (p_reason is not null and p_reason not in ('not_offered','capacity','deadline','other')) then raise exception 'invalid invitation'; end if;
 perform 1 from public.fin_members where organization_id=p_provider_org and user_id=auth.uid() for share;
 if not public.fin_has_role(p_provider_org,array['admin','provider_user'])
 or not exists(select 1 from public.fin_organizations where id=p_provider_org and kind='PROVIDER')
 or public.fin_governance_org_locked(p_provider_org) then raise exception 'forbidden'; end if;
 select * into i from public.fin_rfq_invites where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if i.id is null or i.buyer_organization_id=p_provider_org or public.fin_governance_org_locked(i.buyer_organization_id) then raise exception 'invalid invitation'; end if;
 if i.recipient_mode='exact_email' then
   select lower(trim(u.email)),u.email_confirmed_at into v_email,v_confirmed from auth.users u where u.id=auth.uid() for share;
   if v_confirmed is null or v_email is distinct from i.recipient_email then raise exception 'invalid invitation'; end if;
 end if;
 -- Check canonical binding without granting access to the buyer's private row.
 perform 1 from public.fin_providers where id=i.provider_id and organization_id=i.buyer_organization_id for share;
 if exists(select 1 from public.fin_providers where id=i.provider_id and organization_id=i.buyer_organization_id and provider_organization_id is not null and provider_organization_id<>p_provider_org) then raise exception 'invalid invitation'; end if;
 if i.status='declined' and i.provider_organization_id=p_provider_org then
   select * into e from public.fin_events where organization_id=i.buyer_organization_id and entity_type='rfq' and entity_id=i.rfq_id and event_type='invite_declined' and metadata->>'invite_id'=i.id::text order by happened_at,id limit 1;
   if e.id is null or (e.metadata->>'reason') is distinct from p_reason then raise exception 'invalid invitation'; end if;
   return jsonb_build_object('invite_id',i.id,'status','declined','declined_at',e.happened_at,'replayed',true);
 end if;
 if i.status<>'invited' or i.accepted_at is not null or i.expires_at<=clock_timestamp() then raise exception 'invalid invitation'; end if;
 update public.fin_rfq_invites set status='declined',provider_organization_id=p_provider_org where id=i.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(i.buyer_organization_id,'rfq',i.rfq_id,'invite_declined',auth.uid(),jsonb_build_object('invite_id',i.id,'provider_id',i.provider_id,'provider_organization_id',p_provider_org,'reason',p_reason)) returning * into e;
 return jsonb_build_object('invite_id',i.id,'status','declined','declined_at',e.happened_at,'replayed',false);
end $_$;


ALTER FUNCTION public.fin_decline_provider_invite(p_token text, p_provider_org uuid, p_expected text, p_confirmed boolean, p_reason text) OWNER TO postgres;

--
-- Name: fin_demo_pool_lease(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_pool_lease(p_holder text, p_seconds integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare v_ok boolean;
begin
  perform public.fin_demo_require_environment();
  if p_holder is null or p_holder !~ '^[a-z0-9-]{8,64}$' or p_seconds is null or p_seconds not between 60 and 7200 then
    raise exception 'invalid demo pool lease';
  end if;
  insert into public.fin_demo_pool_leases(name, holder, expires_at) values ('pool', p_holder, now() + make_interval(secs => p_seconds))
  on conflict (name) do update set holder = excluded.holder, expires_at = excluded.expires_at, acquired_at = now()
    where public.fin_demo_pool_leases.holder = excluded.holder or public.fin_demo_pool_leases.expires_at <= now()
  returning true into v_ok;
  return coalesce(v_ok, false);
end $_$;


ALTER FUNCTION public.fin_demo_pool_lease(p_holder text, p_seconds integer) OWNER TO postgres;

--
-- Name: fin_demo_pool_release(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_pool_release(p_holder text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  perform public.fin_demo_require_environment();
  delete from public.fin_demo_pool_leases where name = 'pool' and holder = p_holder;
end $$;


ALTER FUNCTION public.fin_demo_pool_release(p_holder text) OWNER TO postgres;

--
-- Name: fin_demo_quota_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_quota_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare w public.fin_demo_workspaces%rowtype; v_used integer; v_limit integer;
begin
  if tg_table_name = 'fin_organizations' then
    select * into w from public.fin_demo_workspaces where status = 'claimed' and new.created_by = any(user_ids) limit 1;
    if w.id is null then return new; end if;
    -- Serializa as escritas do MESMO workspace: sem isto, transações concorrentes
    -- contam o mesmo total e ultrapassam a quota (reproduzido em 11/10/2026: quota 1, 3 RFQs).
    perform 1 from public.fin_demo_workspaces where id = w.id for update;
    select count(*) into v_used from public.fin_organizations o where o.created_by = any(w.user_ids);
    v_limit := 1 + coalesce(array_length(w.provider_organization_ids, 1), 0) + coalesce((w.quotas->>'organizations')::integer, 0);
  else
    -- Cada tabela lê só a própria coluna: NEW de fin_rfqs não tem buyer_organization_id.
    if tg_table_name = 'fin_rfq_invites' then
      select * into w from public.fin_demo_workspaces where status = 'claimed' and buyer_organization_id = new.buyer_organization_id limit 1;
    else
      select * into w from public.fin_demo_workspaces where status = 'claimed' and buyer_organization_id = new.organization_id limit 1;
    end if;
    if w.id is null then return new; end if;
    -- Serializa as escritas do MESMO workspace: sem isto, transações concorrentes
    -- contam o mesmo total e ultrapassam a quota (reproduzido em 11/10/2026: quota 1, 3 RFQs).
    perform 1 from public.fin_demo_workspaces where id = w.id for update;
    if tg_table_name = 'fin_rfqs' then
      select count(*) into v_used from public.fin_rfqs where organization_id = w.buyer_organization_id;
      v_limit := coalesce((w.quotas->>'rfqs')::integer, 0);
    elsif tg_table_name = 'fin_private_documents' then
      select count(*) into v_used from public.fin_private_documents where organization_id = w.buyer_organization_id;
      v_limit := coalesce((w.quotas->>'documents')::integer, 0);
    else
      select count(*) into v_used from public.fin_rfq_invites where buyer_organization_id = w.buyer_organization_id;
      v_limit := coalesce((w.quotas->>'invites')::integer, 0);
    end if;
  end if;
  if v_used >= v_limit then raise exception 'demo workspace quota exceeded'; end if;
  return new;
end $$;


ALTER FUNCTION public.fin_demo_quota_guard() OWNER TO postgres;

--
-- Name: fin_demo_require_environment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_require_environment() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if coalesce((select value from public.fin_settings where key = 'deployment_environment'), '') <> 'demo' then
    raise exception 'demo workspaces unavailable outside demo';
  end if;
end $$;


ALTER FUNCTION public.fin_demo_require_environment() OWNER TO postgres;

--
-- Name: fin_demo_workspace_active(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_workspace_active(p_slug text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  perform public.fin_demo_require_environment();
  return exists (select 1 from public.fin_demo_workspaces where slug = p_slug and (status = 'provisioning'
    or (status = 'claimed' and expires_at > now() and idle_expires_at > now())));
end $$;


ALTER FUNCTION public.fin_demo_workspace_active(p_slug text) OWNER TO postgres;

--
-- Name: fin_demo_workspaces; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_demo_workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    baseline_version text NOT NULL,
    status text DEFAULT 'provisioning'::text NOT NULL,
    buyer_organization_id uuid,
    provider_organization_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    user_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    personas jsonb DEFAULT '{}'::jsonb NOT NULL,
    claim_token_hash text,
    quotas jsonb DEFAULT '{"rfqs": 40, "invites": 80, "documents": 40, "organizations": 1}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ready_at timestamp with time zone,
    claimed_at timestamp with time zone,
    last_used_at timestamp with time zone,
    idle_expires_at timestamp with time zone,
    expires_at timestamp with time zone,
    cleanup_attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    CONSTRAINT fin_demo_workspaces_baseline_version_check CHECK (((length(baseline_version) >= 1) AND (length(baseline_version) <= 40))),
    CONSTRAINT fin_demo_workspaces_check CHECK (((status <> 'claimed'::text) OR ((claim_token_hash IS NOT NULL) AND (expires_at IS NOT NULL) AND (idle_expires_at IS NOT NULL)))),
    CONSTRAINT fin_demo_workspaces_claim_token_hash_check CHECK (((claim_token_hash IS NULL) OR (claim_token_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT fin_demo_workspaces_cleanup_attempts_check CHECK (((cleanup_attempts >= 0) AND (cleanup_attempts <= 100))),
    CONSTRAINT fin_demo_workspaces_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 500))),
    CONSTRAINT fin_demo_workspaces_personas_check CHECK (((jsonb_typeof(personas) = 'object'::text) AND (length((personas)::text) <= 4000))),
    CONSTRAINT fin_demo_workspaces_quotas_check CHECK ((jsonb_typeof(quotas) = 'object'::text)),
    CONSTRAINT fin_demo_workspaces_slug_check CHECK ((slug ~ '^[a-f0-9]{10}$'::text)),
    CONSTRAINT fin_demo_workspaces_status_check CHECK ((status = ANY (ARRAY['provisioning'::text, 'ready'::text, 'claimed'::text, 'expired'::text, 'cleaning'::text, 'failed'::text])))
);


ALTER TABLE public.fin_demo_workspaces OWNER TO postgres;

--
-- Name: fin_demo_workspace_claim(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_workspace_claim(p_token_hash text, p_idle_minutes integer, p_lifetime_minutes integer, p_max_active integer) RETURNS SETOF public.fin_demo_workspaces
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare v_id uuid; v_active integer;
begin
  perform public.fin_demo_require_environment();
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$'
     or p_idle_minutes is null or p_idle_minutes not between 5 and 1440
     or p_lifetime_minutes is null or p_lifetime_minutes not between p_idle_minutes and 2880
     or p_max_active is null or p_max_active not between 1 and 500 then
    raise exception 'invalid demo workspace claim';
  end if;
  -- Serializa reivindicações concorrentes só no teto de ativos.
  perform pg_advisory_xact_lock(hashtext('fin_demo_workspace_claim'));
  update public.fin_demo_workspaces set status = 'expired'
    where status = 'claimed' and (expires_at <= now() or idle_expires_at <= now());
  select count(*) into v_active from public.fin_demo_workspaces where status = 'claimed';
  if v_active >= p_max_active then return; end if;
  select id into v_id from public.fin_demo_workspaces where status = 'ready'
    order by ready_at, id limit 1 for update skip locked;
  if v_id is null then return; end if;
  return query update public.fin_demo_workspaces set status = 'claimed', claim_token_hash = p_token_hash,
      claimed_at = now(), last_used_at = now(),
      expires_at = now() + make_interval(mins => p_lifetime_minutes),
      idle_expires_at = least(now() + make_interval(mins => p_idle_minutes), now() + make_interval(mins => p_lifetime_minutes))
    where id = v_id returning *;
end $_$;


ALTER FUNCTION public.fin_demo_workspace_claim(p_token_hash text, p_idle_minutes integer, p_lifetime_minutes integer, p_max_active integer) OWNER TO postgres;

--
-- Name: fin_demo_workspace_resume(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_demo_workspace_resume(p_id uuid, p_token_hash text, p_idle_minutes integer) RETURNS SETOF public.fin_demo_workspaces
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
begin
  perform public.fin_demo_require_environment();
  if p_id is null or p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' or p_idle_minutes is null or p_idle_minutes not between 5 and 1440 then
    raise exception 'invalid demo workspace resume';
  end if;
  return query update public.fin_demo_workspaces set last_used_at = now(),
      idle_expires_at = least(now() + make_interval(mins => p_idle_minutes), expires_at)
    where id = p_id and status = 'claimed' and claim_token_hash = p_token_hash
      and expires_at > now() and idle_expires_at > now()
    returning *;
end $_$;


ALTER FUNCTION public.fin_demo_workspace_resume(p_id uuid, p_token_hash text, p_idle_minutes integer) OWNER TO postgres;

--
-- Name: fin_discard_policy_draft(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_discard_policy_draft(p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_policy_versions%rowtype; v_entity uuid;
begin
  select * into v from public.fin_policy_versions where id = p_version for update;
  if not found or not public.fin_has_role(v.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if v.status <> 'draft' then raise exception 'policy version not draft'; end if;
  select legal_entity_id into v_entity from public.fin_policies where id = v.policy_id;
  delete from public.fin_policy_versions where id = p_version;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'organization', v.organization_id, 'policy_draft_discarded', auth.uid(),
            jsonb_build_object('policy_id', v.policy_id, 'version', v.version), v_entity);
end $$;


ALTER FUNCTION public.fin_discard_policy_draft(p_version uuid) OWNER TO postgres;

--
-- Name: fin_document_authorize_download(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_authorize_download(p_document uuid, p_version integer DEFAULT NULL::integer) RETURNS TABLE(bucket text, path text, mime_type text, title text, version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_doc public.fin_private_documents%rowtype; v_row public.fin_document_versions%rowtype;
begin
  if auth.uid() is null or not public.fin_can_read_document(p_document) then raise exception 'forbidden'; end if;
  select d.* into v_doc from public.fin_private_documents d where d.id = p_document;
  select dv.* into v_row from public.fin_document_versions dv
   where dv.document_id = p_document and dv.version = coalesce(p_version, v_doc.current_version) and dv.status = 'available';
  if not found then raise exception 'document not available'; end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (v_doc.organization_id, v_doc.entity_type, v_doc.entity_id, 'document_downloaded', auth.uid(),
    jsonb_build_object('document_id', v_doc.id, 'version', v_row.version));
  return query select v_row.storage_bucket, v_row.storage_path, v_row.mime_type, v_doc.title, v_row.version;
end $$;


ALTER FUNCTION public.fin_document_authorize_download(p_document uuid, p_version integer) OWNER TO postgres;

--
-- Name: fin_document_begin_upload(uuid, text, uuid, text, text, text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_begin_upload(p_org uuid, p_entity_type text, p_entity_id uuid, p_title text, p_visibility text, p_mime text, p_size bigint, p_sha256 text DEFAULT NULL::text, p_document_id uuid DEFAULT NULL::uuid) RETURNS TABLE(document_id uuid, version integer, bucket text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_doc public.fin_private_documents%rowtype; v_buyer uuid; v_rfq uuid; v_version integer; v_path text;
begin
  if auth.uid() is null then raise exception 'forbidden'; end if;
  if not public.fin_document_mime_allowed(p_mime) then raise exception 'document type not allowed'; end if;
  if p_size is null or p_size < 1 or p_size > 10485760 then raise exception 'document too large'; end if;
  if p_sha256 is not null and p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'invalid document hash'; end if;
  if (select count(*) from public.fin_document_versions v where v.uploaded_by = auth.uid() and v.status = 'pending'
      and v.created_at > now() - interval '1 hour') >= 20 then raise exception 'too many pending uploads'; end if;

  if p_document_id is not null then
    select * into v_doc from public.fin_private_documents d where d.id = p_document_id for update;
    if not public.fin_can_read_document(p_document_id) then raise exception 'forbidden'; end if;
    if not found or v_doc.removed_at is not null or v_doc.organization_id <> p_org then raise exception 'forbidden'; end if;
    if not public.fin_has_role(v_doc.organization_id, case when v_doc.organization_id = v_doc.buyer_organization_id
        then array['admin','finance_manager','analyst'] else array['admin','provider_user'] end) then raise exception 'forbidden'; end if;
  else
    if length(coalesce(trim(p_title), '')) < 2 then raise exception 'invalid document title'; end if;
    if p_visibility not in ('internal','shared') then raise exception 'invalid visibility'; end if;
    if p_entity_type = 'proposal' then
      select p.buyer_organization_id, p.rfq_id into v_buyer, v_rfq from public.fin_proposals p
       where p.id = p_entity_id and p.provider_organization_id = p_org;
      if v_buyer is null or not public.fin_has_role(p_org, array['admin','provider_user']) then raise exception 'forbidden'; end if;
    else
      if not public.fin_has_role(p_org, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
      v_buyer := p_org;
      if p_entity_type = 'rfq' then
        select r.id into v_rfq from public.fin_rfqs r where r.id = p_entity_id and r.organization_id = p_org;
        if v_rfq is null then raise exception 'forbidden'; end if;
      elsif p_entity_type = 'contract' then
        if not exists (select 1 from public.fin_contracts c where c.id = p_entity_id and c.organization_id = p_org) then raise exception 'forbidden'; end if;
        select d.rfq_id into v_rfq from public.fin_contracts c join public.fin_decisions d on d.id = c.decision_id where c.id = p_entity_id;
        if p_visibility <> 'internal' then raise exception 'invalid visibility'; end if;
      elsif p_entity_type = 'profile' then
        if p_visibility <> 'internal' or not public.fin_entity_allows(p_org,case when p_entity_id=p_org then null else p_entity_id end,array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
        if p_entity_id<>p_org and not exists(select 1 from public.fin_legal_entities where organization_id=p_org and id=p_entity_id and kind='legal_entity' and status='active') then raise exception 'forbidden'; end if;
      else
        raise exception 'invalid entity';
      end if;
    end if;
    insert into public.fin_private_documents (organization_id, buyer_organization_id, entity_type, entity_id, rfq_id, title, visibility, created_by)
    values (p_org, v_buyer, p_entity_type, p_entity_id, v_rfq, trim(p_title), p_visibility, auth.uid())
    returning * into v_doc;
  end if;

  select coalesce(max(v.version), 0) + 1 into v_version from public.fin_document_versions v where v.document_id = v_doc.id;
  -- O caminho não carrega nome de arquivo nem dado pessoal.
  v_path := v_doc.organization_id::text || '/' || v_doc.id::text || '/v' || v_version || '-' || gen_random_uuid()::text;
  insert into public.fin_document_versions (document_id, version, storage_path, mime_type, size_bytes, sha256, uploaded_by)
  values (v_doc.id, v_version, v_path, p_mime, p_size, p_sha256, auth.uid());
  return query select v_doc.id, v_version, 'fin-documents'::text, v_path;
end $_$;


ALTER FUNCTION public.fin_document_begin_upload(p_org uuid, p_entity_type text, p_entity_id uuid, p_title text, p_visibility text, p_mime text, p_size bigint, p_sha256 text, p_document_id uuid) OWNER TO postgres;

--
-- Name: fin_document_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if auth.uid() is not null and public.fin_has_role(new.buyer_organization_id) then
  if new.entity_type='profile' then
   if not public.fin_entity_visible(new.organization_id,case when new.entity_id=new.organization_id then null else new.entity_id end) then raise exception 'forbidden'; end if;
  elsif not public.fin_object_visible(new.buyer_organization_id,new.entity_type,new.entity_id) then raise exception 'forbidden'; end if;
 end if;
 return new;
end $$;


ALTER FUNCTION public.fin_document_entity_guard() OWNER TO postgres;

--
-- Name: fin_document_extraction_begin(uuid, uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_extraction_begin(p_org uuid, p_document uuid, p_version integer, p_schema text, p_provider text, p_provider_version text) RETURNS TABLE(extraction_id uuid, bucket text, path text, mime_type text, sha256 text, size_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d public.fin_private_documents%rowtype; v public.fin_document_versions%rowtype; x uuid;
begin
  if auth.uid() is null or not public.fin_has_role(p_org, array['admin','finance_manager','analyst'])
     or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  select * into d from public.fin_private_documents where id = p_document;
  if d.id is null or d.buyer_organization_id <> p_org or d.removed_at is not null or not public.fin_can_read_document(p_document) then raise exception 'forbidden'; end if;
  if p_schema is null or p_schema not in ('credit_proposal','acquiring_proposal','fee_schedule','contract_terms')
     or p_provider is null or p_provider not in ('manual','deterministic_v1','model_external')
     or p_provider_version is null or p_provider_version !~ '^[A-Za-z0-9._-]{1,60}$' then raise exception 'invalid extraction'; end if;
  select * into v from public.fin_document_versions where document_id = p_document and version = coalesce(p_version, d.current_version) and status = 'available';
  if v.document_id is null then raise exception 'document not available'; end if;
  insert into public.fin_document_extractions(organization_id, document_id, document_version, schema_key, provider, provider_version, document_sha256, document_mime, requested_by)
  values (p_org, d.id, v.version, p_schema, p_provider, p_provider_version, v.sha256, v.mime_type, auth.uid()) returning id into x;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, d.entity_type, d.entity_id, 'document_extraction_started', auth.uid(), jsonb_build_object('extraction_id', x, 'document_id', d.id, 'version', v.version, 'schema', p_schema, 'provider', p_provider));
  return query select x, v.storage_bucket, case when p_provider = 'manual' then null else v.storage_path end, v.mime_type, v.sha256, v.size_bytes;
end $_$;


ALTER FUNCTION public.fin_document_extraction_begin(p_org uuid, p_document uuid, p_version integer, p_schema text, p_provider text, p_provider_version text) OWNER TO postgres;

--
-- Name: fin_document_extraction_fail(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_extraction_fail(p_extraction uuid, p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_document_extractions%rowtype; d public.fin_private_documents%rowtype;
begin
  select * into x from public.fin_document_extractions where id = p_extraction for update;
  if x.id is null or auth.uid() is null or x.requested_by <> auth.uid() then raise exception 'forbidden'; end if;
  if x.status <> 'processing' then raise exception 'extraction closed'; end if;
  if p_code is null or p_code not in ('unsupported_format','provider_not_configured','unreadable','encrypted','hash_mismatch','too_large','parse_error') then raise exception 'invalid extraction'; end if;
  update public.fin_document_extractions set status = 'failed', error_code = p_code, completed_at = now() where id = x.id;
  select * into d from public.fin_private_documents where id = x.document_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (x.organization_id, d.entity_type, d.entity_id, 'document_extraction_failed', auth.uid(), jsonb_build_object('extraction_id', x.id, 'document_id', d.id, 'code', p_code));
end $$;


ALTER FUNCTION public.fin_document_extraction_fail(p_extraction uuid, p_code text) OWNER TO postgres;

--
-- Name: fin_document_extraction_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_extraction_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (to_jsonb(new) - array['status','pages','error_code','warnings','flags','completed_at']) is distinct from (to_jsonb(old) - array['status','pages','error_code','warnings','flags','completed_at'])
     or old.status <> 'processing' or new.status = 'processing' then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_document_extraction_guard() OWNER TO postgres;

--
-- Name: fin_document_extraction_record(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_extraction_record(p_extraction uuid, p_result jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare x public.fin_document_extractions%rowtype; d public.fin_private_documents%rowtype; f jsonb; v_crit text; v_status text; v_conf numeric; v_count integer := 0; v_review integer := 0; v_title text;
begin
  select * into x from public.fin_document_extractions where id = p_extraction for update;
  if x.id is null or auth.uid() is null or x.requested_by <> auth.uid() or not public.fin_can_read_document(x.document_id)
     or not public.fin_has_role(x.organization_id, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  if x.status <> 'processing' then raise exception 'extraction closed'; end if;
  if p_result is null or jsonb_typeof(p_result) <> 'object' or jsonb_typeof(p_result->'facts') is distinct from 'array' or jsonb_array_length(p_result->'facts') > 200
     or length(p_result::text) > 400000 then raise exception 'invalid extraction'; end if;
  for f in select value from jsonb_array_elements(p_result->'facts') loop
    if jsonb_typeof(f) <> 'object' then raise exception 'invalid extraction fact'; end if;
    v_crit := public.fin_extraction_schema_field(x.schema_key, f->>'field_key');
    if v_crit is null then raise exception 'invalid extraction fact'; end if;
    if exists (select 1 from jsonb_object_keys(f) k where k not in ('field_key','page','locator','raw_value','normalized_value','value_state','unit','currency','confidence','method','parser_version','criticality','status','flags')) then raise exception 'invalid extraction fact'; end if;
    if (f->>'method') is distinct from (case x.provider when 'manual' then 'manual_entry' when 'deterministic_v1' then 'deterministic_parser' else 'model' end) then raise exception 'invalid extraction fact'; end if;
    if f ? 'confidence' and jsonb_typeof(f->'confidence') not in ('number','null') then raise exception 'invalid extraction fact'; end if;
    v_conf := (f->>'confidence')::numeric;
    v_status := case when v_crit = 'standard' and f->>'value_state' = 'present' and coalesce(v_conf, 0) >= 0.85 then 'extracted' else 'needs_review' end;
    begin
      insert into public.fin_extraction_facts(organization_id, extraction_id, document_id, document_version, schema_key, field_key, page, locator, raw_value, normalized_value, value_state, unit, currency, confidence, method, parser_version, criticality, status, flags, created_by)
      values (x.organization_id, x.id, x.document_id, x.document_version, x.schema_key, f->>'field_key', (f->>'page')::integer, nullif(f->>'locator', ''),
        nullif(left(regexp_replace(coalesce(f->>'raw_value', ''), '[[:cntrl:]]', ' ', 'g'), 2000), ''),
        case when f->>'value_state' = 'present' then f->'normalized_value' end, f->>'value_state', nullif(f->>'unit', ''), nullif(f->>'currency', ''), v_conf, f->>'method',
        coalesce(f->>'parser_version', x.provider_version), v_crit, v_status,
        coalesce((select array_agg(e) from jsonb_array_elements_text(case when jsonb_typeof(f->'flags') = 'array' then f->'flags' else '[]'::jsonb end) e where e ~ '^[a-z_]{3,40}$'), '{}'), auth.uid());
    exception when check_violation or not_null_violation or invalid_text_representation or numeric_value_out_of_range then raise exception 'invalid extraction fact';
    end;
    v_count := v_count + 1;
    if v_status = 'needs_review' then v_review := v_review + 1; end if;
  end loop;
  update public.fin_document_extractions set status = 'completed', completed_at = now(),
    pages = case when jsonb_typeof(p_result->'pages') = 'number' then least(greatest((p_result->>'pages')::integer, 1), 2000) end,
    warnings = coalesce((select array_agg(e) from (select e from jsonb_array_elements_text(case when jsonb_typeof(p_result->'warnings') = 'array' then p_result->'warnings' else '[]'::jsonb end) e where e ~ '^[a-z_]{3,40}$' limit 20) w), '{}'),
    flags = coalesce((select array_agg(e) from (select e from jsonb_array_elements_text(case when jsonb_typeof(p_result->'flags') = 'array' then p_result->'flags' else '[]'::jsonb end) e where e ~ '^[a-z_]{3,40}$' limit 20) w), '{}')
  where id = x.id;
  select * into d from public.fin_private_documents where id = x.document_id;
  if v_review > 0 and d.entity_type in ('rfq','proposal','contract') then
    v_title := left('Revisar fatos extraídos: ' || d.title, 200);
    if not exists (select 1 from public.fin_tasks where organization_id = x.organization_id and related_type = d.entity_type and related_id = d.entity_id and title = v_title and status = 'open') then
      insert into public.fin_tasks(organization_id, title, due_on, status, related_type, related_id, created_by)
      values (x.organization_id, v_title, current_date + 3, 'open', d.entity_type, d.entity_id, auth.uid());
    end if;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (x.organization_id, d.entity_type, d.entity_id, 'document_extraction_completed', auth.uid(), jsonb_build_object('extraction_id', x.id, 'facts', v_count, 'needs_review', v_review));
  return v_count;
end $_$;


ALTER FUNCTION public.fin_document_extraction_record(p_extraction uuid, p_result jsonb) OWNER TO postgres;

--
-- Name: fin_document_finalize_upload(uuid, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_finalize_upload(p_document uuid, p_version integer, p_size bigint, p_mime text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row public.fin_document_versions%rowtype; v_doc public.fin_private_documents%rowtype; v_event text;
begin
  -- Leitura inicial sem lock identifica o autor persistido; a versão é relida
  -- depois dos locks. Nenhum ator informado pelo cliente é aceito.
  select * into v_row from public.fin_document_versions where document_id=p_document and version=p_version;
  if not found then raise exception 'invalid document'; end if;
  if not public.fin_document_lock_upload_authorization(p_document,v_row.uploaded_by) then raise exception 'forbidden'; end if;
  select * into v_row from public.fin_document_versions where document_id = p_document and version = p_version for update;
  if not found then raise exception 'invalid document'; end if;
  if v_row.status <> 'pending' then return v_row.status; end if;
  if v_row.created_at <= now() - interval '10 minutes'
     or p_size is distinct from v_row.size_bytes or p_mime is distinct from v_row.mime_type then
    update public.fin_document_versions set status = 'failed', completed_at = now() where document_id = p_document and version = p_version;
    return 'failed';
  end if;
  update public.fin_document_versions set status = 'available', completed_at = now() where document_id = p_document and version = p_version;
  update public.fin_private_documents set current_version = greatest(current_version, p_version) where id = p_document
  returning * into v_doc;
  v_event := case when p_version = 1 then 'document_uploaded' else 'document_version_added' end;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (v_doc.organization_id, v_doc.entity_type, v_doc.entity_id, v_event, v_row.uploaded_by,
    jsonb_build_object('document_id', v_doc.id, 'version', p_version, 'mime_type', v_row.mime_type, 'size_bytes', v_row.size_bytes));
  if v_doc.visibility = 'shared' and v_doc.organization_id <> v_doc.buyer_organization_id and v_doc.rfq_id is not null then
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_doc.buyer_organization_id, 'rfq', v_doc.rfq_id, v_event, v_row.uploaded_by,
      jsonb_build_object('document_id', v_doc.id, 'version', p_version));
  end if;
  return 'available';
end $$;


ALTER FUNCTION public.fin_document_finalize_upload(p_document uuid, p_version integer, p_size bigint, p_mime text) OWNER TO postgres;

--
-- Name: fin_document_lock_upload_authorization(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_lock_upload_authorization(p_document uuid, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_private_documents%rowtype; locked_d public.fin_private_documents%rowtype;
  m public.fin_members%rowtype; v_entity uuid; v_parent uuid; v_grant uuid;
begin
  select * into d from public.fin_private_documents where id=p_document;
  if not found or p_actor is null or d.removed_at is not null then return false; end if;
  select * into m from public.fin_members
    where organization_id=d.organization_id and user_id=p_actor for share;
  if not found then return false; end if;
  if d.organization_id=d.buyer_organization_id then
    if m.role not in ('admin','finance_manager','analyst') then return false; end if;
    if d.entity_type='rfq' then
      select legal_entity_id into v_entity from public.fin_rfqs where id=d.entity_id and organization_id=d.organization_id for share;
      if not found then return false; end if;
    elsif d.entity_type='contract' then
      select legal_entity_id into v_entity from public.fin_contracts where id=d.entity_id and organization_id=d.organization_id for share;
      if not found then return false; end if;
    elsif d.entity_type='profile' then
      v_entity := case when d.entity_id=d.organization_id then null else d.entity_id end;
    else return false;
    end if;
    if v_entity is not null then
      select parent_id into v_parent from public.fin_legal_entities
        where id=v_entity and organization_id=d.organization_id for share;
      if not found then return false; end if;
    end if;
    if m.entity_scope <> 'group' then
      if v_entity is null then return false; end if;
      select entity_id into v_grant from public.fin_member_entity_grants
        where organization_id=d.organization_id and user_id=p_actor
          and entity_id in (v_entity,v_parent) order by entity_id limit 1 for share;
      if not found then return false; end if;
    end if;
  else
    if m.role not in ('admin','provider_user') or d.entity_type <> 'proposal' then return false; end if;
    perform 1 from public.fin_proposals where id=d.entity_id
      and provider_organization_id=d.organization_id and buyer_organization_id=d.buyer_organization_id for share;
    if not found then return false; end if;
  end if;
  select * into locked_d from public.fin_private_documents where id=p_document for update;
  return found and locked_d.removed_at is null
    and locked_d.organization_id=d.organization_id and locked_d.buyer_organization_id=d.buyer_organization_id
    and locked_d.entity_type=d.entity_type and locked_d.entity_id=d.entity_id;
end $$;


ALTER FUNCTION public.fin_document_lock_upload_authorization(p_document uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: fin_document_mime_allowed(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_mime_allowed(p_mime text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_mime = any (array[
    'application/pdf', 'image/jpeg', 'image/png',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ]);
$$;


ALTER FUNCTION public.fin_document_mime_allowed(p_mime text) OWNER TO postgres;

--
-- Name: fin_document_pending_upload(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_pending_upload(p_document uuid, p_version integer) RETURNS TABLE(bucket text, path text, mime_type text, size_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from public.fin_document_versions v where v.document_id=p_document
      and v.version=p_version and v.status='pending' and v.uploaded_by=auth.uid()
      and v.created_at > now()-interval '10 minutes') then return; end if;
  if not public.fin_document_lock_upload_authorization(p_document,auth.uid()) then return; end if;
  return query select v.storage_bucket,v.storage_path,v.mime_type,v.size_bytes
    from public.fin_document_versions v where v.document_id=p_document and v.version=p_version
      and v.status='pending' and v.uploaded_by=auth.uid() and v.created_at > now()-interval '10 minutes';
end $$;


ALTER FUNCTION public.fin_document_pending_upload(p_document uuid, p_version integer) OWNER TO postgres;

--
-- Name: fin_document_remove(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_document_remove(p_document uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_doc public.fin_private_documents%rowtype;
begin
  select * into v_doc from public.fin_private_documents where id = p_document for update;
  if not found or v_doc.removed_at is not null then raise exception 'invalid document'; end if;
  -- Quem não alcança o documento (outra entidade) não o remove, mesmo com papel.
  if not public.fin_can_read_document(p_document) then raise exception 'forbidden'; end if;
  if not (public.fin_has_role(v_doc.organization_id, case when v_doc.organization_id = v_doc.buyer_organization_id
            then array['admin','finance_manager'] else array['admin'] end)
          or (v_doc.created_by = auth.uid() and public.fin_has_role(v_doc.organization_id))) then
    raise exception 'forbidden';
  end if;
  update public.fin_private_documents set removed_at = now(), removed_by = auth.uid() where id = p_document;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (v_doc.organization_id, v_doc.entity_type, v_doc.entity_id, 'document_removed', auth.uid(), jsonb_build_object('document_id', v_doc.id));
end $$;


ALTER FUNCTION public.fin_document_remove(p_document uuid) OWNER TO postgres;

--
-- Name: fin_email_limit(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_email_limit(p_key text, p_default integer, p_min integer, p_max integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select least(p_max, greatest(p_min, coalesce(
    case when public.fin_setting(p_key, '') ~ '^[0-9]{1,6}$' then public.fin_setting(p_key, '')::integer end, p_default)));
$_$;


ALTER FUNCTION public.fin_email_limit(p_key text, p_default integer, p_min integer, p_max integer) OWNER TO postgres;

--
-- Name: fin_enqueue_email(text, text, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_enqueue_email(p_template text, p_recipient text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_idempotency_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_hash text; v_org uuid; v_recipient text := lower(trim(coalesce(p_recipient, '')));
begin
  if public.fin_setting('email_enabled', 'false') <> 'true' then return false; end if;
  if v_recipient !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or length(v_recipient) > 254 then return false; end if;
  if p_template not in (
    'member_invite','provider_invite','rfq_opened','deadline_near',
    'proposal_received','proposal_revised','decision_recorded','renewal_due'
  ) then raise exception 'unknown template'; end if;
  v_org := case p_entity_type
    when 'rfq' then (select r.organization_id from public.fin_rfqs r where r.id = p_entity_id)
    when 'contract' then (select c.organization_id from public.fin_contracts c where c.id = p_entity_id)
    when 'organization' then (select o.id from public.fin_organizations o where o.id = p_entity_id)
    else null end;
  -- Sem origem conhecida não há como aplicar teto: não enfileira.
  if v_org is null then return false; end if;
  v_hash := encode(sha256(convert_to(v_recipient, 'UTF8')), 'hex');
  -- Repetição da mesma chave não conta de novo nem duplica.
  if exists (select 1 from public.transactional_email_outbox o where o.idempotency_key = p_idempotency_key) then return true; end if;
  -- Serializa as contagens da organização: rajadas concorrentes não passam do teto.
  perform pg_advisory_xact_lock(hashtextextended('fin_email_org:' || v_org::text, 0));
  if (select count(*) from public.transactional_email_outbox o
       where o.organization_id = v_org and o.status in ('pending','retry','processing'))
       >= public.fin_email_limit('email_org_pending_limit', 200, 20, 2000)
     or (select count(*) from public.transactional_email_outbox o
       where o.organization_id = v_org and o.created_at > now() - interval '1 hour')
       >= public.fin_email_limit('email_org_hourly_limit', 60, 5, 1000)
     or (select count(*) from public.transactional_email_outbox o
       where o.organization_id = v_org and o.created_at > now() - interval '24 hours')
       >= public.fin_email_limit('email_org_daily_limit', 300, 20, 5000) then
    raise exception 'email volume limit';
  end if;
  -- Destinatário protegido de repetição (mesma organização e todas somadas):
  -- o e-mail é suprimido, o convite segue valendo pelo link manual.
  if (select count(*) from public.transactional_email_outbox o
       where o.recipient_hash = v_hash and o.template = 'finance_' || p_template
         and o.organization_id = v_org and o.created_at > now() - interval '24 hours')
       >= public.fin_email_limit('email_org_recipient_daily_limit', 3, 1, 20)
     or (select count(*) from public.transactional_email_outbox o
       where o.recipient_hash = v_hash and o.template = 'finance_' || p_template
         and o.created_at > now() - interval '24 hours')
       >= public.fin_email_limit('email_recipient_daily_limit', 5, 1, 50) then
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
      values (v_org, coalesce(p_entity_type, 'organization'), p_entity_id, 'email_suppressed', auth.uid(),
              jsonb_build_object('template', p_template, 'reason', 'recipient_limit'));
    return false;
  end if;
  insert into public.transactional_email_outbox (
    event_type, entity_type, entity_id, template, recipient_hash, recipient_address,
    payload, request_id, idempotency_key, organization_id
  ) values (
    'finance_' || p_template, p_entity_type, p_entity_id::text, 'finance_' || p_template, v_hash, v_recipient,
    coalesce(p_payload, '{}'::jsonb), 'finance-' || p_entity_id::text, p_idempotency_key, v_org
  ) on conflict (idempotency_key) do nothing;
  return true;
end $_$;


ALTER FUNCTION public.fin_enqueue_email(p_template text, p_recipient text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fin_enqueue_notification_email(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_enqueue_notification_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_email text; v_path text; v_kind text; v_hash text;
begin
  if new.event_type not in ('mention','approval_requested','approval_approved','approval_rejected',
      'approval_changes_requested','proposal_received','proposal_revised','renewal_due') then return new; end if;
  if not exists (select 1 from public.fin_notification_preferences p where p.organization_id = new.organization_id
      and p.user_id = new.user_id and p.event_type = new.event_type and p.email) then return new; end if;
  if public.fin_setting('email_enabled', 'false') <> 'true' then return new; end if;
  select email into v_email from auth.users where id = new.user_id;
  if v_email is null then return new; end if;
  v_hash := encode(sha256(convert_to(lower(trim(v_email)), 'UTF8')), 'hex');
  if (select count(*) from public.transactional_email_outbox o where o.recipient_hash = v_hash
      and o.template = 'finance_notification' and o.created_at > now() - interval '1 hour') >= 20 then return new; end if;
  if (select count(*) from public.transactional_email_outbox o where o.organization_id = new.organization_id
      and o.status in ('pending','retry','processing')) >= public.fin_email_limit('email_org_pending_limit', 200, 20, 2000) then return new; end if;
  v_path := case new.object_type
    when 'rfq' then '/finance/rfq.html?id=' || new.object_id::text
    when 'contract' then '/finance/contracts.html#contract-' || new.object_id::text
    else '/finance/notifications.html' end;
  v_kind := case when new.event_type like 'approval_%' then 'approval' when new.event_type like 'proposal_%' then 'proposal' else new.event_type end;
  insert into public.transactional_email_outbox (
    event_type, entity_type, entity_id, template, recipient_hash, recipient_address, payload, request_id, idempotency_key, organization_id
  ) values (
    'finance_notification', new.object_type, new.object_id::text, 'finance_notification', v_hash, lower(trim(v_email)),
    jsonb_build_object('kind', v_kind, 'event', new.event_type, 'path', v_path), 'finance-notification-' || new.id::text,
    'notification:' || new.id::text, new.organization_id
  ) on conflict (idempotency_key) do nothing;
  return new;
end $$;


ALTER FUNCTION public.fin_enqueue_notification_email() OWNER TO postgres;

--
-- Name: fin_entity_allows(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_entity_allows(p_org uuid, p_entity uuid, p_roles text[] DEFAULT NULL::text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1 from public.fin_members m
     where m.organization_id = p_org and m.user_id = auth.uid()
       and (p_roles is null or m.role = any(p_roles))
       and (m.entity_scope = 'group' or (p_entity is not null and exists (
         select 1 from public.fin_legal_entities e
           join public.fin_member_entity_grants g
             on g.organization_id = e.organization_id and g.user_id = m.user_id
            and (g.entity_id = e.id or g.entity_id = e.parent_id)
          where e.organization_id = p_org and e.id = p_entity))));
$$;


ALTER FUNCTION public.fin_entity_allows(p_org uuid, p_entity uuid, p_roles text[]) OWNER TO postgres;

