--
-- Name: fin_external_command(uuid, integer, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_command(p_id uuid, p_expected integer, p_revision integer, p_key text, p_operation text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.fin_rfqs%rowtype; old_id uuid; old_hash text; h text; e jsonb; result_id uuid; d public.fin_decisions%rowtype; ct public.fin_contracts%rowtype; ct_terms jsonb; pair record;
begin
 select r0.* into r from public.fin_rfqs r0 join public.fin_external_proposals p on p.rfq_id=r0.id where p.id=p_id for no key update of r0;
 if r.id is null then raise exception 'forbidden'; end if;
 perform public.fin_external_require_actor(r.organization_id,r.legal_entity_id,array['admin','finance_manager']);
 if p_key is null or p_key !~ '^[A-Za-z0-9._:-]{8,80}$' or p_operation is null or p_operation not in ('decision','approval','contract')
 or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>32768 then raise exception 'invalid external command'; end if;
 h:=encode(sha256(convert_to(jsonb_build_object('actor',auth.uid(),'id',p_id,'version',p_expected,'revision',p_revision,'operation',p_operation,'payload',case when p_operation='decision' then jsonb_build_object('weights',p_payload->'criteria'->'weights','rationale',p_payload->'rationale') else p_payload end)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('external-command:'||r.organization_id||':'||p_key,0));
 if p_operation='decision' then select id,external_request_hash into old_id,old_hash from public.fin_decisions where organization_id=r.organization_id and external_request_key=p_key;
 elsif p_operation='approval' then select id,external_request_hash into old_id,old_hash from public.fin_approval_requests where organization_id=r.organization_id and external_request_key=p_key;
 else select id,external_request_hash into old_id,old_hash from public.fin_contracts where organization_id=r.organization_id and external_request_key=p_key; end if;
 if old_id is not null then
  if old_hash is distinct from h then raise exception 'external intent conflict'; end if;
  return jsonb_build_object('id',old_id,'replayed',true,'operation',p_operation);
 end if;
 e:=public.fin_external_lock_source(p_id,p_expected,p_revision,array['admin','finance_manager']);
 perform set_config('arandu.external_intent',jsonb_build_object('actor',auth.uid(),'rfq',r.id,'id',p_id,'version',p_expected,'revision',p_revision,'key',p_key,'hash',h,'operation',p_operation)::text,true);
 if p_operation='decision' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('criteria','rationale')) then raise exception 'invalid external command'; end if;
  result_id:=public.fin_record_decision_v2(r.id,p_id,p_expected,coalesce(p_payload->'criteria','{}'::jsonb),p_payload->>'rationale');
 elsif p_operation='approval' then
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('assignments','approver_ids','rationale','justification','declared')) then raise exception 'invalid external command'; end if;
  if p_payload ? 'assignments' then
   result_id:=public.fin_request_policy_approval(r.id,p_id,p_payload->'assignments',p_payload->>'rationale',p_payload->>'justification',coalesce(p_payload->'declared','{}'::jsonb));
  else
   if jsonb_typeof(p_payload->'approver_ids') is distinct from 'array' then raise exception 'invalid external command'; end if;
   result_id:=public.fin_request_approval(r.id,p_id,array(select jsonb_array_elements_text(p_payload->'approver_ids'))::uuid[],p_payload->>'rationale');
  end if;
 else
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('decision_id','contract_id','expected_contract_version','confirmed_contract_record')) or p_payload->'confirmed_contract_record' is distinct from 'true'::jsonb then raise exception 'invalid external contract confirmation'; end if;
  select * into d from public.fin_decisions where id=(p_payload->>'decision_id')::uuid and organization_id=r.organization_id and rfq_id=r.id for update;
  if d.id is null or d.external_proposal_id is distinct from p_id or d.external_proposal_version is distinct from p_expected then raise exception 'external decision conflict'; end if;
  select * into ct from public.fin_contracts where id=(p_payload->>'contract_id')::uuid and organization_id=r.organization_id for update;
  if ct.id is null or ct.origin<>'imported' or ct.decision_id is not null or ct.provider_id is distinct from (e->>'provider_id')::uuid
   or ct.legal_entity_id is distinct from r.legal_entity_id or ct.product<>r.product or ct.current_version<1
   or ct.current_version is distinct from (p_payload->>'expected_contract_version')::integer
   or (e->>'currency' is not null and ct.currency is distinct from e->>'currency') then raise exception 'external contract conflict'; end if;
  select terms into ct_terms from public.fin_contract_versions where contract_id=ct.id and version=ct.current_version;
  -- Compare only explicit values on the same basis; never convert annual/monthly rates.
  for pair in select * from (values ('offered_amount','principal_amount'),('interest_rate_month','rate_pct_month'),
    ('index_spread','spread_pct_year'),('index','indexer'),('amortization','amortization'),
    ('mdr_debit','mdr_debit_pct'),('mdr_credit_cash','mdr_credit_pct'),('mdr_credit_installment','mdr_installment_pct'),('pix_fee','pix_pct'),('anticipation_rate','anticipation_pct_month'),('settlement_days','settlement_days')) m(source_key,contract_key) loop
   if e->'terms'->pair.source_key is not null and e->'terms'->pair.source_key<>'null'::jsonb
    and ct_terms->pair.contract_key is not null and ct_terms->pair.contract_key<>'null'::jsonb
    and e->'terms'->pair.source_key is distinct from ct_terms->pair.contract_key then raise exception 'external contract conflict'; end if;
  end loop;
  if r.product='credit' and e->'terms'->>'term_months' is not null
   and ct.ends_on not in ((ct.starts_on+make_interval(months=>(e->'terms'->>'term_months')::integer))::date,
    (ct.starts_on+make_interval(months=>(e->'terms'->>'term_months')::integer))::date-1) then raise exception 'external contract conflict'; end if;
  if exists(select 1 from public.fin_contracts where decision_id=d.id) then raise exception 'external contract conflict'; end if;
  update public.fin_contracts set decision_id=d.id,external_proposal_id=p_id,external_proposal_version=p_expected,
   external_request_key=p_key,external_request_hash=h,updated_at=now() where id=ct.id;
  update public.fin_rfqs set status='contracted',updated_at=now() where id=r.id;
  result_id:=ct.id;
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
   values(r.organization_id,'contract',ct.id,'external_decision_linked',auth.uid(),jsonb_build_object('decision_id',d.id,'external_proposal_id',p_id,'version',p_expected,'signature','not_verified'));
 end if;
 perform set_config('arandu.external_intent','',true);
 return jsonb_build_object('id',result_id,'replayed',false,'operation',p_operation);
end $_$;


ALTER FUNCTION public.fin_external_command(p_id uuid, p_expected integer, p_revision integer, p_key text, p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: fin_external_contract_identity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_contract_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if old.external_proposal_id is not null and
 (new.external_proposal_id,new.external_proposal_version,new.external_request_key,new.external_request_hash,new.decision_id,new.organization_id,new.provider_id,new.product,new.legal_entity_id)
 is distinct from (old.external_proposal_id,old.external_proposal_version,old.external_request_key,old.external_request_hash,old.decision_id,old.organization_id,old.provider_id,old.product,old.legal_entity_id) then raise exception 'immutable external contract source'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_external_contract_identity_guard() OWNER TO postgres;

--
-- Name: fin_external_document_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_document_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if exists(select 1 from public.fin_external_proposal_versions where document_id=old.id) and
  ((new.organization_id,new.buyer_organization_id,new.entity_type,new.entity_id,new.rfq_id) is distinct from
   (old.organization_id,old.buyer_organization_id,old.entity_type,old.entity_id,old.rfq_id) or new.visibility<>'internal') then raise exception 'invalid external document'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_external_document_guard() OWNER TO postgres;

--
-- Name: fin_external_identity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if (new.id,new.organization_id,new.legal_entity_id,new.rfq_id,new.provider_id,new.product,new.request_key,new.request_hash,new.recorded_by,new.recorded_at)
 is distinct from (old.id,old.organization_id,old.legal_entity_id,old.rfq_id,old.provider_id,old.product,old.request_key,old.request_hash,old.recorded_by,old.recorded_at) then raise exception 'external proposal identity immutable'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_external_identity_guard() OWNER TO postgres;

--
-- Name: fin_external_lock_source(uuid, integer, integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_lock_source(p_id uuid, p_expected integer, p_revision integer, p_roles text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_rfqs%rowtype; e public.fin_external_proposal_current%rowtype;
begin
 select r0.* into r from public.fin_rfqs r0 join public.fin_external_proposals p on p.rfq_id=r0.id where p.id=p_id for no key update of r0;
 if r.id is null then raise exception 'forbidden'; end if;
 perform public.fin_external_require_actor(r.organization_id,r.legal_entity_id,p_roles);
 perform 1 from public.fin_external_proposals where id=p_id for share;
 select * into e from public.fin_external_proposal_current where id=p_id;
 if e.document_id is not null then
  perform 1 from public.fin_private_documents where id=e.document_id for share;
  perform 1 from public.fin_document_versions where document_id=e.document_id and version=e.document_version for share;
  select * into e from public.fin_external_proposal_current where id=p_id;
 end if;
 if p_expected is null or p_revision is null or e.current_version is distinct from p_expected or r.revision is distinct from p_revision or e.rfq_revision is distinct from p_revision then raise exception 'external version conflict'; end if;
 if e.state<>'reviewed' or e.reviewed_by is null then raise exception 'external review required'; end if;
 if e.document_id is not null and not e.document_available then raise exception 'external document conflict'; end if;
 if exists(select 1 from public.fin_proposals where id=p_id) then raise exception 'external identity conflict'; end if;
 return to_jsonb(e)||jsonb_build_object('snapshot_version',1,'issuer_identity','buyer_attribution','signature','not_verified','credit_approval','not_recorded','disbursement','not_recorded','notice','Transcrição conferida pela empresa; não autentica o emissor nem representa aceite, assinatura, concessão ou desembolso.');
end $$;


ALTER FUNCTION public.fin_external_lock_source(p_id uuid, p_expected integer, p_revision integer, p_roles text[]) OWNER TO postgres;

--
-- Name: fin_external_preview(uuid, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_preview(p_id uuid, p_expected integer, p_revision integer, p_declared jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e jsonb;
begin
 e:=public.fin_external_lock_source(p_id,p_expected,p_revision,array['admin','finance_manager']);
 return public.fin_policy_evaluate((e->>'rfq_id')::uuid,p_id,p_declared);
end $$;


ALTER FUNCTION public.fin_external_preview(p_id uuid, p_expected integer, p_revision integer, p_declared jsonb) OWNER TO postgres;

--
-- Name: fin_external_proposal_review(uuid, integer, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_proposal_review(p_id uuid, p_expected integer, p_action text, p_reason text, p_material_reviewed boolean, p_document_read boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_rfqs%rowtype; p public.fin_external_proposals%rowtype; v public.fin_external_proposal_versions%rowtype;
 old_review public.fin_external_proposal_reviews%rowtype; d public.fin_private_documents%rowtype; result_id uuid;
begin
 select r0.* into r from public.fin_external_proposals p0 join public.fin_rfqs r0 on r0.id=p0.rfq_id where p0.id=p_id for no key update of r0;
 if r.id is null then raise exception 'forbidden'; end if;
 perform public.fin_external_require_actor(r.organization_id,r.legal_entity_id,array['admin','finance_manager']);
 select * into p from public.fin_external_proposals where id=p_id for update;
 if p.current_version is distinct from p_expected then raise exception 'external proposal conflict'; end if;
 if p_action is null or p_action not in ('confirm','withdraw') or p_material_reviewed is distinct from true
 or length(trim(coalesce(p_reason,''))) not between 10 and 1000 then raise exception 'invalid external review'; end if;
 select * into old_review from public.fin_external_proposal_reviews where proposal_id=p.id and version=p_expected and action=p_action;
 if found then
  if old_review.reason<>p_reason or old_review.document_read is distinct from coalesce(p_document_read,false) or (p_action='confirm' and p.state<>'reviewed') then raise exception 'external proposal conflict'; end if;
  return old_review.id;
 end if;
 select * into v from public.fin_external_proposal_versions where proposal_id=p.id and version=p_expected;
 if p_action='confirm' then
  if p.state<>'pending_review' or v.terms='{}'::jsonb then raise exception 'external review required'; end if;
  if v.rfq_revision<>r.revision then raise exception 'external rfq revision conflict'; end if;
  if v.document_id is not null then
   select * into d from public.fin_private_documents where id=v.document_id for share;
   if d.removed_at is not null or not public.fin_can_read_document(d.id) or p_document_read is distinct from true then raise exception 'invalid external document'; end if;
  end if;
 elsif p.state='withdrawn' then raise exception 'external proposal conflict'; end if;
 insert into public.fin_external_proposal_reviews(organization_id,proposal_id,version,action,reason,document_read,reviewed_by)
 values(p.organization_id,p.id,p_expected,p_action,p_reason,coalesce(p_document_read,false),auth.uid()) returning id into result_id;
 update public.fin_external_proposals set state=case when p_action='confirm' then 'reviewed' else 'withdrawn' end where id=p.id;
 insert into public.fin_events(organization_id,legal_entity_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(r.organization_id,r.legal_entity_id,'rfq',r.id,'external_proposal_'||p_action,auth.uid(),jsonb_build_object('proposal_id',p.id,'version',p_expected));
 return result_id;
end $$;


ALTER FUNCTION public.fin_external_proposal_review(p_id uuid, p_expected integer, p_action text, p_reason text, p_material_reviewed boolean, p_document_read boolean) OWNER TO postgres;

--
-- Name: fin_external_proposal_save(uuid, uuid, text, integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_proposal_save(p_rfq uuid, p_provider uuid, p_key text, p_expected integer, p_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.fin_rfqs%rowtype; p public.fin_external_proposals%rowtype; v public.fin_external_proposal_versions%rowtype;
 d public.fin_private_documents%rowtype; f public.fin_document_versions%rowtype; h text; n integer; result_id uuid;
begin
 select * into r from public.fin_rfqs where id=p_rfq for no key update;
 if r.id is null then raise exception 'forbidden'; end if;
 perform public.fin_external_require_actor(r.organization_id,r.legal_entity_id,array['admin','finance_manager','analyst']);
 if p_key is null or p_key !~ '^[A-Za-z0-9._:-]{8,80}$' then raise exception 'invalid external request'; end if;
 if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>40000
 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('terms','state','channel','received_at','source_reference','currency','rfq_revision','document_id','document_version','correction_reason')) then raise exception 'invalid external input'; end if;
 h:=encode(sha256(convert_to(jsonb_build_object('rfq',p_rfq,'provider',p_provider,'expected',p_expected,'input',p_input)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('external:'||r.organization_id||':'||coalesce(p_id::text,p_key),0));
 if p_id is null then
  select * into p from public.fin_external_proposals where organization_id=r.organization_id and request_key=p_key;
  if found then
   if p.request_hash<>h then raise exception 'external proposal conflict'; end if;
   return jsonb_build_object('id',p.id,'version',1,'replayed',true);
  end if;
  if p_expected is distinct from 0 then raise exception 'external proposal conflict'; end if;
 else
  select * into p from public.fin_external_proposals where id=p_id and organization_id=r.organization_id for update;
  if not found or p.rfq_id<>p_rfq or p.provider_id<>p_provider then raise exception 'forbidden'; end if;
  select * into v from public.fin_external_proposal_versions where proposal_id=p.id and request_key=p_key;
  if found then
   if v.request_hash<>h then raise exception 'external proposal conflict'; end if;
   return jsonb_build_object('id',p.id,'version',v.version,'replayed',true);
  end if;
  if p_expected is distinct from p.current_version or p.state='withdrawn' then raise exception 'external proposal conflict'; end if;
  if length(trim(coalesce(p_input->>'correction_reason',''))) not between 10 and 1000 or p_input->>'correction_reason' ~ '[<>]' then raise exception 'invalid external correction'; end if;
 end if;
 if r.status in ('closed','cancelled') then raise exception 'external proposal closed'; end if;
 if not exists(select 1 from public.fin_providers where id=p_provider and organization_id=r.organization_id) then raise exception 'invalid external provider'; end if;
 if (p_input->>'rfq_revision')::integer is distinct from r.revision then raise exception 'external rfq revision conflict'; end if;
 if length(trim(coalesce(p_input->>'source_reference',''))) not between 3 and 500 or p_input->>'source_reference' ~ '[<>]'
 or (nullif(p_input->>'currency','') is not null and p_input->>'currency' !~ '^[A-Z]{3}$') then raise exception 'invalid external input'; end if;
 if p_input->>'state' is null or p_input->>'state' not in ('preparing','pending_review')
 or p_input->>'channel' is null or p_input->>'channel' not in ('email','document','spreadsheet','formal_communication','manual')
 or jsonb_typeof(p_input->'source_reference') is distinct from 'string'
 or (p_input->>'received_at' is not null and (not isfinite((p_input->>'received_at')::timestamptz) or (p_input->>'received_at')::timestamptz > now()))
 or not public.fin_external_terms_valid(r.product,p_input->'terms') then raise exception 'invalid external input'; end if;
 if nullif(p_input->>'document_id','') is not null then
  select * into d from public.fin_private_documents where id=(p_input->>'document_id')::uuid for share;
  select * into f from public.fin_document_versions where document_id=d.id and version=(p_input->>'document_version')::integer for share;
  if d.id is null or d.organization_id<>r.organization_id or d.entity_type<>'rfq' or d.entity_id<>r.id or d.visibility<>'internal' or d.removed_at is not null
   or f.version is null or f.status<>'available' or not public.fin_can_read_document(d.id) then raise exception 'invalid external document'; end if;
 elsif nullif(p_input->>'document_version','') is not null then raise exception 'invalid external document'; end if;
 result_id:=coalesce(p.id,gen_random_uuid()); n:=coalesce(p.current_version,0)+1;
 if p.id is null then
  insert into public.fin_external_proposals(id,organization_id,legal_entity_id,rfq_id,provider_id,product,state,current_version,request_key,request_hash,recorded_by)
  values(result_id,r.organization_id,r.legal_entity_id,r.id,p_provider,r.product,p_input->>'state',1,p_key,h,auth.uid());
 end if;
 insert into public.fin_external_proposal_versions(proposal_id,version,organization_id,terms,preparation_state,channel,received_at,source_reference,currency,rfq_revision,
 document_id,document_version,document_sha256,document_mime,document_size,correction_reason,request_key,request_hash,recorded_by)
 values(result_id,n,r.organization_id,p_input->'terms',p_input->>'state',p_input->>'channel',(p_input->>'received_at')::timestamptz,p_input->>'source_reference',
 nullif(p_input->>'currency',''),r.revision,d.id,f.version,f.sha256,f.mime_type,f.size_bytes,p_input->>'correction_reason',p_key,h,auth.uid());
 if p.id is not null then update public.fin_external_proposals set current_version=n,state=p_input->>'state' where id=result_id; end if;
 insert into public.fin_events(organization_id,legal_entity_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(r.organization_id,r.legal_entity_id,'rfq',r.id,'external_proposal_recorded',auth.uid(),jsonb_build_object('proposal_id',result_id,'version',n));
 return jsonb_build_object('id',result_id,'version',n,'replayed',false);
end $_$;


ALTER FUNCTION public.fin_external_proposal_save(p_rfq uuid, p_provider uuid, p_key text, p_expected integer, p_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_external_proposal_schema(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_proposal_schema() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select '{"credit":[{"key":"offered_amount","type":"money","min":0,"max":1000000000000},{"key":"interest_rate_month","type":"percent","min":0,"max":1000},{"key":"index","type":"enum","options":["pre","cdi","ipca","selic","tr","outro"]},{"key":"index_spread","type":"percent","min":0,"max":1000},{"key":"cet_year","type":"percent","min":0,"max":1000},{"key":"term_months","type":"int","min":1,"max":600},{"key":"grace_months","type":"int","min":0,"max":120},{"key":"amortization","type":"enum","options":["price","sac","bullet","customizada"]},{"key":"collateral_required","type":"text","max":1000},{"key":"fees_amount","type":"money","min":0,"max":1000000000000},{"key":"declared_total_cost","type":"money","min":0,"max":1000000000000},{"key":"institution","type":"text","max":200},{"key":"product_name","type":"text","max":200},{"key":"valid_until","type":"date"},{"key":"contracting_days","type":"int","min":0,"max":3650},{"key":"conditions_precedent","type":"text","max":2000},{"key":"notes","type":"text","max":2000}],"acquiring":[{"key":"mdr_debit","type":"percent","min":0,"max":100},{"key":"mdr_credit_cash","type":"percent","min":0,"max":100},{"key":"mdr_credit_installment","type":"percent","min":0,"max":100},{"key":"pix_fee","type":"percent","min":0,"max":100},{"key":"anticipation_rate","type":"percent","min":0,"max":1000},{"key":"terminal_rent","type":"money","min":0,"max":1000000},{"key":"gateway_cost","type":"money","min":0,"max":1000000},{"key":"settlement_days","type":"int","min":0,"max":365},{"key":"chargeback_terms","type":"text","max":1000},{"key":"contract_months","type":"int","min":0,"max":600},{"key":"early_exit_penalty","type":"money","min":0,"max":1000000000},{"key":"extra_services","type":"text","max":1000},{"key":"institution","type":"text","max":200},{"key":"product_name","type":"text","max":200},{"key":"valid_until","type":"date"},{"key":"contracting_days","type":"int","min":0,"max":3650},{"key":"conditions_precedent","type":"text","max":2000},{"key":"notes","type":"text","max":2000}]}'::jsonb;
$$;


ALTER FUNCTION public.fin_external_proposal_schema() OWNER TO postgres;

--
-- Name: fin_external_require_actor(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_require_actor(p_org uuid, p_entity uuid, p_roles text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if auth.uid() is null then raise exception 'forbidden'; end if;
 perform 1 from public.fin_members where organization_id=p_org and user_id=auth.uid() for share;
 perform 1 from public.fin_member_entity_grants where organization_id=p_org and user_id=auth.uid() for share;
 if not public.fin_entity_allows(p_org,p_entity,p_roles) or not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden'; end if;
 if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
end $$;


