--
-- Name: fin_external_rfq_scope_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_rfq_scope_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if new.legal_entity_id is distinct from old.legal_entity_id and exists(select 1 from public.fin_external_proposals where rfq_id=old.id) then raise exception 'external proposal identity immutable'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_external_rfq_scope_guard() OWNER TO postgres;

--
-- Name: fin_external_selected_source_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_selected_source_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e jsonb; c jsonb; v integer;
begin
 if not exists(select 1 from public.fin_external_proposals where id=new.proposal_id) then return new; end if;
 c:=nullif(current_setting('arandu.external_intent',true),'')::jsonb;
 if c is null or c->>'actor' is distinct from auth.uid()::text or c->>'id' is distinct from new.proposal_id::text
 or c->>'rfq' is distinct from new.rfq_id::text or c->>'operation' is distinct from (case when tg_table_name='fin_decisions' then 'decision' else 'approval' end) then raise exception 'external command required'; end if;
 v:=(c->>'version')::integer;
 e:=public.fin_external_lock_source(new.proposal_id,v,(c->>'revision')::integer,array['admin','finance_manager']);
 new.external_proposal_id:=new.proposal_id; new.proposal_id:=null;
 new.external_rfq_revision:=(c->>'revision')::integer;
 new.external_request_key:=c->>'key'; new.external_request_hash:=c->>'hash';
 if tg_table_name='fin_decisions' then new.external_proposal_version:=v;
 elsif new.proposal_version is distinct from v then raise exception 'external version conflict'; end if;
 new.snapshot:=new.snapshot||jsonb_build_object('selected_source',e,'source_kind','buyer_recorded_external','decided_proposal_id',null,'decided_external_proposal_id',new.external_proposal_id);
 return new;
end $$;


ALTER FUNCTION public.fin_external_selected_source_guard() OWNER TO postgres;

--
-- Name: fin_external_terms_valid(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_external_terms_valid(p_product text, p_terms jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare k text; x jsonb; f jsonb; n numeric; begin
 if jsonb_typeof(p_terms) is distinct from 'object' or octet_length(p_terms::text)>32768 or not (public.fin_external_proposal_schema() ? p_product) then return false; end if;
 for k,x in select * from jsonb_each(p_terms) loop
  select value into f from jsonb_array_elements(public.fin_external_proposal_schema()->p_product) where value->>'key'=k;
  if f is null or x='null'::jsonb then return false; end if;
  if f->>'type' in ('money','percent','number','int') then
   if jsonb_typeof(x)<>'number' then return false; end if;
   n:=(x#>>'{}')::numeric;
   if (f ? 'min' and n<(f->>'min')::numeric) or (f ? 'max' and n>(f->>'max')::numeric) or (f->>'type'='int' and n<>trunc(n)) then return false; end if;
  elsif f->>'type'='text' then
   if jsonb_typeof(x)<>'string' or length(x#>>'{}') not between 1 and coalesce((f->>'max')::integer,2000) or (x#>>'{}') ~ '[<>]' then return false; end if;
  elsif f->>'type'='enum' then
   if jsonb_typeof(x)<>'string' or not ((f->'options') ? (x#>>'{}')) then return false; end if;
  elsif f->>'type'='date' then
   if jsonb_typeof(x)<>'string' or (x#>>'{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
   perform (x#>>'{}')::date;
  elsif f->>'type'='bool' then
   if jsonb_typeof(x)<>'boolean' then return false; end if;
  else return false; end if;
 end loop;
 return true;
 exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then return false;
end $_$;


ALTER FUNCTION public.fin_external_terms_valid(p_product text, p_terms jsonb) OWNER TO postgres;

--
-- Name: fin_extraction_fact_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_extraction_fact_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (to_jsonb(new) - array['status','confirmed_by','confirmed_at','rejection_reason']) is distinct from (to_jsonb(old) - array['status','confirmed_by','confirmed_at','rejection_reason'])
     or old.status not in ('extracted','needs_review') or new.status not in ('confirmed','rejected','superseded') then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_extraction_fact_guard() OWNER TO postgres;

--
-- Name: fin_extraction_schema_field(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_extraction_schema_field(p_schema text, p_field text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_schema
    when 'credit_proposal' then case when p_field in ('amount','currency','tenor_months','indexer','spread_pct_year','validity_date') then 'critical'
      when p_field in ('all_in_rate_pct_year','upfront_fee_pct','amortization','grace_months','collateral','covenants') then 'standard' end
    when 'acquiring_proposal' then case when p_field in ('mdr_debit_pct','mdr_credit_pct','mdr_installment_pct','anticipation_pct_month','validity_date') then 'critical'
      when p_field in ('pix_fee_pct','settlement_days','minimum_volume','terminal_fee') then 'standard' end
    when 'fee_schedule' then case when p_field in ('service','charging_unit','rate','currency','effective_from') then 'critical'
      when p_field in ('minimum_amount') then 'standard' end
    when 'contract_terms' then case when p_field in ('start_date','end_date','notice_days','amount_limit','currency') then 'critical'
      when p_field in ('indexer','spread_pct_year','renewal','termination') then 'standard' end
  end
$$;


ALTER FUNCTION public.fin_extraction_schema_field(p_schema text, p_field text) OWNER TO postgres;

--
-- Name: fin_facility_history_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_facility_history_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_old jsonb; v_new jsonb;
begin
  v_old := to_jsonb(old) - array['updated_at','created_at','created_by','notes'];
  v_new := to_jsonb(new) - array['updated_at','created_at','created_by','notes'];
  if v_old is distinct from v_new then
    insert into public.fin_facility_history(organization_id, facility_id, changed_by, previous, current)
      values (new.organization_id, new.id, auth.uid(),
        (select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) from jsonb_each(v_old) where v_new -> key is distinct from value),
        (select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) from jsonb_each(v_new) where v_old -> key is distinct from value));
  end if;
  return new;
end $$;


