--
-- Name: fin_governance_export_manifest(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_governance_export_manifest(p_export uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_data_exports%rowtype;
begin
  select * into x from public.fin_data_exports where id = p_export for update;
  if not found then raise exception 'forbidden'; end if;
  perform public.fin_governance_require_admin(x.organization_id);
  if x.status <> 'ready' or x.expires_at <= now() then raise exception 'export not available'; end if;
  update public.fin_data_exports set download_count = download_count + 1, last_downloaded_at = now() where id = p_export;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (x.organization_id, 'data_export', x.id, 'export_downloaded', auth.uid(), '{}'::jsonb);
  return x.manifest;
end $$;


ALTER FUNCTION public.fin_governance_export_manifest(p_export uuid) OWNER TO postgres;

--
-- Name: fin_governance_export_part(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_governance_export_part(p_export uuid, p_dataset text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_data_exports%rowtype; v_content text;
begin
  select * into x from public.fin_data_exports where id = p_export;
  if not found then raise exception 'forbidden'; end if;
  perform public.fin_governance_require_admin(x.organization_id);
  if x.status <> 'ready' or x.expires_at <= now() then raise exception 'export not available'; end if;
  select content into v_content from public.fin_data_export_parts where export_id = p_export and dataset = p_dataset;
  if not found then raise exception 'export not available'; end if;
  return v_content;
end $$;


ALTER FUNCTION public.fin_governance_export_part(p_export uuid, p_dataset text) OWNER TO postgres;

--
-- Name: fin_governance_export_part_range(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_governance_export_part_range(p_export uuid, p_dataset text, p_offset integer, p_length integer) RETURNS TABLE(content text, total_chars integer, next_offset integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_data_exports%rowtype; v_total integer;
begin
  if p_offset is null or p_offset < 0 or p_length is null or p_length < 1 or p_length > 4000000 then raise exception 'invalid export range'; end if;
  select * into x from public.fin_data_exports where id = p_export;
  if not found then raise exception 'forbidden'; end if;
  perform public.fin_governance_require_admin(x.organization_id);
  if x.status <> 'ready' or x.expires_at <= now() then raise exception 'export not available'; end if;
  select char_length(p.content) into v_total from public.fin_data_export_parts p where p.export_id = p_export and p.dataset = p_dataset;
  if not found then raise exception 'export not available'; end if;
  if p_offset > v_total then raise exception 'invalid export range'; end if;
  update public.fin_data_exports set download_count = download_count + 1, last_downloaded_at = now() where id = p_export and p_offset = 0;
  return query select substring(p.content from p_offset + 1 for p_length), v_total,
    case when p_offset + p_length >= v_total then null else p_offset + p_length end
    from public.fin_data_export_parts p where p.export_id = p_export and p.dataset = p_dataset;
end $$;


ALTER FUNCTION public.fin_governance_export_part_range(p_export uuid, p_dataset text, p_offset integer, p_length integer) OWNER TO postgres;

--
-- Name: fin_governance_export_parts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_governance_export_parts(p_export uuid) RETURNS TABLE(dataset text, sha256 text, content text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_data_exports%rowtype;
begin
  select * into x from public.fin_data_exports e where e.id = p_export;
  if not found then raise exception 'forbidden'; end if;
  perform public.fin_governance_require_admin(x.organization_id);
  if x.status <> 'ready' or x.expires_at <= now() then raise exception 'export not available'; end if;
  return query select p.dataset, p.sha256, p.content from public.fin_data_export_parts p where p.export_id = p_export order by p.dataset;
end $$;


ALTER FUNCTION public.fin_governance_export_parts(p_export uuid) OWNER TO postgres;

--
-- Name: fin_governance_hold_blocks(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_governance_hold_blocks(p_org uuid, p_class text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.fin_legal_holds h where h.organization_id = p_org and h.status = 'active'
                  and (p_class is null or h.scope_type <> 'retention_class' or h.scope_class = p_class));
$$;


