-- Name: fin_group_or_entity_visible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_group_or_entity_visible(p_org uuid, p_entity uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.fin_has_role(p_org) and (p_entity is null or public.fin_entity_visible(p_org, p_entity))
     and exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER');
$$;


