-- Name: fin_immutable_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_immutable_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and current_user = 'service_role'
     and exists (select 1 from public.fin_settings where key = 'deployment_environment' and value = 'demo') then
    return old;
  end if;
  raise exception 'immutable record';
end $$;


