--
-- Name: fin_implementation_dependency_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_implementation_dependency_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if (select position from public.fin_implementation_milestones where id=new.depends_on_id and plan_id=new.plan_id) >= (select position from public.fin_implementation_milestones where id=new.milestone_id and plan_id=new.plan_id) then raise exception 'invalid implementation dependency'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_implementation_dependency_guard() OWNER TO postgres;

--
-- Name: fin_implementation_issue(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_implementation_issue(p_plan uuid, p_issue uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_implementation_plans%rowtype; v_id uuid; v_owner uuid; v_mid uuid; begin
 p:=public.fin_implementation_require(p_plan,array['admin','finance_manager','analyst']);
 if p.status in ('accepted','cancelled') then raise exception 'implementation closed'; end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' then raise exception 'invalid implementation input'; end if;
 if p_issue is null then
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('title','owner_id','due_on','milestone_id')) then raise exception 'invalid implementation input'; end if;
 v_owner:=coalesce(nullif(p_input->>'owner_id','')::uuid,auth.uid()); v_mid:=nullif(p_input->>'milestone_id','')::uuid;
 if not public.fin_implementation_owner_valid(p.organization_id,p.legal_entity_id,v_owner) then raise exception 'invalid implementation owner'; end if;
 insert into public.fin_implementation_issues(organization_id,plan_id,milestone_id,title,owner_id,due_on,opened_by) values(p.organization_id,p.id,v_mid,trim(p_input->>'title'),v_owner,(p_input->>'due_on')::date,auth.uid()) returning id into v_id;
 else
 if exists(select 1 from jsonb_object_keys(p_input) k where k<>'resolution_reference') then raise exception 'invalid implementation input'; end if;
 update public.fin_implementation_issues set status='resolved',resolution_reference=trim(p_input->>'resolution_reference'),resolved_by=auth.uid(),resolved_at=now() where id=p_issue and plan_id=p.id and status='open' returning id into v_id;
 if v_id is null then raise exception 'implementation conflict'; end if;
 end if;
 update public.fin_implementation_plans set status=case when exists(select 1 from public.fin_implementation_issues where plan_id=p.id and status='open') or exists(select 1 from public.fin_implementation_milestones where plan_id=p.id and status='blocked') then 'blocked' when not exists(select 1 from public.fin_implementation_milestones where plan_id=p.id and status<>'completed') then 'ready_for_acceptance' else 'in_progress' end,version=version+1,updated_at=now() where id=p.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'implementation_issue_changed',auth.uid(),p.legal_entity_id,jsonb_build_object('issue_id',v_id,'resolved',p_issue is not null));
 return v_id;
end $$;


ALTER FUNCTION public.fin_implementation_issue(p_plan uuid, p_issue uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_implementation_milestone_label(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_implementation_milestone_label(p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'documentation' then 'Documentação'
    when 'legal_review' then 'Revisão jurídica'
    when 'signing' then 'Assinatura'
    when 'conditions_precedent' then 'Condições precedentes'
    when 'collateral' then 'Garantias'
    when 'guarantees' then 'Garantias'
    when 'facility_setup' then 'Configuração da linha'
    when 'availability_confirmation' then 'Confirmação de disponibilidade'
    when 'drawdown_readiness' then 'Preparação para liberação'
    when 'go_live' then 'Entrada em produção'
    when 'commercial_setup' then 'Configuração comercial'
    when 'credentials' then 'Credenciais'
    when 'integration' then 'Integração'
    when 'establishments' then 'Estabelecimentos'
    when 'homologation' then 'Homologação'
    when 'pricing_activation' then 'Ativação de preços'
    when 'settlement_validation' then 'Validação de liquidação'
    when 'kickoff' then 'Reunião inicial'
    when 'configuration' then 'Configuração'
    when 'validation' then 'Validação'
    else initcap(replace(coalesce(p_kind, ''), '_', ' '))
  end
$$;


ALTER FUNCTION public.fin_implementation_milestone_label(p_kind text) OWNER TO postgres;

--
-- Name: fin_implementation_owner_valid(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_implementation_owner_valid(p_org uuid, p_entity uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.fin_members m where m.organization_id=p_org and m.user_id=p_user and m.role in ('admin','finance_manager','analyst') and (m.entity_scope='group' or exists(select 1 from public.fin_legal_entities e join public.fin_member_entity_grants g on g.organization_id=e.organization_id and g.user_id=m.user_id and (g.entity_id=e.id or g.entity_id=e.parent_id) where e.id=p_entity and e.organization_id=p_org)))
$$;


ALTER FUNCTION public.fin_implementation_owner_valid(p_org uuid, p_entity uuid, p_user uuid) OWNER TO postgres;

--
-- Name: fin_implementation_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_implementation_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    decision_id uuid,
    product text NOT NULL,
    title text NOT NULL,
    owner_id uuid NOT NULL,
    provider_owner_contact_id uuid,
    status text DEFAULT 'planned'::text NOT NULL,
    starts_on date NOT NULL,
    target_go_live date NOT NULL,
    actual_go_live date,
    cancellation_reason text,
    template_version text NOT NULL,
    source_reference text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_implementation_plans_check CHECK ((target_go_live >= starts_on)),
    CONSTRAINT fin_implementation_plans_check1 CHECK (((status = 'accepted'::text) = (actual_go_live IS NOT NULL))),
    CONSTRAINT fin_implementation_plans_source_reference_check CHECK ((((length(TRIM(BOTH FROM source_reference)) >= 3) AND (length(TRIM(BOTH FROM source_reference)) <= 200)) AND (source_reference !~ '[<>]'::text))),
    CONSTRAINT fin_implementation_plans_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'in_progress'::text, 'blocked'::text, 'ready_for_acceptance'::text, 'accepted'::text, 'cancelled'::text]))),
    CONSTRAINT fin_implementation_plans_title_check CHECK ((((length(TRIM(BOTH FROM title)) >= 3) AND (length(TRIM(BOTH FROM title)) <= 200)) AND (title !~ '[<>]'::text)))
);

ALTER TABLE ONLY public.fin_implementation_plans FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_implementation_plans OWNER TO postgres;

--
-- Name: fin_implementation_require(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_implementation_require(p_plan uuid, p_roles text[]) RETURNS public.fin_implementation_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_implementation_plans%rowtype; begin
 select * into p from public.fin_implementation_plans where id=p_plan for update;
 if p.id is null or auth.uid() is null or not public.fin_entity_allows(p.organization_id,p.legal_entity_id,p_roles) or not exists(select 1 from public.fin_organizations where id=p.organization_id and kind='BUYER') then raise exception 'forbidden'; end if;
 if public.fin_governance_org_locked(p.organization_id) then raise exception 'organization offboarding'; end if;
 return p;
end $$;


ALTER FUNCTION public.fin_implementation_require(p_plan uuid, p_roles text[]) OWNER TO postgres;

--
-- Name: fin_import_contract(uuid, uuid, uuid, text, text, date, date, integer, boolean, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_import_contract(p_org uuid, p_entity uuid, p_provider uuid, p_product text, p_title text, p_starts date, p_ends date, p_notice integer DEFAULT 60, p_auto_renew boolean DEFAULT false, p_currency text DEFAULT NULL::text, p_terms jsonb DEFAULT '{}'::jsonb, p_parent uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return public.fin_import_contract_core(p_org,p_entity,p_provider,p_product,p_title,p_starts,p_ends,p_notice,p_auto_renew,p_currency,p_terms,p_parent,auth.uid(),true);
end $$;


ALTER FUNCTION public.fin_import_contract(p_org uuid, p_entity uuid, p_provider uuid, p_product text, p_title text, p_starts date, p_ends date, p_notice integer, p_auto_renew boolean, p_currency text, p_terms jsonb, p_parent uuid) OWNER TO postgres;

--
-- Name: fin_import_contract_core(uuid, uuid, uuid, text, text, date, date, integer, boolean, text, jsonb, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_import_contract_core(p_org uuid, p_entity uuid, p_provider uuid, p_product text, p_title text, p_starts date, p_ends date, p_notice integer DEFAULT 60, p_auto_renew boolean DEFAULT false, p_currency text DEFAULT NULL::text, p_terms jsonb DEFAULT '{}'::jsonb, p_parent uuid DEFAULT NULL::uuid, p_owner uuid DEFAULT NULL::uuid, p_guard_duplicate boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; v_currency text; v_parent record; v_notice integer; v_review date; v_status text; v_task uuid;
begin
  perform public.fin_contract_import_actor(p_org,p_entity,array['admin','finance_manager']);
  perform public.fin_contract_owner_eligible(p_org,p_entity,coalesce(p_owner,auth.uid()));
  if not public.fin_entity_allows(p_org, p_entity, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if p_entity is not null and not exists (select 1 from public.fin_legal_entities e where e.organization_id = p_org and e.id = p_entity and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_starts is null or p_ends is null or p_ends < p_starts then raise exception 'invalid period'; end if;
  if p_notice is not null and p_notice not between 0 and 3650 then raise exception 'invalid period'; end if;
  if p_terms is null or not public.fin_valid_contract_terms(p_terms) then raise exception 'invalid contract terms'; end if;
  if p_currency is not null and p_terms ? 'currency' and upper(p_currency) is distinct from upper(p_terms->>'currency') then
    raise exception 'currency mismatch';
  end if;
  if p_parent is not null then
    select c.id, c.provider_id, c.legal_entity_id into v_parent from public.fin_contracts c
     where c.organization_id = p_org and c.id = p_parent and public.fin_entity_visible(p_org, c.legal_entity_id);
    if not found then raise exception 'contract not found'; end if;
    if v_parent.provider_id is distinct from p_provider then raise exception 'invalid parent contract'; end if;
    if v_parent.legal_entity_id is not null and p_entity is distinct from v_parent.legal_entity_id then raise exception 'invalid parent contract'; end if;
  end if;
  -- Duplo envio concorrente: a checagem e a inserção ficam serializadas por organização.
  perform pg_advisory_xact_lock(hashtext('fin_import_contract'), hashtext(p_org::text));
  if p_guard_duplicate and exists (select 1 from public.fin_contracts c where c.organization_id = p_org and c.provider_id = p_provider
       and c.product = p_product and c.starts_on = p_starts and c.ends_on = p_ends
       and lower(btrim(coalesce(c.title, ''))) = lower(btrim(p_title))) then
    raise exception 'contract duplicate';
  end if;
  v_currency := coalesce(upper(p_currency), p_terms->>'currency',
    (select e.currency from public.fin_legal_entities e where e.id = p_entity),
    (select o.base_currency from public.fin_organizations o where o.id = p_org));
  v_notice := coalesce(p_notice, 60);
  v_review := p_ends - v_notice;
  v_status := case when p_ends >= current_date and v_review <= current_date then 'renewing' else 'active' end;
  insert into public.fin_contracts(organization_id, provider_id, product, starts_on, ends_on, renewal_notice_days, auto_renew,
      owner_id, origin, title, currency, parent_contract_id, legal_entity_id, current_version, terms_updated_at, status)
    values (p_org, p_provider, p_product, p_starts, p_ends, v_notice, coalesce(p_auto_renew, false),
      coalesce(p_owner,auth.uid()), 'imported', trim(p_title), v_currency, p_parent, p_entity, 1, now(), v_status)
    returning id into v_id;
  insert into public.fin_contract_versions(contract_id, organization_id, version, effective_from, source, terms, recorded_by)
    values (v_id, p_org, 1, p_starts, 'import', p_terms, auth.uid());
  -- Mesma próxima ação do contrato registrado por decisão; encerrado não tem.
  if p_ends >= current_date then
    insert into public.fin_tasks(organization_id, title, due_on, status, related_type, related_id, created_by)
      values (p_org, 'Revisar renovação do contrato antes do aviso prévio', greatest(v_review, current_date), 'open', 'contract', v_id, auth.uid())
      returning id into v_task;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'contract', v_id, 'contract_imported', auth.uid(),
      jsonb_build_object('product', p_product, 'terms_fields', (select count(*) from jsonb_object_keys(p_terms)), 'has_parent', p_parent is not null,
        'status', v_status, 'review_from', case when v_task is null then null else greatest(v_review, current_date) end, 'task_id', v_task));
  return v_id;
exception when check_violation then raise exception 'invalid contract';
end $$;


ALTER FUNCTION public.fin_import_contract_core(p_org uuid, p_entity uuid, p_provider uuid, p_product text, p_title text, p_starts date, p_ends date, p_notice integer, p_auto_renew boolean, p_currency text, p_terms jsonb, p_parent uuid, p_owner uuid, p_guard_duplicate boolean) OWNER TO postgres;

--
-- Name: fin_import_contract_intent(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_import_contract_intent(p_org uuid, p_entity uuid, p_key uuid, p_input jsonb, p_owner uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare h text; c public.fin_contracts%rowtype; v_id uuid; v_input jsonb; v_owner uuid:=coalesce(p_owner,auth.uid());
begin
 perform public.fin_contract_import_actor(p_org,p_entity,array['admin','finance_manager']);
 if p_key is null then raise exception 'invalid request key'; end if;
 if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>40000
 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('provider_id','product','title','starts_on','ends_on','renewal_notice_days','auto_renew','currency','terms','parent_contract_id')) then raise exception 'invalid contract'; end if;
 v_input:=jsonb_build_object('provider_id',(p_input->>'provider_id')::uuid,'product',btrim(p_input->>'product'),
  'title',btrim(p_input->>'title'),'starts_on',(p_input->>'starts_on')::date,'ends_on',(p_input->>'ends_on')::date,
  'renewal_notice_days',coalesce((p_input->>'renewal_notice_days')::integer,60),'auto_renew',coalesce((p_input->>'auto_renew')::boolean,false),
  'currency',upper(nullif(btrim(p_input->>'currency'),'')),'terms',coalesce(p_input->'terms','{}'::jsonb),'parent_contract_id',(p_input->>'parent_contract_id')::uuid);
 h:=encode(sha256(convert_to(jsonb_build_object('organization',p_org,'entity',p_entity,'actor',auth.uid(),'owner',v_owner,'input',v_input)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('contract-import:'||p_org||':'||auth.uid()||':'||p_key,0));
 select * into c from public.fin_contracts where organization_id=p_org and import_actor_id=auth.uid() and import_request_key=p_key;
 if c.id is not null then
  if c.import_request_hash is distinct from h then raise exception 'duplicate request'; end if;
  if c.legal_entity_id is distinct from p_entity or not public.fin_entity_visible(p_org,c.legal_entity_id) then raise exception 'forbidden'; end if;
  return jsonb_build_object('id',c.id,'replayed',true,'creation_version',1);
 end if;
 v_id:=public.fin_import_contract_core(p_org,p_entity,(v_input->>'provider_id')::uuid,v_input->>'product',v_input->>'title',
  (v_input->>'starts_on')::date,(v_input->>'ends_on')::date,(v_input->>'renewal_notice_days')::integer,(v_input->>'auto_renew')::boolean,
  v_input->>'currency',coalesce(v_input->'terms','{}'::jsonb),(v_input->>'parent_contract_id')::uuid,v_owner,false);
 update public.fin_contracts set import_request_key=p_key,import_request_hash=h,import_actor_id=auth.uid() where id=v_id;
 return jsonb_build_object('id',v_id,'replayed',false,'creation_version',1);
end $$;


ALTER FUNCTION public.fin_import_contract_intent(p_org uuid, p_entity uuid, p_key uuid, p_input jsonb, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_import_fee_batch(uuid, uuid, uuid, text, text, jsonb, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_import_fee_batch(p_org uuid, p_contract uuid, p_request uuid, p_fingerprint text, p_file_name text, p_rows jsonb, p_confirmation boolean, p_origin jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare c public.fin_contracts%rowtype; receipt jsonb; request_hash text; result jsonb; row jsonb; entry jsonb; observation uuid; existing public.fin_fee_observations%rowtype; results jsonb:='[]'; integration jsonb; imported integer:=0; ignored integer:=0;
begin
 if p_org is null or p_contract is null or p_request is null or p_confirmation is distinct from true then raise exception 'fee import confirmation required';end if;
 select * into c from public.fin_contracts where organization_id=p_org and id=p_contract for share;
 if c.id is null or not public.fin_has_role(p_org,array['admin','finance_manager']) then raise exception 'forbidden';end if;
 perform public.fin_crm_actor(p_org,c.legal_entity_id,auth.uid());
 perform pg_advisory_xact_lock(hashtextextended('fee-ingestion:'||p_org::text,0));
 if coalesce(p_fingerprint,'') !~ '^[0-9a-f]{64}$' or coalesce(p_file_name,'') !~ '^[^<>[:cntrl:]]{1,120}$' or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 100 or length(p_rows::text)>100000 or jsonb_typeof(p_origin) is distinct from 'object' or length(p_origin::text)>1000 then raise exception 'invalid fee import';end if;
 if exists(select 1 from jsonb_object_keys(p_origin) x where x not in ('integration_id','expected_version','watermark')) then raise exception 'invalid fee import';end if;
 if p_origin ? 'integration_id' then
  integration:=public.fin_fee_integration(p_org,(p_origin->>'integration_id')::uuid);
  if integration is null or integration->>'contract_id'<>p_contract::text or integration->>'status'<>'configured' or integration->>'version' is distinct from p_origin->>'expected_version' then raise exception 'fee integration version conflict';end if;
 end if;
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_contract,p_fingerprint,p_file_name,p_rows,p_origin)::text,'UTF8')),'hex');
 select e.metadata into receipt from public.fin_events e where e.organization_id=p_org and e.actor_id=auth.uid() and e.event_type='fee_import_completed' and e.metadata->>'request_key'=p_request::text limit 1;
 if receipt is not null then
  if receipt->>'input_hash' is distinct from request_hash then raise exception 'fee import request conflict';end if;
  return receipt->'result'||jsonb_build_object('replayed',true);
 end if;
 for row in select * from jsonb_array_elements(p_rows) loop
  if jsonb_typeof(row) is distinct from 'object' or exists(select 1 from jsonb_object_keys(row) x where x not in ('line','values')) or jsonb_typeof(row->'line') is distinct from 'number' or (row->>'line')::integer<1 or (row->>'line')::numeric<>(row->>'line')::integer or jsonb_typeof(row->'values') is distinct from 'object' then raise exception 'invalid fee import';end if;
  entry:=row->'values';
  if coalesce(entry->>'source_type','') not in ('other_import','erp') then raise exception 'invalid fee import';end if;
  if (entry->>'source_type'='erp') is distinct from (integration is not null) then raise exception 'invalid fee import';end if;
  select * into existing from public.fin_fee_observations where organization_id=p_org and contract_id=p_contract and source_type=entry->>'source_type' and lower(btrim(source_reference))=lower(btrim(entry->>'source_reference')) limit 1;
  if existing.id is not null and (lower(btrim(existing.service)) is distinct from lower(btrim(entry->>'service')) or existing.charging_unit is distinct from entry->>'charging_unit' or existing.currency is distinct from entry->>'currency' or existing.period_start is distinct from (entry->>'period_start')::date or existing.period_end is distinct from (entry->>'period_end')::date or existing.observed_amount is distinct from (entry->>'observed_amount')::numeric or existing.volume is distinct from (entry->>'volume')::numeric or existing.base_amount is distinct from (entry->>'base_amount')::numeric) then raise exception 'fee import source conflict';end if;
  observation:=public.fin_record_fee_observation_internal(p_org,p_contract,entry,case when integration is null then 'structured_file' else 'erp_adapter' end);
  if existing.id is null then imported:=imported+1;else ignored:=ignored+1;end if;
  results:=results||jsonb_build_array(jsonb_build_object('line',(row->>'line')::integer,'id',observation,'state',case when existing.id is null then 'imported' else 'ignored' end));
 end loop;
 result:=jsonb_build_object('rows',results,'imported',imported,'ignored',ignored,'fingerprint',p_fingerprint);
 insert into public.fin_events(organization_id,legal_entity_id,entity_type,entity_id,event_type,actor_id,metadata,happened_at) values(p_org,c.legal_entity_id,'contract',p_contract,'fee_import_completed',auth.uid(),jsonb_build_object('request_key',p_request,'input_hash',request_hash,'fingerprint',p_fingerprint,'file_name',p_file_name,'origin',p_origin,'result',result),clock_timestamp());
 return result||jsonb_build_object('replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format then raise exception 'invalid fee import';
end $_$;


ALTER FUNCTION public.fin_import_fee_batch(p_org uuid, p_contract uuid, p_request uuid, p_fingerprint text, p_file_name text, p_rows jsonb, p_confirmation boolean, p_origin jsonb) OWNER TO postgres;

--
-- Name: fin_fee_schedules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_fee_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    service text NOT NULL,
    service_key text GENERATED ALWAYS AS (lower(btrim(service))) STORED,
    category text NOT NULL,
    charging_unit text NOT NULL,
    owner_id uuid NOT NULL,
    current_version integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_fee_schedules_category_check CHECK ((category = ANY (ARRAY['account_maintenance'::text, 'payments'::text, 'collections'::text, 'transfers'::text, 'cards'::text, 'acquiring'::text, 'credit'::text, 'fx'::text, 'cash_management'::text, 'guarantee'::text, 'other'::text]))),
    CONSTRAINT fin_fee_schedules_charging_unit_check CHECK ((charging_unit = ANY (ARRAY['per_month'::text, 'per_year'::text, 'one_off'::text, 'per_transaction'::text, 'per_item'::text, 'percent_of_volume'::text, 'percent_of_amount'::text]))),
    CONSTRAINT fin_fee_schedules_current_version_check CHECK ((current_version >= 0)),
    CONSTRAINT fin_fee_schedules_service_check CHECK ((((length(TRIM(BOTH FROM service)) >= 2) AND (length(TRIM(BOTH FROM service)) <= 120)) AND (service !~ '[<>]'::text)))
);

ALTER TABLE ONLY public.fin_fee_schedules FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_fee_schedules OWNER TO postgres;

--
-- Name: fin_insert_fee_version(public.fin_fee_schedules, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_insert_fee_version(s public.fin_fee_schedules, p_input jsonb, p_version integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cv public.fin_contract_versions%rowtype; v_effective date; v_last date;
begin
  if not public.fin_fee_version_valid(s.charging_unit, p_input) then raise exception 'invalid fee schedule'; end if;
  if p_input->>'currency' is null or p_input->>'currency' not in ('BRL','USD','EUR','GBP','CHF','JPY','CAD','AUD','CNY','MXN','ARS','CLP','COP','PEN') then raise exception 'invalid fee schedule'; end if;
  if p_input->>'source' is null or p_input->>'source' not in ('contract_terms','contract_document','amendment','declared')
     or length(trim(coalesce(p_input->>'source_reference', ''))) not between 3 and 200 or p_input->>'source_reference' ~ '[<>]' then raise exception 'invalid fee schedule'; end if;
  select * into cv from public.fin_contract_versions where contract_id = s.contract_id and organization_id = s.organization_id
    and version = coalesce((p_input->>'contract_version')::integer, (select current_version from public.fin_contracts where id = s.contract_id));
  if cv.contract_id is null then raise exception 'fee contract version unavailable'; end if;
  v_effective := coalesce((p_input->>'effective_from')::date, cv.effective_from);
  select max(effective_from) into v_last from public.fin_fee_schedule_versions where schedule_id = s.id;
  if v_last is not null and v_effective < v_last then raise exception 'fee schedule effective date regression'; end if;
  if p_version > 1 and length(trim(coalesce(p_input->>'reason', ''))) not between 3 and 1000 then raise exception 'fee schedule reason required'; end if;
  insert into public.fin_fee_schedule_versions(schedule_id, organization_id, contract_id, version, contract_version, effective_from, pricing_model, currency, rate, tiers, minimum_amount, maximum_amount, source, source_reference, reason, recorded_by)
  values (s.id, s.organization_id, s.contract_id, p_version, cv.version, v_effective, p_input->>'pricing_model', p_input->>'currency',
    case when p_input->>'pricing_model' <> 'tiered_per_unit' then (p_input->>'rate')::numeric end,
    case when p_input->>'pricing_model' = 'tiered_per_unit' then p_input->'tiers' end,
    (p_input->>'minimum_amount')::numeric, (p_input->>'maximum_amount')::numeric,
    p_input->>'source', trim(p_input->>'source_reference'), nullif(trim(coalesce(p_input->>'reason', '')), ''), auth.uid());
  update public.fin_fee_schedules set current_version = p_version where id = s.id;
end $$;


ALTER FUNCTION public.fin_insert_fee_version(s public.fin_fee_schedules, p_input jsonb, p_version integer) OWNER TO postgres;

--
-- Name: fin_invalidate_value(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_invalidate_value(p_record uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_value_records%rowtype;
begin
  select * into r from public.fin_value_records where id=p_record for update;
  if r.id is null or auth.uid() is null or not public.fin_entity_allows(r.organization_id,r.legal_entity_id,array['admin','finance_manager'])
     or not exists(select 1 from public.fin_contracts c where c.id=r.contract_id and c.organization_id=r.organization_id and public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager'])) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(r.organization_id) then raise exception 'organization offboarding'; end if;
  update public.fin_value_records set status='invalidated',invalidation_reason=p_input->>'reason',invalidated_by=auth.uid(),invalidated_at=now() where id=p_record or (parent_id=p_record and status='active');
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
  values(r.organization_id,'contract',r.contract_id,'value_invalidated',auth.uid(),jsonb_build_object('record_id',r.id));
  return r.id;
end $$;


ALTER FUNCTION public.fin_invalidate_value(p_record uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_invite_member(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_invite_member(p_org uuid, p_email text, p_role text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_token text;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if coalesce(p_email,'') !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or length(p_email) > 254 then
    raise exception 'invalid email';
  end if;
  if p_role not in ('admin','finance_manager','analyst','provider_user','viewer') then raise exception 'invalid role'; end if;
  v_token := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');
  insert into public.fin_member_invitations (organization_id, email, role, token_hash, created_by)
    values (p_org, lower(trim(p_email)), p_role, encode(sha256(convert_to(v_token,'UTF8')),'hex'), auth.uid());
  return v_token;
end $_$;


ALTER FUNCTION public.fin_invite_member(p_org uuid, p_email text, p_role text) OWNER TO postgres;

--
-- Name: fin_invite_provider(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_invite_provider(p_rfq uuid, p_provider uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_status text; v_token text; v_invite uuid; v_contact text; v_buyer text; v_deadline date; v_product text; v_recipient text;
begin
  select organization_id, status, response_deadline, product into v_org, v_status, v_deadline, v_product
    from public.fin_rfqs where id = p_rfq;
  if v_org is null then raise exception 'rfq not found'; end if;
  if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_status not in ('draft','open','collecting') then raise exception 'invalid state'; end if;
  select contact_email into v_contact from public.fin_providers p
    where p.id = p_provider and p.organization_id = v_org and p.status = 'active';
  if not found then raise exception 'provider not found'; end if;
  select legal_name into v_buyer from public.fin_organizations where id = v_org;
  v_invite := gen_random_uuid();
  v_token := encode(sha256(convert_to(public.fin_setting('invite_secret') || ':' || v_invite::text, 'UTF8')), 'hex');
  -- Com contato cadastrado, o convite é daquele e-mail (exact_email); sem
  -- contato, é explicitamente aberto à organização que receber o link.
  v_recipient := nullif(lower(trim(coalesce(v_contact, ''))), '');
  insert into public.fin_rfq_invites (id, buyer_organization_id, rfq_id, provider_id, token_hash, created_by, recipient_mode, recipient_email)
    values (v_invite, v_org, p_rfq, p_provider, encode(sha256(convert_to(v_token,'UTF8')),'hex'), auth.uid(),
            case when v_recipient is null then 'organization_open' else 'exact_email' end, v_recipient);
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (v_org, 'rfq', p_rfq, 'provider_invited', auth.uid());
  if v_contact is not null then
    perform public.fin_enqueue_email(
      'provider_invite', v_contact, 'rfq', p_rfq,
      jsonb_build_object('buyer', v_buyer, 'product', v_product, 'deadline', v_deadline, 'invite_ref', v_invite),
      'provider_invite:' || v_invite::text);
  end if;
  return v_token;
end $$;


ALTER FUNCTION public.fin_invite_provider(p_rfq uuid, p_provider uuid) OWNER TO postgres;

--
-- Name: fin_is_operator(); Type: FUNCTION; Schema: public; Owner: postgres
