    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and public.fin_platform_role() = 'finance_ops'
     and exists (select 1 from public.fin_platform_operators o where o.user_id = auth.uid());
$$;


