--
-- Name: fin_issue_api_credential(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_issue_api_credential(p_account uuid, p_token_hash text, p_token_prefix text, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.fin_service_accounts%rowtype; v_id uuid;
begin
  select * into a from public.fin_service_accounts where id = p_account for update;
  if not found or not public.fin_has_role(a.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if a.status <> 'active' then raise exception 'service account revoked'; end if;
  if p_expires_at is null or p_expires_at <= now() or p_expires_at > now() + interval '365 days' then raise exception 'invalid credential'; end if;
  if (select count(*) from public.fin_api_credentials where service_account_id = p_account and revoked_at is null and expires_at > now()) >= 2 then
    raise exception 'too many active credentials';
  end if;
  insert into public.fin_api_credentials(organization_id, service_account_id, token_prefix, token_hash, created_by, expires_at)
    values (a.organization_id, p_account, p_token_prefix, p_token_hash, auth.uid(), p_expires_at) returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (a.organization_id, 'service_account', p_account, 'api_credential_issued', auth.uid(), jsonb_build_object('credential_id', v_id, 'prefix', p_token_prefix, 'expires_at', p_expires_at));
  return v_id;
exception
  when check_violation then raise exception 'invalid credential';
  when unique_violation then raise exception 'invalid credential';
end $$;


ALTER FUNCTION public.fin_issue_api_credential(p_account uuid, p_token_hash text, p_token_prefix text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fin_job_begin(text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_job_begin(p_job text, p_request_id text, p_started_at timestamp with time zone, p_lease_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    AS $_$
declare v_id uuid; v_token uuid := gen_random_uuid(); v_expires timestamptz;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  if p_job is null or p_job not in ('renewals','contract_milestones','approval_deadlines','webhooks','email_outbox','retention','data_exports','offboarding','opportunities')
    or p_request_id is null or p_request_id !~ '^[A-Za-z0-9-]{1,80}$'
    or p_started_at is null or abs(extract(epoch from clock_timestamp()-p_started_at)) > 60 then raise exception 'invalid job'; end if;
  if not pg_try_advisory_xact_lock(hashtext('fin_job_begin:'||p_job)) then return null; end if;
  if exists (select 1 from public.fin_job_leases where job=p_job and expires_at > clock_timestamp()) then return null; end if;
  update public.fin_job_runs set status='failed',failed=greatest(failed,1),error_code='lease_expired',finished_at=clock_timestamp()
    where job=p_job and status='running' and lease_expires_at <= clock_timestamp();
  v_expires := clock_timestamp() + make_interval(secs => least(greatest(coalesce(p_lease_seconds,90),30),120));
  insert into public.fin_job_runs(job,status,request_id,started_at,finished_at,lease_token,lease_expires_at)
    values(p_job,'running',p_request_id,p_started_at,null,v_token,v_expires) returning id into v_id;
  insert into public.fin_job_leases(job,run_id,lease_token,expires_at) values(p_job,v_id,v_token,v_expires)
    on conflict(job) do update set run_id=excluded.run_id,lease_token=excluded.lease_token,expires_at=excluded.expires_at;
  return jsonb_build_object('run_id',v_id,'lease_token',v_token);
end $_$;


ALTER FUNCTION public.fin_job_begin(p_job text, p_request_id text, p_started_at timestamp with time zone, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: fin_job_finish(uuid, uuid, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_job_finish(p_run uuid, p_lease uuid, p_status text, p_processed integer, p_failed integer, p_error_code text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '1s'
    AS $_$
declare r public.fin_job_runs%rowtype;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  if p_status is null or p_status not in ('succeeded','failed') or p_processed is null or p_processed < 0 or p_failed is null or p_failed < 0
    or p_status='succeeded' and (p_failed <> 0 or p_error_code is not null)
    or p_error_code is not null and p_error_code !~ '^[a-z0-9_]{1,60}$' then raise exception 'invalid job result'; end if;
  select * into r from public.fin_job_runs where id=p_run for update;
  if not found or r.lease_token is distinct from p_lease then raise exception 'stale lease'; end if;
  if r.status <> 'running' then
    if r.status=p_status and r.processed=p_processed and r.failed=p_failed and r.error_code is not distinct from p_error_code then return true; end if;
    raise exception 'job already finished';
  end if;
  if r.lease_expires_at is null or r.lease_expires_at <= clock_timestamp() or not exists(select 1 from public.fin_job_leases where job=r.job and run_id=p_run and lease_token=p_lease and expires_at > clock_timestamp()) then raise exception 'stale lease'; end if;
  update public.fin_job_runs set status=p_status,processed=p_processed,failed=p_failed,error_code=p_error_code,finished_at=clock_timestamp() where id=p_run;
  update public.fin_job_leases set expires_at=clock_timestamp() where job=r.job and run_id=p_run;
  return true;
end $_$;


ALTER FUNCTION public.fin_job_finish(p_run uuid, p_lease uuid, p_status text, p_processed integer, p_failed integer, p_error_code text) OWNER TO postgres;

--
-- Name: fin_jwt_aal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_jwt_aal() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'aal',
                  nullif(current_setting('request.jwt.claim.aal', true), ''), 'aal1');
$$;


ALTER FUNCTION public.fin_jwt_aal() OWNER TO postgres;

--
-- Name: fin_list_fee_integrations(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_list_fee_integrations(p_org uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
 if p_org is null or p_limit is null or p_limit not between 1 and 100 then raise exception 'invalid fee integration';end if;
 return query select x.metadata from (
  select distinct on(e.entity_id) e.entity_id,e.metadata from public.fin_events e
  where e.organization_id=p_org and e.entity_type='fee_integration' and e.event_type='fee_integration_configured' and (p_after is null or e.entity_id>p_after)
  order by e.entity_id,(e.metadata->>'version')::integer desc
 ) x order by x.entity_id limit p_limit+1;
end $$;


ALTER FUNCTION public.fin_list_fee_integrations(p_org uuid, p_after uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fin_list_fee_variances(uuid, date, date, uuid, uuid, text, uuid, text, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_list_fee_variances(p_org uuid, p_start date, p_end date, p_entity uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid, p_category text DEFAULT NULL::text, p_contract uuid DEFAULT NULL::uuid, p_currency text DEFAULT NULL::text, p_review text DEFAULT NULL::text, p_comparison text DEFAULT NULL::text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS SETOF public.fin_fee_variances
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_org is null or auth.uid() is null or not public.fin_has_role(p_org, array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  if p_start is null or p_end is null or p_end < p_start or p_end - p_start > 366 * 5 or p_limit is null or p_limit not between 1 and 50 then raise exception 'invalid fee filters'; end if;
  return query select v.* from public.fin_fee_variances v where v.organization_id = p_org and v.period_start >= p_start and v.period_end <= p_end
    and (p_entity is null or v.legal_entity_id = p_entity) and (p_provider is null or v.provider_id = p_provider)
    and (p_category is null or v.category = p_category) and (p_contract is null or v.contract_id = p_contract)
    and (p_currency is null or v.currency = p_currency) and (p_review is null or v.review_status = p_review)
    and (p_comparison is null or v.comparison_status = p_comparison) and (p_after is null or v.id > p_after)
    order by v.id limit p_limit + 1;
end $$;


ALTER FUNCTION public.fin_list_fee_variances(p_org uuid, p_start date, p_end date, p_entity uuid, p_provider uuid, p_category text, p_contract uuid, p_currency text, p_review text, p_comparison text, p_after uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fin_opportunities; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_opportunities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    legal_entity_id uuid,
    provider_id uuid,
    opportunity_type text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version integer NOT NULL,
    rule_snapshot jsonb NOT NULL,
    facts_snapshot jsonb NOT NULL,
    current_facts jsonb NOT NULL,
    facts_hash text NOT NULL,
    source_object_type text NOT NULL,
    source_object_id uuid NOT NULL,
    discriminator text DEFAULT ''::text NOT NULL,
    fingerprint text NOT NULL,
    possible_action text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    deadline date,
    reviewer_id uuid,
    cooldown_until timestamp with time zone,
    closed_facts_hash text,
    closed_at timestamp with time zone,
    closed_by uuid,
    resolution text,
    dismissal_reason text,
    expiry_reason text,
    reopen_count integer DEFAULT 0 NOT NULL,
    linked_rfq_id uuid,
    CONSTRAINT fin_opportunities_check CHECK ((((status = 'dismissed'::text) = (dismissal_reason IS NOT NULL)) OR (status <> 'dismissed'::text))),
    CONSTRAINT fin_opportunities_check1 CHECK (((status <> 'acted'::text) OR (resolution IS NOT NULL))),
    CONSTRAINT fin_opportunities_check2 CHECK (((status <> 'expired'::text) OR (expiry_reason IS NOT NULL))),
    CONSTRAINT fin_opportunities_check3 CHECK (((status <> 'under_review'::text) OR (reviewer_id IS NOT NULL))),
    CONSTRAINT fin_opportunities_discriminator_check CHECK (((discriminator ~ '^[A-Z]{0,3}$'::text) OR (discriminator ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})?$'::text))),
    CONSTRAINT fin_opportunities_dismissal_reason_check CHECK (((dismissal_reason IS NULL) OR (dismissal_reason = ANY (ARRAY['not_relevant'::text, 'already_handled'::text, 'data_incorrect'::text, 'accepted_risk'::text, 'duplicate'::text, 'other'::text])))),
    CONSTRAINT fin_opportunities_expiry_reason_check CHECK (((expiry_reason IS NULL) OR (expiry_reason = ANY (ARRAY['deadline_passed'::text, 'condition_cleared'::text, 'rule_disabled'::text, 'rule_superseded'::text])))),
    CONSTRAINT fin_opportunities_possible_action_check CHECK ((possible_action = ANY (ARRAY['open_sourcing'::text, 'review_contract'::text, 'review_facility'::text, 'review_guarantee'::text, 'update_passport'::text, 'review_fee'::text, 'review_value'::text, 'review_realization'::text, 'review_policy_exceptions'::text, 'contact_provider'::text]))),
    CONSTRAINT fin_opportunities_reopen_count_check CHECK ((reopen_count >= 0)),
    CONSTRAINT fin_opportunities_resolution_check CHECK (((resolution IS NULL) OR (((length(TRIM(BOTH FROM resolution)) >= 3) AND (length(TRIM(BOTH FROM resolution)) <= 1000)) AND (resolution !~ '[<>]'::text)))),
    CONSTRAINT fin_opportunities_source_object_type_check CHECK ((source_object_type = ANY (ARRAY['contract'::text, 'contract_milestone'::text, 'facility'::text, 'guarantee'::text, 'passport'::text, 'fee_variance'::text, 'value_record'::text, 'rfq'::text, 'provider'::text, 'organization'::text]))),
    CONSTRAINT fin_opportunities_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'under_review'::text, 'acted'::text, 'dismissed'::text, 'expired'::text])))
);

ALTER TABLE ONLY public.fin_opportunities FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_opportunities OWNER TO postgres;

--
-- Name: fin_list_opportunities(uuid, uuid, text, uuid, text, date, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_list_opportunities(p_org uuid, p_entity uuid DEFAULT NULL::uuid, p_type text DEFAULT NULL::text, p_provider uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_due_before date DEFAULT NULL::date, p_source text DEFAULT NULL::text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS SETOF public.fin_opportunities
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_org is null or auth.uid() is null or not public.fin_has_role(p_org, array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  if p_limit is null or p_limit not between 1 and 50 then raise exception 'invalid opportunity filters'; end if;
  return query select x.* from public.fin_opportunities x where x.organization_id = p_org
    and (p_entity is null or x.legal_entity_id = p_entity) and (p_type is null or x.opportunity_type = p_type) and (p_provider is null or x.provider_id = p_provider)
    and (p_status is null or x.status = p_status) and (p_due_before is null or x.deadline <= p_due_before) and (p_source is null or x.source_object_type = p_source)
    and (p_after is null or x.id > p_after) order by x.id limit p_limit + 1;
end $$;


ALTER FUNCTION public.fin_list_opportunities(p_org uuid, p_entity uuid, p_type text, p_provider uuid, p_status text, p_due_before date, p_source text, p_after uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fin_value_records; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_value_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    contract_version integer NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    product text NOT NULL,
    owner_id uuid NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    currency text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    baseline jsonb NOT NULL,
    target_amount numeric(20,2) NOT NULL,
    target_snapshot jsonb NOT NULL,
    target_dimensions jsonb NOT NULL,
    comparability text NOT NULL,
    value_amount numeric(20,2),
    methodology_id uuid NOT NULL,
    methodology_snapshot jsonb NOT NULL,
    evidence_reference text NOT NULL,
    reason text NOT NULL,
    parent_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    invalidation_reason text,
    invalidated_by uuid,
    invalidated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_value_records_check CHECK (((period_end >= period_start) AND ((period_end - period_start) <= (366 * 5)))),
    CONSTRAINT fin_value_records_check1 CHECK (((kind = 'REALIZED_SAVINGS'::text) = (parent_id IS NOT NULL))),
    CONSTRAINT fin_value_records_check2 CHECK (((comparability = 'comparable'::text) = (value_amount IS NOT NULL))),
    CONSTRAINT fin_value_records_comparability_check CHECK ((comparability = ANY (ARRAY['comparable'::text, 'incomplete'::text, 'not_comparable'::text]))),
    CONSTRAINT fin_value_records_currency_check CHECK ((currency = ANY (ARRAY['BRL'::text, 'USD'::text, 'EUR'::text, 'GBP'::text, 'CHF'::text, 'JPY'::text, 'CAD'::text, 'AUD'::text, 'CNY'::text, 'MXN'::text, 'ARS'::text, 'CLP'::text, 'COP'::text, 'PEN'::text]))),
    CONSTRAINT fin_value_records_evidence_reference_check CHECK ((((length(TRIM(BOTH FROM evidence_reference)) >= 3) AND (length(TRIM(BOTH FROM evidence_reference)) <= 200)) AND (evidence_reference !~ '[<>]'::text))),
    CONSTRAINT fin_value_records_kind_check CHECK ((kind = ANY (ARRAY['NEGOTIATED_SAVINGS'::text, 'REALIZED_SAVINGS'::text, 'COST_AVOIDANCE'::text]))),
    CONSTRAINT fin_value_records_reason_check CHECK ((((length(TRIM(BOTH FROM reason)) >= 3) AND (length(TRIM(BOTH FROM reason)) <= 1000)) AND (reason !~ '[<>]'::text))),
    CONSTRAINT fin_value_records_status_check CHECK ((status = ANY (ARRAY['active'::text, 'invalidated'::text]))),
    CONSTRAINT fin_value_records_target_amount_check CHECK (((target_amount >= (0)::numeric) AND (target_amount <= ('1000000000000'::bigint)::numeric))),
    CONSTRAINT fin_value_records_title_check CHECK ((((length(TRIM(BOTH FROM title)) >= 3) AND (length(TRIM(BOTH FROM title)) <= 200)) AND (title !~ '[<>]'::text)))
);

ALTER TABLE ONLY public.fin_value_records FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_value_records OWNER TO postgres;

--
-- Name: fin_list_value(uuid, date, date, text, text, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_list_value(p_org uuid, p_start date, p_end date, p_kind text DEFAULT NULL::text, p_currency text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25, p_product text DEFAULT NULL::text) RETURNS SETOF public.fin_value_records
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_org is null or auth.uid() is null or not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  if p_start is null or p_end is null or p_end<p_start or p_end-p_start>366*5 or p_limit is null or p_limit not between 1 and 50 then raise exception 'invalid value filters'; end if;
  if p_product is not null and p_product not in ('credit','acquiring') then raise exception 'invalid value filters'; end if;
  return query select r.* from public.fin_value_records r where r.organization_id=p_org and r.period_start>=p_start and r.period_end<=p_end
   and (p_kind is null or r.kind=p_kind) and (p_currency is null or r.currency=p_currency) and (p_entity is null or r.legal_entity_id=p_entity)
   and (p_product is null or r.product=p_product) and (p_provider is null or r.provider_id=p_provider) and (p_after is null or r.id>p_after) order by r.id limit p_limit+1;
end $$;


ALTER FUNCTION public.fin_list_value(p_org uuid, p_start date, p_end date, p_kind text, p_currency text, p_entity uuid, p_provider uuid, p_after uuid, p_limit integer, p_product text) OWNER TO postgres;

--
-- Name: fin_log_rfq_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_log_rfq_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if new.revision<>old.revision then
  insert into public.fin_rfq_revisions(rfq_id,revision,organization_id,snapshot,changed_by)
  values(new.id,new.revision,new.organization_id,
   jsonb_build_object('title',new.title,'description',new.description,'demand',new.demand,
    'response_deadline',new.response_deadline),auth.uid());
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
  values(new.organization_id,'rfq',new.id,'rfq_revised',auth.uid(),
   jsonb_build_object('revision',new.revision,'previous_revision',old.revision));
 end if;
 return new;
end $$;


ALTER FUNCTION public.fin_log_rfq_revision() OWNER TO postgres;

--
-- Name: fin_mark_notifications(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_mark_notifications(p_org uuid, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
 if not public.fin_has_role(p_org) then raise exception 'forbidden'; end if;
 if p_ids is not null and cardinality(p_ids)>100 then raise exception 'invalid notification selection'; end if;
 update public.fin_notifications set read_at=now()
 where organization_id=p_org and user_id=auth.uid() and read_at is null
 and (p_ids is null or id=any(p_ids));
 get diagnostics v_count=row_count;
 return v_count;
end $$;


ALTER FUNCTION public.fin_mark_notifications(p_org uuid, p_ids uuid[]) OWNER TO postgres;

--
-- Name: fin_measure_performance(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_measure_performance(p_period uuid, p_dimension uuid, p_expected uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_provider_performance_periods%rowtype;d public.fin_provider_performance_dimensions%rowtype;last public.fin_provider_performance_observations%rowtype;f jsonb;v_id uuid;begin
 p:=public.fin_performance_require(p_period,array['admin','finance_manager','analyst']);
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('value','availability','source_type','source_reference','provenance','coverage_numerator','coverage_denominator','observed_on','correction_reason')) then raise exception 'invalid performance input';end if;
 select x.* into d from public.fin_provider_performance_dimensions x join public.fin_provider_performance_targets t on t.dimension_id=x.id where t.period_id=p.id and x.id=p_dimension;
 if d.id is null then raise exception 'invalid performance dimension';end if;
 select * into last from public.fin_provider_performance_observations where period_id=p.id and dimension_id=d.id order by revision desc limit 1;
 if last.id is distinct from p_expected then raise exception 'performance conflict';end if;
 if p_input->>'source_type'='internal' then f:=public.fin_performance_source(p.id,d.id);
 else f:=jsonb_build_object('value',p_input->>'value','availability',p_input->>'availability','formula_version','customer-methodology-v'||d.version,'coverage_numerator',p_input->>'coverage_numerator','coverage_denominator',p_input->>'coverage_denominator');end if;
 if d.unit='count' and (f->>'value')::numeric<>trunc((f->>'value')::numeric) or d.unit='percent' and (f->>'value')::numeric>100 or (p_input->>'observed_on')::date not between p.period_start and least(p.period_end,current_date) then raise exception 'invalid performance value';end if;
 insert into public.fin_provider_performance_observations(organization_id,period_id,dimension_id,revision,supersedes_id,value,availability,source_type,source_reference,provenance,formula_version,source_facts,coverage_numerator,coverage_denominator,observed_on,recorded_by,correction_reason)
 values(p.organization_id,p.id,d.id,coalesce(last.revision,0)+1,last.id,nullif(f->>'value','')::numeric,f->>'availability',p_input->>'source_type',trim(p_input->>'source_reference'),trim(p_input->>'provenance'),f->>'formula_version',case when p_input->>'source_type'='internal' then f else jsonb_build_object('methodology',d.methodology,'dimension_version',d.version) end,(f->>'coverage_numerator')::integer,(f->>'coverage_denominator')::integer,(p_input->>'observed_on')::date,auth.uid(),trim(p_input->>'correction_reason')) returning id into v_id;
 update public.fin_provider_performance_periods set version=version+1 where id=p.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'performance_measured',auth.uid(),p.legal_entity_id,jsonb_build_object('period_id',p.id,'observation_id',v_id,'revision',coalesce(last.revision,0)+1));return v_id;
end $$;


ALTER FUNCTION public.fin_measure_performance(p_period uuid, p_dimension uuid, p_expected uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_member_default_name(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_member_default_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_name text;
begin
  if new.display_name is null then
    select trim(u.raw_user_meta_data ->> 'full_name') into v_name from auth.users u where u.id = new.user_id;
    if v_name is not null and length(v_name) between 2 and 120 and v_name !~ '[<>@]' then new.display_name := v_name; end if;
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_member_default_name() OWNER TO postgres;

--
-- Name: fin_notify_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_notify_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_user uuid;v_type text;v_object text;v_target uuid;v_next uuid;v_policy boolean;
begin
 if new.event_type in ('proposal_submitted','proposal_revised') then
  select r.owner_id,r.id into v_user,v_target from public.fin_proposals p join public.fin_rfqs r on r.id=p.rfq_id where p.id=new.entity_id;
  v_type:=case when new.event_type='proposal_submitted' then 'proposal_received' else 'proposal_revised' end;
  v_object:='rfq';
 elsif new.event_type in ('approval_requested','approval_approved','policy_exception_approved')
   and exists (select 1 from public.fin_approval_requests r where r.id=(new.metadata->>'request_id')::uuid and r.policy_snapshot is not null) then
  select rfq_id,requested_by into v_target,v_user from public.fin_approval_requests where id=(new.metadata->>'request_id')::uuid;
  for v_next in select s.approver_id from public.fin_approval_steps s join public.fin_approval_stages st on st.id=s.stage_id and st.status='active'
                 join public.fin_approval_requests r on r.id=s.request_id and r.status='pending'
                 where s.request_id=(new.metadata->>'request_id')::uuid and s.status='pending' and s.approver_id is distinct from new.actor_id loop
   insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
   values(new.organization_id,v_next,'approval_requested','rfq',v_target,new.id,'Aprovação solicitada',
    'Uma etapa de aprovação aguarda você. Abra o processo para ver a policy e os detalhes.')
   on conflict(user_id,event_type,event_id) do nothing;
  end loop;
  if new.event_type='approval_requested' then return new; end if;
  if new.event_type='policy_exception_approved' then
   select e.requested_by into v_user from public.fin_policy_exceptions e where e.id=(new.metadata->>'exception_id')::uuid;
   if v_user is not null and v_user is distinct from new.actor_id then
    insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
    values(new.organization_id,v_user,'policy_exception_decided','rfq',v_target,new.id,'Exceção de policy decidida','A exceção que você pediu foi decidida. Abra o processo para ver a decisão e o comentário.')
    on conflict(user_id,event_type,event_id) do nothing;
   end if;
   return new;
  end if;
  v_type:='approval_approved';v_object:='rfq';
 elsif new.event_type='policy_exception_requested' then
  -- Exceção pedida: avisa quem pode decidir (papéis da policy dona da regra,
  -- com acesso à entidade), nunca quem pediu a exceção ou a aprovação.
  for v_next in select m.user_id from public.fin_policy_exceptions e
                  join public.fin_approval_requests r on r.id=e.request_id
                  join public.fin_policy_versions pv on pv.id=e.policy_version_id
                  join public.fin_rfqs q on q.id=r.rfq_id
                  join public.fin_members m on m.organization_id=e.organization_id
                 where e.id=(new.metadata->>'exception_id')::uuid and e.status='requested'
                   and m.user_id not in (e.requested_by, r.requested_by)
                   and public.fin_approval_member_eligible(e.organization_id, q.legal_entity_id, m.user_id,
                         array(select jsonb_array_elements_text(coalesce(pv.document->'exception_approver_roles','["admin"]'::jsonb))), 'any')
                 order by m.user_id limit 50 loop
   insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
   values(new.organization_id,v_next,'policy_exception_requested','rfq',new.entity_id,new.id,'Exceção de policy para decidir',
    'Pediram uma exceção a uma regra de aprovação. Abra o processo para ver o motivo, a evidência e decidir.')
   on conflict(user_id,event_type,event_id) do nothing;
  end loop;
  return new;
 elsif new.event_type in ('policy_exception_rejected','policy_exception_approved') then
  select e.requested_by,new.entity_id into v_user,v_target from public.fin_policy_exceptions e where e.id=(new.metadata->>'exception_id')::uuid;
  v_type:='policy_exception_decided';v_object:='rfq';
 elsif new.event_type='approval_requested' then
  select s.approver_id,r.rfq_id into v_user,v_target from public.fin_approval_steps s join public.fin_approval_requests r on r.id=s.request_id where s.request_id=(new.metadata->>'request_id')::uuid order by s.position limit 1;
  v_type:='approval_requested';v_object:='rfq';
 elsif new.event_type in ('approval_approved','approval_rejected','approval_changes_requested') then
  select requested_by,rfq_id into v_user,v_target from public.fin_approval_requests where id=(new.metadata->>'request_id')::uuid;
  v_type:=new.event_type;v_object:='rfq';
  -- Etapa aprovada e pedido ainda pendente: a vez passou para o próximo aprovador.
  if new.event_type='approval_approved' then
   select s.approver_id into v_next from public.fin_approval_steps s join public.fin_approval_requests r on r.id=s.request_id
    where s.request_id=(new.metadata->>'request_id')::uuid and s.status='pending' and r.status='pending'
    order by s.position limit 1;
   if v_next is not null and v_next is distinct from new.actor_id then
    insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
    values(new.organization_id,v_next,'approval_requested','rfq',v_target,new.id,'Aprovação solicitada',
     'Chegou a sua vez de aprovar. Abra o processo para ver os detalhes.')
    on conflict(user_id,event_type,event_id) do nothing;
   end if;
  end if;
 else return new;
 end if;
 if v_user is not null and v_user is distinct from new.actor_id then
  insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
  values(new.organization_id,v_user,v_type,v_object,v_target,new.id,
   case v_type when 'proposal_received' then 'Proposta recebida' when 'proposal_revised' then 'Proposta revisada'
    when 'approval_requested' then 'Aprovação solicitada' when 'approval_approved' then 'Aprovação registrada'
    when 'approval_rejected' then 'Aprovação rejeitada' when 'policy_exception_decided' then 'Exceção de policy decidida' else 'Alterações solicitadas' end,
   'Abra o processo para ver os detalhes.')
  on conflict(user_id,event_type,event_id) do nothing;
 end if;
 return new;
end $$;


ALTER FUNCTION public.fin_notify_event() OWNER TO postgres;

--
-- Name: fin_object_legal_entity(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_object_legal_entity(p_type text, p_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_type
    when 'rfq' then (select r.legal_entity_id from public.fin_rfqs r where r.id = p_id)
    when 'proposal' then (select r.legal_entity_id from public.fin_proposals p join public.fin_rfqs r on r.id = p.rfq_id where p.id = p_id)
    when 'decision' then (select r.legal_entity_id from public.fin_decisions d join public.fin_rfqs r on r.id = d.rfq_id where d.id = p_id)
    when 'approval' then (select r.legal_entity_id from public.fin_approval_requests a join public.fin_rfqs r on r.id = a.rfq_id where a.id = p_id)
    when 'contract' then (select c.legal_entity_id from public.fin_contracts c where c.id = p_id)
    when 'task' then (select t.legal_entity_id from public.fin_tasks t where t.id = p_id)
    when 'legal_entity' then p_id
    when 'facility' then (select f.legal_entity_id from public.fin_facilities f where f.id = p_id)
    when 'guarantee' then (select g.legal_entity_id from public.fin_guarantees g where g.id = p_id)
    else null end;
$$;


ALTER FUNCTION public.fin_object_legal_entity(p_type text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_object_visible(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_object_visible(p_org uuid, p_type text, p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case
 when p_type='crm_contact' then exists(select 1 from public.fin_provider_contacts c where c.organization_id=p_org and c.id=p_id and (public.fin_group_or_entity_visible(c.organization_id,c.legal_entity_id) or public.fin_crm_scope_visible(c.organization_id,c.legal_entity_id)))
 when p_type='crm_activity' then exists(select 1 from public.fin_crm_activities a where a.organization_id=p_org and a.id=p_id and public.fin_crm_scope_visible(a.organization_id,a.legal_entity_id))
 when p_type='crm_process' then exists(select 1 from public.fin_crm_processes p where p.organization_id=p_org and p.id=p_id and public.fin_crm_scope_visible(p.organization_id,p.legal_entity_id))
 when p_type in ('rfq','proposal','decision','approval','contract','task','legal_entity') then public.fin_entity_visible(p_org,public.fin_object_legal_entity(p_type,p_id))
 else public.fin_has_role(p_org) end;
$$;


ALTER FUNCTION public.fin_object_visible(p_org uuid, p_type text, p_id uuid) OWNER TO postgres;

--
-- Name: fin_obligation_add_period(uuid, date, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_obligation_add_period(p_obligation uuid, p_start date, p_end date, p_due date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype; v_id uuid;v_task uuid;begin
 select * into o from public.fin_obligations where id=p_obligation for update;
 select id into v_id from public.fin_obligation_periods where obligation_id=o.id and period_start=p_start;
 if v_id is not null then return v_id;end if;
 insert into public.fin_tasks(organization_id,title,due_on,related_type,related_id,created_by) values(o.organization_id,'Obrigação: '||o.title,p_due,'contract',o.contract_id,o.created_by) returning id into v_task;
 insert into public.fin_obligation_periods(organization_id,obligation_id,period_start,period_end,due_on,task_id) values(o.organization_id,o.id,p_start,p_end,p_due,v_task) returning id into v_id;
 return v_id;
end $$;


ALTER FUNCTION public.fin_obligation_add_period(p_obligation uuid, p_start date, p_end date, p_due date) OWNER TO postgres;

--
-- Name: fin_obligation_facts(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_obligation_facts(p_period uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('status',case
 when o.status='cancelled' then 'not_applicable'
 when w.id is not null then 'waived'
 when r.status='not_applicable' then 'not_applicable'
 when r.status in ('compliant','non_compliant') and coalesce(m.recorded_at,e.recorded_at)<=r.reviewed_at then r.status
 when m.id is not null or e.id is not null then 'under_review'
 when p_day<p.due_on-o.due_soon_days then 'not_due'
 when p_day<p.due_on then 'due_soon'
 else 'awaiting_data' end,
 'period_id',p.id,'obligation_id',o.id,'contract_id',o.contract_id,'due_on',p.due_on,'grace_until',p.due_on+o.grace_days,'observed_at',p_day,
 'has_data',m.id is not null or e.id is not null,'measurement_id',m.id,'evidence_id',e.id,'review_id',r.id,'waiver_id',w.id,'waiver_until',w.valid_until,
 'measured_value',m.measured_value::text,'metric',c.metric,'operator',c.operator,'threshold',c.threshold::text,'unit',c.unit,'currency',c.currency,
 'factual_result',case when m.id is null then null else case c.operator when 'lt' then m.measured_value<c.threshold when 'le' then m.measured_value<=c.threshold when 'eq' then m.measured_value=c.threshold when 'ge' then m.measured_value>=c.threshold when 'gt' then m.measured_value>c.threshold end end,
 'formula','measured_value operator customer threshold; missing data is unknown; compliance requires independent human review',
 'reviewed_by',r.reviewed_by,'review_reason',r.reason,'source_reference',coalesce(m.source_reference,e.source_reference,o.source_reference),'provenance',coalesce(m.provenance,e.provenance))
 from public.fin_obligation_periods p join public.fin_obligations o on o.id=p.obligation_id left join public.fin_covenants c on c.obligation_id=o.id
 left join lateral(select * from public.fin_covenant_measurements where period_id=p.id order by recorded_at desc,id desc limit 1)m on true
 left join lateral(select * from public.fin_obligation_evidence where period_id=p.id order by recorded_at desc,id desc limit 1)e on true
 left join lateral(select * from public.fin_obligation_reviews where period_id=p.id order by reviewed_at desc,id desc limit 1)r on true
 left join lateral(select * from public.fin_covenant_waivers where period_id=p.id and status='approved' and valid_until>=p_day order by valid_until desc,id desc limit 1)w on true
 where p.id=p_period and p_day is not null
$$;


ALTER FUNCTION public.fin_obligation_facts(p_period uuid, p_day date) OWNER TO postgres;

--
-- Name: fin_obligations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_obligations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    source_contract_version integer NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    title text NOT NULL,
    kind text NOT NULL,
    source_clause text NOT NULL,
    source_reference text NOT NULL,
    owner_id uuid NOT NULL,
    frequency text NOT NULL,
    first_period_start date NOT NULL,
    first_period_end date NOT NULL,
    first_due_on date NOT NULL,
    grace_days integer DEFAULT 0 NOT NULL,
    due_soon_days integer DEFAULT 30 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    cancellation_reason text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_obligations_check CHECK (((first_period_end >= first_period_start) AND (first_due_on >= first_period_end))),
    CONSTRAINT fin_obligations_due_soon_days_check CHECK (((due_soon_days >= 0) AND (due_soon_days <= 90))),
    CONSTRAINT fin_obligations_frequency_check CHECK ((frequency = ANY (ARRAY['once'::text, 'monthly'::text, 'quarterly'::text, 'annually'::text]))),
    CONSTRAINT fin_obligations_grace_days_check CHECK (((grace_days >= 0) AND (grace_days <= 365))),
    CONSTRAINT fin_obligations_kind_check CHECK ((kind = ANY (ARRAY['financial_covenant'::text, 'reporting_covenant'::text, 'information_obligation'::text, 'contractual_deadline'::text, 'operational_obligation'::text, 'document_delivery'::text]))),
    CONSTRAINT fin_obligations_source_clause_check CHECK ((((length(TRIM(BOTH FROM source_clause)) >= 3) AND (length(TRIM(BOTH FROM source_clause)) <= 2000)) AND (source_clause !~ '[<>]'::text))),
    CONSTRAINT fin_obligations_source_contract_version_check CHECK ((source_contract_version >= 0)),
    CONSTRAINT fin_obligations_source_reference_check CHECK ((((length(TRIM(BOTH FROM source_reference)) >= 3) AND (length(TRIM(BOTH FROM source_reference)) <= 200)) AND (source_reference !~ '[<>]'::text))),
    CONSTRAINT fin_obligations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'cancelled'::text]))),
    CONSTRAINT fin_obligations_title_check CHECK ((((length(TRIM(BOTH FROM title)) >= 3) AND (length(TRIM(BOTH FROM title)) <= 200)) AND (title !~ '[<>]'::text)))
);

ALTER TABLE ONLY public.fin_obligations FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_obligations OWNER TO postgres;

--
-- Name: fin_obligation_require(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_obligation_require(p_period uuid, p_roles text[]) RETURNS public.fin_obligations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype;begin
 select s.* into o from public.fin_obligations s join public.fin_obligation_periods p on p.obligation_id=s.id where p.id=p_period for update of s;
 if o.id is null or auth.uid() is null or not public.fin_entity_allows(o.organization_id,o.legal_entity_id,p_roles) or not exists(select 1 from public.fin_organizations where id=o.organization_id and kind='BUYER') then raise exception 'forbidden';end if;
 if public.fin_governance_org_locked(o.organization_id) then raise exception 'organization offboarding';end if;
 if o.status<>'active' then raise exception 'obligation closed';end if;
 return o;
end $$;


ALTER FUNCTION public.fin_obligation_require(p_period uuid, p_roles text[]) OWNER TO postgres;

--
-- Name: fin_obligation_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_obligation_summary(p_org uuid, p_entity uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v jsonb;begin
 if not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) or not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden';end if;
 select coalesce(jsonb_agg(s),'[]'::jsonb) into v from(select kind,facts->>'status' as status,count(*) as periods,count(*) filter(where (facts->>'has_data')::boolean) as with_data from public.fin_obligation_monitor where organization_id=p_org and (p_entity is null or legal_entity_id=p_entity) group by kind,facts->>'status')s;
 return jsonb_build_object('rows',v,'observed_at',current_date,'scope','authorized periods only','formula','count authorized periods grouped by kind and effective state; missing data does not establish compliance');
end $$;


ALTER FUNCTION public.fin_obligation_summary(p_org uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_observe_value(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_observe_value(p_record uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_value_records%rowtype; v_id uuid:=gen_random_uuid(); v_amount numeric; m public.fin_value_methodologies%rowtype;
begin
  select * into r from public.fin_value_records where id=p_record for update;
  if r.id is null or auth.uid() is null or not public.fin_entity_allows(r.organization_id,r.legal_entity_id,array['admin','finance_manager'])
     or not exists(select 1 from public.fin_contracts c where c.id=r.contract_id and c.organization_id=r.organization_id and public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager'])) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(r.organization_id) then raise exception 'organization offboarding'; end if;
  if r.kind<>'NEGOTIATED_SAVINGS' or r.status<>'active' or r.comparability<>'comparable' then raise exception 'value not realizable'; end if;
  if exists(select 1 from public.fin_value_records where parent_id=r.id) then raise exception 'value already realized'; end if;
  v_amount:=(p_input->>'observed_amount')::numeric;
  if v_amount is null or v_amount<0 or v_amount>1000000000000 or v_amount::text='NaN' or v_amount<>round(v_amount,2)
    or p_input->>'currency' is distinct from r.currency or p_input->>'coverage' is distinct from 'complete'
    or (p_input->>'period_start')::date is distinct from r.period_start or (p_input->>'period_end')::date is distinct from r.period_end
    or r.period_end>=current_date or r.period_start<=(r.baseline->>'as_of')::date
    or p_input->'verified' is distinct from 'true'::jsonb then raise exception 'value observation incomplete'; end if;
  insert into public.fin_value_methodologies(organization_id,method_key,definition,created_by)
    values(r.organization_id,'observed_period_total_difference',
      '{"formula":"baseline_period_total - observed_period_total","version":1,"unit":"period_total","rounding":"2 decimal places","verification":"Human verified evidence for complete closed period; negotiated amount is not realized amount"}',auth.uid())
    on conflict(organization_id,method_key,version) do nothing;
  select * into m from public.fin_value_methodologies where organization_id=r.organization_id and method_key='observed_period_total_difference' and version=1;
  insert into public.fin_value_records(id,organization_id,contract_id,contract_version,legal_entity_id,provider_id,product,owner_id,kind,title,currency,period_start,period_end,baseline,target_amount,target_snapshot,target_dimensions,comparability,value_amount,methodology_id,methodology_snapshot,evidence_reference,reason,parent_id)
  values(v_id,r.organization_id,r.contract_id,r.contract_version,r.legal_entity_id,r.provider_id,r.product,auth.uid(),'REALIZED_SAVINGS',r.title,r.currency,r.period_start,r.period_end,r.baseline,v_amount,r.target_snapshot,r.target_dimensions,'comparable',round((r.baseline->>'amount')::numeric-v_amount,2),m.id,m.definition,p_input->>'evidence_reference',p_input->>'verification_reason',r.id);
  insert into public.fin_value_observations(organization_id,record_id,realized_record_id,observed_amount,currency,period_start,period_end,coverage,source,evidence_reference,verification_reason,verified_by)
  values(r.organization_id,r.id,v_id,v_amount,r.currency,r.period_start,r.period_end,'complete',p_input->>'source',p_input->>'evidence_reference',p_input->>'verification_reason',auth.uid());
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
  values(r.organization_id,'contract',r.contract_id,'value_realized',auth.uid(),jsonb_build_object('record_id',v_id,'parent_id',r.id,'coverage','complete'));
  return v_id;
end $$;


ALTER FUNCTION public.fin_observe_value(p_record uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_open_implementation(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_open_implementation(p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype; v_id uuid; v_owner uuid; v_contact uuid; v_kind text;
  v_i integer:=0; v_prev uuid; v_mid uuid; v_task uuid; v_kinds text[];
begin
 select * into c from public.fin_contracts where id=p_contract for update;
 if c.id is null or auth.uid() is null or not public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager']) or not exists(select 1 from public.fin_organizations where id=c.organization_id and kind='BUYER') then raise exception 'forbidden'; end if;
 if public.fin_governance_org_locked(c.organization_id) then raise exception 'organization offboarding'; end if;
 if c.status not in ('active','renewing') then raise exception 'implementation contract inactive'; end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('title','owner_id','provider_owner_contact_id','starts_on','target_go_live','source_reference')) then raise exception 'invalid implementation input'; end if;
 if exists(select 1 from public.fin_implementation_plans where contract_id=c.id) then raise exception 'implementation already exists'; end if;
 v_owner:=coalesce(nullif(p_input->>'owner_id','')::uuid,auth.uid()); v_contact:=nullif(p_input->>'provider_owner_contact_id','')::uuid;
 if not public.fin_implementation_owner_valid(c.organization_id,c.legal_entity_id,v_owner) then raise exception 'invalid implementation owner'; end if;
 if v_contact is not null and not exists(select 1 from public.fin_provider_contacts where id=v_contact and organization_id=c.organization_id and provider_id=c.provider_id and (legal_entity_id is null or legal_entity_id is not distinct from c.legal_entity_id)) then raise exception 'invalid implementation owner'; end if;
 if c.product='credit' then v_kinds:=array['documentation','legal_review','signing','conditions_precedent','collateral','guarantees','facility_setup','availability_confirmation','drawdown_readiness','go_live'];
 elsif c.product='acquiring' then v_kinds:=array['commercial_setup','credentials','integration','establishments','homologation','pricing_activation','settlement_validation','go_live'];
 else v_kinds:=array['kickoff','documentation','configuration','validation','go_live']; end if;
 insert into public.fin_implementation_plans(organization_id,legal_entity_id,provider_id,contract_id,decision_id,product,title,owner_id,provider_owner_contact_id,starts_on,target_go_live,template_version,source_reference,created_by)
 values(c.organization_id,c.legal_entity_id,c.provider_id,c.id,c.decision_id,c.product,trim(p_input->>'title'),v_owner,v_contact,(p_input->>'starts_on')::date,(p_input->>'target_go_live')::date,c.product||':v1',trim(p_input->>'source_reference'),auth.uid()) returning id into v_id;
 foreach v_kind in array v_kinds loop
   v_i:=v_i+1;
   insert into public.fin_tasks(organization_id,title,due_on,related_type,related_id,created_by)
   values(c.organization_id,'Implantação: '||public.fin_implementation_milestone_label(v_kind),(p_input->>'target_go_live')::date,'contract',c.id,auth.uid()) returning id into v_task;
   insert into public.fin_implementation_milestones(organization_id,plan_id,position,kind,title,owner_id,due_on,task_id)
   values(c.organization_id,v_id,v_i,v_kind,public.fin_implementation_milestone_label(v_kind),v_owner,(p_input->>'target_go_live')::date,v_task) returning id into v_mid;
   if v_prev is not null then insert into public.fin_implementation_dependencies values(c.organization_id,v_id,v_mid,v_prev); end if;
   v_prev:=v_mid;
 end loop;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
 values(c.organization_id,'contract',c.id,'implementation_opened',auth.uid(),c.legal_entity_id,jsonb_build_object('implementation_id',v_id,'milestones',v_i));
 insert into public.fin_notifications(organization_id,user_id,event_type,object_type,object_id,event_id,title,body)
 values(c.organization_id,v_owner,'task_assigned','contract',c.id,v_id,'Implantação atribuída','Consulte os marcos e prazos do contrato.');
 return v_id;
end $$;


ALTER FUNCTION public.fin_open_implementation(p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_open_obligation(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_open_obligation(p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype;v_id uuid;v_owner uuid;v_step integer;begin
 select * into c from public.fin_contracts where id=p_contract for update;
 if c.id is null or auth.uid() is null or not public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager']) or not exists(select 1 from public.fin_organizations where id=c.organization_id and kind='BUYER') then raise exception 'forbidden';end if;
 if public.fin_governance_org_locked(c.organization_id) then raise exception 'organization offboarding';end if;
 if c.status not in ('active','renewing') then raise exception 'obligation contract inactive';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('title','kind','source_clause','source_reference','owner_id','frequency','first_period_start','first_period_end','first_due_on','grace_days','due_soon_days','metric','operator','threshold','unit','currency')) then raise exception 'invalid obligation input';end if;
 v_owner:=coalesce(nullif(p_input->>'owner_id','')::uuid,auth.uid());
 if not public.fin_implementation_owner_valid(c.organization_id,c.legal_entity_id,v_owner) then raise exception 'invalid obligation owner';end if;
 v_step:=case p_input->>'frequency' when 'monthly' then 1 when 'quarterly' then 3 when 'annually' then 12 else 0 end;
 if (p_input->>'first_period_start')::date < current_date-interval '5 years' or (v_step>0 and (p_input->>'first_period_end')::date<>((p_input->>'first_period_start')::date+make_interval(months=>v_step))::date-1) then raise exception 'invalid obligation period';end if;
 if p_input->>'kind'<>'financial_covenant' and exists(select 1 from jsonb_object_keys(p_input) k where k in ('metric','operator','threshold','unit','currency') and p_input->>k is not null and p_input->>k<>'') then raise exception 'invalid obligation metric';end if;
 insert into public.fin_obligations(organization_id,contract_id,source_contract_version,legal_entity_id,provider_id,title,kind,source_clause,source_reference,owner_id,frequency,first_period_start,first_period_end,first_due_on,grace_days,due_soon_days,created_by)
 values(c.organization_id,c.id,c.current_version,c.legal_entity_id,c.provider_id,trim(p_input->>'title'),p_input->>'kind',trim(p_input->>'source_clause'),trim(p_input->>'source_reference'),v_owner,p_input->>'frequency',(p_input->>'first_period_start')::date,(p_input->>'first_period_end')::date,(p_input->>'first_due_on')::date,coalesce((p_input->>'grace_days')::int,0),coalesce((p_input->>'due_soon_days')::int,30),auth.uid()) returning id into v_id;
 if p_input->>'kind'='financial_covenant' then insert into public.fin_covenants(obligation_id,organization_id,metric,operator,threshold,unit,currency) values(v_id,c.organization_id,trim(p_input->>'metric'),p_input->>'operator',(p_input->>'threshold')::numeric,p_input->>'unit',nullif(p_input->>'currency',''));end if;
 perform public.fin_obligation_add_period(v_id,(p_input->>'first_period_start')::date,(p_input->>'first_period_end')::date,(p_input->>'first_due_on')::date);
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(c.organization_id,'contract',c.id,'obligation_opened',auth.uid(),c.legal_entity_id,jsonb_build_object('obligation_id',v_id));
 return v_id;
end $$;


ALTER FUNCTION public.fin_open_obligation(p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_open_performance_period(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_open_performance_period(p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype;prev public.fin_provider_performance_periods%rowtype;v_id uuid;v_task uuid;v_owner uuid;x jsonb;d public.fin_provider_performance_dimensions%rowtype;begin
 select * into c from public.fin_contracts where id=p_contract for update;
 if auth.uid() is null or c.id is null or not public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager']) or not exists(select 1 from public.fin_organizations where id=c.organization_id and kind='BUYER') then raise exception 'forbidden';end if;
 if public.fin_governance_org_locked(c.organization_id) then raise exception 'organization offboarding';end if;
 if c.status not in ('active','renewing') then raise exception 'performance contract inactive';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('title','period_start','period_end','review_due_on','owner_id','dimensions','previous_period_id')) or jsonb_typeof(p_input->'dimensions') is distinct from 'array' or jsonb_array_length(p_input->'dimensions') not between 1 and 20 then raise exception 'invalid performance input';end if;
 v_owner:=coalesce(nullif(p_input->>'owner_id','')::uuid,auth.uid());if not public.fin_implementation_owner_valid(c.organization_id,c.legal_entity_id,v_owner) then raise exception 'invalid performance owner';end if;
 if nullif(p_input->>'previous_period_id','') is not null then
 select * into prev from public.fin_provider_performance_periods where id=(p_input->>'previous_period_id')::uuid for update;
 if prev.id is null or prev.contract_id<>c.id or prev.status<>'closed' or prev.period_start<>(p_input->>'period_start')::date or prev.period_end<>(p_input->>'period_end')::date then raise exception 'invalid performance predecessor';end if;
 end if;
 insert into public.fin_tasks(organization_id,title,due_on,related_type,related_id,created_by) values(c.organization_id,left('Revisar performance: '||trim(p_input->>'title'),200),(p_input->>'review_due_on')::date,'contract',c.id,auth.uid()) returning id into v_task;
 insert into public.fin_provider_performance_periods(organization_id,contract_id,legal_entity_id,provider_id,product,source_contract_version,title,period_start,period_end,review_due_on,owner_id,previous_period_id,task_id,created_by)
 values(c.organization_id,c.id,c.legal_entity_id,c.provider_id,c.product,c.current_version,trim(p_input->>'title'),(p_input->>'period_start')::date,(p_input->>'period_end')::date,(p_input->>'review_due_on')::date,v_owner,prev.id,v_task,auth.uid()) returning id into v_id;
 for x in select value from jsonb_array_elements(p_input->'dimensions') loop
 if jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_object_keys(x) k where k not in ('dimension_id','operator','threshold','source_reference')) then raise exception 'invalid performance target';end if;
 select * into d from public.fin_provider_performance_dimensions where id=(x->>'dimension_id')::uuid and organization_id=c.organization_id;
 if d.id is null or d.unit='percent' and (x->>'threshold')::numeric>100 then raise exception 'invalid performance target';end if;
 insert into public.fin_provider_performance_targets(organization_id,period_id,dimension_id,operator,threshold,source_reference,created_by) values(c.organization_id,v_id,d.id,nullif(x->>'operator',''),nullif(x->>'threshold','')::numeric,trim(x->>'source_reference'),auth.uid());
 end loop;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(c.organization_id,'contract',c.id,'performance_period_opened',auth.uid(),c.legal_entity_id,jsonb_build_object('period_id',v_id,'previous_period_id',prev.id));return v_id;
end $$;


ALTER FUNCTION public.fin_open_performance_period(p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_open_provider_issue(uuid, uuid, text, text, text, text, uuid, uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_open_provider_issue(p_org uuid, p_provider uuid, p_title text, p_category text DEFAULT 'service'::text, p_severity text DEFAULT 'medium'::text, p_description text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_contract uuid DEFAULT NULL::uuid, p_due date DEFAULT NULL::date, p_owner uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; v_entity uuid := p_entity;
begin
  if p_contract is not null then
    select legal_entity_id into v_entity from public.fin_contracts where id = p_contract and organization_id = p_org and provider_id = p_provider;
    if not found then raise exception 'contract not found'; end if;
    if p_entity is not null and p_entity is distinct from v_entity then raise exception 'invalid legal entity'; end if;
  end if;
  perform public.fin_assert_portfolio_write(p_org, v_entity);
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_owner is not null and not exists (select 1 from public.fin_members m where m.organization_id = p_org and m.user_id = p_owner) then raise exception 'invalid owner'; end if;
  insert into public.fin_provider_issues(organization_id, provider_id, legal_entity_id, contract_id, title, description, category, severity, due_on, owner_id, created_by)
    values (p_org, p_provider, v_entity, p_contract, trim(p_title), nullif(trim(coalesce(p_description,'')),''), coalesce(p_category,'service'),
      coalesce(p_severity,'medium'), p_due, coalesce(p_owner, auth.uid()), auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'provider', p_provider, 'provider_issue_opened', auth.uid(), jsonb_build_object('issue_id', v_id, 'severity', p_severity, 'category', p_category), v_entity);
  return v_id;
exception when check_violation then raise exception 'invalid issue';
end $$;


ALTER FUNCTION public.fin_open_provider_issue(p_org uuid, p_provider uuid, p_title text, p_category text, p_severity text, p_description text, p_entity uuid, p_contract uuid, p_due date, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_open_provider_qualification(uuid, uuid, uuid, text, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_open_provider_qualification(p_org uuid, p_provider uuid, p_entity uuid, p_category text, p_owner uuid, p_review_due date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if auth.uid() is null or not public.fin_entity_allows(p_org, p_entity, array['admin','finance_manager']) or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  if not exists (select 1 from public.fin_providers where organization_id = p_org and id = p_provider) then raise exception 'invalid qualification'; end if;
  if p_category is null or p_category not in ('all','credit','acquiring','cash_management','payments','fx','guarantee','insurance','other') or (p_review_due is not null and p_review_due < current_date) then raise exception 'invalid qualification'; end if;
  if not public.fin_entity_allows(p_org, p_entity, array['admin','finance_manager','analyst']) or not exists (select 1 from public.fin_members m where m.organization_id = p_org and m.user_id = coalesce(p_owner, auth.uid()) and m.role in ('admin','finance_manager','analyst')) then raise exception 'invalid qualification owner'; end if;
  if exists (select 1 from public.fin_provider_qualifications where organization_id = p_org and provider_id = p_provider and legal_entity_id is not distinct from p_entity and category = p_category) then raise exception 'qualification already exists'; end if;
  insert into public.fin_provider_qualifications(organization_id, provider_id, legal_entity_id, category, owner_id, review_due_on, created_by)
  values (p_org, p_provider, p_entity, p_category, coalesce(p_owner, auth.uid()), p_review_due, auth.uid()) returning id into v_id;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, to_status, actor_id) values (p_org, v_id, 'opened', 'not_started', auth.uid());
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, 'provider', p_provider, 'provider_qualification_opened', auth.uid(), jsonb_build_object('qualification_id', v_id, 'category', p_category));
  return v_id;
end $$;


ALTER FUNCTION public.fin_open_provider_qualification(p_org uuid, p_provider uuid, p_entity uuid, p_category text, p_owner uuid, p_review_due date) OWNER TO postgres;

--
-- Name: fin_opportunity_candidates(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_candidates(p_org uuid, p_day date) RETURNS TABLE(rule_id uuid, rule_key text, rule_version integer, parameters jsonb, legal_entity_id uuid, provider_id uuid, source_type text, source_id uuid, discriminator text, deadline date, facts jsonb, material jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with r as (
    select distinct on (x.rule_key) x.* from public.fin_opportunity_rules x
    where x.organization_id = p_org and x.effective_at <= now() order by x.rule_key, x.version desc
  ), live as (select * from r where enabled)
  -- Contract renewal: the contract's own notice window + customer lead days.
  select l.id, l.rule_key, l.version, l.parameters, c.legal_entity_id, c.provider_id, 'contract', c.id, '', (c.ends_on - c.renewal_notice_days),
    jsonb_build_object('contract_id', c.id, 'title', c.title, 'ends_on', c.ends_on, 'renewal_notice_days', c.renewal_notice_days, 'notice_date', c.ends_on - c.renewal_notice_days,
      'days_to_notice', (c.ends_on - c.renewal_notice_days) - p_day, 'days_to_end', c.ends_on - p_day, 'lead_days', (l.parameters->>'lead_days')::int, 'observed_at', p_day),
    jsonb_build_object('contract_id', c.id, 'ends_on', c.ends_on, 'renewal_notice_days', c.renewal_notice_days, 'lead_days', (l.parameters->>'lead_days')::int)
  from live l join public.fin_contracts c on c.organization_id = p_org
  where l.rule_key = 'contract_renewal' and c.status in ('active','renewing')
    and p_day between (c.ends_on - c.renewal_notice_days - (l.parameters->>'lead_days')::int) and (c.ends_on - c.renewal_notice_days)
  union all
  -- Repricing window: milestone due date and the milestone's own lead days.
  select l.id, l.rule_key, l.version, l.parameters, c.legal_entity_id, c.provider_id, 'contract_milestone', m.id, '', m.due_on,
    jsonb_build_object('milestone_id', m.id, 'contract_id', c.id, 'title', m.title, 'due_on', m.due_on, 'lead_days', m.lead_days, 'days_to_due', m.due_on - p_day, 'observed_at', p_day),
    jsonb_build_object('milestone_id', m.id, 'due_on', m.due_on, 'lead_days', m.lead_days)
  from live l join public.fin_contract_milestones m on m.organization_id = p_org join public.fin_contracts c on c.organization_id = m.organization_id and c.id = m.contract_id
  where l.rule_key = 'repricing_window' and m.kind = 'repricing' and m.status = 'scheduled' and p_day between m.due_on - m.lead_days and m.due_on
  union all
  select l.id, l.rule_key, l.version, l.parameters, f.legal_entity_id, f.provider_id, 'facility', f.id, '', f.maturity_on,
    jsonb_build_object('facility_id', f.id, 'name', f.name, 'maturity_on', f.maturity_on, 'days_to_maturity', f.maturity_on - p_day, 'lead_days', (l.parameters->>'lead_days')::int, 'observed_at', p_day),
    jsonb_build_object('facility_id', f.id, 'maturity_on', f.maturity_on, 'lead_days', (l.parameters->>'lead_days')::int)
  from live l join public.fin_facilities f on f.organization_id = p_org
  where l.rule_key = 'facility_maturity' and f.status = 'active' and f.maturity_on between p_day and p_day + (l.parameters->>'lead_days')::int
  union all
  select l.id, l.rule_key, l.version, l.parameters, g.legal_entity_id, coalesce(g.provider_id, f.provider_id), 'guarantee', g.id, '', g.ends_on,
    jsonb_build_object('guarantee_id', g.id, 'description', g.description, 'ends_on', g.ends_on, 'days_to_end', g.ends_on - p_day, 'lead_days', (l.parameters->>'lead_days')::int, 'observed_at', p_day),
    jsonb_build_object('guarantee_id', g.id, 'ends_on', g.ends_on, 'lead_days', (l.parameters->>'lead_days')::int)
  from live l join public.fin_guarantees g on g.organization_id = p_org left join public.fin_facilities f on f.organization_id = g.organization_id and f.id = g.facility_id
  where l.rule_key = 'guarantee_review' and g.status = 'active' and g.ends_on between p_day and p_day + (l.parameters->>'lead_days')::int
  union all
  -- Passport: declared validity dates, aggregated per scope (group or entity).
  select l.id, l.rule_key, l.version, l.parameters, p.legal_entity_id, null::uuid, 'passport', coalesce(p.legal_entity_id, p_org), '', min(p.valid_until),
    jsonb_build_object('fields', count(*), 'field_keys', jsonb_agg(p.field_key order by p.field_key), 'earliest_valid_until', min(p.valid_until), 'lead_days', (l.parameters->>'lead_days')::int, 'observed_at', p_day),
    jsonb_build_object('field_keys', jsonb_agg(p.field_key order by p.field_key), 'earliest_valid_until', min(p.valid_until))
  from live l join public.fin_company_profiles p on p.organization_id = p_org
  where l.rule_key = 'passport_stale' and p.valid_until is not null and p.valid_until <= p_day + (l.parameters->>'lead_days')::int
  group by l.id, l.rule_key, l.version, l.parameters, p.legal_entity_id
  union all
  -- Facility data freshness: the facility's own review_after_days.
  select l.id, l.rule_key, l.version, l.parameters, f.legal_entity_id, f.provider_id, 'facility', f.id, '', null::date,
    jsonb_build_object('facility_id', f.id, 'name', f.name, 'verified_at', f.verified_at, 'review_after_days', f.review_after_days, 'source', f.source, 'observed_at', p_day),
    jsonb_build_object('facility_id', f.id, 'verified_at', f.verified_at, 'review_after_days', f.review_after_days)
  from live l join public.fin_facilities f on f.organization_id = p_org
  where l.rule_key = 'facility_data_stale' and f.status = 'active' and (f.verified_at is null or f.verified_at::date + f.review_after_days < p_day)
  union all
  select l.id, l.rule_key, l.version, l.parameters, v.legal_entity_id, v.provider_id, 'fee_variance', v.id, '', null::date,
    jsonb_build_object('variance_id', v.id, 'contract_id', v.contract_id, 'service', v.service, 'currency', v.currency, 'comparison_status', v.comparison_status, 'direction', v.direction,
      'variance_amount', v.variance_amount, 'period_start', v.period_start, 'period_end', v.period_end, 'review_status', v.review_status, 'observed_at', p_day),
    jsonb_build_object('variance_id', v.id, 'review_status', v.review_status)
  from live l join public.fin_fee_variances v on v.organization_id = p_org
  where l.rule_key = 'fee_variance_review' and v.review_status = 'new' and v.created_at::date <= p_day - (l.parameters->>'min_age_days')::int
  union all
  -- A human-confirmed and resolved difference may deserve a value record: a
  -- prompt only; the value ledger keeps its own methodology and validation.
  select l.id, l.rule_key, l.version, l.parameters, v.legal_entity_id, v.provider_id, 'fee_variance', v.id, '', null::date,
    jsonb_build_object('variance_id', v.id, 'contract_id', v.contract_id, 'service', v.service, 'currency', v.currency, 'variance_amount', v.variance_amount, 'resolved_at', v.last_reviewed_at, 'observed_at', p_day),
    jsonb_build_object('variance_id', v.id, 'resolved_at', v.last_reviewed_at)
  from live l join public.fin_fee_variances v on v.organization_id = p_org
  where l.rule_key = 'fee_resolution_value_review' and v.review_status = 'resolved' and v.direction = 'above'
    and exists (select 1 from public.fin_fee_reviews w where w.variance_id = v.id and w.to_status = 'confirmed')
  union all
  select l.id, l.rule_key, l.version, l.parameters, x.legal_entity_id, x.provider_id, 'value_record', x.id, '', null::date,
    jsonb_build_object('value_record_id', x.id, 'contract_id', x.contract_id, 'title', x.title, 'currency', x.currency, 'period_end', x.period_end, 'grace_days', (l.parameters->>'grace_days')::int, 'observed_at', p_day),
    jsonb_build_object('value_record_id', x.id, 'period_end', x.period_end)
  from live l join public.fin_value_records x on x.organization_id = p_org
  where l.rule_key = 'value_realization_review' and x.kind = 'NEGOTIATED_SAVINGS' and x.status = 'active' and x.comparability = 'comparable'
    and x.period_end <= p_day - (l.parameters->>'grace_days')::int and not exists (select 1 from public.fin_value_records y where y.parent_id = x.id)
  union all
  select l.id, l.rule_key, l.version, l.parameters, q.legal_entity_id, null::uuid, 'rfq', q.id, '', q.response_deadline,
    jsonb_build_object('rfq_id', q.id, 'title', q.title, 'status', q.status, 'proposals', (select count(*) from public.fin_proposals p where p.rfq_id = q.id and p.status in ('submitted','revised')),
      'min_proposals', (l.parameters->>'min_proposals')::int, 'observed_at', p_day),
    jsonb_build_object('rfq_id', q.id, 'proposals', (select count(*) from public.fin_proposals p where p.rfq_id = q.id and p.status in ('submitted','revised')), 'min_proposals', (l.parameters->>'min_proposals')::int)
  from live l join public.fin_rfqs q on q.organization_id = p_org
  where l.rule_key = 'proposal_count_below' and q.status in ('collecting','comparing')
    and (select count(*) from public.fin_proposals p where p.rfq_id = q.id and p.status in ('submitted','revised')) < (l.parameters->>'min_proposals')::int
  union all
  -- Concentration per currency over approved limits of active facilities.
  select l.id, l.rule_key, l.version, l.parameters, null::uuid, s.provider_id, 'provider', s.provider_id, s.currency, null::date,
    jsonb_build_object('provider_id', s.provider_id, 'currency', s.currency, 'provider_limit', s.provider_limit, 'total_limit', s.total_limit,
      'share_pct', round(s.provider_limit * 100 / s.total_limit, 2), 'max_share_pct', (l.parameters->>'max_share_pct')::int, 'facilities', s.facilities, 'observed_at', p_day),
    jsonb_build_object('provider_id', s.provider_id, 'currency', s.currency, 'provider_limit', s.provider_limit, 'total_limit', s.total_limit, 'max_share_pct', (l.parameters->>'max_share_pct')::int)
  from live l join (
    select f.provider_id, f.currency, sum(f.approved_limit) as provider_limit, count(*) as facilities,
      sum(sum(f.approved_limit)) over (partition by f.currency) as total_limit
    from public.fin_facilities f where f.organization_id = p_org and f.status = 'active' and f.approved_limit is not null and f.approved_limit > 0
    group by f.provider_id, f.currency) s on true
  where l.rule_key = 'provider_concentration' and s.provider_limit * 100 > (l.parameters->>'max_share_pct')::numeric * s.total_limit
  union all
  select l.id, l.rule_key, l.version, l.parameters, f.legal_entity_id, f.provider_id, 'facility', f.id, '', null::date,
    jsonb_build_object('facility_id', f.id, 'name', f.name, 'currency', f.currency, 'as_of', b.as_of, 'used_limit_amount', b.used_limit_amount, 'approved_limit', f.approved_limit,
      'utilization_pct', round(b.used_limit_amount * 100 / f.approved_limit, 2), 'max_utilization_pct', (l.parameters->>'max_utilization_pct')::int, 'observed_at', p_day),
    jsonb_build_object('facility_id', f.id, 'as_of', b.as_of, 'used_limit_amount', b.used_limit_amount, 'approved_limit', f.approved_limit, 'max_utilization_pct', (l.parameters->>'max_utilization_pct')::int)
  from live l join public.fin_facilities f on f.organization_id = p_org
  join lateral (select z.as_of, z.used_limit_amount from public.fin_facility_balances z where z.organization_id = f.organization_id and z.facility_id = f.id and z.used_limit_amount is not null order by z.as_of desc, z.recorded_at desc limit 1) b on true
  where l.rule_key = 'facility_utilization' and f.status = 'active' and f.approved_limit > 0
    and b.used_limit_amount * 100 > (l.parameters->>'max_utilization_pct')::numeric * f.approved_limit
  union all
  select l.id, l.rule_key, l.version, l.parameters, null::uuid, null::uuid, 'organization', p_org, '', null::date,
    jsonb_build_object('exceptions', e.n, 'window_days', (l.parameters->>'window_days')::int, 'min_count', (l.parameters->>'min_count')::int, 'reason_codes', e.codes, 'observed_at', p_day),
    jsonb_build_object('exceptions', e.n, 'window_days', (l.parameters->>'window_days')::int, 'min_count', (l.parameters->>'min_count')::int)
  from live l join lateral (select count(*) as n, jsonb_agg(distinct x.reason_code) as codes from public.fin_policy_exceptions x
    where x.organization_id = p_org and x.status in ('requested','approved') and x.created_at >= p_day - (l.parameters->>'window_days')::int) e on true
  where l.rule_key = 'approval_exception_frequency' and e.n >= (l.parameters->>'min_count')::int
  union all
  select l.id, l.rule_key, l.version, l.parameters, c.legal_entity_id, c.provider_id, 'contract', c.id, '', null::date,
    jsonb_build_object('contract_id', c.id, 'title', c.title, 'product', c.product, 'starts_on', c.starts_on, 'origin', c.origin, 'lookback_months', (l.parameters->>'lookback_months')::int, 'observed_at', p_day),
    jsonb_build_object('contract_id', c.id, 'starts_on', c.starts_on, 'lookback_months', (l.parameters->>'lookback_months')::int)
  from live l join public.fin_contracts c on c.organization_id = p_org
  where l.rule_key = 'contract_without_sourcing' and c.status = 'active'
    and c.starts_on <= (p_day - make_interval(months => (l.parameters->>'lookback_months')::int))::date
    and not exists (select 1 from public.fin_rfqs q where q.organization_id = p_org and q.product = c.product
      and q.created_at >= p_day - make_interval(months => (l.parameters->>'lookback_months')::int))
 union all
 select l.id,l.rule_key,l.version,l.parameters,p.legal_entity_id,p.provider_id,'contract',p.contract_id,'',p.target_go_live,
 jsonb_build_object('implementation_id',p.id,'contract_id',p.contract_id,'target_go_live',p.target_go_live,'status',p.status,'observed_at',p_day),
 jsonb_build_object('implementation_id',p.id,'target_go_live',p.target_go_live,'status',p.status)
 from live l join public.fin_implementation_plans p on p.organization_id=p_org
 where p.status not in ('accepted','cancelled') and ((l.rule_key='implementation_blocked' and (p.status='blocked' or exists(select 1 from public.fin_implementation_issues i where i.plan_id=p.id and i.status='open'))) or (l.rule_key='implementation_overdue' and (p.target_go_live<p_day or exists(select 1 from public.fin_implementation_milestones m where m.plan_id=p.id and m.status<>'completed' and m.due_on<p_day))))

 union all
 select l.id,l.rule_key,l.version,l.parameters,o.legal_entity_id,o.provider_id,'contract',o.contract_id,p.id::text,p.due_on,
 jsonb_build_object('obligation_id',o.id,'period_id',p.id,'status',f.data->>'status','due_on',p.due_on,'grace_until',p.due_on+o.grace_days,'has_data',f.data->'has_data','factual_result',f.data->'factual_result','waiver_expired',w.valid_until,'observed_at',p_day),
 jsonb_build_object('period_id',p.id,'status',f.data->>'status','due_on',p.due_on,'measurement_id',f.data->'measurement_id','review_id',f.data->'review_id','waiver_expired',w.valid_until)
 from live l join public.fin_obligations o on o.organization_id=p_org and o.status='active' join public.fin_obligation_periods p on p.obligation_id=o.id
 cross join lateral(select public.fin_obligation_facts(p.id,p_day) as data)f
 left join lateral(select valid_until from public.fin_covenant_waivers where period_id=p.id and status='approved' and valid_until<p_day order by valid_until desc limit 1)w on true
 where (l.rule_key='covenant_due' and o.kind in ('financial_covenant','reporting_covenant') and p.due_on between p_day and p_day+(l.parameters->>'lead_days')::int and f.data->>'status' not in ('compliant','waived','not_applicable'))
 or (l.rule_key='covenant_awaiting_data' and o.kind in ('financial_covenant','reporting_covenant') and f.data->>'status'='awaiting_data')
 or (l.rule_key='covenant_non_compliance' and f.data->>'status'='non_compliant')
 or (l.rule_key='waiver_expiry' and w.valid_until is not null and f.data->>'status'<>'waived')
 or (l.rule_key='contractual_obligation_overdue' and p.due_on+o.grace_days<p_day and f.data->>'status' not in ('compliant','waived','not_applicable'))

 union all
 select l.id,l.rule_key,l.version,l.parameters,p.legal_entity_id,p.provider_id,'contract',p.contract_id,p.id::text,p.review_due_on,
 jsonb_build_object('period_id',p.id,'review_due_on',p.review_due_on,'status',p.status,'observed_at',p_day),jsonb_build_object('period_id',p.id,'version',p.version,'review_due_on',p.review_due_on)
 from live l join public.fin_provider_performance_periods p on p.organization_id=p_org where l.rule_key='performance_review_due' and p.status='open' and p.review_due_on<=p_day
 union all
 select l.id,l.rule_key,l.version,l.parameters,m.legal_entity_id,m.provider_id,'contract',m.contract_id,m.period_id::text||':'||m.dimension_id::text,m.review_due_on,
 jsonb_build_object('period_id',m.period_id,'dimension_id',m.dimension_id,'metric',m.metric,'actual',m.actual,'operator',m.operator,'threshold',m.threshold,'source_reference',m.source_reference,'formula_version',m.formula_version,'coverage_numerator',m.coverage_numerator,'coverage_denominator',m.coverage_denominator,'review_id',m.review_id,'observed_at',p_day),
 jsonb_build_object('period_id',m.period_id,'observation_id',m.observation_id,'review_id',m.review_id,'actual',m.actual,'threshold',m.threshold)
 from live l join public.fin_provider_performance_monitor m on m.organization_id=p_org where l.rule_key='performance_sla_issue' and m.metric in ('sla_adherence','service_availability') and m.verification_status='confirmed' and m.target_met=false and not exists(select 1 from public.fin_provider_performance_periods q where q.previous_period_id=m.period_id)
$$;


ALTER FUNCTION public.fin_opportunity_candidates(p_org uuid, p_day date) OWNER TO postgres;

--
-- Name: fin_opportunity_fee_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_fee_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from public.fin_opportunity_rules r where r.organization_id = new.organization_id and r.rule_key in ('fee_variance_review','fee_resolution_value_review')) then
    perform public.fin_evaluate_opportunities(new.organization_id, current_date, array['fee_variance_review','fee_resolution_value_review']);
  end if;
  return null;
end $$;


ALTER FUNCTION public.fin_opportunity_fee_event() OWNER TO postgres;

--
-- Name: fin_opportunity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Identity and the reason it first fired never change.
  if (new.organization_id, new.opportunity_type, new.rule_id, new.rule_version, new.rule_snapshot, new.source_object_type, new.source_object_id, new.discriminator, new.fingerprint, new.opened_at, new.legal_entity_id, new.provider_id, new.possible_action)
     is distinct from (old.organization_id, old.opportunity_type, old.rule_id, old.rule_version, old.rule_snapshot, old.source_object_type, old.source_object_id, old.discriminator, old.fingerprint, old.opened_at, old.legal_entity_id, old.provider_id, old.possible_action) then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_opportunity_guard() OWNER TO postgres;

--
-- Name: fin_opportunity_parameters_valid(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_parameters_valid(p_key text, p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare c record; k text; v numeric;
begin
  select * into c from public.fin_opportunity_rule_catalog() x where x.rule_key = p_key;
  if c.rule_key is null or p is null or jsonb_typeof(p) <> 'object' then return false; end if;
  if exists (select 1 from jsonb_object_keys(p) j where j <> all (c.required || c.optional)) then return false; end if;
  if exists (select 1 from unnest(c.required) r where not p ? r) then return false; end if;
  for k in select jsonb_object_keys(p) loop
    if jsonb_typeof(p->k) <> 'number' then return false; end if;
    v := (p->>k)::numeric;
    if v <> trunc(v) then return false; end if;
    if not ((k = 'lead_days' and v between 0 and 730) or (k = 'cooldown_days' and v between 0 and 365) or (k = 'min_age_days' and v between 0 and 365)
      or (k = 'grace_days' and v between 0 and 365) or (k = 'min_proposals' and v between 1 and 20) or (k = 'max_share_pct' and v between 1 and 100)
      or (k = 'max_utilization_pct' and v between 1 and 100) or (k = 'window_days' and v between 7 and 365) or (k = 'min_count' and v between 1 and 100)
      or (k = 'lookback_months' and v between 1 and 120)) then return false; end if;
  end loop;
  return true;
end $$;


ALTER FUNCTION public.fin_opportunity_parameters_valid(p_key text, p jsonb) OWNER TO postgres;

