--
-- Name: fin_opportunity_start_rfq(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_start_rfq(p_id uuid, p_confirmed boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_opportunities%rowtype; v_contract uuid; v_rfq uuid;
begin
  select * into o from public.fin_opportunities where id = p_id for update;
  if o.id is null or auth.uid() is null or not public.fin_entity_allows(o.organization_id, o.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(o.organization_id) then raise exception 'organization offboarding'; end if;
  if p_confirmed is not true then raise exception 'opportunity rfq requires confirmation'; end if;
  if o.status not in ('open','acknowledged','under_review') or o.linked_rfq_id is not null then raise exception 'opportunity rfq unavailable'; end if;
  v_contract := case when o.source_object_type = 'contract' then o.source_object_id
    when o.source_object_type = 'contract_milestone' then (select m.contract_id from public.fin_contract_milestones m where m.id = o.source_object_id) end;
  if v_contract is null then raise exception 'opportunity rfq unavailable'; end if;
  v_rfq := public.fin_start_contract_rfq(v_contract);
  update public.fin_opportunities set linked_rfq_id = v_rfq where id = o.id;
  insert into public.fin_opportunity_events(organization_id, opportunity_id, event_type, from_status, to_status, actor_id, note)
    values (o.organization_id, o.id, 'rfq_draft_created', o.status, o.status, auth.uid(), 'RFQ draft ' || v_rfq::text);
  return v_rfq;
end $$;


ALTER FUNCTION public.fin_opportunity_start_rfq(p_id uuid, p_confirmed boolean) OWNER TO postgres;

--
-- Name: fin_opportunity_summary(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_opportunity_summary(p_org uuid, p_entity uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid, p_day date DEFAULT CURRENT_DATE) RETURNS TABLE(status text, opportunities bigint, due_30 bigint, overdue bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_org is null or auth.uid() is null or not public.fin_has_role(p_org, array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  return query select x.status, count(*), count(*) filter (where x.deadline between p_day and p_day + 30), count(*) filter (where x.deadline < p_day)
    from public.fin_opportunities x where x.organization_id = p_org and (p_entity is null or x.legal_entity_id = p_entity) and (p_provider is null or x.provider_id = p_provider)
    group by x.status order by x.status;
end $$;


ALTER FUNCTION public.fin_opportunity_summary(p_org uuid, p_entity uuid, p_provider uuid, p_day date) OWNER TO postgres;

--
-- Name: fin_ops_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_ops_overview() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  perform public.fin_require_operator();
  insert into public.fin_ops_access_log (user_id, action) values (auth.uid(), 'overview');
  select jsonb_build_object(
    'schema_version', public.fin_setting('schema_version', 'financial-pilot-grade-1'),
    'generated_at', now(),
    'email_enabled', public.fin_setting('email_enabled', 'false') = 'true',
    'jobs', coalesce((select jsonb_agg(jsonb_build_object('job', j.job, 'status', j.status, 'processed', j.processed, 'request_id', j.request_id,
        'failed', j.failed, 'duration_ms', floor(extract(epoch from coalesce(j.finished_at,now()) - j.started_at)*1000), 'error_code', j.error_code, 'started_at', j.started_at, 'finished_at', j.finished_at) order by j.finished_at desc)
      from (select * from public.fin_job_runs order by started_at desc limit 20) j), '[]'::jsonb),
    'webhooks', jsonb_build_object(
      'by_status', coalesce((select jsonb_object_agg(status,total) from (select status,count(*) total from public.fin_webhook_deliveries group by status) x),'{}'::jsonb),
      'oldest_pending_minutes', (select floor(extract(epoch from now()-min(created_at))/60) from public.fin_webhook_deliveries where status in ('pending','failed')),
      'recent_failures', coalesce((select jsonb_agg(jsonb_build_object('id',id,'status',status,'attempts',attempts,'error_code',last_error_code,'created_at',created_at)) from
        (select id,status,attempts,last_error_code,created_at from public.fin_webhook_deliveries where status in ('failed','dead') order by created_at desc limit 20) w),'[]'::jsonb)),
    'sso', jsonb_build_object('connections_by_status',coalesce((select jsonb_object_agg(status,total) from (select status,count(*) total from public.fin_sso_connections group by status) s),'{}'::jsonb),
      'failures_24h',(select count(*) from public.fin_sso_events where happened_at > now()-interval '24 hours' and outcome <> 'success')),
    'governance', jsonb_build_object(
      'exports_by_status', coalesce((select jsonb_object_agg(status,total) from (select status,count(*) total from public.fin_data_exports group by status) x),'{}'::jsonb),
      'offboarding_by_status', coalesce((select jsonb_object_agg(status,total) from (select status,count(*) total from public.fin_offboarding_requests group by status) x),'{}'::jsonb),
      'active_legal_holds', (select count(*) from public.fin_legal_holds where status = 'active'),
      'last_retention_run', (select max(finished_at) from public.fin_job_runs where job = 'retention' and status = 'succeeded'),
      'retention_purged_24h', coalesce((select sum(object_count) from public.fin_governance_log where action = 'retention_purged' and happened_at > now() - interval '24 hours'), 0)),
    'expired_job_leases', (select count(*) from public.fin_job_runs where status='running' and lease_expires_at <= now()),
    'last_renewal_success', (select max(finished_at) from public.fin_job_runs where job = 'renewals' and status = 'succeeded'),
    'renewal_milestones_24h', (select count(*) from public.fin_renewal_milestones where triggered_at > now() - interval '24 hours'),
    'outbox', jsonb_build_object(
      'by_status', coalesce((select jsonb_object_agg(status, total) from (select status, count(*) total from public.transactional_email_outbox
          where template = 'finance_notification' group by status) s), '{}'::jsonb),
      'oldest_pending_minutes', (select floor(extract(epoch from now() - min(created_at)) / 60) from public.transactional_email_outbox
          where template = 'finance_notification' and status in ('pending','retry')),
      'recent_failures', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'status', o.status, 'attempts', o.attempts,
          'error_code', o.last_error_code, 'created_at', o.created_at) order by o.created_at desc)
        from (select * from public.transactional_email_outbox where template = 'finance_notification' and status in ('retry','dead')
              order by created_at desc limit 10) o), '[]'::jsonb)),
    'documents', jsonb_build_object(
      'pending_over_1h', (select count(*) from public.fin_document_versions where status = 'pending' and created_at < now() - interval '1 hour'),
      'failed_24h', (select count(*) from public.fin_document_versions where status = 'failed' and completed_at > now() - interval '24 hours'),
      'available_total', (select count(*) from public.fin_document_versions where status = 'available')),
    'notifications_24h', (select count(*) from public.fin_notifications where created_at > now() - interval '24 hours'),
    'invite_denials_24h', coalesce((select jsonb_object_agg(reason, total) from (select reason, count(*) total
      from public.fin_invite_acceptance_denials where happened_at > now() - interval '24 hours' group by reason) d), '{}'::jsonb)
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION public.fin_ops_overview() OWNER TO postgres;

--
-- Name: fin_ops_trace(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_ops_trace(p_request_id text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  perform public.fin_require_operator();
  if p_request_id is null and p_entity_id is null then raise exception 'lookup required'; end if;
  if p_request_id is not null and p_request_id !~ '^[A-Za-z0-9-]{1,80}$' then raise exception 'invalid lookup'; end if;
  insert into public.fin_ops_access_log (user_id, action, lookup) values (auth.uid(), 'trace', coalesce(p_request_id, p_entity_id::text));
  return jsonb_build_object(
    'jobs', coalesce((select jsonb_agg(jsonb_build_object('job', job, 'status', status, 'processed', processed, 'error_code', error_code, 'finished_at', finished_at))
      from public.fin_job_runs where p_request_id is not null and request_id = p_request_id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object('organization_id', e.organization_id, 'entity_type', e.entity_type, 'entity_id', e.entity_id,
        'event_type', e.event_type, 'happened_at', e.happened_at) order by e.happened_at desc)
      from (select * from public.fin_events where p_entity_id is not null and (entity_id = p_entity_id or organization_id = p_entity_id)
            order by happened_at desc limit 50) e), '[]'::jsonb),
    'invite_denials', coalesce((select jsonb_agg(jsonb_build_object('invite_id', d.invite_id, 'reason', d.reason, 'happened_at', d.happened_at)
        order by d.happened_at desc)
      from (select * from public.fin_invite_acceptance_denials where p_entity_id is not null and (rfq_id = p_entity_id or invite_id = p_entity_id)
            order by happened_at desc limit 50) d), '[]'::jsonb));
end $_$;


ALTER FUNCTION public.fin_ops_trace(p_request_id text, p_entity_id uuid) OWNER TO postgres;

