-- Name: fin_passport_confirm_field(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_passport_confirm_field(p_org uuid, p_key text) RETURNS timestamp with time zone
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$ select public.fin_passport_confirm_scoped_field(p_org,null,p_key); $$;


ALTER FUNCTION public.fin_passport_confirm_field(p_org uuid, p_key text) OWNER TO postgres;

--
-- Name: fin_passport_confirm_scoped_field(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_passport_confirm_scoped_field(p_org uuid, p_entity uuid, p_key text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_at timestamptz := now();
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not public.fin_entity_allows(p_org, p_entity, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  update public.fin_company_profiles set verified_at = v_at, verified_by = auth.uid(), status = 'revisado'
   where organization_id = p_org and legal_entity_id is not distinct from p_entity and field_key = p_key;
  if not found then raise exception 'invalid profile field'; end if;
  insert into public.fin_events(organization_id, legal_entity_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, p_entity, 'profile', coalesce(p_entity,p_org), 'profile_field_confirmed', auth.uid(), jsonb_build_object('legal_entity_id',p_entity,'field_key', p_key));
  return v_at;
end $$;


ALTER FUNCTION public.fin_passport_confirm_scoped_field(p_org uuid, p_entity uuid, p_key text) OWNER TO postgres;

--
-- Name: fin_passport_freshness(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_passport_freshness(p_due date, p_on date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_due is null then 'untracked' when p_on > p_due then 'stale' when p_due - p_on <= 30 then 'review_due' else 'current' end;
$$;


