-- Name: fin_passport_review_due(timestamp with time zone, timestamp with time zone, integer, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_passport_review_due(p_updated timestamp with time zone, p_verified timestamp with time zone, p_days integer, p_valid_until date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select least((greatest(p_updated, coalesce(p_verified, p_updated)) at time zone 'UTC')::date + p_days, coalesce(p_valid_until, 'infinity'::date));
