    CONSTRAINT fin_qualification_requirements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT fin_qualification_requirements_title_check CHECK ((((length(TRIM(BOTH FROM title)) >= 3) AND (length(TRIM(BOTH FROM title)) <= 200)) AND (title !~ '[<>]'::text))),
    CONSTRAINT fin_qualification_requirements_validity_days_check CHECK (((validity_days IS NULL) OR ((validity_days >= 1) AND (validity_days <= 3650)))),
