--

CREATE VIEW public.fin_obligation_monitor WITH (security_invoker='true') AS
 SELECT p.id,
    p.organization_id,
    p.obligation_id,
    p.period_start,
    p.period_end,
    p.due_on,
    p.task_id,
    p.created_at,
    o.contract_id,
    o.legal_entity_id,
    o.provider_id,
    o.title,
    o.kind,
    o.owner_id,
    o.frequency,
    o.source_clause,
    o.source_reference,
    o.source_contract_version,
    o.version AS obligation_version,
    o.cancellation_reason,
    public.fin_obligation_facts(p.id, CURRENT_DATE) AS facts
   FROM (public.fin_obligation_periods p
     JOIN public.fin_obligations o ON ((o.id = p.obligation_id)));


