    CONSTRAINT fin_providers_creation_receipt CHECK ((((creation_request_key IS NULL) AND (creation_request_hash IS NULL)) OR ((creation_request_key IS NOT NULL) AND (creation_request_hash IS NOT NULL) AND (creation_request_hash ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT fin_providers_kind_check CHECK ((kind = ANY (ARRAY['bank'::text, 'fintech'::text, 'acquirer'::text, 'subacquirer'::text, 'credit_provider'::text, 'payment_provider'::text, 'other'::text]))),
    CONSTRAINT fin_providers_name_check CHECK (((length(name) >= 2) AND (length(name) <= 200))),
    CONSTRAINT fin_providers_origin_check CHECK ((origin = ANY (ARRAY['cadastrado_pela_empresa'::text, 'indicacao'::text, 'pesquisa_publica'::text, 'outro'::text]))),
    CONSTRAINT fin_providers_regulator_evidence_url_check CHECK (((regulator_evidence_url IS NULL) OR (regulator_evidence_url ~ '^https://'::text))),
    CONSTRAINT fin_providers_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT fin_providers_verification_state_check CHECK ((verification_state = ANY (ARRAY['NAO_VERIFICADO'::text, 'EVIDENCIA_REGISTRADA'::text]))),
    CONSTRAINT fin_providers_website_check CHECK (((website IS NULL) OR (website ~ '^https://'::text)))
);

