-- Name: fin_spend_records; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_spend_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    legal_entity_id uuid,
    provider_id uuid NOT NULL,
    product text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    currency text NOT NULL,
    value_kind text NOT NULL,
    amount numeric(20,2) NOT NULL,
    source_type text NOT NULL,
    source_reference text NOT NULL,
    source_line text NOT NULL,
    provenance text NOT NULL,
    source_key text NOT NULL,
    revision integer NOT NULL,
    supersedes_id uuid,
    correction_reason text,
    recorded_by uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_spend_records_amount_check CHECK (((amount >= (0)::numeric) AND (amount <= '1000000000000'::numeric))),
    CONSTRAINT fin_spend_records_check CHECK (((period_end >= period_start) AND ((period_end - period_start) <= 366))),
    CONSTRAINT fin_spend_records_check1 CHECK (((supersedes_id IS NULL) OR ((correction_reason IS NOT NULL) AND ((length(TRIM(BOTH FROM correction_reason)) >= 10) AND (length(TRIM(BOTH FROM correction_reason)) <= 2000)) AND (correction_reason !~ '[<>]'::text)))),
    CONSTRAINT fin_spend_records_currency_check CHECK ((currency = ANY (ARRAY['BRL'::text, 'USD'::text, 'EUR'::text, 'GBP'::text, 'CHF'::text, 'JPY'::text, 'CAD'::text, 'AUD'::text, 'CNY'::text, 'MXN'::text, 'ARS'::text, 'CLP'::text, 'COP'::text, 'PEN'::text]))),
    CONSTRAINT fin_spend_records_provenance_check CHECK ((((length(TRIM(BOTH FROM provenance)) >= 10) AND (length(TRIM(BOTH FROM provenance)) <= 2000)) AND (provenance !~ '[<>]'::text))),
    CONSTRAINT fin_spend_records_revision_check CHECK ((revision > 0)),
    CONSTRAINT fin_spend_records_source_line_check CHECK ((((length(TRIM(BOTH FROM source_line)) >= 1) AND (length(TRIM(BOTH FROM source_line)) <= 200)) AND (source_line !~ '[<>]'::text))),
    CONSTRAINT fin_spend_records_source_reference_check CHECK ((((length(TRIM(BOTH FROM source_reference)) >= 3) AND (length(TRIM(BOTH FROM source_reference)) <= 200)) AND (source_reference !~ '[<>]'::text))),
    CONSTRAINT fin_spend_records_source_type_check CHECK ((source_type = ANY (ARRAY['declared'::text, 'imported'::text]))),
    CONSTRAINT fin_spend_records_value_kind_check CHECK ((value_kind = ANY (ARRAY['contracted'::text, 'observed'::text, 'estimated'::text])))
);

ALTER TABLE ONLY public.fin_spend_records FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_spend_records OWNER TO postgres;

--
-- Name: fin_spend_monitor; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_spend_monitor WITH (security_invoker='true') AS
 SELECT r.id,
    r.organization_id,
    r.contract_id,
    r.legal_entity_id,
    r.provider_id,
    r.product,
    r.period_start,
    r.period_end,
    r.currency,
        CASE
            WHEN ((x.status = 'confirmed'::text) AND (r.value_kind = 'observed'::text)) THEN 'verified'::text
            ELSE r.value_kind
        END AS value_kind,
    (r.amount)::text AS amount,
    r.source_type,
    r.source_reference,
    r.source_line,
    r.provenance,
    r.revision,
    r.supersedes_id,
    r.recorded_by,
    r.recorded_at,
    COALESCE(x.status, 'unreviewed'::text) AS reconciliation_status,
    ((x.status = 'confirmed'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.fin_fee_observations f
          WHERE ((f.organization_id = r.organization_id) AND (lower(TRIM(BOTH FROM f.source_reference)) = lower(TRIM(BOTH FROM r.source_reference)))))))) AS included,
    'fin_spend_records'::text AS source_table,
    r.id AS source_id,
    'recorded amount; no currency conversion'::text AS formula
   FROM (public.fin_spend_records r
     LEFT JOIN public.fin_spend_reconciliations x ON ((x.record_id = r.id)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.fin_spend_records n
          WHERE (n.supersedes_id = r.id))))
UNION ALL
 SELECT o.id,
    o.organization_id,
    o.contract_id,
    o.legal_entity_id,
    o.provider_id,
    c.product,
    o.period_start,
    o.period_end,
    o.currency,
        CASE
            WHEN (o.verification_status = 'verified'::text) THEN 'verified'::text
            ELSE 'observed'::text
        END AS value_kind,
    (o.observed_amount)::text AS amount,
    'fee_observation'::text AS source_type,
    o.source_reference,
    COALESCE(o.source_object_id, (o.id)::text) AS source_line,
    o.evidence_reference AS provenance,
    1 AS revision,
    NULL::uuid AS supersedes_id,
    o.owner_id AS recorded_by,
    o.ingested_at AS recorded_at,
    o.verification_status AS reconciliation_status,
    (o.verification_status <> 'rejected'::text) AS included,
    'fin_fee_observations'::text AS source_table,
    o.id AS source_id,
    'observed fee amount; verification preserved'::text AS formula
   FROM (public.fin_fee_observations o
     JOIN public.fin_contracts c ON ((c.id = o.contract_id)))
UNION ALL
 SELECT v.id,
    v.organization_id,
    v.contract_id,
    v.legal_entity_id,
    v.provider_id,
    c.product,
    v.period_start,
    v.period_end,
    v.currency,
    'contracted'::text AS value_kind,
    (v.contracted_amount)::text AS amount,
    'fee_schedule'::text AS source_type,
    o.source_reference,
    (v.id)::text AS source_line,
    o.evidence_reference AS provenance,
    1 AS revision,
    NULL::uuid AS supersedes_id,
    o.owner_id AS recorded_by,
    o.ingested_at AS recorded_at,
    o.verification_status AS reconciliation_status,
    (o.verification_status <> 'rejected'::text) AS included,
    'fin_fee_variances'::text AS source_table,
    v.id AS source_id,
    'contracted charge for observed cohort; not total contract spend'::text AS formula
   FROM ((public.fin_fee_variances v
     JOIN public.fin_fee_observations o ON ((o.id = v.observation_id)))
     JOIN public.fin_contracts c ON ((c.id = v.contract_id)))
  WHERE (v.comparison_status = 'comparable'::text);


ALTER VIEW public.fin_spend_monitor OWNER TO postgres;

--
-- Name: fin_graph_objects; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_graph_objects WITH (security_invoker='true') AS
 SELECT organization_id,
    object_type,
    object_id,
    title,
    status,
    legal_entity_id,
    provider_id,
    rfq_id,
    contract_id,
    facility_id,
    owner_id,
    due_on,
    facts
   FROM ( SELECT o.id AS organization_id,
            'organization'::text AS object_type,
            (o.id)::text AS object_id,
            o.legal_name AS title,
            NULL::text AS status,
            NULL::uuid AS legal_entity_id,
            NULL::uuid AS provider_id,
            NULL::uuid AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            NULL::uuid AS owner_id,
            NULL::date AS due_on,
            '{}'::jsonb AS facts
           FROM public.fin_organizations o
        UNION ALL
         SELECT e.organization_id,
            'entity'::text AS object_type,
            (e.id)::text AS object_id,
            e.legal_name AS title,
            e.status,
            e.id AS legal_entity_id,
            NULL::uuid AS provider_id,
            NULL::uuid AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            NULL::uuid AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('kind', e.kind, 'currency', e.currency) AS facts
           FROM public.fin_legal_entities e
        UNION ALL
         SELECT p.organization_id,
            'provider'::text AS object_type,
            (p.id)::text AS object_id,
            p.name AS title,
            p.status,
            NULL::uuid AS legal_entity_id,
            p.id AS provider_id,
            NULL::uuid AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            NULL::uuid AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('kind', p.kind, 'verification_state', p.verification_state) AS facts
           FROM public.fin_providers p
        UNION ALL
         SELECT x.organization_id,
            'relationship'::text AS object_type,
            (x.id)::text AS object_id,
            COALESCE(p.name, 'Relacionamento'::text) AS title,
            x.status,
            e.id AS legal_entity_id,
            p.id AS provider_id,
            NULL::uuid AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            x.owner_id,
            NULL::date AS due_on,
            jsonb_build_object('entity', e.legal_name, 'categories', x.categories, 'since_on', x.since_on) AS facts
           FROM ((public.fin_provider_relationships x
             JOIN public.fin_legal_entities e ON (((e.organization_id = x.organization_id) AND (e.id = x.legal_entity_id))))
             JOIN public.fin_providers p ON (((p.organization_id = x.organization_id) AND (p.id = x.provider_id))))
        UNION ALL
         SELECT r.organization_id,
            'rfq'::text AS object_type,
            (r.id)::text AS object_id,
            r.title,
            r.status,
            r.legal_entity_id,
            NULL::uuid AS provider_id,
            r.id AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            r.owner_id,
            r.response_deadline AS due_on,
            jsonb_build_object('product', r.product) AS facts
           FROM public.fin_rfqs r
        UNION ALL
         SELECT r.organization_id,
            'proposal'::text AS object_type,
            (x.id)::text AS object_id,
            COALESCE(p.name, 'Proposta'::text) AS title,
            x.status,
            r.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            NULL::uuid AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('version', x.current_version, 'product', x.product) AS facts
           FROM ((public.fin_proposals x
             JOIN public.fin_rfqs r ON (((r.organization_id = x.buyer_organization_id) AND (r.id = x.rfq_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = r.organization_id) AND (p.id = x.provider_id))))
        UNION ALL
         SELECT d.organization_id,
            'decision'::text AS object_type,
            (d.id)::text AS object_id,
            ('Decisão — '::text || r.title) AS title,
            NULL::text AS status,
            r.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            d.decided_by AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('decided_at', d.decided_at, 'proposal_id', x.id) AS facts
           FROM (((public.fin_decisions d
             JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
             LEFT JOIN public.fin_proposals x ON (((x.buyer_organization_id = d.organization_id) AND (x.id = d.proposal_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = d.organization_id) AND (p.id = x.provider_id))))
        UNION ALL
         SELECT c.organization_id,
            'contract'::text AS object_type,
            (c.id)::text AS object_id,
            COALESCE(c.title, p.name, 'Contrato'::text) AS title,
            c.status,
            c.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            NULL::uuid AS facility_id,
            c.owner_id,
            c.ends_on AS due_on,
            jsonb_build_object('origin', c.origin, 'decision_id', d.id, 'rfq', r.title, 'currency', c.currency) AS facts
           FROM (((public.fin_contracts c
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT f.organization_id,
            'facility'::text AS object_type,
            (f.id)::text AS object_id,
            f.name AS title,
            f.status,
            f.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            f.id AS facility_id,
            f.owner_id,
            f.maturity_on AS due_on,
            jsonb_build_object('kind', f.kind, 'currency', f.currency, 'approved_limit', f.approved_limit, 'source', f.source, 'verified_at', f.verified_at) AS facts
           FROM ((((public.fin_facilities f
             LEFT JOIN public.fin_providers p ON (((p.organization_id = f.organization_id) AND (p.id = f.provider_id))))
             LEFT JOIN public.fin_contracts c ON (((c.organization_id = f.organization_id) AND (c.id = f.contract_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT f.organization_id,
            'limit'::text AS object_type,
            (f.id)::text AS object_id,
            f.name AS title,
            f.status,
            f.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            f.id AS facility_id,
            f.owner_id,
            f.maturity_on AS due_on,
            jsonb_build_object('kind', f.kind, 'currency', f.currency, 'approved_limit', f.approved_limit, 'source', f.source, 'verified_at', f.verified_at) AS facts
           FROM ((((public.fin_facilities f
             LEFT JOIN public.fin_providers p ON (((p.organization_id = f.organization_id) AND (p.id = f.provider_id))))
             LEFT JOIN public.fin_contracts c ON (((c.organization_id = f.organization_id) AND (c.id = f.contract_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
          WHERE (f.approved_limit IS NOT NULL)
        UNION ALL
         SELECT g.organization_id,
            'guarantee'::text AS object_type,
            (g.id)::text AS object_id,
            g.description AS title,
            g.status,
            g.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            f.id AS facility_id,
            NULL::uuid AS owner_id,
            g.ends_on AS due_on,
            jsonb_build_object('kind', g.kind, 'currency', g.currency, 'committed_amount', g.committed_amount, 'source', g.source) AS facts
           FROM (((((public.fin_guarantees g
             LEFT JOIN public.fin_facilities f ON (((f.organization_id = g.organization_id) AND (f.id = g.facility_id))))
             LEFT JOIN public.fin_contracts c ON (((c.organization_id = g.organization_id) AND (c.id = COALESCE(g.contract_id, f.contract_id)))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = g.organization_id) AND (p.id = COALESCE(g.provider_id, f.provider_id, c.provider_id)))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT s.organization_id,
            'passport_snapshot'::text AS object_type,
            (s.id)::text AS object_id,
            ((s.field_key || ' — '::text) || r.title) AS title,
            NULL::text AS status,
            r.legal_entity_id,
            NULL::uuid AS provider_id,
            r.id AS rfq_id,
            NULL::uuid AS contract_id,
            NULL::uuid AS facility_id,
            s.profile_updated_by AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('value', s.field_value, 'source', s.source, 'original_scope', s.original_scope, 'source_legal_entity_id', s.source_legal_entity_id, 'vintage', s.vintage, 'verified_at', s.verified_at, 'captured_at', s.captured_at) AS facts
           FROM (public.fin_rfq_profile_snapshots s
             JOIN public.fin_rfqs r ON (((r.organization_id = s.organization_id) AND (r.id = s.rfq_id))))
        UNION ALL
         SELECT m.organization_id,
            'milestone'::text AS object_type,
            (m.id)::text AS object_id,
            m.title,
            m.status,
            c.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            NULL::uuid AS facility_id,
            m.owner_id,
            m.due_on,
            jsonb_build_object('kind', m.kind, 'recurrence', m.recurrence) AS facts
           FROM ((((public.fin_contract_milestones m
             JOIN public.fin_contracts c ON (((c.organization_id = m.organization_id) AND (c.id = m.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
          WHERE (m.kind <> 'obligation'::text)
        UNION ALL
         SELECT m.organization_id,
            'obligation'::text AS object_type,
            (m.id)::text AS object_id,
            m.title,
            m.status,
            c.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            NULL::uuid AS facility_id,
            m.owner_id,
            m.due_on,
            jsonb_build_object('kind', m.kind, 'recurrence', m.recurrence) AS facts
           FROM ((((public.fin_contract_milestones m
             JOIN public.fin_contracts c ON (((c.organization_id = m.organization_id) AND (c.id = m.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
          WHERE (m.kind = 'obligation'::text)
        UNION ALL
         SELECT s.organization_id,
            'obligation'::text AS object_type,
            (((((s.facility_id)::text || ':'::text) || (s.schedule_version)::text) || ':'::text) || (s.due_on)::text) AS object_id,
            ('Amortização — '::text || f.name) AS title,
            NULL::text AS status,
            f.legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            f.id AS facility_id,
            s.recorded_by AS owner_id,
            s.due_on,
            jsonb_build_object('source', 'fin_facility_repayments', 'schedule_version', s.schedule_version, 'principal_amount', s.principal_amount, 'currency', f.currency) AS facts
           FROM (((((public.fin_facility_repayments s
             JOIN public.fin_facilities f ON (((f.organization_id = s.organization_id) AND (f.id = s.facility_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = f.organization_id) AND (p.id = f.provider_id))))
             LEFT JOIN public.fin_contracts c ON (((c.organization_id = f.organization_id) AND (c.id = f.contract_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
          WHERE (s.schedule_version = f.schedule_version)
        UNION ALL
         SELECT x.organization_id,
            'document'::text AS object_type,
            (x.id)::text AS object_id,
            x.title,
            NULL::text AS status,
                CASE
                    WHEN (x.entity_type = 'profile'::text) THEN
                    CASE
                        WHEN (x.entity_id = x.organization_id) THEN NULL::uuid
                        ELSE x.entity_id
                    END
                    ELSE COALESCE(c.legal_entity_id, r.legal_entity_id)
                END AS legal_entity_id,
            p.id AS provider_id,
            r.id AS rfq_id,
            c.id AS contract_id,
            NULL::uuid AS facility_id,
            x.created_by AS owner_id,
            NULL::date AS due_on,
            jsonb_build_object('entity_type', x.entity_type, 'version', x.current_version, 'visibility', x.visibility) AS facts
           FROM (((public.fin_private_documents x
             LEFT JOIN public.fin_contracts c ON (((x.entity_type = 'contract'::text) AND (c.organization_id = x.organization_id) AND (c.id = x.entity_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = x.buyer_organization_id) AND (r.id = x.rfq_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
          WHERE (x.removed_at IS NULL)
        UNION ALL
         SELECT v.organization_id,
            'value_realization'::text AS text,
            (v.id)::text AS id,
            v.title,
            v.status,
            v.legal_entity_id,
            p.id,
            r.id,
            c.id,
            NULL::uuid AS uuid,
            v.owner_id,
            v.period_end,
            jsonb_build_object('kind', v.kind, 'currency', v.currency, 'comparability', v.comparability, 'value_amount', v.value_amount, 'baseline_source', (v.baseline ->> 'source'::text), 'methodology', v.methodology_snapshot, 'contract_version', v.contract_version) AS jsonb_build_object
           FROM ((((public.fin_value_records v
             JOIN public.fin_contracts c ON (((c.organization_id = v.organization_id) AND (c.id = v.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT s.organization_id,
            'fee_schedule'::text AS text,
            (s.id)::text AS id,
            s.service,
            NULL::text AS text,
            c.legal_entity_id,
            p.id,
            r.id,
            c.id,
            NULL::uuid AS uuid,
            s.owner_id,
            NULL::date AS date,
            jsonb_build_object('category', s.category, 'charging_unit', s.charging_unit, 'current_version', s.current_version) AS jsonb_build_object
           FROM ((((public.fin_fee_schedules s
             JOIN public.fin_contracts c ON (((c.organization_id = s.organization_id) AND (c.id = s.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT x.organization_id,
            'fee_observation'::text AS text,
            (x.id)::text AS id,
            ((((x.service || ' · '::text) || x.period_start) || ' – '::text) || x.period_end) AS text,
            x.verification_status,
            c.legal_entity_id,
            p.id,
            r.id,
            c.id,
            NULL::uuid AS uuid,
            x.owner_id,
            NULL::date AS date,
            jsonb_build_object('source_type', x.source_type, 'source_reference', x.source_reference, 'currency', x.currency, 'observed_amount', x.observed_amount, 'period_start', x.period_start, 'period_end', x.period_end) AS jsonb_build_object
           FROM ((((public.fin_fee_observations x
             JOIN public.fin_contracts c ON (((c.organization_id = x.organization_id) AND (c.id = x.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT v.organization_id,
            'fee_variance'::text AS text,
            (v.id)::text AS id,
            ('Diferença de tarifa — '::text || v.service) AS text,
            v.review_status,
            c.legal_entity_id,
            p.id,
            r.id,
            c.id,
            NULL::uuid AS uuid,
            v.reviewer_id,
            NULL::date AS date,
            jsonb_build_object('comparison_status', v.comparison_status, 'direction', v.direction, 'currency', v.currency, 'contracted_amount', v.contracted_amount, 'observed_amount', v.observed_amount, 'variance_amount', v.variance_amount, 'reasons', v.reasons, 'observation_id', v.observation_id, 'schedule_id', v.schedule_id, 'schedule_version', v.schedule_version) AS jsonb_build_object
           FROM ((((public.fin_fee_variances v
             JOIN public.fin_contracts c ON (((c.organization_id = v.organization_id) AND (c.id = v.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT w.organization_id,
            'fee_review'::text AS text,
            (w.id)::text AS id,
            ('Revisão de tarifa — '::text || v.service) AS text,
            w.to_status,
            c.legal_entity_id,
            p.id,
            r.id,
            c.id,
            NULL::uuid AS uuid,
            w.reviewer_id,
            NULL::date AS date,
            jsonb_build_object('variance_id', w.variance_id, 'from_status', w.from_status, 'to_status', w.to_status, 'reason_code', w.reason_code, 'reviewed_at', w.reviewed_at) AS jsonb_build_object
           FROM (((((public.fin_fee_reviews w
             JOIN public.fin_fee_variances v ON (((v.organization_id = w.organization_id) AND (v.id = w.variance_id))))
             JOIN public.fin_contracts c ON (((c.organization_id = v.organization_id) AND (c.id = v.contract_id))))
             LEFT JOIN public.fin_providers p ON (((p.organization_id = c.organization_id) AND (p.id = c.provider_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT x.organization_id,
            'opportunity'::text AS text,
            (x.id)::text AS id,
            ('Oportunidade — '::text || x.opportunity_type) AS text,
            x.status,
            x.legal_entity_id,
            x.provider_id,
            COALESCE(q.id, r.id) AS "coalesce",
            c.id,
            f.id,
            x.reviewer_id,
            x.deadline,
            jsonb_build_object('type', x.opportunity_type, 'possible_action', x.possible_action, 'rule_version', x.rule_version, 'source_object_type', x.source_object_type, 'source_object_id', x.source_object_id) AS jsonb_build_object
           FROM (((((public.fin_opportunities x
             LEFT JOIN public.fin_contracts c ON (((c.organization_id = x.organization_id) AND (c.id =
                CASE x.source_object_type
                    WHEN 'contract'::text THEN x.source_object_id
                    WHEN 'contract_milestone'::text THEN ( SELECT m.contract_id
                       FROM public.fin_contract_milestones m
                      WHERE ((m.organization_id = x.organization_id) AND (m.id = x.source_object_id)))
                    WHEN 'fee_variance'::text THEN ( SELECT v.contract_id
                       FROM public.fin_fee_variances v
                      WHERE ((v.organization_id = x.organization_id) AND (v.id = x.source_object_id)))
                    WHEN 'value_record'::text THEN ( SELECT w.contract_id
                       FROM public.fin_value_records w
                      WHERE ((w.organization_id = x.organization_id) AND (w.id = x.source_object_id)))
                    ELSE NULL::uuid
                END))))
             LEFT JOIN public.fin_facilities f ON (((x.source_object_type = 'facility'::text) AND (f.organization_id = x.organization_id) AND (f.id = x.source_object_id))))
             LEFT JOIN public.fin_rfqs q ON (((x.source_object_type = 'rfq'::text) AND (q.organization_id = x.organization_id) AND (q.id = x.source_object_id))))
             LEFT JOIN public.fin_decisions d ON (((d.organization_id = c.organization_id) AND (d.id = c.decision_id))))
             LEFT JOIN public.fin_rfqs r ON (((r.organization_id = d.organization_id) AND (r.id = d.rfq_id))))
        UNION ALL
         SELECT p.organization_id,
            'implementation'::text AS text,
            (p.id)::text AS id,
            p.title,
            p.status,
            p.legal_entity_id,
            p.provider_id,
            NULL::uuid AS uuid,
            p.contract_id,
            NULL::uuid AS uuid,
            p.owner_id,
            p.target_go_live,
            jsonb_build_object('source', 'fin_implementation_plans', 'template', p.template_version, 'actual_go_live', p.actual_go_live, 'updated_at', p.updated_at) AS jsonb_build_object
           FROM public.fin_implementation_plans p
        UNION ALL
         SELECT x.organization_id,
                CASE
                    WHEN (x.kind = 'financial_covenant'::text) THEN 'covenant'::text
                    ELSE 'obligation'::text
                END AS "case",
            (x.id)::text AS id,
            x.title,
            (x.facts ->> 'status'::text),
            x.legal_entity_id,
            x.provider_id,
            NULL::uuid AS uuid,
            x.contract_id,
            NULL::uuid AS uuid,
            x.owner_id,
            x.due_on,
            x.facts
           FROM public.fin_obligation_monitor x
        UNION ALL
         SELECT p.organization_id,
            'performance'::text AS text,
            (p.id)::text AS id,
            p.title,
            p.status,
            p.legal_entity_id,
            p.provider_id,
            NULL::uuid AS uuid,
            p.contract_id,
            NULL::uuid AS uuid,
            p.owner_id,
            p.review_due_on,
            jsonb_build_object('source', 'fin_provider_performance_periods', 'period_start', p.period_start, 'period_end', p.period_end, 'version', p.version) AS jsonb_build_object
           FROM public.fin_provider_performance_periods p
        UNION ALL
         SELECT r.organization_id,
            'spend'::text AS text,
            (r.id)::text AS id,
            ('Spend '::text || r.source_reference) AS text,
            r.reconciliation_status,
            r.legal_entity_id,
            r.provider_id,
            NULL::uuid AS uuid,
            r.contract_id,
            NULL::uuid AS uuid,
            r.recorded_by,
            r.period_end,
            jsonb_build_object('source', r.source_table, 'source_id', r.source_id, 'kind', r.value_kind, 'currency', r.currency, 'amount', r.amount, 'included', r.included, 'period_start', r.period_start, 'period_end', r.period_end) AS jsonb_build_object
           FROM public.fin_spend_monitor r) n
  WHERE ((EXISTS ( SELECT 1
           FROM public.fin_organizations o
          WHERE ((o.id = n.organization_id) AND (o.kind = 'BUYER'::text)))) AND public.fin_has_role(organization_id, ARRAY['admin'::text, 'finance_manager'::text, 'analyst'::text, 'viewer'::text]));


ALTER VIEW public.fin_graph_objects OWNER TO postgres;

--
-- Name: fin_members; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fin_members (
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    display_name text,
    job_title text,
    entity_scope text DEFAULT 'group'::text NOT NULL,
    CONSTRAINT fin_members_admin_group_scope CHECK (((role <> 'admin'::text) OR (entity_scope = 'group'::text))),
    CONSTRAINT fin_members_display_name_check CHECK (((display_name IS NULL) OR (((length(display_name) >= 2) AND (length(display_name) <= 120)) AND (display_name !~ '[<>@]'::text)))),
    CONSTRAINT fin_members_entity_scope_check CHECK ((entity_scope = ANY (ARRAY['group'::text, 'entities'::text]))),
    CONSTRAINT fin_members_job_title_check CHECK (((job_title IS NULL) OR (((length(job_title) >= 2) AND (length(job_title) <= 80)) AND (job_title !~ '[<>]'::text)))),
    CONSTRAINT fin_members_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'finance_manager'::text, 'analyst'::text, 'provider_user'::text, 'viewer'::text])))
);

ALTER TABLE ONLY public.fin_members FORCE ROW LEVEL SECURITY;


ALTER TABLE public.fin_members OWNER TO postgres;

--
-- Name: fin_financial_graph; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_financial_graph WITH (security_invoker='true') AS
 SELECT fin_graph_objects.organization_id,
    fin_graph_objects.object_type,
    fin_graph_objects.object_id,
    fin_graph_objects.title,
    fin_graph_objects.status,
    fin_graph_objects.legal_entity_id,
    fin_graph_objects.provider_id,
    fin_graph_objects.rfq_id,
    fin_graph_objects.contract_id,
    fin_graph_objects.facility_id,
    fin_graph_objects.owner_id,
    fin_graph_objects.due_on,
    fin_graph_objects.facts
   FROM public.fin_graph_objects
UNION
 SELECT n.organization_id,
    'owner'::text AS object_type,
    (m.user_id)::text AS object_id,
    COALESCE(m.display_name, 'Responsável'::text) AS title,
    NULL::text AS status,
    n.legal_entity_id,
    n.provider_id,
    n.rfq_id,
    n.contract_id,
    n.facility_id,
    m.user_id AS owner_id,
    NULL::date AS due_on,
    jsonb_build_object('source', 'fin_members') AS facts
   FROM (public.fin_graph_objects n
     JOIN public.fin_members m ON (((m.organization_id = n.organization_id) AND (m.user_id = n.owner_id))));


ALTER VIEW public.fin_financial_graph OWNER TO postgres;

--
-- Name: fin_query_graph(uuid, text, uuid, text, uuid, text, text, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_query_graph(p_org uuid, p_root_type text, p_root uuid, p_kind text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT NULL::text, p_due_before date DEFAULT NULL::date, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF public.fin_financial_graph
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$ begin
 if not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
 if p_root_type is null or p_root is null or p_org is null or p_root_type not in ('organization','entity','provider','rfq','contract','facility')
 or p_kind is not null and p_kind not in ('organization','entity','provider','relationship','rfq','proposal','decision','contract','facility','limit','guarantee','passport_snapshot','milestone','obligation','document','owner','value_realization','fee_schedule','fee_observation','fee_variance','fee_review','opportunity','implementation','covenant','performance','spend')
 or p_limit is null or p_offset is null or p_limit not between 1 and 50 or p_offset not between 0 and 5000
 or p_query is not null and length(trim(p_query)) not between 2 and 100 then raise exception 'invalid graph query'; end if;
 if not exists(select 1 from public.fin_financial_graph n where n.organization_id=p_org and n.object_type=p_root_type and n.object_id=p_root::text) then raise exception 'graph root unavailable'; end if;
 if p_entity is not null and not public.fin_entity_visible(p_org,p_entity) then raise exception 'graph root unavailable'; end if;
 return query select n.* from public.fin_financial_graph n where n.organization_id=p_org
 and case p_root_type when 'organization' then n.organization_id=p_root when 'entity' then n.legal_entity_id=p_root when 'provider' then n.provider_id=p_root when 'rfq' then n.rfq_id=p_root when 'contract' then n.contract_id=p_root when 'facility' then n.facility_id=p_root end
 and (p_kind is null or n.object_type=p_kind) and (p_entity is null or n.legal_entity_id=p_entity)
 and (p_status is null or n.status=p_status) and (p_query is null or position(lower(trim(p_query)) in lower(n.title))>0)
 and (p_due_before is null or n.due_on between current_date and p_due_before)
 order by n.object_type,n.object_id,n.legal_entity_id nulls first,n.provider_id nulls first,n.rfq_id nulls first,n.contract_id nulls first,n.facility_id nulls first,n.owner_id nulls first limit p_limit + 1 offset p_offset;
end $$;


ALTER FUNCTION public.fin_query_graph(p_org uuid, p_root_type text, p_root uuid, p_kind text, p_entity uuid, p_status text, p_query text, p_due_before date, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fin_reconcile_spend(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_reconcile_spend(p_record uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_spend_records%rowtype;v_id uuid;begin
 select * into r from public.fin_spend_records where id=p_record for update;
 if auth.uid() is null or r.id is null or not public.fin_entity_allows(r.organization_id,r.legal_entity_id,array['admin','finance_manager']) then raise exception 'forbidden';end if;
 if public.fin_governance_org_locked(r.organization_id) then raise exception 'organization offboarding';end if;
 if r.recorded_by=auth.uid() then raise exception 'spend independent review required';end if;
 if exists(select 1 from public.fin_spend_records where supersedes_id=r.id) or exists(select 1 from public.fin_spend_reconciliations where record_id=r.id) then raise exception 'spend conflict';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('status','reason','no_duplicate_confirmed')) or p_input->>'no_duplicate_confirmed' is distinct from 'true' then raise exception 'spend duplicate confirmation required';end if;
 insert into public.fin_spend_reconciliations(organization_id,record_id,status,no_duplicate_confirmed,reason,reviewed_by) values(r.organization_id,r.id,p_input->>'status',true,trim(p_input->>'reason'),auth.uid()) returning id into v_id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(r.organization_id,'contract',r.contract_id,'spend_reconciled',auth.uid(),r.legal_entity_id,jsonb_build_object('record_id',r.id,'reconciliation_id',v_id));return v_id;
end $$;


ALTER FUNCTION public.fin_reconcile_spend(p_record uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_record_client_event(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_client_event(p_org uuid, p_entity_type text, p_entity_id uuid, p_event text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.fin_has_role(p_org) then raise exception 'forbidden'; end if;
  if p_event not in (
    'invite_opened','proposal_started','comparison_viewed','weights_applied',
    'onboarding_step_completed','export_generated'
  ) then raise exception 'unknown event'; end if;
  if p_entity_type not in ('rfq','proposal','contract','organization','invite') then raise exception 'unknown entity'; end if;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (p_org, p_entity_type, p_entity_id, p_event, auth.uid());
end $$;


ALTER FUNCTION public.fin_record_client_event(p_org uuid, p_entity_type text, p_entity_id uuid, p_event text) OWNER TO postgres;

--
-- Name: fin_record_contract_amendment(uuid, text, date, date, text, jsonb, date, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_contract_amendment(p_contract uuid, p_title text, p_effective_from date, p_signed_on date DEFAULT NULL::date, p_summary text DEFAULT NULL::text, p_terms jsonb DEFAULT NULL::jsonb, p_new_ends_on date DEFAULT NULL::date, p_new_notice_days integer DEFAULT NULL::integer, p_document uuid DEFAULT NULL::uuid, p_expected integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_contracts%rowtype; v_id uuid; v_number integer; v_version integer;
  v_ends date; v_notice integer; v_review date; v_status text;
begin
  v := public.fin_contract_for_write(p_contract);
  if v.status not in ('active','renewing') then raise exception 'invalid state'; end if;
  if p_effective_from is null or p_effective_from < v.starts_on then raise exception 'invalid period'; end if;
  if p_new_ends_on is not null and p_new_ends_on < v.starts_on then raise exception 'invalid period'; end if;
  if p_new_notice_days is not null and p_new_notice_days not between 0 and 3650 then raise exception 'invalid period'; end if;
  if p_terms is not null and p_expected is distinct from v.current_version then raise exception 'contract version conflict'; end if;
  if p_terms is not null and not public.fin_valid_contract_terms(p_terms) then raise exception 'invalid contract terms'; end if;
  if p_terms is null and p_new_ends_on is null and p_new_notice_days is null and length(trim(coalesce(p_summary,''))) < 3 then
    raise exception 'empty amendment';
  end if;
  if p_document is not null and not exists (select 1 from public.fin_private_documents d where d.id = p_document
       and d.organization_id = v.organization_id and d.entity_type = 'contract' and d.entity_id = v.id and d.removed_at is null) then
    raise exception 'invalid document';
  end if;
  select coalesce(max(number), 0) + 1 into v_number from public.fin_contract_amendments where contract_id = v.id;
  insert into public.fin_contract_amendments(organization_id, contract_id, number, title, signed_on, effective_from, summary,
      previous_ends_on, new_ends_on, previous_notice_days, new_notice_days, document_id, recorded_by)
    values (v.organization_id, v.id, v_number, trim(p_title), p_signed_on, p_effective_from, nullif(trim(coalesce(p_summary,'')),''),
      v.ends_on, p_new_ends_on, v.renewal_notice_days, p_new_notice_days, p_document, auth.uid())
    returning id into v_id;
  if p_terms is not null then
    v_version := v.current_version + 1;
    insert into public.fin_contract_versions(contract_id, organization_id, version, effective_from, source, amendment_id, terms, recorded_by)
      values (v.id, v.organization_id, v_version, p_effective_from, 'amendment', v_id, p_terms, auth.uid());
  end if;
  update public.fin_contracts set
      ends_on = coalesce(p_new_ends_on, ends_on),
      renewal_notice_days = coalesce(p_new_notice_days, renewal_notice_days),
      current_version = coalesce(v_version, current_version),
      terms_updated_at = case when v_version is null then terms_updated_at else now() end,
      currency = coalesce(p_terms->>'currency', currency),
      updated_at = now()
    where id = v.id;
  -- Novo fim ou novo aviso prévio: o status e a próxima ação acompanham o novo
  -- ciclo, como no registro do contrato existente. Os marcos do ciclo anterior
  -- ficam como histórico; os do novo ciclo voltam a disparar (cycle_ends_on).
  v_ends := coalesce(p_new_ends_on, v.ends_on);
  v_notice := coalesce(p_new_notice_days, v.renewal_notice_days);
  v_status := v.status;
  if v_ends is distinct from v.ends_on or v_notice is distinct from v.renewal_notice_days then
    v_review := v_ends - v_notice;
    v_status := case when v_ends >= current_date and v_review <= current_date then 'renewing'
                     when v_review > current_date then 'active' else v.status end;
    if v_status is distinct from v.status then
      update public.fin_contracts set status = v_status, updated_at = now() where id = v.id;
    end if;
    update public.fin_tasks t set due_on = greatest(v_review, current_date),
        title = case when t.title = 'Revisar contrato vencido' and v_ends >= current_date then 'Revisar renovação de contrato' else t.title end
      where t.organization_id = v.organization_id and t.related_type = 'contract' and t.related_id = v.id and t.status = 'open'
        and (t.title in ('Revisar renovação do contrato antes do aviso prévio', 'Revisar renovação de contrato', 'Revisar contrato vencido')
             or t.id in (select m.task_id from public.fin_renewal_milestones m where m.contract_id = v.id));
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v.organization_id, 'contract', v.id, 'contract_amended', auth.uid(),
      jsonb_build_object('amendment', v_number, 'terms_version', v_version, 'dates_changed', p_new_ends_on is not null or p_new_notice_days is not null,
        'status_before', v.status, 'status_after', v_status));
  return v_id;
exception when check_violation then raise exception 'invalid amendment';
end $$;


ALTER FUNCTION public.fin_record_contract_amendment(p_contract uuid, p_title text, p_effective_from date, p_signed_on date, p_summary text, p_terms jsonb, p_new_ends_on date, p_new_notice_days integer, p_document uuid, p_expected integer) OWNER TO postgres;

--
-- Name: fin_record_contract_terms(uuid, jsonb, integer, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_contract_terms(p_contract uuid, p_terms jsonb, p_expected integer, p_reason text DEFAULT NULL::text, p_effective_from date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_contracts%rowtype; v_version integer; v_source text;
begin
  v := public.fin_contract_for_write(p_contract);
  if p_expected is distinct from v.current_version then raise exception 'contract version conflict'; end if;
  if p_terms is null or not public.fin_valid_contract_terms(p_terms) then raise exception 'invalid contract terms'; end if;
  v_source := case when v.current_version = 0 then 'registration' else 'correction' end;
  if v_source = 'correction' and length(trim(coalesce(p_reason, ''))) < 3 then raise exception 'correction reason required'; end if;
  v_version := v.current_version + 1;
  insert into public.fin_contract_versions(contract_id, organization_id, version, effective_from, source, reason, terms, recorded_by)
    values (v.id, v.organization_id, v_version, coalesce(p_effective_from, v.starts_on), v_source,
      nullif(trim(coalesce(p_reason, '')), ''), p_terms, auth.uid());
  update public.fin_contracts set current_version = v_version, terms_updated_at = now(), updated_at = now(),
    currency = coalesce(p_terms->>'currency', currency)
   where id = v.id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v.organization_id, 'contract', v.id, 'contract_terms_' || v_source, auth.uid(), jsonb_build_object('version', v_version));
  return v_version;
end $$;


ALTER FUNCTION public.fin_record_contract_terms(p_contract uuid, p_terms jsonb, p_expected integer, p_reason text, p_effective_from date) OWNER TO postgres;

--
-- Name: fin_record_decision(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_decision(p_rfq uuid, p_proposal uuid, p_criteria jsonb DEFAULT '{}'::jsonb, p_rationale text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_status text; v_snapshot jsonb; v_id uuid; v_version integer; v_approval public.fin_approval_requests%rowtype; v_updated timestamptz;
  v_eval jsonb; v_final integer; v_actors uuid[];
begin
  select organization_id,status,updated_at into v_org,v_status,v_updated from public.fin_rfqs where id=p_rfq for update;
  if v_org is null then raise exception 'rfq not found'; end if;
  if not public.fin_has_role(v_org,array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_status not in ('collecting','comparing') and not (v_status='open' and exists(select 1 from public.fin_external_proposals where id=p_proposal)) then raise exception 'invalid state'; end if;
  if jsonb_typeof(coalesce(p_criteria,'null'::jsonb)) is distinct from 'object' then raise exception 'invalid criteria'; end if;
  if exists(select 1 from public.fin_decisions where rfq_id=p_rfq) then raise exception 'decision already recorded'; end if;
  select current_version into v_version from public.fin_decision_sources
    where id=p_proposal and rfq_id=p_rfq and buyer_organization_id=v_org and status in ('submitted','revised','reviewed');
  if v_version is null then raise exception 'proposal not eligible'; end if;
  select * into v_approval from public.fin_approval_requests where rfq_id=p_rfq order by requested_at desc,id desc limit 1;
  if v_approval.id is null then
    -- Sem pedido: a exigência é a da policy vigente agora (inclui a política v1).
    v_eval := public.fin_policy_evaluate(p_rfq, p_proposal, '{}'::jsonb);
    if coalesce((v_eval->>'approval_required')::boolean, false) then raise exception 'approval required or stale'; end if;
    if coalesce((v_eval->'requirements'->>'justification')::boolean, false) and length(trim(coalesce(p_rationale,''))) < 10 then
      raise exception 'policy justification required';
    end if;
  elsif v_approval.status <> 'approved' or coalesce(v_approval.proposal_id,v_approval.external_proposal_id) <> p_proposal
    or v_approval.proposal_version <> v_version or v_approval.rfq_updated_at is distinct from v_updated then
    raise exception 'approval required or stale';
  elsif v_approval.policy_snapshot is not null then
    v_eval := v_approval.policy_snapshot;
    if coalesce((v_eval->'sod'->>'requester_cannot_decide')::boolean, false) and v_approval.requested_by = auth.uid() then
      raise exception 'segregation of duties';
    end if;
    if coalesce((v_eval->'sod'->>'decider_not_sole_final_approver')::boolean, true) then
      select max(st.sequence) into v_final from public.fin_approval_stages st where st.request_id = v_approval.id and st.status = 'approved';
      select array_agg(distinct s.acted_by) into v_actors from public.fin_approval_steps s join public.fin_approval_stages st on st.id = s.stage_id
       where st.request_id = v_approval.id and st.sequence = v_final and st.status = 'approved' and s.status = 'approved';
      if v_actors = array[auth.uid()] then raise exception 'segregation of duties'; end if;
    end if;
  end if;
  select jsonb_build_object('decided_proposal_id',p_proposal,'decided_version',v_version,'captured_at',now(),
    'approval_request_id',v_approval.id,
    'policy', case when v_eval is null then null else jsonb_build_object('engine', v_eval->'engine', 'policies', v_eval->'policies',
       'matched', v_eval->'matched', 'evaluated_at', v_eval->'evaluated_at', 'from_request', v_approval.policy_snapshot is not null) end,
    'proposals',coalesce(jsonb_agg(jsonb_build_object(
      'proposal_id',case when p.source_kind='institution_authenticated' then p.id end,'external_proposal_id',case when p.source_kind='buyer_recorded_external' then p.id end,'origin',p.source_kind,'provider_id',p.provider_id,'status',p.status,'version',p.current_version,
      'terms',v.terms,'submitted_at',v.submitted_at) order by p.created_at),'[]'::jsonb)) into v_snapshot
    from public.fin_decision_sources p left join public.fin_decision_source_versions v on v.proposal_id=p.id and v.version=p.current_version
    where p.rfq_id=p_rfq and p.buyer_organization_id=v_org and p.current_version>0;
  insert into public.fin_decisions(organization_id,rfq_id,proposal_id,decided_by,criteria,rationale,snapshot)
    values(v_org,p_rfq,p_proposal,auth.uid(),coalesce(p_criteria,'{}'::jsonb),p_rationale,v_snapshot) returning id into v_id;
  update public.fin_rfqs set status='decided',updated_at=now() where id=p_rfq;
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
    values(v_org,'rfq',p_rfq,'decision_recorded',auth.uid(),jsonb_build_object('decided_version',v_version,'approval_request_id',v_approval.id,
      'policy_rules', jsonb_array_length(coalesce(v_eval->'matched','[]'::jsonb))));
  return v_id;
end $$;


ALTER FUNCTION public.fin_record_decision(p_rfq uuid, p_proposal uuid, p_criteria jsonb, p_rationale text) OWNER TO postgres;

--
-- Name: fin_record_decision_v2(uuid, uuid, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_decision_v2(p_rfq uuid, p_proposal uuid, p_expected_version integer, p_criteria jsonb DEFAULT '{}'::jsonb, p_rationale text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1 then raise exception 'invalid expected version'; end if;
  -- A RFQ travada impede envio concorrente (o envio trava a RFQ antes da proposta):
  -- a versão lida aqui é a que a decisão vai gravar.
  select organization_id into v_org from public.fin_rfqs where id = p_rfq for update;
  if v_org is null then raise exception 'rfq not found'; end if;
  if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  select current_version into v_version from public.fin_decision_sources
    where id = p_proposal and rfq_id = p_rfq and buyer_organization_id = v_org;
  if v_version is null then raise exception 'proposal not eligible'; end if;
  if v_version <> p_expected_version then raise exception 'proposal version changed'; end if;
  return public.fin_record_decision(p_rfq, p_proposal, p_criteria, p_rationale);
end $$;


ALTER FUNCTION public.fin_record_decision_v2(p_rfq uuid, p_proposal uuid, p_expected_version integer, p_criteria jsonb, p_rationale text) OWNER TO postgres;

--
-- Name: fin_record_facility_balance(uuid, date, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_facility_balance(p_facility uuid, p_as_of date, p_outstanding numeric DEFAULT NULL::numeric, p_used_limit numeric DEFAULT NULL::numeric, p_source text DEFAULT 'declared'::text, p_source_reference text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_facilities%rowtype; v_id uuid;
begin
  select * into v from public.fin_facilities where id = p_facility;
  if not found or not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'facility not found'; end if;
  if p_as_of is null or p_as_of > current_date then raise exception 'invalid date'; end if;
  if p_used_limit is not null and v.approved_limit is not null and p_used_limit > v.approved_limit then raise exception 'used limit exceeds approved'; end if;
  insert into public.fin_facility_balances(organization_id, facility_id, as_of, outstanding_amount, used_limit_amount, source, source_reference, recorded_by)
    values (v.organization_id, v.id, p_as_of, p_outstanding, p_used_limit, coalesce(p_source,'declared'), nullif(trim(coalesce(p_source_reference,'')),''), auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'facility', v.id, 'facility_balance_recorded', auth.uid(), jsonb_build_object('as_of', p_as_of, 'source', p_source), v.legal_entity_id);
  return v_id;
exception when check_violation then raise exception 'invalid balance';
end $$;


ALTER FUNCTION public.fin_record_facility_balance(p_facility uuid, p_as_of date, p_outstanding numeric, p_used_limit numeric, p_source text, p_source_reference text) OWNER TO postgres;

--
-- Name: fin_record_facility_schedule(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_facility_schedule(p_facility uuid, p_items jsonb, p_expected integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v public.fin_facilities%rowtype; v_version integer; item jsonb;
begin
  select * into v from public.fin_facilities where id = p_facility for update;
  if not found or not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'facility not found'; end if;
  if p_expected is distinct from v.schedule_version then raise exception 'schedule version conflict'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 600 then raise exception 'invalid schedule'; end if;
  v_version := v.schedule_version + 1;
  for item in select * from jsonb_array_elements(p_items) loop
    if coalesce(item->>'due_on','') !~ '^\d{4}-\d{2}-\d{2}$' or jsonb_typeof(item->'principal_amount') <> 'number' then raise exception 'invalid schedule'; end if;
    insert into public.fin_facility_repayments(organization_id, facility_id, schedule_version, due_on, principal_amount, recorded_by)
      values (v.organization_id, v.id, v_version, (item->>'due_on')::date, (item->>'principal_amount')::numeric, auth.uid());
  end loop;
  update public.fin_facilities set schedule_version = v_version, updated_at = now() where id = v.id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'facility', v.id, 'facility_schedule_recorded', auth.uid(), jsonb_build_object('version', v_version, 'items', jsonb_array_length(p_items)), v.legal_entity_id);
  return v_version;
exception when unique_violation then raise exception 'invalid schedule';
  when check_violation then raise exception 'invalid schedule';
end $_$;


ALTER FUNCTION public.fin_record_facility_schedule(p_facility uuid, p_items jsonb, p_expected integer) OWNER TO postgres;

--
-- Name: fin_record_fee_observation(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_fee_observation(p_org uuid, p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select public.fin_record_fee_observation_internal(p_org,p_contract,p_input,'manual_entry');
$$;


ALTER FUNCTION public.fin_record_fee_observation(p_org uuid, p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_record_fee_observation_internal(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_fee_observation_internal(p_org uuid, p_contract uuid, p_input jsonb, p_channel text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype; x public.fin_fee_observations%rowtype; e public.fin_fee_observations%rowtype; r public.fin_fee_variances%rowtype; v_key text;
begin
  if p_channel is null or p_channel not in ('manual_entry','structured_file','erp_adapter') or p_channel='structured_file' and p_input->>'source_type' is distinct from 'other_import' or p_channel='erp_adapter' and p_input->>'source_type' is distinct from 'erp' then raise exception 'invalid fee observation source';end if;
  select * into c from public.fin_contracts where organization_id = p_org and id = p_contract for share;
  if c.id is null or auth.uid() is null or not public.fin_entity_allows(p_org, c.legal_entity_id, array['admin','finance_manager'])
     or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  -- Existing declared sources remain valid; the capture channel is supplied only by canonical wrappers.
  if p_input->>'source_type' is null or p_input->>'source_type' not in ('manual','bank_statement','erp','tms','bank_file','other_import') then raise exception 'invalid fee observation source'; end if;
  begin
    if p_input is null or jsonb_typeof(p_input) <> 'object' or length(p_input::text) > 4000
       or exists (select 1 from jsonb_object_keys(p_input) k where k not in ('service','charging_unit','currency','period_start','period_end','volume','base_amount','observed_amount','source_type','source_reference','source_object_id','evidence_reference'))
       or jsonb_typeof(p_input->'observed_amount') is distinct from 'number'
       or (p_input ? 'volume' and jsonb_typeof(p_input->'volume') not in ('number','null'))
       or (p_input ? 'base_amount' and jsonb_typeof(p_input->'base_amount') not in ('number','null')) then raise exception 'invalid fee observation'; end if;
    if (p_input->>'observed_amount')::numeric <> round((p_input->>'observed_amount')::numeric, 2)
       or (p_input->>'base_amount')::numeric <> round((p_input->>'base_amount')::numeric, 2)
       or (p_input->>'period_start')::date is null or (p_input->>'period_end')::date is null
       or (p_input->>'period_end')::date >= current_date + 1 then raise exception 'invalid fee observation'; end if;
  exception when others then raise exception 'invalid fee observation';
  end;
  v_key := md5(concat_ws('|', p_input->>'source_type', lower(btrim(p_input->>'source_reference')), c.id::text, lower(btrim(p_input->>'service')), p_input->>'charging_unit', p_input->>'period_start', p_input->>'period_end'));
  select * into e from public.fin_fee_observations where organization_id = p_org and dedupe_key = v_key;
  if e.id is not null then
    -- Replay of the same fact is idempotent; a different fact under the same key is a conflict.
    if e.observed_amount = (p_input->>'observed_amount')::numeric and e.currency = p_input->>'currency'
       and e.volume is not distinct from (p_input->>'volume')::numeric and e.base_amount is not distinct from (p_input->>'base_amount')::numeric then return e.id; end if;
    raise exception 'fee observation conflict';
  end if;
  begin
    insert into public.fin_fee_observations(organization_id, contract_id, legal_entity_id, provider_id, service, charging_unit, currency, period_start, period_end,
      volume, base_amount, observed_amount, source_type, source_reference, source_object_id, evidence_reference, owner_id, dedupe_key, ingestion_channel)
    values (p_org, c.id, c.legal_entity_id, c.provider_id, trim(p_input->>'service'), p_input->>'charging_unit', p_input->>'currency',
      (p_input->>'period_start')::date, (p_input->>'period_end')::date, (p_input->>'volume')::numeric, (p_input->>'base_amount')::numeric,
      (p_input->>'observed_amount')::numeric, p_input->>'source_type', trim(p_input->>'source_reference'), nullif(trim(coalesce(p_input->>'source_object_id', '')), ''),
      trim(p_input->>'evidence_reference'), auth.uid(), v_key, p_channel)
    returning * into x;
  exception when check_violation or not_null_violation or invalid_datetime_format or datetime_field_overflow or invalid_text_representation then raise exception 'invalid fee observation';
  end;
  r := public.fin_compare_fee(x);
  insert into public.fin_fee_variances select r.*;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'contract', c.id, 'fee_observation_recorded', auth.uid(), jsonb_build_object('observation_id', x.id, 'source_type', x.source_type, 'comparison_status', r.comparison_status));
  if r.comparison_status = 'comparable' and r.direction <> 'equal' then
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
      values (p_org, 'contract', c.id, 'fee_variance_detected', auth.uid(), jsonb_build_object('variance_id', r.id, 'direction', r.direction, 'schedule_version', r.schedule_version));
  end if;
  return x.id;
end $$;


ALTER FUNCTION public.fin_record_fee_observation_internal(p_org uuid, p_contract uuid, p_input jsonb, p_channel text) OWNER TO postgres;

