-- Name: fin_record_job_run(text, text, integer, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_job_run(p_job text, p_status text, p_processed integer, p_request_id text, p_error_code text, p_started_at timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.fin_job_runs(job,status,processed,failed,request_id,error_code,started_at,finished_at)
  values(p_job,p_status,greatest(coalesce(p_processed,0),0),case when p_status='failed' then 1 else 0 end,p_request_id,p_error_code,p_started_at,now());
$$;


