--
-- Name: fin_record_obligation_data(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_obligation_data(p_period uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype;v_id uuid;v_doc uuid;begin
 o:=public.fin_obligation_require(p_period,array['admin','finance_manager','analyst']);
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('measured_value','measured_on','source_reference','provenance','document_id')) then raise exception 'invalid obligation input';end if;
 v_doc:=nullif(p_input->>'document_id','')::uuid;
 if v_doc is not null and not(public.fin_can_read_document(v_doc) and exists(select 1 from public.fin_private_documents where id=v_doc and buyer_organization_id=o.organization_id and entity_type='contract' and entity_id=o.contract_id)) then raise exception 'invalid obligation evidence';end if;
 if o.kind='financial_covenant' then
 if (p_input->>'measured_on')::date>current_date or (p_input->>'measured_on')::date<(select period_end from public.fin_obligation_periods where id=p_period) then raise exception 'invalid obligation measurement date';end if;
 insert into public.fin_covenant_measurements(organization_id,period_id,measured_value,measured_on,source_reference,provenance,document_id,recorded_by) values(o.organization_id,p_period,(p_input->>'measured_value')::numeric,(p_input->>'measured_on')::date,trim(p_input->>'source_reference'),trim(p_input->>'provenance'),v_doc,auth.uid()) returning id into v_id;
 else
 if p_input ? 'measured_value' or p_input ? 'measured_on' then raise exception 'invalid obligation metric';end if;
 insert into public.fin_obligation_evidence(organization_id,period_id,source_reference,provenance,document_id,recorded_by) values(o.organization_id,p_period,trim(p_input->>'source_reference'),trim(p_input->>'provenance'),v_doc,auth.uid()) returning id into v_id;
 end if;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(o.organization_id,'contract',o.contract_id,'obligation_data_recorded',auth.uid(),o.legal_entity_id,jsonb_build_object('period_id',p_period,'record_id',v_id));
 update public.fin_tasks set status=case when public.fin_obligation_facts(p_period,current_date)->>'status' in ('waived','not_applicable') then 'done' else 'open' end where id=(select task_id from public.fin_obligation_periods where id=p_period);
 return v_id;
end $$;


ALTER FUNCTION public.fin_record_obligation_data(p_period uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_record_provider_evidence(uuid, text, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_provider_evidence(p_provider uuid, p_authority text, p_registry text, p_evidence_url text, p_checked_at date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid;
begin
  select organization_id into v_org from public.fin_providers where id = p_provider;
  if v_org is null then raise exception 'not found'; end if;
  if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if coalesce(p_evidence_url,'') !~ '^https://' then raise exception 'evidence url must use https'; end if;
  if length(trim(coalesce(p_authority,''))) < 2 or length(trim(coalesce(p_registry,''))) < 1 then
    raise exception 'authority and registry are required';
  end if;
  if p_checked_at is null or p_checked_at > current_date then raise exception 'invalid check date'; end if;
  update public.fin_providers
    set verification_state = 'EVIDENCIA_REGISTRADA', regulator_authority = trim(p_authority),
        regulator_registry = trim(p_registry), regulator_evidence_url = p_evidence_url,
        regulator_checked_at = p_checked_at, updated_at = now()
    where id = p_provider;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (v_org, 'provider', p_provider, 'provider_evidence_recorded', auth.uid());
end $$;


ALTER FUNCTION public.fin_record_provider_evidence(p_provider uuid, p_authority text, p_registry text, p_evidence_url text, p_checked_at date) OWNER TO postgres;

--
-- Name: fin_record_provider_review(uuid, uuid, uuid, date, date, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_provider_review(p_org uuid, p_provider uuid, p_template uuid, p_period_start date, p_period_end date, p_scores jsonb, p_entity uuid DEFAULT NULL::uuid, p_comment text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.fin_scorecard_templates%rowtype; c jsonb; v_total numeric := 0; v_answered numeric := 0; v_sum numeric := 0; v_score numeric; v_id uuid;
begin
  perform public.fin_assert_portfolio_write(p_org, p_entity);
  select * into t from public.fin_scorecard_templates where id = p_template and organization_id = p_org;
  if not found or t.status <> 'active' then raise exception 'invalid scorecard'; end if;
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if jsonb_typeof(p_scores) <> 'object' or exists (select 1 from jsonb_object_keys(p_scores) k
       where not exists (select 1 from jsonb_array_elements(t.criteria) x where x->>'key' = k)) then
    raise exception 'invalid review';
  end if;
  for c in select * from jsonb_array_elements(t.criteria) loop
    v_total := v_total + (c->>'weight')::numeric;
    if p_scores ? (c->>'key') then
      if jsonb_typeof(p_scores->(c->>'key')) <> 'number' then raise exception 'invalid review'; end if;
      v_score := (p_scores->>(c->>'key'))::numeric;
      if v_score < 0 or v_score > (c->>'scale_max')::numeric then raise exception 'invalid review'; end if;
      v_answered := v_answered + (c->>'weight')::numeric;
      v_sum := v_sum + (c->>'weight')::numeric * v_score / (c->>'scale_max')::numeric * 100;
    end if;
  end loop;
  if v_answered = 0 then raise exception 'invalid review'; end if;
  insert into public.fin_provider_reviews(organization_id, provider_id, template_id, legal_entity_id, period_start, period_end, scores,
      weighted_result, answered_weight, comment, reviewer_id)
    values (p_org, p_provider, p_template, p_entity, p_period_start, p_period_end, p_scores,
      round(v_sum / v_answered, 3), round(v_answered / v_total * 100, 3), nullif(trim(coalesce(p_comment,'')),''), auth.uid())
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'provider', p_provider, 'provider_review_recorded', auth.uid(), jsonb_build_object('review_id', v_id, 'template_id', p_template), p_entity);
  return v_id;
exception when check_violation then raise exception 'invalid review';
end $$;


ALTER FUNCTION public.fin_record_provider_review(p_org uuid, p_provider uuid, p_template uuid, p_period_start date, p_period_end date, p_scores jsonb, p_entity uuid, p_comment text) OWNER TO postgres;

--
-- Name: fin_record_qualification_evidence(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_qualification_evidence(p_qualification uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.fin_provider_qualifications%rowtype; r public.fin_qualification_requirements%rowtype; v_id uuid; v_doc uuid;
begin
  select * into q from public.fin_provider_qualifications where id = p_qualification for update;
  if q.id is null or auth.uid() is null or not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(q.organization_id) then raise exception 'organization offboarding'; end if;
  if q.status not in ('not_started','in_progress','pending_provider','pending_internal_review','qualified','qualified_with_conditions') then raise exception 'qualification closed'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or exists (select 1 from jsonb_object_keys(p_input) k where k not in ('requirement_id','source','external_service','evidence_reference','document_id','valid_until')) then raise exception 'invalid qualification evidence'; end if;
  select * into r from public.fin_qualification_applicable(q) a where a.id = (p_input->>'requirement_id')::uuid;
  if r.id is null then raise exception 'invalid qualification evidence'; end if;
  v_doc := nullif(p_input->>'document_id', '')::uuid;
  if v_doc is not null and not (public.fin_can_read_document(v_doc) and exists (select 1 from public.fin_private_documents d where d.id = v_doc and d.buyer_organization_id = q.organization_id)) then raise exception 'invalid qualification evidence'; end if;
  if nullif(p_input->>'valid_until', '')::date < current_date then raise exception 'invalid qualification evidence'; end if;
  begin
    insert into public.fin_qualification_evidence(organization_id, qualification_id, requirement_id, source, external_service, evidence_reference, document_id, valid_until, created_by)
    values (q.organization_id, q.id, r.id, p_input->>'source', nullif(trim(coalesce(p_input->>'external_service', '')), ''), trim(p_input->>'evidence_reference'), v_doc,
      coalesce(nullif(p_input->>'valid_until', '')::date, case when r.validity_days is not null then current_date + r.validity_days end), auth.uid())
    returning id into v_id;
  exception when check_violation or not_null_violation or invalid_text_representation then raise exception 'invalid qualification evidence';
  end;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, object_id, actor_id) values (q.organization_id, q.id, 'evidence_recorded', v_id, auth.uid());
  return v_id;
end $$;


ALTER FUNCTION public.fin_record_qualification_evidence(p_qualification uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_record_spend(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_spend(p_contract uuid, p_expected uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype;last public.fin_spend_records%rowtype;v_key text;v_id uuid;begin
 select * into c from public.fin_contracts where id=p_contract for update;
 if auth.uid() is null or c.id is null or not public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager','analyst']) or not exists(select 1 from public.fin_organizations where id=c.organization_id and kind='BUYER') then raise exception 'forbidden';end if;
 if public.fin_governance_org_locked(c.organization_id) then raise exception 'organization offboarding';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('period_start','period_end','currency','value_kind','amount','source_type','source_reference','source_line','provenance','correction_reason')) then raise exception 'invalid spend input';end if;
 if (p_input->>'amount')::numeric<>round((p_input->>'amount')::numeric,2) then raise exception 'invalid spend precision';end if;
 -- Stable reference/line identity prevents changed dates or kinds from silently creating another copy.
 v_key:=md5(lower(trim(p_input->>'source_reference'))||':'||lower(trim(p_input->>'source_line')));
 perform pg_advisory_xact_lock(hashtextextended(c.organization_id::text||':spend:'||v_key,0));
 select * into last from public.fin_spend_records where organization_id=c.organization_id and source_key=v_key order by revision desc limit 1;
 if last.id is not null and last.contract_id<>c.id then raise exception 'spend duplicate source';end if;
 if last.id is distinct from p_expected then raise exception 'spend conflict';end if;
 if exists(select 1 from public.fin_fee_observations o where o.organization_id=c.organization_id and lower(trim(o.source_reference))=lower(trim(p_input->>'source_reference'))) then raise exception 'spend duplicate fee source';end if;
 insert into public.fin_spend_records(organization_id,contract_id,legal_entity_id,provider_id,product,period_start,period_end,currency,value_kind,amount,source_type,source_reference,source_line,provenance,source_key,revision,supersedes_id,correction_reason,recorded_by)
 values(c.organization_id,c.id,c.legal_entity_id,c.provider_id,c.product,(p_input->>'period_start')::date,(p_input->>'period_end')::date,p_input->>'currency',p_input->>'value_kind',(p_input->>'amount')::numeric,p_input->>'source_type',trim(p_input->>'source_reference'),trim(p_input->>'source_line'),trim(p_input->>'provenance'),v_key,coalesce(last.revision,0)+1,last.id,trim(p_input->>'correction_reason'),auth.uid()) returning id into v_id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(c.organization_id,'contract',c.id,'spend_recorded',auth.uid(),c.legal_entity_id,jsonb_build_object('record_id',v_id,'revision',coalesce(last.revision,0)+1));return v_id;
end $$;


ALTER FUNCTION public.fin_record_spend(p_contract uuid, p_expected uuid, p_input jsonb) OWNER TO postgres;

