--
-- Name: fin_record_value(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_record_value(p_org uuid, p_contract uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype; cv public.fin_contract_versions%rowtype; m public.fin_value_methodologies%rowtype;
  b jsonb; ds jsonb; v_id uuid; v_start date; v_end date; v_base numeric; v_target numeric; v_method text; v_definition jsonb;
begin
  select * into c from public.fin_contracts where organization_id=p_org and id=p_contract for share;
  if c.id is null or auth.uid() is null or not public.fin_entity_allows(p_org,c.legal_entity_id,array['admin','finance_manager'])
     or not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  if p_input->>'kind' is null or p_input->>'kind' not in ('NEGOTIATED_SAVINGS','COST_AVOIDANCE') then raise exception 'invalid value kind'; end if;
  b:=p_input->'baseline'; ds:=p_input->'target_dimensions';
  v_start:=(p_input->>'period_start')::date; v_end:=(p_input->>'period_end')::date;
  v_base:=(b->>'amount')::numeric; v_target:=(p_input->>'target_amount')::numeric;
  if b is null or jsonb_typeof(b)<>'object' or b->>'source' is null or b->>'source' not in ('contract','proposal','approved_budget','manual','import')
     or length(trim(coalesce(b->>'reference',''))) not between 3 and 200
     or b->>'as_of' is null or (b->>'as_of')::date>v_start
     or b->>'currency' is distinct from p_input->>'currency' or b->>'unit' is distinct from 'period_total'
     or (b->>'period_start')::date is distinct from v_start or (b->>'period_end')::date is distinct from v_end
     or v_base is null or v_base<0 or v_base>1000000000000 or v_base::text='NaN' or v_base<>round(v_base,2)
     or v_target is null or v_target<0 or v_target>1000000000000 or v_target::text='NaN' or v_target<>round(v_target,2)
     or exists(select 1 from jsonb_object_keys(b) k where k not in ('source','reference','as_of','amount','currency','unit','period_start','period_end','dimensions'))
     or length(b::text)>6000 or b::text ~ '[<>]' then raise exception 'invalid value baseline'; end if;
  if jsonb_typeof(b->'dimensions') is distinct from 'object' or jsonb_typeof(ds) is distinct from 'object'
     or length(ds::text)>4000 or ds::text ~ '[<>]'
     or exists(select 1 from jsonb_object_keys(ds) k where k not in ('service','unit','volume','indexer','term_months','amortization','fees','guarantee','grace_months'))
     or exists(select 1 from jsonb_object_keys(b->'dimensions') k where k not in ('service','unit','volume','indexer','term_months','amortization','fees','guarantee','grace_months')) then raise exception 'invalid value dimensions'; end if;
  if p_input->>'comparability'='comparable' and
    (not (b->'dimensions' ?& array['service','unit','volume','indexer','term_months','amortization','fees','guarantee','grace_months'])
      or b->'dimensions' is distinct from ds
      or exists(select 1 from jsonb_each(ds) d where d.value='null'::jsonb or d.value='""'::jsonb)) then raise exception 'value not comparable'; end if;
  if c.currency is not null and c.currency is distinct from p_input->>'currency' then raise exception 'value currency mismatch'; end if;
  select * into cv from public.fin_contract_versions where contract_id=c.id and organization_id=p_org order by version desc limit 1;
  if cv.contract_id is null then raise exception 'value target version unavailable'; end if;
  v_method:=case when p_input->>'kind'='COST_AVOIDANCE' then 'counterfactual_period_total_avoidance' else 'period_total_difference' end;
  v_definition:=jsonb_build_object('formula',case when p_input->>'kind'='COST_AVOIDANCE' then 'counterfactual_period_total - target_period_total' else 'baseline_period_total - target_period_total' end,
    'version',1,'unit','period_total','rounding','2 decimal places',
    'verification',case when p_input->>'kind'='COST_AVOIDANCE' then 'Customer declared counterfactual expense avoided; not cash saved or observed realization' else 'Human declared total costs and equal economic dimensions; no spread projection' end);
  insert into public.fin_value_methodologies(organization_id,method_key,definition,created_by) values(p_org,v_method,v_definition,auth.uid())
    on conflict(organization_id,method_key,version) do nothing;
  select * into m from public.fin_value_methodologies where organization_id=p_org and method_key=v_method and version=1;
  insert into public.fin_value_records(organization_id,contract_id,contract_version,legal_entity_id,provider_id,product,owner_id,kind,title,currency,period_start,period_end,baseline,target_amount,target_snapshot,target_dimensions,comparability,value_amount,methodology_id,methodology_snapshot,evidence_reference,reason)
  values(p_org,c.id,cv.version,c.legal_entity_id,c.provider_id,c.product,auth.uid(),p_input->>'kind',p_input->>'title',p_input->>'currency',v_start,v_end,b,v_target,
    jsonb_build_object('contract_id',c.id,'version',cv.version,'terms',cv.terms,'effective_from',cv.effective_from),ds,p_input->>'comparability',
    case when p_input->>'comparability'='comparable' then round(v_base-v_target,2) end,m.id,m.definition,p_input->>'evidence_reference',p_input->>'reason') returning id into v_id;
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
    values(p_org,'contract',c.id,'value_recorded',auth.uid(),jsonb_build_object('record_id',v_id,'kind',p_input->>'kind','methodology_version',m.version));
  return v_id;
end $$;


ALTER FUNCTION public.fin_record_value(p_org uuid, p_contract uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_register_contract(uuid, date, date, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_register_contract(p_decision uuid, p_starts date, p_ends date, p_notice integer DEFAULT 60, p_cost text DEFAULT NULL::text, p_conditions text DEFAULT NULL::text, p_reference text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_dec public.fin_decisions%rowtype; v_provider uuid; v_product text; v_id uuid; v_review date;
begin
  select * into v_dec from public.fin_decisions where id = p_decision for update;
  if not found then raise exception 'decision not found'; end if;
  if v_dec.external_proposal_id is not null then raise exception 'external command required'; end if;
  if not public.fin_has_role(v_dec.organization_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if exists (select 1 from public.fin_contracts c where c.decision_id = p_decision) then raise exception 'contract already registered'; end if;
  if p_ends < p_starts then raise exception 'invalid period'; end if;
  select p.provider_id, p.product into v_provider, v_product from public.fin_proposals p where p.id = v_dec.proposal_id;
  insert into public.fin_contracts (organization_id, decision_id, proposal_id, provider_id, product,
      starts_on, ends_on, renewal_notice_days, cost_summary, main_conditions, document_reference, owner_id)
    values (v_dec.organization_id, p_decision, v_dec.proposal_id, v_provider, v_product,
      p_starts, p_ends, coalesce(p_notice,60), p_cost, p_conditions, p_reference, auth.uid())
    returning id into v_id;
  update public.fin_rfqs set status = 'contracted', updated_at = now()
    where id = v_dec.rfq_id and status = 'decided';
  v_review := p_ends - coalesce(p_notice,60);
  insert into public.fin_tasks (organization_id, title, due_on, related_type, related_id, created_by)
    values (v_dec.organization_id,
            'Revisar renovação do contrato antes do aviso prévio', v_review, 'contract', v_id, auth.uid());
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_dec.organization_id, 'contract', v_id, 'contract_registered', auth.uid(),
            jsonb_build_object('review_from', v_review));
  return v_id;
end $$;


ALTER FUNCTION public.fin_register_contract(p_decision uuid, p_starts date, p_ends date, p_notice integer, p_cost text, p_conditions text, p_reference text) OWNER TO postgres;

--
-- Name: fin_renewal_milestone_cycle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_renewal_milestone_cycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.cycle_ends_on is null then
    select c.ends_on into new.cycle_ends_on from public.fin_contracts c where c.id = new.contract_id;
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_renewal_milestone_cycle() OWNER TO postgres;

--
-- Name: fin_replay_webhook_delivery(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_replay_webhook_delivery(p_delivery uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_webhook_deliveries%rowtype; v_id uuid;
begin
  select * into d from public.fin_webhook_deliveries where id = p_delivery;
  if not found or not public.fin_has_role(d.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if d.status not in ('succeeded','failed','dead','cancelled') then raise exception 'delivery not replayable'; end if;
  if not exists (select 1 from public.fin_webhook_endpoints e where e.id = d.endpoint_id and e.status = 'active') then raise exception 'webhook disabled'; end if;
  insert into public.fin_webhook_deliveries(organization_id, endpoint_id, event_id, replay_of, requested_by_user)
    values (d.organization_id, d.endpoint_id, d.event_id, d.id, auth.uid()) returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (d.organization_id, 'webhook_endpoint', d.endpoint_id, 'webhook_delivery_replayed', auth.uid(), jsonb_build_object('delivery_id', v_id, 'replay_of', d.id));
  return v_id;
end $$;


ALTER FUNCTION public.fin_replay_webhook_delivery(p_delivery uuid) OWNER TO postgres;

--
-- Name: fin_reply_comment(uuid, text, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_reply_comment(p_parent uuid, p_body text, p_mention_ids uuid[] DEFAULT '{}'::uuid[], p_client_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_parent public.fin_comments%rowtype; v_id uuid; v_parent_now uuid;
begin
  select * into v_parent from public.fin_comments where id = p_parent;
  if not found or v_parent.parent_id is not null then raise exception 'invalid parent'; end if;
  if not (public.fin_has_role(v_parent.organization_id)
          or (v_parent.visibility = 'provider_visible'
              and public.fin_provider_reads_comment(v_parent.organization_id, v_parent.author_id, v_parent.object_type, v_parent.object_id))) then
    raise exception 'forbidden';
  end if;
  v_id := public.fin_add_comment(v_parent.object_type, v_parent.object_id, v_parent.visibility, p_body, p_mention_ids, p_client_id);
  update public.fin_comments set parent_id = p_parent where id = v_id and parent_id is null;
  select parent_id into v_parent_now from public.fin_comments where id = v_id;
  if v_parent_now is distinct from p_parent then raise exception 'comment conflict'; end if;
  if v_parent.author_id <> auth.uid()
     and exists (select 1 from public.fin_members m where m.organization_id = v_parent.organization_id and m.user_id = v_parent.author_id) then
    insert into public.fin_notifications(organization_id, user_id, event_type, object_type, object_id, event_id, title, body)
    values (v_parent.organization_id, v_parent.author_id, 'comment', v_parent.object_type, v_parent.object_id, v_id,
      'Responderam ao seu comentário', 'Abra o processo para ler a resposta.')
    on conflict (user_id, event_type, event_id) do nothing;
  end if;
  return v_id;
end $$;


ALTER FUNCTION public.fin_reply_comment(p_parent uuid, p_body text, p_mention_ids uuid[], p_client_id uuid) OWNER TO postgres;

--
-- Name: fin_request_approval(uuid, uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_request_approval(p_rfq uuid, p_proposal uuid, p_approvers uuid[], p_rationale text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_rfq public.fin_rfqs%rowtype; v_version integer; v_id uuid; v_actor uuid; v_position integer := 0; v_terms jsonb; v_eval jsonb;
begin
  select * into v_rfq from public.fin_rfqs where id = p_rfq for update;
  if not found then raise exception 'rfq not found'; end if;
  if not public.fin_has_role(v_rfq.organization_id,array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_rfq.status not in ('collecting','comparing') and not (v_rfq.status='open' and exists(select 1 from public.fin_external_proposals where id=p_proposal)) then raise exception 'invalid state'; end if;
  if coalesce(array_length(p_approvers,1),0) not between 1 and 5 or length(trim(coalesce(p_rationale,''))) not between 1 and 4000 then
    raise exception 'invalid approval request';
  end if;
  if exists(select 1 from public.fin_approval_requests where rfq_id = p_rfq and status = 'pending') then raise exception 'approval pending'; end if;
  select p.current_version,v.terms into v_version,v_terms
    from public.fin_decision_sources p join public.fin_decision_source_versions v on v.proposal_id=p.id and v.version=p.current_version
    where p.id=p_proposal and p.rfq_id=p_rfq and p.buyer_organization_id=v_rfq.organization_id and p.status in ('submitted','revised','reviewed');
  if v_version is null then raise exception 'proposal not eligible'; end if;
  v_eval := public.fin_policy_evaluate(p_rfq, p_proposal, '{}'::jsonb);
  if v_eval->>'engine' = 'policy' and (jsonb_array_length(v_eval->'stages') > 0 or jsonb_array_length(v_eval->'blockers') > 0) then
    raise exception 'policy assignment required';
  end if;
  foreach v_actor in array p_approvers loop
    if v_actor = auth.uid() or not exists(select 1 from public.fin_members m where m.organization_id=v_rfq.organization_id and m.user_id=v_actor and m.role in ('admin','finance_manager','analyst','viewer')) then
      raise exception 'invalid approver';
    end if;
    if p_approvers[1:v_position] @> array[v_actor] then raise exception 'duplicate approver'; end if;
    v_position := v_position+1;
  end loop;
  insert into public.fin_approval_requests(organization_id,rfq_id,proposal_id,proposal_version,rfq_updated_at,requested_by,rationale,snapshot)
    values(v_rfq.organization_id,p_rfq,p_proposal,v_version,v_rfq.updated_at,auth.uid(),trim(p_rationale),
      jsonb_build_object('proposal_version',v_version,'terms',v_terms,'rfq_demand',v_rfq.demand,'rfq_title',v_rfq.title,'deadline',v_rfq.response_deadline))
    returning id into v_id;
  for v_position in 1..array_length(p_approvers,1) loop
    insert into public.fin_approval_steps(request_id,position,approver_id) values(v_id,v_position,p_approvers[v_position]);
  end loop;
  insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
    values(v_rfq.organization_id,'rfq',p_rfq,'approval_requested',auth.uid(),jsonb_build_object('request_id',v_id,'steps',array_length(p_approvers,1),'version',v_version));
  return v_id;
end $$;


ALTER FUNCTION public.fin_request_approval(p_rfq uuid, p_proposal uuid, p_approvers uuid[], p_rationale text) OWNER TO postgres;

--
-- Name: fin_request_policy_approval(uuid, uuid, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_request_policy_approval(p_rfq uuid, p_proposal uuid, p_assignments jsonb, p_rationale text, p_justification text DEFAULT NULL::text, p_declared jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_rfq public.fin_rfqs%rowtype; v_version integer; v_terms jsonb; v_eval jsonb; s jsonb; v_people uuid[] := '{}'; v_user uuid; v_nominees jsonb;
  v_id uuid; v_stage uuid; v_position integer := 0; v_first integer; v_count integer; v_declared jsonb;
begin
  select * into v_rfq from public.fin_rfqs where id = p_rfq for update;
  if not found then raise exception 'rfq not found'; end if;
  if not public.fin_has_role(v_rfq.organization_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_rfq.status not in ('collecting','comparing') and not (v_rfq.status='open' and exists(select 1 from public.fin_external_proposals where id=p_proposal)) then raise exception 'invalid state'; end if;
  if length(trim(coalesce(p_rationale,''))) not between 1 and 4000 then raise exception 'invalid approval request'; end if;
  if jsonb_typeof(coalesce(p_assignments, 'null'::jsonb)) <> 'object' or jsonb_typeof(coalesce(p_declared, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid approval request';
  end if;
  if exists (select 1 from public.fin_approval_requests where rfq_id = p_rfq and status = 'pending') then raise exception 'approval pending'; end if;
  select p.current_version, v.terms into v_version, v_terms
    from public.fin_decision_sources p join public.fin_decision_source_versions v on v.proposal_id = p.id and v.version = p.current_version
   where p.id = p_proposal and p.rfq_id = p_rfq and p.buyer_organization_id = v_rfq.organization_id and p.status in ('submitted','revised','reviewed');
  if v_version is null then raise exception 'proposal not eligible'; end if;
  -- Só o que o engine lê fica gravado como declarado.
  v_declared := jsonb_strip_nulls(jsonb_build_object(
    'covenant_present', case when jsonb_typeof(p_declared->'covenant_present') = 'boolean' then p_declared->'covenant_present' end,
    'flags', case when jsonb_typeof(p_declared->'flags') = 'array' then p_declared->'flags' end));
  v_eval := public.fin_policy_evaluate(p_rfq, p_proposal, v_declared);
  -- Plano só com bloqueio (ex.: mínimo de propostas) também abre pedido: é nele
  -- que a exceção é pedida e decidida.
  if v_eval->>'engine' <> 'policy' or (jsonb_array_length(v_eval->'stages') = 0 and jsonb_array_length(v_eval->'blockers') = 0) then
    raise exception 'policy approval not applicable';
  end if;
  if jsonb_array_length(v_eval->'stages') > 8 then raise exception 'policy plan too large'; end if;
  if (v_eval->'requirements'->>'justification')::boolean and length(trim(coalesce(p_justification,''))) < 10 then
    raise exception 'policy justification required';
  end if;
  if exists (select 1 from jsonb_object_keys(p_assignments) k where not exists (select 1 from jsonb_array_elements(v_eval->'stages') x where x->>'key' = k)) then
    raise exception 'invalid approval request';
  end if;
  for s in select * from jsonb_array_elements(v_eval->'stages') loop
    v_nominees := p_assignments->(s->>'key');
    if jsonb_typeof(coalesce(v_nominees, 'null'::jsonb)) <> 'array' or jsonb_array_length(v_nominees) < (s->>'min_approvals')::integer
       or jsonb_array_length(v_nominees) > 5 then
      raise exception 'policy approvers required';
    end if;
    for v_user in select (x #>> '{}')::uuid from jsonb_array_elements(v_nominees) x loop
      -- SoD padrão: quem pede não aprova; ninguém ocupa duas etapas.
      if v_user = auth.uid() then raise exception 'invalid approver'; end if;
      if v_user = any(v_people) then raise exception 'duplicate approver'; end if;
      if not public.fin_approval_member_eligible(v_rfq.organization_id, v_rfq.legal_entity_id, v_user,
               array(select jsonb_array_elements_text(s->'roles')), s->>'scope') then
        raise exception 'policy approver ineligible';
      end if;
      v_people := v_people || v_user;
    end loop;
  end loop;
  insert into public.fin_approval_requests(organization_id, rfq_id, proposal_id, proposal_version, rfq_updated_at, requested_by, rationale, snapshot,
      policy_snapshot, policy_version_ids, evaluated_at, justification, declared_facts, expires_at)
    values (v_rfq.organization_id, p_rfq, p_proposal, v_version, v_rfq.updated_at, auth.uid(), trim(p_rationale),
      jsonb_build_object('proposal_version', v_version, 'terms', v_terms, 'rfq_demand', v_rfq.demand, 'rfq_title', v_rfq.title, 'deadline', v_rfq.response_deadline),
      v_eval, array(select (x->>'version_id')::uuid from jsonb_array_elements(v_eval->'policies') x),
      (v_eval->>'evaluated_at')::timestamptz, nullif(trim(coalesce(p_justification,'')),''), v_declared,
      case when jsonb_typeof(v_eval->'expire_after_hours') = 'number' then now() + make_interval(hours => (v_eval->>'expire_after_hours')::integer) end)
    returning id into v_id;
  v_first := (select min((x->>'sequence')::integer) from jsonb_array_elements(v_eval->'stages') x);
  for s in select * from jsonb_array_elements(v_eval->'stages') loop
    insert into public.fin_approval_stages(request_id, organization_id, stage_key, label, sequence, roles, scope, min_approvals, due_hours,
        allow_delegation, sources, status, opened_at, due_at)
      values (v_id, v_rfq.organization_id, s->>'key', s->>'label', (s->>'sequence')::integer, array(select jsonb_array_elements_text(s->'roles')),
        s->>'scope', (s->>'min_approvals')::integer, (s->>'due_hours')::integer, (s->>'allow_delegation')::boolean, s->'sources',
        case when (s->>'sequence')::integer = v_first then 'active' else 'pending' end,
        case when (s->>'sequence')::integer = v_first then now() end,
        case when (s->>'sequence')::integer = v_first and jsonb_typeof(s->'due_hours') = 'number' then now() + make_interval(hours => (s->>'due_hours')::integer) end)
      returning id into v_stage;
    for v_user in select (x #>> '{}')::uuid from jsonb_array_elements(p_assignments->(s->>'key')) x loop
      v_position := v_position + 1;
      insert into public.fin_approval_steps(request_id, position, approver_id, stage_id) values (v_id, v_position, v_user, v_stage);
    end loop;
  end loop;
  v_count := v_position;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_rfq.organization_id, 'rfq', p_rfq, 'approval_requested', auth.uid(), jsonb_build_object('request_id', v_id, 'steps', v_count, 'version', v_version,
      'engine', 'policy', 'stages', jsonb_array_length(v_eval->'stages'), 'policy_versions', jsonb_array_length(v_eval->'policies'),
      'rules', jsonb_array_length(v_eval->'matched'), 'blockers', jsonb_array_length(v_eval->'blockers')));
  return v_id;
end $$;


ALTER FUNCTION public.fin_request_policy_approval(p_rfq uuid, p_proposal uuid, p_assignments jsonb, p_rationale text, p_justification text, p_declared jsonb) OWNER TO postgres;

--
-- Name: fin_request_policy_exception(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_request_policy_exception(p_request uuid, p_policy_version uuid, p_rule text, p_reason_code text, p_reason text, p_evidence jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.fin_approval_requests%rowtype; v_id uuid; x jsonb;
begin
  select * into v_request from public.fin_approval_requests where id = p_request;
  if not found then raise exception 'approval not found'; end if;
  perform 1 from public.fin_rfqs where id = v_request.rfq_id for update;
  select * into v_request from public.fin_approval_requests where id = p_request for update;
  if not public.fin_has_role(v_request.organization_id, array['admin','finance_manager']) or not public.fin_rfq_visible(v_request.rfq_id) then raise exception 'forbidden'; end if;
  if v_request.status <> 'pending' or v_request.policy_snapshot is null then raise exception 'approval not pending'; end if;
  if not exists (select 1 from jsonb_array_elements(v_request.policy_snapshot->'matched') m
                  where m->>'policy_version_id' = p_policy_version::text and m->>'rule_id' = p_rule) then
    raise exception 'invalid policy exception';
  end if;
  if jsonb_typeof(coalesce(p_evidence, '[]'::jsonb)) <> 'array' then raise exception 'invalid policy exception'; end if;
  for x in select * from jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) loop
    if jsonb_typeof(x) <> 'object' or exists (select 1 from jsonb_object_keys(x) k where k not in ('label','document_id','reference'))
       or length(trim(coalesce(x->>'label',''))) not between 2 and 160
       or (x ? 'reference' and length(coalesce(x->>'reference','')) not between 3 and 300)
       or (x ? 'document_id' and not public.fin_policy_evidence_document_allowed(v_request.organization_id, x->>'document_id')) then
      raise exception 'invalid policy exception';
    end if;
  end loop;
  insert into public.fin_policy_exceptions(organization_id, request_id, policy_version_id, rule_id, requested_by, reason_code, reason, evidence)
    values (v_request.organization_id, p_request, p_policy_version, p_rule, auth.uid(), p_reason_code, trim(p_reason), coalesce(p_evidence, '[]'::jsonb))
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_request.organization_id, 'rfq', v_request.rfq_id, 'policy_exception_requested', auth.uid(),
            jsonb_build_object('request_id', p_request, 'exception_id', v_id, 'rule_id', p_rule, 'reason_code', p_reason_code));
  return v_id;
exception
  when unique_violation then raise exception 'policy exception already open';
  when check_violation then raise exception 'invalid policy exception';
end $$;


ALTER FUNCTION public.fin_request_policy_exception(p_request uuid, p_policy_version uuid, p_rule text, p_reason_code text, p_reason text, p_evidence jsonb) OWNER TO postgres;

--
-- Name: fin_request_qualification_exception(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_request_qualification_exception(p_qualification uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.fin_provider_qualifications%rowtype; r public.fin_qualification_requirements%rowtype; v_id uuid;
begin
  select * into q from public.fin_provider_qualifications where id = p_qualification for update;
  if q.id is null or auth.uid() is null or not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' then raise exception 'invalid qualification exception'; end if;
  select * into r from public.fin_qualification_applicable(q) a where a.id = (p_input->>'requirement_id')::uuid;
  if r.id is null or (p_input->>'expires_on')::date is null or (p_input->>'expires_on')::date <= current_date or (p_input->>'expires_on')::date > current_date + 366 then raise exception 'invalid qualification exception'; end if;
  if exists (select 1 from public.fin_qualification_exceptions x where x.qualification_id = q.id and x.requirement_id = r.id and x.status in ('requested','approved') and x.expires_on >= current_date) then raise exception 'qualification exception already open'; end if;
  begin
    insert into public.fin_qualification_exceptions(organization_id, qualification_id, requirement_id, reason, compensating_controls, expires_on, requested_by)
    values (q.organization_id, q.id, r.id, trim(p_input->>'reason'), nullif(trim(coalesce(p_input->>'compensating_controls', '')), ''), (p_input->>'expires_on')::date, auth.uid())
    returning id into v_id;
  exception when check_violation or not_null_violation or invalid_text_representation then raise exception 'invalid qualification exception';
  end;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, object_id, actor_id) values (q.organization_id, q.id, 'exception_requested', v_id, auth.uid());
  return v_id;
end $$;


ALTER FUNCTION public.fin_request_qualification_exception(p_qualification uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_request_session_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_request_session_guard() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_claims jsonb;
begin
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  exception when others then v_claims := null;
  end;
  -- Só JWT de usuário: anon (sem token) e service_role ficam como estão.
  if v_claims is null or coalesce(v_claims->>'role', '') <> 'authenticated' then return; end if;
  if not public.fin_current_session_alive() then
    raise sqlstate 'PGRST' using
      message = '{"code":"session_revoked","message":"Sessão encerrada. Entre de novo para continuar.","details":null,"hint":null}',
      detail = '{"status":401,"headers":{}}';
  end if;
end $$;


ALTER FUNCTION public.fin_request_session_guard() OWNER TO postgres;

--
-- Name: fin_require_operator(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_require_operator() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or public.fin_platform_role() <> 'finance_ops'
     or not exists (select 1 from public.fin_platform_operators o where o.user_id = auth.uid()) then
    raise exception 'forbidden';
  end if;
  if public.fin_jwt_aal() <> 'aal2' then raise exception 'mfa required'; end if;
end $$;


ALTER FUNCTION public.fin_require_operator() OWNER TO postgres;

--
-- Name: fin_resolve_provider_invite_token(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_resolve_provider_invite_token(p_invite uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_secret text; v_token text;
begin
  if current_setting('request.jwt.claim.role', true) <> 'service_role' then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_rfq_invites
    where id = p_invite and status = 'invited' and expires_at > now()) then
    raise exception 'invite unavailable';
  end if;
  select value into v_secret from public.fin_settings where key = 'invite_secret';
  if length(coalesce(v_secret,'')) < 64 then raise exception 'invite secret unavailable'; end if;
  v_token := encode(sha256(convert_to(v_secret || ':' || p_invite::text, 'UTF8')), 'hex');
  return v_token;
end $$;


ALTER FUNCTION public.fin_resolve_provider_invite_token(p_invite uuid) OWNER TO postgres;

--
-- Name: fin_retention_class_catalog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_retention_class_catalog() RETURNS TABLE(retention_class text, scope text, min_days integer, max_days integer, action text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  values ('TEMPORARY_OPERATIONAL','tenant',30,3650,'delete'),
         ('WEBHOOK_DELIVERY','tenant',30,3650,'delete'),
         ('SECURITY_EVENT','tenant',365,3650,'delete'),
         ('CONTACT_PII','tenant',30,3650,'anonymize'),
         ('PLATFORM_TELEMETRY','platform',30,3650,'delete'),
         ('PLATFORM_SECURITY_TRAIL','platform',365,3650,'delete');
$$;


ALTER FUNCTION public.fin_retention_class_catalog() OWNER TO postgres;

--
-- Name: fin_retire_policy(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_retire_policy(p_policy uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.fin_policies%rowtype; v_version uuid;
begin
  select * into p from public.fin_policies where id = p_policy for update;
  if not found or not public.fin_has_role(p.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if p.status = 'retired' then return; end if;
  update public.fin_policy_versions set status = 'retired', ended_at = now() where policy_id = p_policy and status = 'active' returning id into v_version;
  update public.fin_policies set status = 'retired', retired_at = now() where id = p_policy;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p.organization_id, 'organization', p.organization_id, 'policy_retired', auth.uid(),
            jsonb_build_object('policy_id', p.id, 'version_id', v_version), p.legal_entity_id);
end $$;


ALTER FUNCTION public.fin_retire_policy(p_policy uuid) OWNER TO postgres;

--
-- Name: fin_retire_qualification_requirement(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_retire_qualification_requirement(p_requirement uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.fin_qualification_requirements%rowtype;
begin
  select * into r from public.fin_qualification_requirements where id = p_requirement for update;
  if r.id is null or auth.uid() is null or not public.fin_has_role(r.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if r.status <> 'active' then raise exception 'invalid qualification requirement'; end if;
  update public.fin_qualification_requirements set status = 'retired', retired_at = now() where id = r.id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (r.organization_id, 'qualification_requirement', r.id, 'qualification_requirement_retired', auth.uid(), '{}'::jsonb);
end $$;


ALTER FUNCTION public.fin_retire_qualification_requirement(p_requirement uuid) OWNER TO postgres;

--
-- Name: fin_review_extraction_fact(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_review_extraction_fact(p_fact uuid, p_expected text, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare f public.fin_extraction_facts%rowtype; d public.fin_private_documents%rowtype; v_action text := p_input->>'action'; v_reason text := nullif(trim(coalesce(p_input->>'reason', '')), ''); v_new uuid; v_to text;
begin
  select * into f from public.fin_extraction_facts where id = p_fact for update;
  if f.id is null or auth.uid() is null or not public.fin_has_role(f.organization_id, array['admin','finance_manager','analyst'])
     or not exists (select 1 from public.fin_document_extractions x where x.id = f.extraction_id and public.fin_can_read_document(x.document_id)) then raise exception 'forbidden'; end if;
  if f.criticality = 'critical' and v_action in ('confirm','correct') and not public.fin_has_role(f.organization_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(f.organization_id) then raise exception 'organization offboarding'; end if;
  if p_expected is distinct from f.status or f.status not in ('extracted','needs_review') then raise exception 'extraction review conflict'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or v_action is null or v_action not in ('confirm','reject','correct')
     or (v_action <> 'confirm' and (v_reason is null or length(v_reason) not between 3 and 1000 or v_reason ~ '[<>]'))
     or (v_action = 'confirm' and f.value_state <> 'present') then raise exception 'invalid extraction review'; end if;
  if v_action = 'correct' then
    if p_input->>'value_state' is null or (p_input->>'value_state' = 'present' and jsonb_typeof(p_input->'normalized_value') is null) then raise exception 'invalid extraction review'; end if;
    begin
      insert into public.fin_extraction_facts(organization_id, extraction_id, document_id, document_version, schema_key, field_key, page, locator, raw_value, normalized_value, value_state, unit, currency, confidence, method, parser_version, criticality, status, confirmed_by, confirmed_at, supersedes, created_by)
      values (f.organization_id, f.extraction_id, f.document_id, f.document_version, f.schema_key, f.field_key, f.page, f.locator,
        left(coalesce(p_input->>'raw_value', f.raw_value), 2000), case when p_input->>'value_state' = 'present' then p_input->'normalized_value' end, p_input->>'value_state',
        nullif(p_input->>'unit', ''), nullif(p_input->>'currency', ''), 1, 'manual_entry', 'human-correction-1', f.criticality, 'confirmed', auth.uid(), now(), f.id, auth.uid())
      returning id into v_new;
    exception when check_violation or not_null_violation or invalid_text_representation then raise exception 'invalid extraction review';
    end;
    v_to := 'superseded';
    update public.fin_extraction_facts set status = 'superseded' where id = f.id;
  elsif v_action = 'confirm' then
    v_to := 'confirmed';
    update public.fin_extraction_facts set status = 'confirmed', confirmed_by = auth.uid(), confirmed_at = now() where id = f.id;
  else
    v_to := 'rejected';
    update public.fin_extraction_facts set status = 'rejected', rejection_reason = v_reason where id = f.id;
  end if;
  insert into public.fin_extraction_reviews(organization_id, fact_id, from_status, to_status, action, reason, replacement_fact_id, actor_id)
  values (f.organization_id, f.id, f.status, v_to, v_action, v_reason, v_new, auth.uid());
  select * into d from public.fin_private_documents where id = f.document_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (f.organization_id, d.entity_type, d.entity_id, 'extraction_fact_' || v_to, auth.uid(), jsonb_build_object('fact_id', f.id, 'document_id', d.id, 'field', f.field_key, 'replacement', v_new));
  return coalesce(v_new, f.id);
end $$;


ALTER FUNCTION public.fin_review_extraction_fact(p_fact uuid, p_expected text, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_review_fee_variance(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_review_fee_variance(p_variance uuid, p_expected text, p_input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_fee_variances%rowtype; v_to text := p_input->>'to_status';
begin
  select * into v from public.fin_fee_variances where id = p_variance for update;
  if v.id is null or auth.uid() is null or not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager'])
     or not exists (select 1 from public.fin_contracts c where c.organization_id = v.organization_id and c.id = v.contract_id and public.fin_entity_allows(c.organization_id, c.legal_entity_id, array['admin','finance_manager'])) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(v.organization_id) then raise exception 'organization offboarding'; end if;
  if p_expected is distinct from v.review_status then raise exception 'fee review conflict'; end if;
  if not ((v.review_status = 'new' and v_to in ('under_review','dismissed'))
       or (v.review_status = 'under_review' and v_to in ('confirmed','explained','dismissed'))
       or (v.review_status in ('confirmed','explained') and v_to = 'resolved')) then raise exception 'invalid fee review transition'; end if;
  if v_to = 'confirmed' and v.comparison_status <> 'comparable' then raise exception 'invalid fee review transition'; end if;
  begin
    insert into public.fin_fee_reviews(organization_id, variance_id, from_status, to_status, reason_code, notes, evidence_reference, resolution, reviewer_id)
    values (v.organization_id, v.id, v.review_status, v_to, p_input->>'reason_code', trim(p_input->>'notes'),
      nullif(trim(coalesce(p_input->>'evidence_reference', '')), ''), nullif(trim(coalesce(p_input->>'resolution', '')), ''), auth.uid());
  exception when check_violation or not_null_violation then raise exception 'invalid fee review';
  end;
  update public.fin_fee_variances set review_status = v_to, reviewer_id = auth.uid(), last_reviewed_at = now() where id = v.id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v.organization_id, 'contract', v.contract_id, case when v_to = 'resolved' then 'fee_variance_resolved' else 'fee_variance_reviewed' end, auth.uid(),
      jsonb_build_object('variance_id', v.id, 'from', v.review_status, 'to', v_to, 'reason_code', p_input->>'reason_code'));
  return v_to;
end $$;


ALTER FUNCTION public.fin_review_fee_variance(p_variance uuid, p_expected text, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_review_obligation(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_review_obligation(p_period uuid, p_expected uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_obligations%rowtype;r public.fin_obligation_reviews%rowtype;m public.fin_covenant_measurements%rowtype;e public.fin_obligation_evidence%rowtype;c public.fin_covenants%rowtype;v_ok boolean;v_status text;v_id uuid;begin
 o:=public.fin_obligation_require(p_period,array['admin','finance_manager']);
 select * into r from public.fin_obligation_reviews where period_id=p_period order by reviewed_at desc,id desc limit 1;
 if r.id is distinct from p_expected then raise exception 'obligation conflict';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('status','reason','measurement_id','evidence_id')) then raise exception 'invalid obligation input';end if;
 v_status:=p_input->>'status';
 if v_status in ('compliant','non_compliant') then
 if o.kind='financial_covenant' then
 select * into m from public.fin_covenant_measurements where id=nullif(p_input->>'measurement_id','')::uuid and period_id=p_period;
 select * into c from public.fin_covenants where obligation_id=o.id;
 if m.id is null then raise exception 'obligation data missing';end if;
 if m.recorded_by=auth.uid() then raise exception 'obligation independent reviewer required';end if;
 if m.id<>(select id from public.fin_covenant_measurements where period_id=p_period order by recorded_at desc,id desc limit 1) then raise exception 'obligation stale data';end if;
 v_ok:=case c.operator when 'lt' then m.measured_value<c.threshold when 'le' then m.measured_value<=c.threshold when 'eq' then m.measured_value=c.threshold when 'ge' then m.measured_value>=c.threshold when 'gt' then m.measured_value>c.threshold end;
 if (v_status='compliant') is distinct from v_ok then raise exception 'obligation factual result mismatch';end if;
 else
 select * into e from public.fin_obligation_evidence where id=nullif(p_input->>'evidence_id','')::uuid and period_id=p_period;
 if e.id is null then raise exception 'obligation data missing';end if;
 if e.recorded_by=auth.uid() then raise exception 'obligation independent reviewer required';end if;
 if e.id<>(select id from public.fin_obligation_evidence where period_id=p_period order by recorded_at desc,id desc limit 1) then raise exception 'obligation stale data';end if;
 end if;
 end if;
 insert into public.fin_obligation_reviews(organization_id,period_id,status,measurement_id,evidence_id,reason,reviewed_by) values(o.organization_id,p_period,v_status,m.id,e.id,trim(p_input->>'reason'),auth.uid()) returning id into v_id;
 update public.fin_tasks set status=case when v_status in ('compliant','not_applicable') then 'done' else 'open' end where id=(select task_id from public.fin_obligation_periods where id=p_period);
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(o.organization_id,'contract',o.contract_id,'obligation_reviewed',auth.uid(),o.legal_entity_id,jsonb_build_object('period_id',p_period,'review_id',v_id,'status',v_status));return v_id;
end $$;


ALTER FUNCTION public.fin_review_obligation(p_period uuid, p_expected uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_review_performance(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_review_performance(p_observation uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_provider_performance_observations%rowtype;p public.fin_provider_performance_periods%rowtype;v_id uuid;begin
 select * into o from public.fin_provider_performance_observations where id=p_observation;
 p:=public.fin_performance_require(o.period_id,array['admin','finance_manager']);
 if o.recorded_by=auth.uid() then raise exception 'performance independent review required';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('status','reason')) then raise exception 'invalid performance review';end if;
 if exists(select 1 from public.fin_provider_performance_observations where period_id=p.id and dimension_id=o.dimension_id and revision>o.revision) or exists(select 1 from public.fin_provider_performance_reviews where observation_id=o.id) then raise exception 'performance conflict';end if;
 if (p_input->>'status'='not_available')<>(o.availability='not_available') and p_input->>'status'<>'rejected' then raise exception 'invalid performance review';end if;
 insert into public.fin_provider_performance_reviews(organization_id,period_id,observation_id,status,reason,reviewed_by) values(p.organization_id,p.id,o.id,p_input->>'status',trim(p_input->>'reason'),auth.uid()) returning id into v_id;
 update public.fin_provider_performance_periods set version=version+1 where id=p.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'performance_reviewed',auth.uid(),p.legal_entity_id,jsonb_build_object('period_id',p.id,'review_id',v_id,'status',p_input->>'status'));return v_id;
end $$;


ALTER FUNCTION public.fin_review_performance(p_observation uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_review_qualification_evidence(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_review_qualification_evidence(p_evidence uuid, p_input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.fin_qualification_evidence%rowtype; q public.fin_provider_qualifications%rowtype; v_status text := p_input->>'status'; v_reason text := nullif(trim(coalesce(p_input->>'reason', '')), '');
begin
  select * into e from public.fin_qualification_evidence where id = p_evidence for update;
  select * into q from public.fin_provider_qualifications where id = e.qualification_id;
  if e.id is null or auth.uid() is null or not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if e.status <> 'submitted' then raise exception 'qualification evidence conflict'; end if;
  -- Quem registrou a evidência não a aceita sozinho.
  if v_status = 'accepted' and e.created_by = auth.uid() then raise exception 'segregation of duties'; end if;
  if v_status is null or v_status not in ('accepted','rejected') or (v_status = 'rejected' and (v_reason is null or length(v_reason) not between 3 and 1000 or v_reason ~ '[<>]')) then raise exception 'invalid qualification evidence review'; end if;
  update public.fin_qualification_evidence set status = v_status, reviewed_by = auth.uid(), reviewed_at = now(), review_reason = v_reason where id = e.id;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, to_status, reason, object_id, actor_id) values (q.organization_id, q.id, 'evidence_reviewed', v_status, v_reason, e.id, auth.uid());
end $$;


ALTER FUNCTION public.fin_review_qualification_evidence(p_evidence uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_revise_rfq(uuid, integer, text, text, jsonb, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_revise_rfq(p_rfq uuid, p_expected integer, p_title text, p_description text, p_demand jsonb, p_deadline date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_rfq public.fin_rfqs%rowtype;v_revision integer;
begin
 select * into v_rfq from public.fin_rfqs where id=p_rfq for update;
 if not found then raise exception 'not found'; end if;
 if not public.fin_has_role(v_rfq.organization_id,array['admin','finance_manager']) then raise exception 'forbidden'; end if;
 if v_rfq.status not in ('draft','open','collecting') then raise exception 'invalid state'; end if;
 if p_expected is distinct from v_rfq.revision then raise exception 'rfq revision conflict'; end if;
 if length(trim(coalesce(p_title,''))) not between 3 and 200
 or jsonb_typeof(p_demand)<>'object' then raise exception 'invalid demand'; end if;
 update public.fin_rfqs set title=trim(p_title),description=p_description,demand=p_demand,
   response_deadline=p_deadline,updated_at=now() where id=p_rfq returning revision into v_revision;
 -- Mantém o rastro de auditoria da edição legada: mudança após abertura é nomeada.
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(v_rfq.organization_id,'rfq',p_rfq,
  case when v_rfq.status='draft' then 'rfq_demand_updated' else 'rfq_demand_updated_after_open' end,
  auth.uid(),jsonb_build_object('status',v_rfq.status,'revision',v_revision));
 return v_revision;
end $$;


ALTER FUNCTION public.fin_revise_rfq(p_rfq uuid, p_expected integer, p_title text, p_description text, p_demand jsonb, p_deadline date) OWNER TO postgres;

--
-- Name: fin_revoke_api_credential(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_revoke_api_credential(p_credential uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_api_credentials%rowtype;
begin
  select * into c from public.fin_api_credentials where id = p_credential for update;
  if not found or not public.fin_has_role(c.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if c.revoked_at is not null then return; end if;
  update public.fin_api_credentials set revoked_at = now(), revoked_by = auth.uid() where id = p_credential;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'service_account', c.service_account_id, 'api_credential_revoked', auth.uid(), jsonb_build_object('credential_id', c.id, 'prefix', c.token_prefix));
end $$;


ALTER FUNCTION public.fin_revoke_api_credential(p_credential uuid) OWNER TO postgres;

--
-- Name: fin_revoke_approval_delegation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_revoke_approval_delegation(p_delegation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_approval_delegations%rowtype;
begin
  select * into d from public.fin_approval_delegations where id = p_delegation for update;
  if not found or not (d.delegator_id = auth.uid() or public.fin_has_role(d.organization_id, array['admin'])) or not public.fin_has_role(d.organization_id) then
    raise exception 'forbidden';
  end if;
  if d.revoked_at is not null then return; end if;
  update public.fin_approval_delegations set revoked_at = now(), revoked_by = auth.uid() where id = p_delegation;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (d.organization_id, 'organization', d.organization_id, 'approval_delegation_revoked', auth.uid(), jsonb_build_object('delegation_id', d.id));
end $$;


ALTER FUNCTION public.fin_revoke_approval_delegation(p_delegation uuid) OWNER TO postgres;

--
-- Name: fin_revoke_service_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_revoke_service_account(p_account uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.fin_service_accounts%rowtype;
begin
  select * into a from public.fin_service_accounts where id = p_account for update;
  if not found or not public.fin_has_role(a.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if a.status = 'revoked' then return; end if;
  update public.fin_service_accounts set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), updated_at = now() where id = p_account;
  update public.fin_api_credentials set revoked_at = now(), revoked_by = auth.uid() where service_account_id = p_account and revoked_at is null;
  update public.fin_webhook_endpoints set status = 'disabled', disabled_at = now(), disabled_reason = 'service_account_revoked', updated_at = now()
   where created_by_service_account = p_account and status = 'active';
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (a.organization_id, 'service_account', p_account, 'service_account_revoked', auth.uid(), '{}'::jsonb);
end $$;


ALTER FUNCTION public.fin_revoke_service_account(p_account uuid) OWNER TO postgres;

--
-- Name: fin_rfq_child_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_rfq_child_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_entity uuid;
begin
  select r.organization_id, r.legal_entity_id into v_org, v_entity from public.fin_rfqs r where r.id = new.rfq_id;
  if v_org is not null then perform public.fin_assert_entity_write(v_org, v_entity); end if;
  return new;
end $$;


ALTER FUNCTION public.fin_rfq_child_entity_guard() OWNER TO postgres;

--
-- Name: fin_rfq_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_rfq_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_setting text;
begin
  if tg_op = 'INSERT' then
    if new.legal_entity_id is null then
      v_setting := nullif(current_setting('arandu.legal_entity', true), '');
      if v_setting is not null then new.legal_entity_id := v_setting::uuid; end if;
    end if;
    if new.legal_entity_id is not null and not exists (
      select 1 from public.fin_legal_entities e where e.organization_id = new.organization_id and e.id = new.legal_entity_id and e.status = 'active') then
      raise exception 'invalid legal entity';
    end if;
    perform public.fin_assert_entity_write(new.organization_id, new.legal_entity_id);
  else
    perform public.fin_assert_entity_write(old.organization_id, old.legal_entity_id);
    if new.legal_entity_id is distinct from old.legal_entity_id then
      if coalesce(current_setting('arandu.entity_change', true), '') <> 'on' then raise exception 'legal entity change requires rpc'; end if;
      perform public.fin_assert_entity_write(new.organization_id, new.legal_entity_id);
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_rfq_entity_guard() OWNER TO postgres;

--
-- Name: fin_rfq_request_receipt(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_rfq_request_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_actor uuid := auth.uid(); v_key text;
begin
  v_key := coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb) ->> 'x-arandu-request-key';
  if v_key is null or v_actor is null then return null; end if;
  if v_key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid request key'; end if;
  delete from public.fin_request_receipts where actor_id = v_actor and created_at < now() - interval '24 hours';
  -- Concorrência: a segunda transação com a mesma chave espera a primeira e,
  -- se ela confirmou, cai aqui; se ela desfez, esta segue normalmente.
  insert into public.fin_request_receipts(actor_id, request_key, operation, organization_id, rfq_id)
    values (v_actor, v_key::uuid, 'rfq_create', new.organization_id, new.id)
    on conflict (actor_id, request_key) do nothing;
  if not found then raise exception 'duplicate request'; end if;
  return null;
end $_$;


ALTER FUNCTION public.fin_rfq_request_receipt() OWNER TO postgres;

--
-- Name: fin_rfq_visible(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_rfq_visible(p_rfq uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.fin_rfqs r where r.id = p_rfq and public.fin_entity_visible(r.organization_id, r.legal_entity_id));
$$;


