--
-- Name: fin_run_qualification_expiry(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_run_qualification_expiry(p_today date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q record; v_expired integer := 0; v_ev integer := 0; v_tasks integer := 0; v_title text;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  update public.fin_qualification_evidence set status = 'expired' where status = 'accepted' and valid_until < p_today;
  get diagnostics v_ev = row_count;
  update public.fin_qualification_exceptions set status = 'expired' where status = 'approved' and expires_on < p_today;
  for q in select * from public.fin_provider_qualifications where status in ('qualified','qualified_with_conditions') and valid_until < p_today for update loop
    update public.fin_provider_qualifications set status = 'expired', updated_at = now() where id = q.id;
    insert into public.fin_qualification_events(organization_id, qualification_id, event_type, from_status, to_status, reason) values (q.organization_id, q.id, 'expired', q.status, 'expired', 'validade encerrada em ' || q.valid_until);
    v_expired := v_expired + 1;
  end loop;
  for q in select x.*, p.name as provider_name from public.fin_provider_qualifications x join public.fin_providers p on p.organization_id = x.organization_id and p.id = x.provider_id
            where x.status in ('qualified','qualified_with_conditions') and x.valid_until between p_today and p_today + 30 loop
    v_title := left('Revalidar qualificação: ' || q.provider_name || ' (' || q.category || ')', 200);
    if not exists (select 1 from public.fin_tasks where organization_id = q.organization_id and title = v_title and status = 'open') then
      insert into public.fin_tasks(organization_id, title, due_on, status, created_by) values (q.organization_id, v_title, q.valid_until, 'open', q.owner_id);
      v_tasks := v_tasks + 1;
    end if;
  end loop;
  return jsonb_build_object('qualifications_expired', v_expired, 'evidence_expired', v_ev, 'tasks_created', v_tasks);
end $$;


ALTER FUNCTION public.fin_run_qualification_expiry(p_today date) OWNER TO postgres;

--
-- Name: fin_run_renewal_schedule(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_run_renewal_schedule(p_day date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c record; v_days integer; v_mark text; v_task uuid; v_created integer := 0; v_milestone uuid; v_new boolean;
begin
  if p_day is null or abs(p_day - current_date) > 1 then raise exception 'invalid date'; end if;
  if not pg_try_advisory_xact_lock(hashtext('fin_run_renewal_schedule')) then raise exception using errcode='55P03', message='job busy'; end if;
  for c in select id, organization_id, owner_id, ends_on, renewal_notice_days, status from public.fin_contracts ct
    where status in ('active','renewing') and ends_on <= p_day + greatest(90, renewal_notice_days)
    and not exists (select 1 from public.fin_renewal_milestones rm where rm.contract_id=ct.id and rm.cycle_ends_on=ct.ends_on and rm.milestone =
      case when ct.ends_on <= p_day then 'expired' else
        (select m.mark from (values ('notice',ct.renewal_notice_days,0),('d30',30,1),('d60',60,1),('d90',90,1)) m(mark,threshold,tiebreak)
          where ct.ends_on-p_day <= m.threshold order by m.threshold,m.tiebreak limit 1) end)
    order by ends_on, id limit 100 for update skip locked
  loop
    v_days := c.ends_on - p_day;
    v_mark := null;
    if v_days <= 0 then v_mark := 'expired';
    else
      -- O menor limite já alcançado é o marco atual; empate favorece o aviso prévio.
      select m.mark into v_mark from (values ('notice', c.renewal_notice_days, 0), ('d30', 30, 1), ('d60', 60, 1), ('d90', 90, 1))
        as m(mark, threshold, tiebreak) where v_days <= m.threshold order by m.threshold, m.tiebreak limit 1;
    end if;
    if v_mark is null then continue; end if;
    if exists (select 1 from public.fin_renewal_milestones where contract_id = c.id and cycle_ends_on = c.ends_on and milestone = v_mark) then continue; end if;
    select id into v_task from public.fin_tasks where organization_id = c.organization_id and related_type = 'contract'
      and related_id = c.id and status = 'open' order by created_at limit 1;
    v_new := v_task is null;
    if v_new then
      insert into public.fin_tasks(organization_id, title, due_on, status, related_type, related_id, created_by)
      values (c.organization_id, case when v_days <= 0 then 'Revisar contrato vencido' else 'Revisar renovação de contrato' end,
        least(c.ends_on - c.renewal_notice_days, c.ends_on), 'open', 'contract', c.id, c.owner_id)
      returning id into v_task;
    end if;
    insert into public.fin_renewal_milestones(organization_id, contract_id, milestone, task_id, cycle_ends_on)
    values (c.organization_id, c.id, v_mark, v_task, c.ends_on) on conflict (contract_id, cycle_ends_on, milestone) do nothing
    returning id into v_milestone;
    if v_milestone is null then
      if v_new then delete from public.fin_tasks where id = v_task; end if;
      continue;
    end if;
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'contract', c.id, 'renewal_milestone_reached', null,
      jsonb_build_object('milestone', v_mark, 'task_id', v_task, 'scheduled', true));
    -- Um aviso por marco novo (chave = marco), com ou sem tarefa nova: o contrato
    -- registrado pelo produto já nasce com a tarefa de revisão aberta.
    insert into public.fin_notifications(organization_id, user_id, event_type, object_type, object_id, event_id, title, body)
    values (c.organization_id, c.owner_id, 'renewal_due', 'contract', c.id, v_milestone, 'Contrato em revisão de renovação',
      case v_mark when 'expired' then 'O contrato chegou ao fim. Registre a decisão de renovação.'
                  when 'notice' then 'O prazo de aviso prévio do contrato chegou.'
                  else 'Faltam ' || substr(v_mark, 2) || ' dias para o fim do contrato.' end)
    on conflict (user_id, event_type, event_id) do nothing;
    if v_new then v_created := v_created + 1; end if;
    if v_days <= c.renewal_notice_days and c.status = 'active' then
      update public.fin_contracts set status = 'renewing', updated_at = now() where id = c.id;
    end if;
  end loop;
  return v_created;
end $$;


ALTER FUNCTION public.fin_run_renewal_schedule(p_day date) OWNER TO postgres;

--
-- Name: fin_save_facility(uuid, uuid, uuid, uuid, text, text, text, numeric, numeric, text, numeric, numeric, text, date, date, text, uuid, text, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_save_facility(p_org uuid, p_facility uuid, p_entity uuid, p_provider uuid, p_kind text, p_name text, p_currency text, p_approved_limit numeric DEFAULT NULL::numeric, p_principal numeric DEFAULT NULL::numeric, p_indexer text DEFAULT NULL::text, p_spread numeric DEFAULT NULL::numeric, p_rate numeric DEFAULT NULL::numeric, p_amortization text DEFAULT NULL::text, p_starts date DEFAULT NULL::date, p_maturity date DEFAULT NULL::date, p_status text DEFAULT 'active'::text, p_contract uuid DEFAULT NULL::uuid, p_source text DEFAULT 'declared'::text, p_source_reference text DEFAULT NULL::text, p_review_days integer DEFAULT 90, p_notes text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid := p_facility; v public.fin_facilities%rowtype;
begin
  perform public.fin_assert_portfolio_write(p_org, p_entity);
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_contract is not null and not exists (select 1 from public.fin_contracts c where c.organization_id = p_org and c.id = p_contract
       and c.legal_entity_id is not distinct from p_entity and public.fin_entity_visible(p_org, c.legal_entity_id)) then
    raise exception 'contract not found';
  end if;
  if p_owner is not null and not exists (select 1 from public.fin_members m where m.organization_id = p_org and m.user_id = p_owner) then raise exception 'invalid owner'; end if;
  if p_facility is null then
    insert into public.fin_facilities(organization_id, legal_entity_id, provider_id, contract_id, kind, name, currency, approved_limit, principal_amount,
        indexer, spread_pct_year, rate_pct_year, amortization, starts_on, maturity_on, status, owner_id, source, source_reference,
        verified_at, review_after_days, notes, created_by)
      values (p_org, p_entity, p_provider, p_contract, p_kind, trim(p_name), upper(coalesce(p_currency,'BRL')), p_approved_limit, p_principal,
        p_indexer, p_spread, p_rate, p_amortization, p_starts, p_maturity, coalesce(p_status,'active'), coalesce(p_owner, auth.uid()), coalesce(p_source,'declared'),
        nullif(trim(coalesce(p_source_reference,'')),''), now(), coalesce(p_review_days, 90), nullif(trim(coalesce(p_notes,'')),''), auth.uid())
      returning id into v_id;
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
      values (p_org, 'facility', v_id, 'facility_created', auth.uid(), jsonb_build_object('kind', p_kind, 'source', p_source), p_entity);
  else
    select * into v from public.fin_facilities where id = p_facility and organization_id = p_org for update;
    if not found or not public.fin_entity_allows(p_org, v.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'facility not found'; end if;
    update public.fin_facilities set legal_entity_id = p_entity, provider_id = p_provider, contract_id = p_contract, kind = p_kind, name = trim(p_name),
        currency = upper(coalesce(p_currency, currency)), approved_limit = p_approved_limit, principal_amount = p_principal, indexer = p_indexer,
        spread_pct_year = p_spread, rate_pct_year = p_rate, amortization = p_amortization, starts_on = p_starts, maturity_on = p_maturity,
        status = coalesce(p_status, status), owner_id = coalesce(p_owner, owner_id), source = coalesce(p_source, source),
        source_reference = nullif(trim(coalesce(p_source_reference,'')),''), verified_at = now(), review_after_days = coalesce(p_review_days, review_after_days),
        notes = nullif(trim(coalesce(p_notes,'')),''), updated_at = now()
     where id = p_facility;
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
      values (p_org, 'facility', p_facility, 'facility_updated', auth.uid(), jsonb_build_object('source', p_source), p_entity);
  end if;
  return v_id;
exception when check_violation then raise exception 'invalid facility';
end $$;


ALTER FUNCTION public.fin_save_facility(p_org uuid, p_facility uuid, p_entity uuid, p_provider uuid, p_kind text, p_name text, p_currency text, p_approved_limit numeric, p_principal numeric, p_indexer text, p_spread numeric, p_rate numeric, p_amortization text, p_starts date, p_maturity date, p_status text, p_contract uuid, p_source text, p_source_reference text, p_review_days integer, p_notes text, p_owner uuid) OWNER TO postgres;

--
-- Name: fin_save_guarantee(uuid, uuid, uuid, text, text, text, numeric, uuid, uuid, uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_save_guarantee(p_org uuid, p_guarantee uuid, p_entity uuid, p_kind text, p_description text, p_currency text, p_committed numeric DEFAULT NULL::numeric, p_facility uuid DEFAULT NULL::uuid, p_contract uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid, p_starts date DEFAULT NULL::date, p_ends date DEFAULT NULL::date, p_status text DEFAULT 'active'::text, p_source text DEFAULT 'declared'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid := p_guarantee; v public.fin_guarantees%rowtype;
begin
  perform public.fin_assert_portfolio_write(p_org, p_entity);
  if p_facility is not null and not exists (select 1 from public.fin_facilities f where f.organization_id = p_org and f.id = p_facility and f.legal_entity_id is not distinct from p_entity) then
    raise exception 'facility not found';
  end if;
  if p_contract is not null and not exists (select 1 from public.fin_contracts c where c.organization_id = p_org and c.id = p_contract and c.legal_entity_id is not distinct from p_entity) then
    raise exception 'contract not found';
  end if;
  if p_provider is not null and not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_guarantee is null then
    insert into public.fin_guarantees(organization_id, legal_entity_id, facility_id, contract_id, provider_id, kind, description, currency,
        committed_amount, starts_on, ends_on, status, source, created_by)
      values (p_org, p_entity, p_facility, p_contract, p_provider, p_kind, trim(p_description), upper(coalesce(p_currency,'BRL')),
        p_committed, p_starts, p_ends, coalesce(p_status,'active'), coalesce(p_source,'declared'), auth.uid())
      returning id into v_id;
  else
    select * into v from public.fin_guarantees where id = p_guarantee and organization_id = p_org for update;
    if not found or not public.fin_entity_allows(p_org, v.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'guarantee not found'; end if;
    update public.fin_guarantees set legal_entity_id = p_entity, facility_id = p_facility, contract_id = p_contract, provider_id = p_provider, kind = p_kind,
        description = trim(p_description), currency = upper(coalesce(p_currency, currency)), committed_amount = p_committed, starts_on = p_starts, ends_on = p_ends,
        status = coalesce(p_status, status), source = coalesce(p_source, source), updated_at = now()
     where id = p_guarantee;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'guarantee', v_id, case when p_guarantee is null then 'guarantee_created' else 'guarantee_updated' end, auth.uid(),
      jsonb_build_object('kind', p_kind, 'status', p_status), p_entity);
  return v_id;
exception when check_violation then raise exception 'invalid guarantee';
end $$;


ALTER FUNCTION public.fin_save_guarantee(p_org uuid, p_guarantee uuid, p_entity uuid, p_kind text, p_description text, p_currency text, p_committed numeric, p_facility uuid, p_contract uuid, p_provider uuid, p_starts date, p_ends date, p_status text, p_source text) OWNER TO postgres;

--
-- Name: fin_save_policy_draft(uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_save_policy_draft(p_org uuid, p_entity uuid, p_name text, p_document jsonb, p_change_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_policy uuid; v_version uuid; v_next integer; v_bad text;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'forbidden'; end if;
  if p_entity is not null and not exists (select 1 from public.fin_legal_entities e where e.organization_id = p_org and e.id = p_entity and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  if length(trim(coalesce(p_name,''))) not between 2 and 160 or p_name ~ '[<>]' then raise exception 'invalid policy'; end if;
  if p_document is null or not public.fin_policy_valid_document(p_document) then raise exception 'invalid policy'; end if;
  -- Entidades citadas nas condições precisam ser do próprio grupo.
  select x #>> '{}' into v_bad from jsonb_array_elements(p_document->'rules') r, jsonb_array_elements(coalesce(r->'when','[]'::jsonb)) c,
         jsonb_array_elements(case when c->>'fact' = 'legal_entity' then c->'value' else '[]'::jsonb end) x
   where not exists (select 1 from public.fin_legal_entities e where e.organization_id = p_org and e.id::text = x #>> '{}')
   limit 1;
  if v_bad is not null then raise exception 'invalid policy'; end if;
  select id into v_policy from public.fin_policies where organization_id = p_org and legal_entity_id is not distinct from p_entity for update;
  if v_policy is null then
    insert into public.fin_policies(organization_id, legal_entity_id, name, created_by) values (p_org, p_entity, trim(p_name), auth.uid())
      returning id into v_policy;
  else
    update public.fin_policies set name = trim(p_name) where id = v_policy and name is distinct from trim(p_name);
  end if;
  select id into v_version from public.fin_policy_versions where policy_id = v_policy and status = 'draft' for update;
  if v_version is null then
    select coalesce(max(version), 0) + 1 into v_next from public.fin_policy_versions where policy_id = v_policy;
    insert into public.fin_policy_versions(policy_id, organization_id, version, document, change_note, created_by)
      values (v_policy, p_org, v_next, p_document, nullif(trim(coalesce(p_change_note,'')),''), auth.uid()) returning id into v_version;
  else
    update public.fin_policy_versions set document = p_document, change_note = nullif(trim(coalesce(p_change_note,'')),''), updated_at = now()
     where id = v_version;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'organization', p_org, 'policy_draft_saved', auth.uid(),
            jsonb_build_object('policy_id', v_policy, 'version_id', v_version, 'rules', jsonb_array_length(p_document->'rules')), p_entity);
  return v_version;
exception when check_violation then raise exception 'invalid policy';
end $$;


ALTER FUNCTION public.fin_save_policy_draft(p_org uuid, p_entity uuid, p_name text, p_document jsonb, p_change_note text) OWNER TO postgres;

--
-- Name: fin_save_proposal_draft(uuid, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_save_proposal_draft(p_proposal uuid, p_terms jsonb, p_expected_revision integer, p_base_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_proposal public.fin_proposals%rowtype; v_revision integer; v_existing public.fin_proposal_drafts%rowtype; v_rfq_status text;
begin
 if jsonb_typeof(coalesce(p_terms,'null'::jsonb)) is distinct from 'object' or pg_column_size(p_terms)>32768 then raise exception 'invalid draft'; end if;
 if p_expected_revision is null or p_expected_revision<0 or p_base_version is null then raise exception 'invalid draft revision'; end if;
 select * into v_proposal from public.fin_proposals where id=p_proposal for update;
 if not found then raise exception 'proposal not found'; end if;
 if not public.fin_has_role(v_proposal.provider_organization_id,array['admin','provider_user']) then raise exception 'forbidden'; end if;
 select status into v_rfq_status from public.fin_rfqs where id=v_proposal.rfq_id;
 if v_proposal.status='withdrawn' or v_rfq_status not in ('open','collecting') then raise exception 'invalid state'; end if;
 if v_proposal.current_version<>p_base_version then raise exception 'draft conflict'; end if;
 select * into v_existing from public.fin_proposal_drafts where proposal_id=p_proposal for update;
 if found then
   if v_existing.revision<>p_expected_revision or v_existing.base_version<>p_base_version then raise exception 'draft conflict'; end if;
   v_revision:=v_existing.revision+1;
   update public.fin_proposal_drafts set terms=p_terms,revision=v_revision,updated_by=auth.uid(),updated_at=now() where proposal_id=p_proposal;
 else
   if p_expected_revision<>0 then raise exception 'draft conflict'; end if;
   v_revision:=1;
   insert into public.fin_proposal_drafts(proposal_id,provider_organization_id,base_version,revision,terms,updated_by)
     values(p_proposal,v_proposal.provider_organization_id,p_base_version,v_revision,p_terms,auth.uid());
 end if;
 return v_revision;
end $$;


ALTER FUNCTION public.fin_save_proposal_draft(p_proposal uuid, p_terms jsonb, p_expected_revision integer, p_base_version integer) OWNER TO postgres;

--
-- Name: fin_save_rfq_editor(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_save_rfq_editor(p_org uuid, p_payload jsonb, p_expected integer) RETURNS TABLE(revision integer, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row public.fin_rfq_editor_drafts%rowtype;
begin
 if not public.fin_has_role(p_org,array['admin','finance_manager']) then raise exception 'forbidden'; end if;
 if p_expected is null or p_expected<0 or jsonb_typeof(p_payload)<>'object' or pg_column_size(p_payload)>32768
  or (select count(*) from jsonb_object_keys(p_payload))>4
  or exists(select 1 from jsonb_object_keys(p_payload) as keys(key) where key not in ('product','title','response_deadline','demand'))
  or (p_payload ? 'demand' and jsonb_typeof(p_payload->'demand')<>'object')
 then raise exception 'invalid editor draft'; end if;
 insert into public.fin_rfq_editor_drafts(organization_id,user_id,payload,revision)
 values(p_org,auth.uid(),p_payload,1)
 on conflict(organization_id,user_id) do update
 set payload=excluded.payload,revision=public.fin_rfq_editor_drafts.revision+1,updated_at=now()
 where public.fin_rfq_editor_drafts.revision=p_expected
 returning * into v_row;
 if not found then raise exception 'rfq draft conflict'; end if;
 return query select v_row.revision,v_row.updated_at;
end $$;


ALTER FUNCTION public.fin_save_rfq_editor(p_org uuid, p_payload jsonb, p_expected integer) OWNER TO postgres;

--
-- Name: fin_scorecard_template_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_scorecard_template_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Só o estado muda (aposentar); critérios, pesos, nome e versão não.
  if new.criteria is distinct from old.criteria or new.name is distinct from old.name or new.version is distinct from old.version
     or new.template_key is distinct from old.template_key or new.organization_id is distinct from old.organization_id then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_scorecard_template_guard() OWNER TO postgres;

--
-- Name: fin_search(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_search(p_org uuid, p_query text, p_kind text DEFAULT NULL::text, p_limit integer DEFAULT 12, p_offset integer DEFAULT 0) RETURNS TABLE(kind text, id uuid, title text, detail text, href text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_query text;
begin
 if not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
 v_query:=lower(trim(coalesce(p_query,'')));
 if length(v_query) not between 2 and 100 or p_limit not between 1 and 30 or p_offset not between 0 and 1000
 or (p_kind is not null and p_kind not in ('rfq','proposal','provider','contract','task','implementation','covenant','performance','spend')) then
  raise exception 'invalid search'; end if;
 return query
 select x.kind,x.id,x.title,x.detail,x.href from (
  select 'rfq'::text kind,r.id,r.title::text,coalesce(r.status,'')::text detail,
    ('/finance/rfq.html?id='||r.id)::text href, 1 priority,r.created_at sorted_at
  from public.fin_rfqs r where r.organization_id=p_org and (p_kind is null or p_kind='rfq')
    and public.fin_entity_visible(p_org, r.legal_entity_id)
    and (position(v_query in lower(r.title))>0 or position(v_query in lower(r.id::text))>0)
  union all
  select 'proposal'::text,p.id,coalesce(v.name,'Proposta')::text,r.title::text,
    ('/finance/rfq.html?id='||r.id)::text,2,p.updated_at
  from public.fin_proposals p join public.fin_rfqs r on r.id=p.rfq_id and r.organization_id=p_org
   left join public.fin_providers v on v.id=p.provider_id and v.organization_id=p_org
  where p.buyer_organization_id=p_org and (p_kind is null or p_kind='proposal')
   and public.fin_entity_visible(p_org, r.legal_entity_id)
   and (position(v_query in lower(coalesce(v.name,'')))>0 or position(v_query in lower(r.title))>0 or position(v_query in lower(p.id::text))>0)
  union all
  select 'provider'::text,v.id,v.name::text,coalesce(v.region,'')::text,
    '/finance/providers.html'::text,3,v.created_at
  from public.fin_providers v where v.organization_id=p_org and (p_kind is null or p_kind='provider')
   and (position(v_query in lower(v.name))>0 or position(v_query in lower(v.id::text))>0)
  union all
  select 'contract'::text,c.id,coalesce(v.name,'Contrato')::text,c.ends_on::text,
    '/finance/contracts.html'::text,4,c.created_at
  from public.fin_contracts c left join public.fin_providers v on v.id=c.provider_id and v.organization_id=p_org
  where c.organization_id=p_org and (p_kind is null or p_kind='contract')
   and public.fin_entity_visible(p_org, c.legal_entity_id)
   and (position(v_query in lower(coalesce(v.name,'')))>0 or position(v_query in lower(c.id::text))>0)
  union all
  select 'task'::text,t.id,t.title::text,coalesce(t.due_on::text,'')::text,
    '/finance/dashboard.html'::text,5,t.created_at
  from public.fin_tasks t where t.organization_id=p_org and (p_kind is null or p_kind='task')
   and (public.fin_entity_visible(p_org, t.legal_entity_id) or (t.related_type is null and t.created_by = auth.uid()))
   and (position(v_query in lower(t.title))>0 or position(v_query in lower(t.id::text))>0)
 union all
 select 'implementation'::text,p.id,p.title::text,p.status::text,('/finance/implementations.html?id='||p.id)::text,6,p.created_at
 from public.fin_implementation_plans p where p.organization_id=p_org and (p_kind is null or p_kind='implementation') and public.fin_entity_visible(p_org,p.legal_entity_id) and (position(v_query in lower(p.title))>0 or position(v_query in lower(p.id::text))>0)
 union all
 select 'covenant'::text,o.id,o.title::text,o.kind::text,('/finance/covenants.html?obligation_id='||o.id)::text,7,o.created_at from public.fin_obligations o where o.organization_id=p_org and (p_kind is null or p_kind='covenant') and public.fin_entity_visible(p_org,o.legal_entity_id) and (position(v_query in lower(o.title))>0 or position(v_query in lower(o.id::text))>0)
 union all
 select 'performance'::text,p.id,p.title::text,p.status::text,('/finance/performance.html?id='||p.id)::text,8,p.created_at from public.fin_provider_performance_periods p where p.organization_id=p_org and (p_kind is null or p_kind='performance') and public.fin_entity_visible(p_org,p.legal_entity_id) and (position(v_query in lower(p.title))>0 or position(v_query in lower(p.id::text))>0)
 union all
 select 'spend'::text,r.id,('Spend '||r.source_reference)::text,r.value_kind::text,('/finance/spend.html?id='||r.id)::text,9,r.recorded_at from public.fin_spend_monitor r where r.organization_id=p_org and (p_kind is null or p_kind='spend') and public.fin_entity_visible(p_org,r.legal_entity_id) and (position(v_query in lower(r.source_reference))>0 or position(v_query in lower(r.id::text))>0)
 ) x order by x.priority,x.sorted_at desc,x.id limit p_limit offset p_offset;
end $$;


ALTER FUNCTION public.fin_search(p_org uuid, p_query text, p_kind text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fin_search_passport(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_search_passport(p_org uuid, p_entity uuid, p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, field_key text, field_value text, legal_entity_id uuid, source text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$ begin
 if not public.fin_has_role(p_org) or (p_entity is not null and not public.fin_entity_visible(p_org,p_entity)) then raise exception 'forbidden'; end if;
 if length(trim(coalesce(p_query,''))) not between 2 and 100 or p_limit is null or p_offset is null or p_limit not between 1 and 50 or p_offset not between 0 and 1000 then raise exception 'invalid search'; end if;
 return query select r.id,r.field_key,r.field_value,r.legal_entity_id,r.source,r.updated_at from (
  select distinct on (cp.field_key) cp.* from public.fin_company_profiles cp
  where cp.organization_id=p_org and (cp.legal_entity_id is not distinct from p_entity or (p_entity is not null and cp.legal_entity_id is null and cp.field_key in ('sector','moeda_base','necessidades_recorrentes','canais_de_venda')))
  order by cp.field_key,(cp.legal_entity_id is not null) desc
 ) r where position(lower(trim(p_query)) in lower(r.field_key||' '||r.field_value))>0 order by r.field_key limit p_limit offset p_offset;
end $$;


ALTER FUNCTION public.fin_search_passport(p_org uuid, p_entity uuid, p_query text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fin_seed_rfq_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_seed_rfq_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.fin_rfq_revisions(rfq_id,revision,organization_id,snapshot,changed_by)
 values(new.id,new.revision,new.organization_id,
  jsonb_build_object('title',new.title,'description',new.description,'demand',new.demand,
   'response_deadline',new.response_deadline),auth.uid())
 on conflict(rfq_id,revision) do nothing;
 return new;
end $$;


ALTER FUNCTION public.fin_seed_rfq_revision() OWNER TO postgres;

--
-- Name: fin_set_approval_delegation(uuid, uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_approval_delegation(p_org uuid, p_delegate uuid, p_starts timestamp with time zone, p_ends timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if not public.fin_has_role(p_org, array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'forbidden'; end if;
  if p_delegate is null or p_delegate = auth.uid() or not exists (select 1 from public.fin_members m where m.organization_id = p_org and m.user_id = p_delegate
       and m.role in ('admin','finance_manager','analyst','viewer')) then
    raise exception 'invalid delegation';
  end if;
  if p_starts is null or p_ends is null or p_ends <= p_starts or p_ends <= now() or p_ends - p_starts > interval '90 days'
     or length(trim(coalesce(p_reason,''))) not between 3 and 500 or p_reason ~ '[<>]' then
    raise exception 'invalid delegation';
  end if;
  insert into public.fin_approval_delegations(organization_id, delegator_id, delegate_id, starts_at, ends_at, reason, created_by)
    values (p_org, auth.uid(), p_delegate, p_starts, p_ends, trim(p_reason), auth.uid()) returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'approval_delegation_created', auth.uid(), jsonb_build_object('delegation_id', v_id, 'delegate_id', p_delegate,
            'starts_at', p_starts, 'ends_at', p_ends));
  return v_id;
end $$;


ALTER FUNCTION public.fin_set_approval_delegation(p_org uuid, p_delegate uuid, p_starts timestamp with time zone, p_ends timestamp with time zone, p_reason text) OWNER TO postgres;

--
-- Name: fin_set_approval_policy(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_approval_policy(p_org uuid, p_required boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.fin_has_role(p_org,array['admin']) then raise exception 'forbidden'; end if;
 if not exists(select 1 from public.fin_organizations where id=p_org and kind='BUYER') then raise exception 'forbidden'; end if;
 if p_required is null then raise exception 'invalid policy'; end if;
 insert into public.fin_approval_policies(organization_id,required_for_decision,updated_by)
 values(p_org,p_required,auth.uid())
 on conflict(organization_id) do update set required_for_decision=excluded.required_for_decision,updated_by=auth.uid(),updated_at=now();
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,metadata)
 values(p_org,'organization',p_org,'approval_policy_updated',auth.uid(),jsonb_build_object('required_for_decision',p_required));
end $$;


ALTER FUNCTION public.fin_set_approval_policy(p_org uuid, p_required boolean) OWNER TO postgres;

--
-- Name: fin_set_base_currency(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_base_currency(p_org uuid, p_currency text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if coalesce(p_currency,'') !~ '^[A-Z]{3}$' then raise exception 'invalid currency'; end if;
  update public.fin_organizations set base_currency = p_currency where id = p_org;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, 'organization', p_org, 'base_currency_updated', auth.uid(), jsonb_build_object('currency', p_currency));
end $_$;


ALTER FUNCTION public.fin_set_base_currency(p_org uuid, p_currency text) OWNER TO postgres;

--
-- Name: fin_set_member_entity_scope(uuid, uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_member_entity_scope(p_org uuid, p_user uuid, p_scope text, p_entities uuid[] DEFAULT '{}'::uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role text; v_count integer;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  select role into v_role from public.fin_members where organization_id = p_org and user_id = p_user for update;
  if v_role is null then raise exception 'member not found'; end if;
  if p_scope not in ('group','entities') then raise exception 'invalid scope'; end if;
  if p_scope = 'entities' and v_role = 'admin' then raise exception 'invalid scope'; end if;
  v_count := coalesce(array_length(p_entities, 1), 0);
  if p_scope = 'entities' and (v_count = 0 or v_count > 200 or (select count(*) from public.fin_legal_entities e
      where e.organization_id = p_org and e.id = any(p_entities) and e.status = 'active') <> (select count(distinct x) from unnest(p_entities) x)) then
    raise exception 'invalid scope';
  end if;
  delete from public.fin_member_entity_grants where organization_id = p_org and user_id = p_user;
  update public.fin_members set entity_scope = p_scope where organization_id = p_org and user_id = p_user;
  if p_scope = 'entities' then
    insert into public.fin_member_entity_grants(organization_id, user_id, entity_id, granted_by)
    select distinct p_org, p_user, x, auth.uid() from unnest(p_entities) x;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, 'member', p_user, 'member_entity_scope_set', auth.uid(),
          jsonb_build_object('scope', p_scope, 'entities', case when p_scope = 'entities' then v_count else 0 end));
end $$;


ALTER FUNCTION public.fin_set_member_entity_scope(p_org uuid, p_user uuid, p_scope text, p_entities uuid[]) OWNER TO postgres;

--
-- Name: fin_set_notification_preference(uuid, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_notification_preference(p_org uuid, p_event text, p_in_app boolean, p_email boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not public.fin_has_role(p_org) then raise exception 'forbidden'; end if;
 if p_event not in ('mention','comment','proposal_received','proposal_revised','approval_requested','approval_approved','approval_rejected','approval_changes_requested','renewal_due','task_assigned','policy_exception_requested','policy_exception_decided')
 or p_in_app is null or p_email is null then raise exception 'invalid preference'; end if;
 insert into public.fin_notification_preferences(organization_id,user_id,event_type,in_app,email)
 values(p_org,auth.uid(),p_event,p_in_app,p_email)
 on conflict(organization_id,user_id,event_type) do update set in_app=excluded.in_app,email=excluded.email;
end $$;


ALTER FUNCTION public.fin_set_notification_preference(p_org uuid, p_event text, p_in_app boolean, p_email boolean) OWNER TO postgres;

--
-- Name: fin_set_opportunity_rule(uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_opportunity_rule(p_org uuid, p_key text, p_expected integer, p_input jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_current integer;
begin
  if auth.uid() is null or not public.fin_has_role(p_org, array['admin']) or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  perform pg_advisory_xact_lock(hashtext('fin_opportunity_rule:' || p_org::text || ':' || coalesce(p_key, '')));
  select max(version) into v_current from public.fin_opportunity_rules where organization_id = p_org and rule_key = p_key;
  if coalesce(v_current, 0) is distinct from coalesce(p_expected, 0) then raise exception 'opportunity rule version conflict'; end if;
  if p_input is null or jsonb_typeof(p_input->'enabled') is distinct from 'boolean' or not public.fin_opportunity_parameters_valid(p_key, p_input->'parameters')
     or length(trim(coalesce(p_input->>'reason', ''))) not between 3 and 1000 or p_input->>'reason' ~ '[<>]' then raise exception 'invalid opportunity rule'; end if;
  insert into public.fin_opportunity_rules(organization_id, rule_key, version, parameters, enabled, reason, created_by)
    values (p_org, p_key, coalesce(v_current, 0) + 1, p_input->'parameters', (p_input->>'enabled')::boolean, trim(p_input->>'reason'), auth.uid());
  insert into public.fin_opportunity_scans(organization_id) values (p_org) on conflict (organization_id) do nothing;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'opportunity_rule_versioned', auth.uid(), jsonb_build_object('rule_key', p_key, 'version', coalesce(v_current, 0) + 1, 'enabled', (p_input->>'enabled')::boolean));
  return coalesce(v_current, 0) + 1;
end $$;


ALTER FUNCTION public.fin_set_opportunity_rule(p_org uuid, p_key text, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_set_policy_flag(uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_policy_flag(p_org uuid, p_key text, p_label text, p_kind text, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'forbidden'; end if;
  if coalesce(p_key,'') !~ '^[a-z][a-z0-9_]{1,40}$' or length(trim(coalesce(p_label,''))) not between 2 and 120 or p_label ~ '[<>]'
     or coalesce(p_kind,'') not in ('exception','risk','compliance','other') or p_active is null then
    raise exception 'invalid policy';
  end if;
  insert into public.fin_policy_flags(organization_id, key, label, kind, active, updated_by)
    values (p_org, p_key, trim(p_label), p_kind, p_active, auth.uid())
  on conflict (organization_id, key) do update set label = excluded.label, kind = excluded.kind, active = excluded.active,
    updated_by = auth.uid(), updated_at = now();
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'policy_flag_updated', auth.uid(), jsonb_build_object('key', p_key, 'kind', p_kind, 'active', p_active));
end $_$;


ALTER FUNCTION public.fin_set_policy_flag(p_org uuid, p_key text, p_label text, p_kind text, p_active boolean) OWNER TO postgres;

--
-- Name: fin_set_provider_relationship(uuid, uuid, uuid, text, uuid, text[], date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_provider_relationship(p_org uuid, p_provider uuid, p_entity uuid, p_status text, p_owner uuid DEFAULT NULL::uuid, p_categories text[] DEFAULT '{}'::text[], p_since date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if p_entity is null then raise exception 'invalid legal entity'; end if;
  perform public.fin_assert_portfolio_write(p_org, p_entity);
  if not exists (select 1 from public.fin_providers p where p.organization_id = p_org and p.id = p_provider) then raise exception 'provider not found'; end if;
  if p_owner is not null and not exists (select 1 from public.fin_members m where m.organization_id = p_org and m.user_id = p_owner) then raise exception 'invalid owner'; end if;
  if exists (select 1 from unnest(coalesce(p_categories,'{}')) c where c not in ('credit','acquiring','cash_management','guarantee','fx','insurance','investment','other')) then
    raise exception 'invalid relationship';
  end if;
  insert into public.fin_provider_relationships(organization_id, provider_id, legal_entity_id, status, owner_id, categories, since_on, notes, updated_by)
    values (p_org, p_provider, p_entity, p_status, p_owner, coalesce(p_categories,'{}'), p_since, nullif(trim(coalesce(p_notes,'')),''), auth.uid())
    on conflict (organization_id, provider_id, legal_entity_id) do update set
      status = excluded.status, owner_id = excluded.owner_id, categories = excluded.categories, since_on = excluded.since_on,
      notes = excluded.notes, updated_by = auth.uid(), updated_at = now()
    returning id into v_id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (p_org, 'provider', p_provider, 'provider_relationship_set', auth.uid(), jsonb_build_object('status', p_status, 'categories', cardinality(coalesce(p_categories,'{}'))), p_entity);
  return v_id;
exception when check_violation then raise exception 'invalid relationship';
end $$;


ALTER FUNCTION public.fin_set_provider_relationship(p_org uuid, p_provider uuid, p_entity uuid, p_status text, p_owner uuid, p_categories text[], p_since date, p_notes text) OWNER TO postgres;

--
-- Name: fin_set_qualification_requirement(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_qualification_requirement(p_org uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_prev public.fin_qualification_requirements%rowtype; v_id uuid; v_key uuid; v_version integer := 1; v_entity uuid;
begin
  if auth.uid() is null or not public.fin_has_role(p_org, array['admin']) or not exists (select 1 from public.fin_organizations where id = p_org and kind = 'BUYER') then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(p_org) then raise exception 'organization offboarding'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or exists (select 1 from jsonb_object_keys(p_input) k where k not in ('requirement_key','area','title','description','category','legal_entity_id','validity_days','critical')) then raise exception 'invalid qualification requirement'; end if;
  v_entity := nullif(p_input->>'legal_entity_id', '')::uuid;
  if v_entity is not null and not exists (select 1 from public.fin_legal_entities where organization_id = p_org and id = v_entity) then raise exception 'invalid qualification requirement'; end if;
  if p_input ? 'requirement_key' and nullif(p_input->>'requirement_key', '') is not null then
    select * into v_prev from public.fin_qualification_requirements where organization_id = p_org and requirement_key = (p_input->>'requirement_key')::uuid and status = 'active' for update;
    if v_prev.id is null then raise exception 'invalid qualification requirement'; end if;
    v_key := v_prev.requirement_key; v_version := v_prev.version + 1;
    update public.fin_qualification_requirements set status = 'retired', retired_at = now() where id = v_prev.id;
  end if;
  begin
    insert into public.fin_qualification_requirements(organization_id, requirement_key, version, area, title, description, category, legal_entity_id, validity_days, critical, created_by)
    values (p_org, coalesce(v_key, gen_random_uuid()), v_version, p_input->>'area', trim(p_input->>'title'), nullif(trim(coalesce(p_input->>'description', '')), ''),
      coalesce(nullif(p_input->>'category', ''), 'all'), v_entity, nullif(p_input->>'validity_days', '')::integer, coalesce((p_input->>'critical')::boolean, false), auth.uid())
    returning id into v_id;
  exception when check_violation or not_null_violation or invalid_text_representation then raise exception 'invalid qualification requirement';
  end;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (p_org, 'qualification_requirement', v_id, 'qualification_requirement_set', auth.uid(), jsonb_build_object('version', v_version));
  return v_id;
end $$;


ALTER FUNCTION public.fin_set_qualification_requirement(p_org uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_set_rfq_entity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_rfq_entity(p_rfq uuid, p_entity uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_rfqs%rowtype;
begin
  select * into v from public.fin_rfqs where id = p_rfq for update;
  if not found then raise exception 'rfq not found'; end if;
  if not public.fin_entity_allows(v.organization_id, v.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v.status not in ('draft','open','collecting','comparing') then raise exception 'invalid state'; end if;
  if p_entity is not null and not exists (select 1 from public.fin_legal_entities e
       where e.organization_id = v.organization_id and e.id = p_entity and e.status = 'active') then
    raise exception 'invalid legal entity';
  end if;
  if not public.fin_entity_allows(v.organization_id, p_entity, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v.legal_entity_id is not distinct from p_entity then return; end if;
  perform set_config('arandu.entity_change', 'on', true);
  update public.fin_rfqs set legal_entity_id = p_entity, updated_at = now() where id = p_rfq;
  perform set_config('arandu.entity_change', '', true);
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
  values (v.organization_id, 'rfq', p_rfq, 'rfq_entity_changed', auth.uid(),
          jsonb_build_object('from', v.legal_entity_id, 'to', p_entity), p_entity);
end $$;


ALTER FUNCTION public.fin_set_rfq_entity(p_rfq uuid, p_entity uuid) OWNER TO postgres;

--
-- Name: fin_set_webhook_status(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_set_webhook_status(p_endpoint uuid, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.fin_webhook_endpoints%rowtype;
begin
  select * into e from public.fin_webhook_endpoints where id = p_endpoint for update;
  if not found or not public.fin_has_role(e.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if p_active then
    update public.fin_webhook_endpoints set status = 'active', disabled_at = null, disabled_reason = null, consecutive_failures = 0, updated_at = now() where id = p_endpoint;
  else
    update public.fin_webhook_endpoints set status = 'disabled', disabled_at = coalesce(disabled_at, now()), disabled_reason = 'manual', updated_at = now() where id = p_endpoint;
    update public.fin_webhook_deliveries set status = 'cancelled', lease_token = null, lease_expires_at = null where endpoint_id = p_endpoint and status in ('pending','failed');
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (e.organization_id, 'webhook_endpoint', p_endpoint, case when p_active then 'webhook_endpoint_enabled' else 'webhook_endpoint_disabled' end, auth.uid(), '{}'::jsonb);
end $$;


ALTER FUNCTION public.fin_set_webhook_status(p_endpoint uuid, p_active boolean) OWNER TO postgres;

