--
-- Name: fin_settle_contract_milestone(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_settle_contract_milestone(p_milestone uuid, p_action text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m public.fin_contract_milestones%rowtype; v_next date; v_months integer; v_status text;
begin
  select * into m from public.fin_contract_milestones where id = p_milestone for update;
  if not found then raise exception 'milestone not found'; end if;
  perform public.fin_contract_for_write(m.contract_id);
  if m.status <> 'scheduled' then raise exception 'milestone closed'; end if;
  if p_action not in ('done','cancelled') then raise exception 'invalid milestone'; end if;
  v_months := case m.recurrence when 'monthly' then 1 when 'quarterly' then 3 when 'semiannual' then 6 when 'annual' then 12 else null end;
  if p_action = 'done' and v_months is not null then
    v_next := (m.due_on + make_interval(months => v_months))::date;
  end if;
  if v_next is not null and (m.ends_after is null or v_next <= m.ends_after) then
    update public.fin_contract_milestones set due_on = v_next, updated_at = now() where id = m.id;
    v_status := 'scheduled';
  else
    update public.fin_contract_milestones set status = p_action, completed_at = now(), completed_by = auth.uid(), updated_at = now() where id = m.id;
    v_status := p_action;
  end if;
  -- A tarefa da ocorrência concluída fecha junto.
  update public.fin_tasks t set status = case when p_action = 'done' then 'done' else 'cancelled' end
   where t.id in (select r.task_id from public.fin_contract_milestone_runs r where r.milestone_id = m.id and r.occurrence_due_on = m.due_on)
     and t.status = 'open';
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (m.organization_id, 'contract', m.contract_id, 'contract_milestone_' || p_action, auth.uid(),
      jsonb_build_object('milestone_id', m.id, 'occurrence', m.due_on, 'next', v_next));
  return v_status;
end $$;


ALTER FUNCTION public.fin_settle_contract_milestone(p_milestone uuid, p_action text) OWNER TO postgres;

--
-- Name: fin_simulate_policy_version(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_simulate_policy_version(p_version uuid, p_facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_policy_versions%rowtype; p public.fin_policies%rowtype; v_facts jsonb;
begin
  select * into v from public.fin_policy_versions where id = p_version;
  if not found or not public.fin_has_role(v.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  select * into p from public.fin_policies where id = v.policy_id;
  if jsonb_typeof(coalesce(p_facts, 'null'::jsonb)) <> 'object' or length(p_facts::text) > 4000 then raise exception 'invalid policy'; end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_facts from jsonb_each(p_facts)
   where key in ('product','legal_entity_id','legal_entity_parent_id','currency','amount','provider_status','provider_new','proposals_count',
                 'guarantee_required','covenant_present','contract_duration_months','maturity_date','flags');
  return public.fin_policy_combine(v_facts, jsonb_build_array(jsonb_build_object('policy_id', p.id, 'version_id', v.id, 'version', v.version,
    'scope', case when p.legal_entity_id is null then 'group' else 'entity' end, 'legal_entity_id', p.legal_entity_id, 'name', p.name, 'document', v.document)))
    || jsonb_build_object('simulation', true);
end $$;


ALTER FUNCTION public.fin_simulate_policy_version(p_version uuid, p_facts jsonb) OWNER TO postgres;

--
-- Name: fin_spend_summary(uuid, date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_spend_summary(p_org uuid, p_start date, p_end date, p_entity uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$ begin
 if auth.uid() is null or not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) or p_entity is not null and not public.fin_entity_visible(p_org,p_entity) then raise exception 'forbidden';end if;
 if p_start is null or p_end is null or p_end<p_start or p_end-p_start>1826 then raise exception 'invalid spend period';end if;
 return jsonb_build_object('source','fin_spend_monitor','observed_at',now(),'formula','sum included evidence, separated by currency/kind/entity/provider/product; no FX or savings','rows',(select coalesce(jsonb_agg(x),'[]') from(select currency,value_kind,legal_entity_id,provider_id,product,count(*) as records,count(*) filter(where included and period_start>=p_start and period_end<=p_end) as included_records,sum(amount::numeric) filter(where included and period_start>=p_start and period_end<=p_end)::text as amount,count(*) filter(where period_start<p_start or period_end>p_end) as outside_complete_period from public.fin_spend_monitor where organization_id=p_org and period_end>=p_start and period_start<=p_end and (p_entity is null or legal_entity_id=p_entity) and (p_provider is null or provider_id=p_provider) group by currency,value_kind,legal_entity_id,provider_id,product)x));
end $$;


ALTER FUNCTION public.fin_spend_summary(p_org uuid, p_start date, p_end date, p_entity uuid, p_provider uuid) OWNER TO postgres;

--
-- Name: fin_sso_authorize(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_authorize(p_connection uuid, p_user uuid, p_email text, p_provider_ref text, p_issued_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_sso_connections%rowtype; v_domain text; d public.fin_sso_domains%rowtype; m record;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  select * into c from public.fin_sso_connections where id = p_connection;
  if not found or c.status not in ('testing','active') then raise exception 'sso connection inactive'; end if;
  if c.provider_ref is distinct from p_provider_ref then raise exception 'sso provider mismatch'; end if;
  v_domain := lower(split_part(coalesce(p_email, ''), '@', 2));
  select * into d from public.fin_sso_domains where domain = v_domain;
  if not found or d.status <> 'verified' or d.connection_id is distinct from c.id then raise exception 'sso domain mismatch'; end if;
  if d.organization_id <> c.organization_id then raise exception 'sso org mismatch'; end if;
  if p_issued_at is null or p_issued_at < now() - make_interval(hours => c.max_session_hours) then raise exception 'sso session expired'; end if;
  if c.sessions_valid_after is not null and p_issued_at < c.sessions_valid_after then raise exception 'sso session revoked'; end if;
  if exists (select 1 from auth.users u where u.id = p_user and u.banned_until is not null and u.banned_until > now()) then raise exception 'sso member disabled'; end if;
  select role, entity_scope into m from public.fin_members where organization_id = c.organization_id and user_id = p_user;
  if not found then raise exception 'sso member not found'; end if;
  return jsonb_build_object('organization_id', c.organization_id, 'role', m.role, 'entity_scope', m.entity_scope, 'mfa_policy', c.mfa_policy,
    'max_session_hours', c.max_session_hours, 'status', c.status);
end $$;


ALTER FUNCTION public.fin_sso_authorize(p_connection uuid, p_user uuid, p_email text, p_provider_ref text, p_issued_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fin_sso_claim_domain(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_claim_domain(p_org uuid, p_domain text, p_token_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_sso_domains%rowtype; v_domain text := lower(trim(coalesce(p_domain, '')));
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  -- Domínios de e-mail pessoal nunca viram SSO de empresa.
  if v_domain in ('gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','yahoo.com','yahoo.com.br','icloud.com','me.com','proton.me','protonmail.com','uol.com.br','bol.com.br','terra.com.br') then
    raise exception 'invalid sso domain';
  end if;
  select * into d from public.fin_sso_domains where domain = v_domain for update;
  if found and d.status = 'verified' then
    raise exception '%', case when d.organization_id = p_org then 'sso domain already verified' else 'sso domain unavailable' end;
  end if;
  -- Pedido de outra organização sem verificação por 7 dias não segura o domínio:
  -- sem isto, qualquer empresa cadastrada bloqueava o SSO do dono real.
  if found and d.organization_id <> p_org and d.created_at > now() - interval '7 days' then raise exception 'sso domain unavailable'; end if;
  if found and d.organization_id <> p_org then
    update public.fin_sso_domains set organization_id = p_org, connection_id = null, verification_token_hash = p_token_hash,
      status = 'pending', verified_at = null, created_by = auth.uid(), created_at = now() where domain = v_domain;
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
      values (d.organization_id, 'organization', d.organization_id, 'sso_domain_claim_expired', null, jsonb_build_object('domain', v_domain));
  else
    insert into public.fin_sso_domains(domain, organization_id, verification_token_hash, created_by)
      values (v_domain, p_org, p_token_hash, auth.uid())
    on conflict (domain) do update set verification_token_hash = excluded.verification_token_hash, status = 'pending', verified_at = null, created_by = auth.uid(), created_at = now();
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'organization', p_org, 'sso_domain_claimed', auth.uid(), jsonb_build_object('domain', v_domain));
exception when check_violation then raise exception 'invalid sso domain';
end $$;


ALTER FUNCTION public.fin_sso_claim_domain(p_org uuid, p_domain text, p_token_hash text) OWNER TO postgres;

--
-- Name: fin_sso_discover(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_discover(p_domain text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  select c.id, c.protocol, c.broker, c.provider_ref, c.status, c.enforce_sso into r
    from public.fin_sso_domains d join public.fin_sso_connections c on c.id = d.connection_id
   where d.domain = lower(trim(coalesce(p_domain, ''))) and d.status = 'verified' and c.status in ('testing','active');
  if not found then return null; end if;
  return jsonb_build_object('connection_id', r.id, 'protocol', r.protocol, 'broker', r.broker, 'provider_ref', r.provider_ref, 'status', r.status, 'enforce', r.enforce_sso);
end $$;


ALTER FUNCTION public.fin_sso_discover(p_domain text) OWNER TO postgres;

--
-- Name: fin_sso_link_domain(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_link_domain(p_domain text, p_connection uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_sso_domains%rowtype;
begin
  select * into d from public.fin_sso_domains where domain = lower(trim(coalesce(p_domain, ''))) for update;
  if not found or not public.fin_has_role(d.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if p_connection is not null and not exists (select 1 from public.fin_sso_connections c where c.id = p_connection and c.organization_id = d.organization_id) then
    raise exception 'forbidden';
  end if;
  update public.fin_sso_domains set connection_id = p_connection where domain = d.domain;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (d.organization_id, 'organization', d.organization_id, 'sso_domain_linked', auth.uid(), jsonb_build_object('domain', d.domain, 'connection_id', p_connection));
end $$;


ALTER FUNCTION public.fin_sso_link_domain(p_domain text, p_connection uuid) OWNER TO postgres;

--
-- Name: fin_sso_mark_domain_verified(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_mark_domain_verified(p_domain text, p_token_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.fin_sso_domains%rowtype;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  select * into d from public.fin_sso_domains where domain = lower(trim(coalesce(p_domain, ''))) for update;
  if not found or d.status <> 'pending' or d.verification_token_hash <> coalesce(p_token_hash, '') then raise exception 'sso domain not verified'; end if;
  update public.fin_sso_domains set status = 'verified', verified_at = now() where domain = d.domain;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (d.organization_id, 'organization', d.organization_id, 'sso_domain_verified', null, jsonb_build_object('domain', d.domain));
  return d.organization_id;
end $$;


ALTER FUNCTION public.fin_sso_mark_domain_verified(p_domain text, p_token_hash text) OWNER TO postgres;

--
-- Name: fin_sso_password_allowed(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_password_allowed(p_domain text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (select 1 from public.fin_sso_domains d join public.fin_sso_connections c on c.id = d.connection_id
                      where d.domain = lower(trim(coalesce(p_domain, ''))) and d.status = 'verified' and c.status = 'active' and c.enforce_sso);
$$;


ALTER FUNCTION public.fin_sso_password_allowed(p_domain text) OWNER TO postgres;

--
-- Name: fin_sso_revoke_sessions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_revoke_sessions(p_connection uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_sso_connections%rowtype;
begin
  select * into c from public.fin_sso_connections where id = p_connection for update;
  if not found or not public.fin_has_role(c.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  update public.fin_sso_connections set sessions_valid_after = now(), updated_at = now() where id = p_connection;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'sso_connection', c.id, 'sso_sessions_revoked', auth.uid(), '{}'::jsonb);
end $$;


ALTER FUNCTION public.fin_sso_revoke_sessions(p_connection uuid) OWNER TO postgres;

--
-- Name: fin_sso_save_connection(uuid, uuid, text, text, text, text, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_save_connection(p_org uuid, p_connection uuid, p_protocol text, p_broker text, p_display_name text, p_provider_ref text, p_issuer text, p_audience text, p_metadata_url text, p_mapping jsonb, p_max_session_hours integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; c public.fin_sso_connections%rowtype;
begin
  if not public.fin_has_role(p_org, array['admin']) then raise exception 'forbidden'; end if;
  if not exists (select 1 from public.fin_organizations o where o.id = p_org and o.kind = 'BUYER') then raise exception 'buyer organization required'; end if;
  if p_mapping is not null and (jsonb_typeof(p_mapping) <> 'object' or not (p_mapping ? 'email')
     or exists (select 1 from jsonb_object_keys(p_mapping) k where k not in ('email','name','groups'))
     or exists (select 1 from jsonb_each(p_mapping) e where jsonb_typeof(e.value) <> 'string' or length(e.value #>> '{}') not between 1 and 120)) then
    raise exception 'invalid sso connection';
  end if;
  if p_connection is null then
    insert into public.fin_sso_connections(organization_id, protocol, broker, display_name, provider_ref, issuer, audience, metadata_url, attribute_mapping, max_session_hours, created_by)
      values (p_org, p_protocol, coalesce(p_broker, 'supabase'), trim(p_display_name), nullif(trim(coalesce(p_provider_ref,'')),''), nullif(trim(coalesce(p_issuer,'')),''),
              nullif(trim(coalesce(p_audience,'')),''), nullif(trim(coalesce(p_metadata_url,'')),''), coalesce(p_mapping, '{"email":"email"}'::jsonb), coalesce(p_max_session_hours, 12), auth.uid())
      returning id into v_id;
  else
    select * into c from public.fin_sso_connections where id = p_connection and organization_id = p_org for update;
    if not found then raise exception 'forbidden'; end if;
    -- Conexão ativa não muda em produção: desative, ajuste, teste e reative.
    if c.status = 'active' then raise exception 'sso connection active'; end if;
    update public.fin_sso_connections set protocol = p_protocol, broker = coalesce(p_broker, broker), display_name = trim(p_display_name),
           provider_ref = nullif(trim(coalesce(p_provider_ref,'')),''), issuer = nullif(trim(coalesce(p_issuer,'')),''), audience = nullif(trim(coalesce(p_audience,'')),''),
           metadata_url = nullif(trim(coalesce(p_metadata_url,'')),''), attribute_mapping = coalesce(p_mapping, attribute_mapping),
           max_session_hours = coalesce(p_max_session_hours, max_session_hours), status = case when status = 'testing' then 'draft' else status end, updated_at = now()
     where id = p_connection returning id into v_id;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (p_org, 'sso_connection', v_id, 'sso_connection_saved', auth.uid(), jsonb_build_object('protocol', p_protocol, 'broker', coalesce(p_broker, 'supabase')));
  return v_id;
exception when check_violation or not_null_violation then raise exception 'invalid sso connection';
end $$;


ALTER FUNCTION public.fin_sso_save_connection(p_org uuid, p_connection uuid, p_protocol text, p_broker text, p_display_name text, p_provider_ref text, p_issuer text, p_audience text, p_metadata_url text, p_mapping jsonb, p_max_session_hours integer) OWNER TO postgres;

--
-- Name: fin_sso_session_valid(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_session_valid(p_connection uuid, p_user uuid, p_issued_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_sso_connections%rowtype;
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  select * into c from public.fin_sso_connections where id = p_connection;
  return found and c.status in ('testing','active') and p_issued_at is not null
     and p_issued_at >= now() - make_interval(hours => c.max_session_hours)
     and (c.sessions_valid_after is null or p_issued_at >= c.sessions_valid_after)
     and exists (select 1 from public.fin_members m where m.organization_id = c.organization_id and m.user_id = p_user)
     and not exists (select 1 from auth.users u where u.id = p_user and u.banned_until is not null and u.banned_until > now());
end $$;


ALTER FUNCTION public.fin_sso_session_valid(p_connection uuid, p_user uuid, p_issued_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fin_sso_set_status(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_sso_set_status(p_connection uuid, p_status text, p_enforce boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_sso_connections%rowtype;
begin
  select * into c from public.fin_sso_connections where id = p_connection for update;
  if not found or not public.fin_has_role(c.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if p_status not in ('draft','testing','active','disabled') then raise exception 'invalid sso connection'; end if;
  if p_status in ('testing','active') then
    if c.provider_ref is null or c.metadata_url is null or (c.protocol = 'oidc' and (c.issuer is null or c.audience is null)) then raise exception 'sso connection incomplete'; end if;
    if not exists (select 1 from public.fin_sso_domains d where d.connection_id = c.id and d.status = 'verified') then raise exception 'sso domain not verified'; end if;
  end if;
  if p_status = 'active' then
    if c.broker = 'mock' then raise exception 'sso mock broker'; end if;
    if not exists (select 1 from public.fin_sso_events e where e.connection_id = c.id and e.outcome = 'success') then raise exception 'sso test login required'; end if;
  end if;
  if coalesce(p_enforce, false) and p_status <> 'active' then raise exception 'invalid sso connection'; end if;
  update public.fin_sso_connections set status = p_status, enforce_sso = coalesce(p_enforce, false) and p_status = 'active', updated_at = now(),
         activated_by = case when p_status = 'active' then auth.uid() else activated_by end, activated_at = case when p_status = 'active' then now() else activated_at end
   where id = p_connection;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'sso_connection', c.id, 'sso_connection_status', auth.uid(), jsonb_build_object('status', p_status, 'enforce', coalesce(p_enforce, false)));
end $$;


ALTER FUNCTION public.fin_sso_set_status(p_connection uuid, p_status text, p_enforce boolean) OWNER TO postgres;

--
-- Name: fin_stamp_contract_rfq_origin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_stamp_contract_rfq_origin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.fin_contracts%rowtype; r public.fin_rfqs%rowtype; v_origin_version integer;
begin
  if new.event_type <> 'rfq_created_from_contract' then return new; end if;
  select * into c from public.fin_contracts where id=(new.metadata->>'contract_id')::uuid for share;
  select * into r from public.fin_rfqs where id=new.entity_id;
  if c.id is null or r.id is null or new.entity_type<>'rfq'
    or c.organization_id<>new.organization_id or r.organization_id<>c.organization_id
    or c.legal_entity_id is distinct from r.legal_entity_id
    or not public.fin_entity_allows(c.organization_id,c.legal_entity_id,array['admin','finance_manager'])
  then raise exception 'forbidden'; end if;
  select version into v_origin_version from public.fin_contract_versions
    where contract_id=c.id and effective_from<=current_date order by effective_from desc,version desc limit 1;
  new.metadata := new.metadata || jsonb_build_object('contract_id',c.id,'contract_version',v_origin_version,'origin_schema','contract-rfq-v2');
  return new;
end $$;


ALTER FUNCTION public.fin_stamp_contract_rfq_origin() OWNER TO postgres;

--
-- Name: fin_stamp_proposal_rfq_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_stamp_proposal_rfq_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 select r.revision into new.rfq_revision from public.fin_proposals p
 join public.fin_rfqs r on r.id=p.rfq_id where p.id=new.proposal_id for share of r;
 if new.rfq_revision is null then raise exception 'rfq not found'; end if;
 return new;
end $$;


ALTER FUNCTION public.fin_stamp_proposal_rfq_revision() OWNER TO postgres;

--
-- Name: fin_start_contract_rfq(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_start_contract_rfq(p_contract uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c record; v_id uuid; v_title text;
begin
  select ct.organization_id, ct.product, ct.id, ct.legal_entity_id, ct.origin, ct.status ct_status, ct.title ct_title, r.title, r.description, r.demand into c
    from public.fin_contracts ct
    left join public.fin_decisions d on d.id = ct.decision_id
    left join public.fin_rfqs r on r.id = d.rfq_id and r.organization_id = ct.organization_id
   where ct.id = p_contract for update of ct;
  if not found then raise exception 'contract not found'; end if;
  if not public.fin_entity_allows(c.organization_id, c.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if c.product not in ('credit','acquiring') then raise exception 'invalid product'; end if;
  -- Concorrência de renovação ainda em andamento: devolve a mesma.
  select r.id into v_id from public.fin_events e
    join public.fin_rfqs r on r.id = e.entity_id and r.organization_id = c.organization_id
   where e.organization_id = c.organization_id and e.entity_type = 'rfq' and e.event_type = 'rfq_created_from_contract'
     and e.metadata->>'contract_id' = c.id::text and r.status in ('draft','open','collecting','comparing','decided')
   order by e.happened_at desc limit 1;
  if v_id is not null then return v_id; end if;
  v_title := left('Renovação: ' || coalesce(c.title, c.ct_title, 'contrato existente'), 200);
  insert into public.fin_rfqs(organization_id, product, title, description, demand, owner_id, status, legal_entity_id)
    values (c.organization_id, c.product, v_title, c.description, coalesce(c.demand, '{}'::jsonb), auth.uid(), 'draft', c.legal_entity_id)
    returning id into v_id;
  if c.ct_status = 'active' then
    update public.fin_contracts set status = 'renewing', updated_at = now() where id = c.id;
  end if;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'contract', c.id, 'renewal_rfq_started', auth.uid(), jsonb_build_object('rfq_id', v_id));
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (c.organization_id, 'rfq', v_id, 'rfq_created_from_contract', auth.uid(), jsonb_build_object('contract_id', c.id));
  return v_id;
end $$;


ALTER FUNCTION public.fin_start_contract_rfq(p_contract uuid) OWNER TO postgres;

--
-- Name: fin_submit_proposal(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_submit_proposal(p_proposal uuid, p_terms jsonb, p_note text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row public.fin_proposals%rowtype; v_rfq uuid; v_rfq_status text; v_version integer; v_current jsonb;
begin
  if jsonb_typeof(coalesce(p_terms,'null'::jsonb)) is distinct from 'object' then raise exception 'invalid terms'; end if;
  -- Mesma ordem de locks da decisão (RFQ antes da proposta): sem deadlock entre
  -- envio e decisão, e o status da RFQ é lido já travado. NO KEY UPDATE porque
  -- o envio pode mover a RFQ para "collecting", sem bloquear FKs que a referenciam.
  select p.rfq_id into v_rfq from public.fin_proposals p where p.id = p_proposal;
  if v_rfq is null then raise exception 'proposal not found'; end if;
  select status into v_rfq_status from public.fin_rfqs where id = v_rfq for no key update;
  select * into v_row from public.fin_proposals where id = p_proposal for update;
  if not found or v_row.rfq_id is distinct from v_rfq then raise exception 'proposal not found'; end if;
  if not public.fin_has_role(v_row.provider_organization_id, array['admin','provider_user']) then raise exception 'forbidden'; end if;
  if v_row.status = 'withdrawn' then raise exception 'invalid state'; end if;
  if v_rfq_status not in ('open','collecting') then raise exception 'rfq is not receiving proposals'; end if;

  if v_row.current_version > 0 then
    select terms into v_current from public.fin_proposal_versions
      where proposal_id = p_proposal and version = v_row.current_version;
    if v_current = p_terms then return v_row.current_version; end if;
  end if;

  v_version := v_row.current_version + 1;
  insert into public.fin_proposal_versions (proposal_id, version, terms, note, submitted_by)
    values (p_proposal, v_version, p_terms, p_note, auth.uid());
  update public.fin_proposals
    set current_version = v_version,
        status = case when v_version = 1 then 'submitted' else 'revised' end,
        updated_at = now()
    where id = p_proposal;
  update public.fin_rfqs set status = 'collecting', updated_at = now()
    where id = v_row.rfq_id and status = 'open';
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_row.buyer_organization_id, 'proposal', p_proposal,
            case when v_version = 1 then 'proposal_submitted' else 'proposal_revised' end,
            auth.uid(), jsonb_build_object('version', v_version));
  return v_version;
end $$;


ALTER FUNCTION public.fin_submit_proposal(p_proposal uuid, p_terms jsonb, p_note text) OWNER TO postgres;

--
-- Name: fin_supersede_approval(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_supersede_approval(p_request uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.fin_approval_requests%rowtype;
begin
  select * into v_request from public.fin_approval_requests where id = p_request;
  if not found then raise exception 'approval not found'; end if;
  perform 1 from public.fin_rfqs where id = v_request.rfq_id for update;
  select * into v_request from public.fin_approval_requests where id = p_request for update;
  if not public.fin_has_role(v_request.organization_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_request.status <> 'pending' then raise exception 'approval not pending'; end if;
  if length(trim(coalesce(p_reason,''))) not between 3 and 1000 or p_reason ~ '[<>]' then raise exception 'approval comment required'; end if;
  update public.fin_approval_requests set status = 'superseded', resolved_at = now(), resolution_note = trim(p_reason) where id = p_request;
  perform public.fin_approval_close_open(p_request, 'superseded');
  update public.fin_policy_exceptions set status = 'cancelled' where request_id = p_request and status = 'requested';
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_request.organization_id, 'rfq', v_request.rfq_id, 'approval_superseded', auth.uid(), jsonb_build_object('request_id', p_request));
end $$;


ALTER FUNCTION public.fin_supersede_approval(p_request uuid, p_reason text) OWNER TO postgres;

--
-- Name: fin_task_actor_can_assign(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_actor_can_assign(p_org uuid, p_entity uuid, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role text;
begin
  select m.role into v_role from public.fin_members m
   where m.organization_id=p_org and m.user_id=p_actor
   for share;
  if not found or v_role not in ('admin','finance_manager') then return false; end if;
  return public.fin_task_assignee_member_valid(p_org,p_entity,p_actor);
end
$$;


ALTER FUNCTION public.fin_task_actor_can_assign(p_org uuid, p_entity uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: fin_task_assignee_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_assignee_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_can_assign boolean := false;
  v_changed boolean;
  v_assignment_changed boolean;
begin
  if tg_op = 'UPDATE' and (new.idempotency_key is distinct from old.idempotency_key
      or new.idempotency_hash is distinct from old.idempotency_hash) then
    raise exception 'task idempotency immutable';
  end if;
  v_changed := tg_op = 'INSERT'
    and (new.assignee_id is not null or new.assignee_source is not null);
  if tg_op = 'UPDATE' then
    v_assignment_changed := new.assignee_id is distinct from old.assignee_id
      or new.assignee_source is distinct from old.assignee_source;
    v_changed := new.assignee_id is distinct from old.assignee_id
      or new.assignee_source is distinct from old.assignee_source
      or new.organization_id is distinct from old.organization_id
      or new.legal_entity_id is distinct from old.legal_entity_id;

    -- A human decision (including an explicit unassignment) is authoritative.
    -- Automatic synchronization must not replace it.
    if old.assignee_source = 'manual' and new.assignee_source = 'inherited' then
      new.assignee_id := old.assignee_id;
      new.assignee_source := old.assignee_source;
      if new.organization_id is not distinct from old.organization_id
         and new.legal_entity_id is not distinct from old.legal_entity_id then
        return new;
      end if;
    end if;
  end if;
  if not v_changed then return new; end if;

  -- The only identity-free UPDATE permitted is the FK action that clears an
  -- assignee after their membership row has been removed.
  if new.assignee_id is null and tg_op = 'UPDATE' and old.assignee_id is not null
     and not exists (
       select 1 from public.fin_members m
        where m.organization_id = old.organization_id and m.user_id = old.assignee_id
     ) then
    if old.assignee_source='inherited' then new.assignee_source := null; end if;
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
    values(new.organization_id,'task',new.id,'task_assignee_cleared',v_actor,new.legal_entity_id,
      jsonb_build_object('task_id',new.id,'previous_assignee_id',old.assignee_id,
        'new_assignee_id',null,'reason','membership_removed'));
    return new;
  end if;

  if new.assignee_source = 'inherited' then
    -- No source-specific synchronization path exists in this migration.
    -- Reject inherited provenance for every caller until one is introduced
    -- with its own source validation; an identity-free/service JWT is not enough.
    raise exception 'forbidden';
  end if;

  if v_actor is not null then
    if v_assignment_changed or tg_op='INSERT' and (new.assignee_id is not null or new.assignee_source is not null) then
      if new.assignee_source = 'manual' then
        null;
      elsif new.assignee_id is null and new.assignee_source is null
         and current_setting('arandu.task_assignee_cleanup',true) = 'trusted' then
        return new;
      else
        raise exception 'forbidden';
      end if;
    end if;
    if (new.assignee_id is not null or new.assignee_source = 'manual')
       and current_setting('arandu.task_assignee_cleanup',true) is distinct from 'trusted' then
      v_can_assign := public.fin_task_actor_can_assign(new.organization_id,new.legal_entity_id,v_actor);
      if not v_can_assign then raise exception 'forbidden'; end if;
      if public.fin_governance_org_locked(new.organization_id) then
        raise exception 'organization offboarding';
      end if;
    end if;
  elsif new.assignee_id is null and current_setting('arandu.task_assignee_cleanup',true) = 'trusted' then
    return new;
  elsif new.assignee_source = 'manual' then
    -- System identities may inherit, but may not forge a human decision.
    raise exception 'forbidden';
  end if;

  if new.assignee_id is not null then
    if not public.fin_task_assignee_member_valid(new.organization_id,new.legal_entity_id,new.assignee_id) then
      raise exception 'invalid task assignee';
    end if;
    if new.assignee_source is null then raise exception 'invalid task assignee'; end if;
  end if;

  if v_actor is not null and tg_op='UPDATE' and (old.assignee_id is distinct from new.assignee_id
      or old.assignee_source is distinct from new.assignee_source)
     and current_setting('arandu.task_assignee_cleanup',true) is distinct from 'trusted' then
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
    values(new.organization_id,'task',new.id,'task_assignee_changed',v_actor,new.legal_entity_id,
      jsonb_build_object('task_id',new.id,'previous_assignee_id',case when tg_op='INSERT' then null else old.assignee_id end,
        'new_assignee_id',new.assignee_id,'source','manual'));
  end if;
  if new.assignee_id is null then return new; end if;
  return new;
end
$$;


ALTER FUNCTION public.fin_task_assignee_guard() OWNER TO postgres;

--
-- Name: fin_task_assignee_insert_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_assignee_insert_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is not null and (new.assignee_id is not null or new.assignee_source='manual') then
    insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
    values(new.organization_id,'task',new.id,'task_assignee_changed',auth.uid(),new.legal_entity_id,
      jsonb_build_object('task_id',new.id,'previous_assignee_id',null,
        'new_assignee_id',new.assignee_id,'source','manual'));
  end if;
  return new;
end
$$;


ALTER FUNCTION public.fin_task_assignee_insert_audit() OWNER TO postgres;

--
-- Name: fin_task_assignee_member_valid(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_assignee_member_valid(p_org uuid, p_entity uuid, p_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_member public.fin_members%rowtype;
begin
  select m.* into v_member from public.fin_members m
   where m.organization_id=p_org and m.user_id=p_user
   for share;
  if not found or v_member.role not in ('admin','finance_manager','analyst') then return false; end if;
  if v_member.entity_scope='group' then return true; end if;
  if p_entity is null then return false; end if;
  perform 1
    from public.fin_legal_entities e
    join public.fin_member_entity_grants g
      on g.organization_id=e.organization_id and g.user_id=p_user
     and (g.entity_id=e.id or g.entity_id=e.parent_id)
   where e.organization_id=p_org and e.id=p_entity
   for key share of g;
  return found;
end
$$;


ALTER FUNCTION public.fin_task_assignee_member_valid(p_org uuid, p_entity uuid, p_user uuid) OWNER TO postgres;

--
-- Name: fin_task_clear_invalid_assignee(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_clear_invalid_assignee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_actor uuid := auth.uid();
  v_subject text := current_setting('request.jwt.claim.sub',true);
  v_claims text := current_setting('request.jwt.claims',true);
begin
  for r in select t.id,t.organization_id,t.legal_entity_id,t.assignee_id,t.assignee_source
             from public.fin_tasks t
            where t.organization_id=old.organization_id and t.assignee_id=old.user_id
            for update
  loop
    if not public.fin_task_assignee_member_valid(r.organization_id,r.legal_entity_id,r.assignee_id) then
      -- A revoked member/scope cannot retain an assignment. This transaction-
      -- local marker permits only this trigger to clear inherited provenance.
      -- The linked-entity guard must also see an identity-free internal write:
      -- the actor may have just lost the entity grant being revoked.
      perform set_config('request.jwt.claim.sub','',true);
      perform set_config('request.jwt.claims','{"role":"service_role"}',true);
      perform set_config('arandu.task_assignee_cleanup','trusted',true);
      update public.fin_tasks set assignee_id=null,
        assignee_source=case when assignee_source='inherited' then null else assignee_source end
       where id=r.id;
      insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata)
      values(r.organization_id,'task',r.id,'task_assignee_cleared',v_actor,r.legal_entity_id,
        jsonb_build_object('task_id',r.id,'previous_assignee_id',r.assignee_id,
          'new_assignee_id',null,'reason','membership_scope_changed'));
      perform set_config('arandu.task_assignee_cleanup','',true);
      perform set_config('request.jwt.claim.sub',coalesce(v_subject,''),true);
      perform set_config('request.jwt.claims',coalesce(v_claims,''),true);
    end if;
  end loop;
  return null;
end
$$;


ALTER FUNCTION public.fin_task_clear_invalid_assignee() OWNER TO postgres;

--
-- Name: fin_task_entity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_task_entity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.related_type is distinct from old.related_type or new.related_id is distinct from old.related_id then
    new.legal_entity_id := case when new.related_type is null or new.related_id is null then null
      else public.fin_object_legal_entity(new.related_type, new.related_id) end;
  end if;
  if tg_op = 'UPDATE' then perform public.fin_assert_entity_write(old.organization_id, old.legal_entity_id); end if;
  -- Tarefa avulsa (sem objeto) de quem a cria continua permitida a qualquer escopo.
  if not (new.related_type is null and new.created_by = auth.uid()) then
    perform public.fin_assert_entity_write(new.organization_id, new.legal_entity_id);
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_task_entity_guard() OWNER TO postgres;

--
-- Name: fin_transition(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_transition(p_kind text, p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid;
begin
  if p_kind = 'rfq' then
    select organization_id into v_org from public.fin_rfqs where id = p_id;
    if v_org is null then raise exception 'not found'; end if;
    if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
    update public.fin_rfqs set status = p_status, updated_at = now()
      where id = p_id and (status, p_status) in (
        ('draft','open'), ('draft','cancelled'),
        ('open','collecting'), ('open','cancelled'),
        ('collecting','comparing'), ('collecting','cancelled'),
        ('comparing','collecting'), ('comparing','cancelled'),
        ('decided','contracted'), ('decided','closed'),
        ('contracted','closed')
      );
  elsif p_kind = 'contract' then
    select organization_id into v_org from public.fin_contracts where id = p_id;
    if v_org is null then raise exception 'not found'; end if;
    if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
    update public.fin_contracts set status = p_status, updated_at = now()
      where id = p_id and (status, p_status) in (
        ('active','renewing'), ('active','expired'), ('active','terminated'),
        ('renewing','active'), ('renewing','expired'), ('renewing','terminated')
      );
  else
    raise exception 'invalid transition';
  end if;
  if not found then raise exception 'invalid transition'; end if;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (v_org, p_kind, p_id, p_kind || '_' || p_status, auth.uid());
end $$;


ALTER FUNCTION public.fin_transition(p_kind text, p_id uuid, p_status text) OWNER TO postgres;

--
-- Name: fin_transition_opportunity(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_transition_opportunity(p_id uuid, p_expected text, p_input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.fin_opportunities%rowtype; v_to text := p_input->>'to_status'; v_reviewer uuid; v_cooldown integer;
begin
  select * into o from public.fin_opportunities where id = p_id for update;
  if o.id is null or auth.uid() is null or not public.fin_entity_allows(o.organization_id, o.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(o.organization_id) then raise exception 'organization offboarding'; end if;
  if p_expected is distinct from o.status then raise exception 'opportunity state conflict'; end if;
  if not ((o.status = 'open' and v_to in ('acknowledged','under_review','dismissed'))
       or (o.status = 'acknowledged' and v_to in ('under_review','acted','dismissed'))
       or (o.status = 'under_review' and v_to in ('acted','dismissed'))) then raise exception 'invalid opportunity transition'; end if;
  -- Under review, only the assigned reviewer or an admin closes it.
  if o.status = 'under_review' and auth.uid() is distinct from o.reviewer_id and not public.fin_has_role(o.organization_id, array['admin']) then raise exception 'invalid opportunity reviewer'; end if;
  if v_to = 'under_review' then
    v_reviewer := coalesce(nullif(p_input->>'reviewer_id', '')::uuid, auth.uid());
    -- The reviewer must be able to act on the opportunity's entity scope.
    if not exists (select 1 from public.fin_members m where m.organization_id = o.organization_id and m.user_id = v_reviewer and m.role in ('admin','finance_manager')
         and (m.entity_scope = 'group' or (o.legal_entity_id is not null and exists (select 1 from public.fin_legal_entities e
           join public.fin_member_entity_grants g on g.organization_id = e.organization_id and g.user_id = m.user_id and (g.entity_id = e.id or g.entity_id = e.parent_id)
           where e.organization_id = o.organization_id and e.id = o.legal_entity_id)))) then raise exception 'invalid opportunity reviewer'; end if;
  end if;
  if (v_to = 'dismissed' and (p_input->>'dismissal_reason' is null or p_input->>'dismissal_reason' not in ('not_relevant','already_handled','data_incorrect','accepted_risk','duplicate','other')))
     or (v_to = 'acted' and length(trim(coalesce(p_input->>'resolution', ''))) not between 3 and 1000)
     or (p_input ? 'note' and (length(trim(coalesce(p_input->>'note', ''))) not between 1 and 1000 or p_input->>'note' ~ '[<>]')) then raise exception 'invalid opportunity transition'; end if;
  v_cooldown := coalesce((o.rule_snapshot->'parameters'->>'cooldown_days')::int, 0);
  begin
    update public.fin_opportunities set status = v_to,
      reviewer_id = case when v_to = 'under_review' then v_reviewer else reviewer_id end,
      resolution = case when v_to = 'acted' then trim(p_input->>'resolution') else resolution end,
      dismissal_reason = case when v_to = 'dismissed' then p_input->>'dismissal_reason' else dismissal_reason end,
      closed_at = case when v_to in ('acted','dismissed') then now() end, closed_by = case when v_to in ('acted','dismissed') then auth.uid() end,
      closed_facts_hash = case when v_to in ('acted','dismissed') then facts_hash end,
      cooldown_until = case when v_to in ('acted','dismissed') then now() + make_interval(days => v_cooldown) end
    where id = o.id;
  exception when check_violation then raise exception 'invalid opportunity transition';
  end;
  insert into public.fin_opportunity_events(organization_id, opportunity_id, event_type, from_status, to_status, actor_id, note)
    values (o.organization_id, o.id, case v_to when 'acknowledged' then 'acknowledged' when 'under_review' then 'review_started' when 'acted' then 'acted' else 'dismissed' end,
      o.status, v_to, auth.uid(), nullif(trim(coalesce(p_input->>'note', p_input->>'resolution', '')), ''));
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (o.organization_id, 'opportunity', o.id, 'opportunity_' || v_to, auth.uid(), jsonb_build_object('type', o.opportunity_type, 'from', o.status, 'rule_version', o.rule_version));
  return v_to;
end $$;


ALTER FUNCTION public.fin_transition_opportunity(p_id uuid, p_expected text, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_transition_provider_qualification(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_transition_provider_qualification(p_qualification uuid, p_expected text, p_input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.fin_provider_qualifications%rowtype; v_to text := p_input->>'to_status'; v_reason text := nullif(trim(coalesce(p_input->>'reason', '')), ''); v_cond text := nullif(trim(coalesce(p_input->>'conditions', '')), '');
        v_ready record; v_until date;
begin
  select * into q from public.fin_provider_qualifications where id = p_qualification for update;
  if q.id is null or auth.uid() is null or not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager','analyst']) then raise exception 'forbidden'; end if;
  if v_to in ('qualified','qualified_with_conditions','rejected','suspended') and not public.fin_entity_allows(q.organization_id, q.legal_entity_id, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(q.organization_id) then raise exception 'organization offboarding'; end if;
  if p_expected is distinct from q.status then raise exception 'qualification state conflict'; end if;
  if not (v_to = any (case q.status
      when 'not_started' then array['in_progress'] when 'in_progress' then array['pending_provider','pending_internal_review']
      when 'pending_provider' then array['in_progress','pending_internal_review'] when 'pending_internal_review' then array['qualified','qualified_with_conditions','rejected','in_progress']
      when 'qualified' then array['suspended','expired','in_progress'] when 'qualified_with_conditions' then array['suspended','expired','in_progress']
      when 'suspended' then array['in_progress','rejected'] when 'rejected' then array['in_progress'] when 'expired' then array['in_progress'] else array[]::text[] end)) then raise exception 'invalid qualification transition'; end if;
  if (v_to in ('qualified','qualified_with_conditions','rejected','suspended') or (v_to = 'in_progress' and q.status in ('rejected','suspended','expired'))) and (v_reason is null or length(v_reason) not between 10 and 2000 or v_reason ~ '[<>]') then raise exception 'invalid qualification transition'; end if;
  if v_to = 'qualified_with_conditions' and (v_cond is null or length(v_cond) not between 10 and 2000 or v_cond ~ '[<>]') then raise exception 'invalid qualification transition'; end if;
  if v_to in ('qualified','qualified_with_conditions') then
    select * into v_ready from public.fin_qualification_readiness(q.id);
    if v_ready.missing > 0 then raise exception 'qualification requirements missing'; end if;
    if v_to = 'qualified' and v_ready.excepted > 0 then raise exception 'qualification has exceptions'; end if;
    v_until := least(v_ready.valid_until, nullif(p_input->>'valid_until', '')::date);
    if v_until is not null and v_until < current_date then raise exception 'invalid qualification transition'; end if;
  end if;
  update public.fin_provider_qualifications set status = v_to, updated_at = now(),
    conditions = case when v_to = 'qualified_with_conditions' then v_cond else null end,
    valid_until = case when v_to in ('qualified','qualified_with_conditions') then v_until when v_to in ('in_progress','rejected') then null else valid_until end,
    decided_by = case when v_to in ('qualified','qualified_with_conditions','rejected','suspended') then auth.uid() else decided_by end,
    decided_at = case when v_to in ('qualified','qualified_with_conditions','rejected','suspended') then now() else decided_at end,
    decision_reason = case when v_to in ('qualified','qualified_with_conditions','rejected','suspended') then v_reason else decision_reason end
  where id = q.id;
  insert into public.fin_qualification_events(organization_id, qualification_id, event_type, from_status, to_status, reason, actor_id) values (q.organization_id, q.id, 'transition', q.status, v_to, v_reason, auth.uid());
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
  values (q.organization_id, 'provider', q.provider_id, 'provider_qualification_' || v_to, auth.uid(), jsonb_build_object('qualification_id', q.id, 'from', q.status));
  return v_to;
end $$;


ALTER FUNCTION public.fin_transition_provider_qualification(p_qualification uuid, p_expected text, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_try_numeric(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_try_numeric(p_value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p_value is null or p_value !~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' then return null; end if;
  return p_value::numeric;
end $_$;


ALTER FUNCTION public.fin_try_numeric(p_value text) OWNER TO postgres;

--
-- Name: fin_update_implementation_milestone(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_implementation_milestone(p_milestone uuid, p_expected integer, p_input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m public.fin_implementation_milestones%rowtype; p public.fin_implementation_plans%rowtype; v_status text; v_owner uuid; v_doc uuid;
begin
 select * into m from public.fin_implementation_milestones where id=p_milestone;
 p:=public.fin_implementation_require(m.plan_id,array['admin','finance_manager','analyst']);
 select * into m from public.fin_implementation_milestones where id=p_milestone for update;
 if p_expected is null or m.version<>p_expected then raise exception 'implementation conflict'; end if;
 if p.status in ('accepted','cancelled') or m.status='completed' then raise exception 'implementation closed'; end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('status','owner_id','due_on','evidence_reference','document_id','blocker')) then raise exception 'invalid implementation input'; end if;
 v_status:=coalesce(p_input->>'status',m.status); v_owner:=coalesce(nullif(p_input->>'owner_id','')::uuid,m.owner_id); v_doc:=nullif(p_input->>'document_id','')::uuid;
 if not public.fin_implementation_owner_valid(p.organization_id,p.legal_entity_id,v_owner) then raise exception 'invalid implementation owner'; end if;
 if v_doc is not null and not(public.fin_can_read_document(v_doc) and exists(select 1 from public.fin_private_documents d where d.id=v_doc and d.buyer_organization_id=p.organization_id and d.entity_type='contract' and d.entity_id=p.contract_id)) then raise exception 'invalid implementation evidence'; end if;
 if v_status in ('in_progress','completed') and exists(select 1 from public.fin_implementation_dependencies d join public.fin_implementation_milestones dep on dep.id=d.depends_on_id where d.milestone_id=m.id and dep.status<>'completed') then raise exception 'implementation dependency pending'; end if;
 update public.fin_implementation_milestones set status=v_status,owner_id=v_owner,due_on=coalesce(nullif(p_input->>'due_on','')::date,due_on),evidence_reference=coalesce(nullif(trim(p_input->>'evidence_reference'),''),evidence_reference),document_id=coalesce(v_doc,document_id),blocker=case when v_status='blocked' then nullif(trim(p_input->>'blocker'),'') else null end,completed_at=case when v_status='completed' then now() end,version=version+1 where id=m.id;
 update public.fin_tasks set status=case when v_status='completed' then 'done' else 'open' end,due_on=coalesce(nullif(p_input->>'due_on','')::date,due_on) where id=m.task_id;
 update public.fin_implementation_plans set status=case when exists(select 1 from public.fin_implementation_milestones where plan_id=p.id and status='blocked') or exists(select 1 from public.fin_implementation_issues where plan_id=p.id and status='open') then 'blocked' when not exists(select 1 from public.fin_implementation_milestones where plan_id=p.id and status<>'completed') then 'ready_for_acceptance' else 'in_progress' end,version=version+1,updated_at=now() where id=p.id;
 insert into public.fin_events(organization_id,entity_type,entity_id,event_type,actor_id,legal_entity_id,metadata) values(p.organization_id,'contract',p.contract_id,'implementation_milestone_changed',auth.uid(),p.legal_entity_id,jsonb_build_object('milestone_id',m.id,'from',m.status,'to',v_status));
end $$;


ALTER FUNCTION public.fin_update_implementation_milestone(p_milestone uuid, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_update_legal_entity(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_legal_entity(p_entity uuid, p_legal_name text, p_short_name text DEFAULT NULL::text, p_currency text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_legal_entities%rowtype;
begin
  select * into v from public.fin_legal_entities where id = p_entity for update;
  if not found or not public.fin_has_role(v.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if p_status is not null and p_status not in ('active','archived') then raise exception 'invalid legal entity'; end if;
  -- Arquivar não apaga: processos e contratos continuam lá, com histórico;
  -- a entidade só deixa de aceitar processos novos.
  if p_status = 'archived' and v.kind = 'legal_entity' and exists (
       select 1 from public.fin_legal_entities c where c.organization_id = v.organization_id and c.parent_id = v.id and c.status = 'active') then
    raise exception 'legal entity has active units';
  end if;
  update public.fin_legal_entities set
    legal_name = coalesce(nullif(trim(coalesce(p_legal_name,'')),''), legal_name),
    short_name = case when p_short_name is null then short_name else nullif(trim(p_short_name),'') end,
    currency = coalesce(upper(p_currency), currency),
    status = coalesce(p_status, status),
    archived_at = case when coalesce(p_status, status) = 'archived' then coalesce(archived_at, now()) else null end,
    updated_at = now()
  where id = p_entity;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
  values (v.organization_id, 'legal_entity', p_entity,
          case when p_status is not null and p_status <> v.status then 'legal_entity_' || p_status else 'legal_entity_updated' end,
          auth.uid(), jsonb_build_object('currency_changed', p_currency is not null and upper(p_currency) <> v.currency), p_entity);
exception when check_violation then raise exception 'invalid legal entity';
end $$;


ALTER FUNCTION public.fin_update_legal_entity(p_entity uuid, p_legal_name text, p_short_name text, p_currency text, p_status text) OWNER TO postgres;

--
-- Name: fin_update_my_member_profile(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_my_member_profile(p_org uuid, p_display_name text, p_job_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then raise exception 'forbidden'; end if;
  update public.fin_members
     set display_name = nullif(trim(p_display_name), ''), job_title = nullif(trim(p_job_title), '')
   where organization_id = p_org and user_id = auth.uid();
  if not found then raise exception 'forbidden'; end if;
end $$;


ALTER FUNCTION public.fin_update_my_member_profile(p_org uuid, p_display_name text, p_job_title text) OWNER TO postgres;

--
-- Name: fin_update_organization(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_organization(p_org uuid, p_trade_name text DEFAULT NULL::text, p_tax_identifier text DEFAULT NULL::text, p_sector text DEFAULT NULL::text, p_revenue_band text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if not public.fin_has_role(p_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if p_tax_identifier is not null and p_tax_identifier !~ '^[0-9]{14}$' then raise exception 'invalid tax identifier'; end if;
  if p_revenue_band is not null and p_revenue_band not in ('ate_360k','360k_4_8m','4_8m_30m','30m_300m','acima_300m') then
    raise exception 'invalid revenue band';
  end if;
  update public.fin_organizations
    set trade_name = coalesce(nullif(trim(coalesce(p_trade_name,'')),''), trade_name),
        tax_identifier = coalesce(p_tax_identifier, tax_identifier),
        sector = coalesce(nullif(trim(coalesce(p_sector,'')),''), sector),
        revenue_band = coalesce(p_revenue_band, revenue_band)
    where id = p_org;
  if not found then raise exception 'not found'; end if;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id)
    values (p_org, 'organization', p_org, 'organization_updated', auth.uid());
end $_$;


ALTER FUNCTION public.fin_update_organization(p_org uuid, p_trade_name text, p_tax_identifier text, p_sector text, p_revenue_band text) OWNER TO postgres;

--
-- Name: fin_update_provider_issue(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_provider_issue(p_issue uuid, p_status text, p_resolution text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.fin_provider_issues%rowtype;
begin
  select * into v from public.fin_provider_issues where id = p_issue for update;
  if not found then raise exception 'issue not found'; end if;
  perform public.fin_assert_portfolio_write(v.organization_id, v.legal_entity_id);
  if v.status in ('resolved','cancelled') then raise exception 'issue closed'; end if;
  if p_status not in ('in_progress','resolved','cancelled') then raise exception 'invalid issue'; end if;
  if p_status = 'resolved' and length(trim(coalesce(p_resolution,''))) < 3 then raise exception 'resolution required'; end if;
  update public.fin_provider_issues set status = p_status, updated_at = now(),
      resolved_at = case when p_status in ('resolved','cancelled') then now() else null end,
      resolution = coalesce(nullif(trim(coalesce(p_resolution,'')),''), resolution)
   where id = p_issue;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata, legal_entity_id)
    values (v.organization_id, 'provider', v.provider_id, 'provider_issue_' || p_status, auth.uid(), jsonb_build_object('issue_id', v.id), v.legal_entity_id);
exception when check_violation then raise exception 'invalid issue';
end $$;


ALTER FUNCTION public.fin_update_provider_issue(p_issue uuid, p_status text, p_resolution text) OWNER TO postgres;

--
-- Name: fin_update_rfq_demand(uuid, text, text, jsonb, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_rfq_demand(p_rfq uuid, p_title text, p_description text, p_demand jsonb, p_deadline date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_org uuid; v_status text;
begin
  if jsonb_typeof(coalesce(p_demand,'null'::jsonb)) is distinct from 'object' then raise exception 'invalid demand'; end if;
  select organization_id, status into v_org, v_status from public.fin_rfqs where id = p_rfq for update;
  if v_org is null then raise exception 'not found'; end if;
  if not public.fin_has_role(v_org, array['admin','finance_manager']) then raise exception 'forbidden'; end if;
  if v_status not in ('draft','open') then raise exception 'invalid state'; end if;
  update public.fin_rfqs
    set title = coalesce(nullif(trim(coalesce(p_title,'')),''), title),
        description = p_description, demand = p_demand, response_deadline = p_deadline, updated_at = now()
    where id = p_rfq;
  insert into public.fin_events (organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (v_org, 'rfq', p_rfq,
            case when v_status = 'open' then 'rfq_demand_updated_after_open' else 'rfq_demand_updated' end,
            auth.uid(), jsonb_build_object('status', v_status));
end $$;


ALTER FUNCTION public.fin_update_rfq_demand(p_rfq uuid, p_title text, p_description text, p_demand jsonb, p_deadline date) OWNER TO postgres;

--
-- Name: fin_update_service_account(uuid, text[], text, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_update_service_account(p_account uuid, p_scopes text[], p_entity_scope text, p_entities uuid[], p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.fin_service_accounts%rowtype; x uuid;
begin
  select * into a from public.fin_service_accounts where id = p_account for update;
  if not found or not public.fin_has_role(a.organization_id, array['admin']) then raise exception 'forbidden'; end if;
  if a.status = 'revoked' then raise exception 'service account revoked'; end if;
  if p_scopes is null or cardinality(p_scopes) = 0 or not (p_scopes <@ public.fin_api_scope_catalog())
     or not public.fin_api_valid_entities(a.organization_id, coalesce(p_entity_scope, ''), p_entities) or coalesce(p_status, '') not in ('active','disabled') then
    raise exception 'invalid service account';
  end if;
  update public.fin_service_accounts set scopes = (select array_agg(distinct s order by s) from unnest(p_scopes) s), entity_scope = p_entity_scope,
         status = p_status, updated_at = now() where id = p_account;
  delete from public.fin_service_account_entities where service_account_id = p_account;
  foreach x in array coalesce(p_entities, '{}'::uuid[]) loop
    insert into public.fin_service_account_entities(organization_id, service_account_id, entity_id, granted_by) values (a.organization_id, p_account, x, auth.uid());
  end loop;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (a.organization_id, 'service_account', p_account, 'service_account_updated', auth.uid(),
            jsonb_build_object('scopes', p_scopes, 'entity_scope', p_entity_scope, 'status', p_status, 'entities', coalesce(cardinality(p_entities), 0)));
end $$;


ALTER FUNCTION public.fin_update_service_account(p_account uuid, p_scopes text[], p_entity_scope text, p_entities uuid[], p_status text) OWNER TO postgres;

--
-- Name: fin_valid_contract_terms(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_valid_contract_terms(p_terms jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select jsonb_typeof(p_terms) = 'object'
     and length(p_terms::text) <= 32000
     and p_terms::text !~ '[<>]'
     and (not p_terms ? 'fees' or (jsonb_typeof(p_terms->'fees') = 'array' and jsonb_array_length(p_terms->'fees') <= 50))
     and (not p_terms ? 'currency' or (p_terms->>'currency') ~ '^[A-Z]{3}$');
$_$;


ALTER FUNCTION public.fin_valid_contract_terms(p_terms jsonb) OWNER TO postgres;

--
-- Name: fin_valid_product_terms(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_valid_product_terms(p_category text, p_terms jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare catalog jsonb := $schema${"bank_guarantee":{"category":"guarantee","family":"guarantees","fields":[{"key":"source_reference","label":"Referência da fonte","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"beneficiary","label":"Beneficiário","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"currency","label":"Moeda","type":"currency","unit":"ISO_4217","required":true},{"key":"guaranteed_amount","label":"Valor garantido","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0.01,"max":1000000000000},{"key":"valid_from","label":"Início da vigência","type":"date","unit":"ISO_date","required":true},{"key":"valid_until","label":"Fim da vigência","type":"date","unit":"ISO_date","required":true},{"key":"commission_pct_year","label":"Comissão anual (%)","type":"number","unit":"percent_per_year","required":true,"decimal_places":8,"min":0,"max":1000},{"key":"day_count","label":"Convenção de dias","type":"enum","unit":"convention","required":true,"options":["ACT/365F","ACT/360"]},{"key":"upfront_fee","label":"Despesa inicial","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0,"max":1000000000},{"key":"other_expenses","label":"Outras despesas iniciais","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0,"max":1000000000}],"methodology":"bank-guarantee-explicit-cost-v1"},"fx_spot":{"category":"fx","family":"fx","fields":[{"key":"source_reference","label":"Referência da fonte","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"base_currency","label":"Moeda base","type":"currency","unit":"ISO_4217","required":true},{"key":"quote_currency","label":"Moeda cotada","type":"currency","unit":"ISO_4217","required":true},{"key":"base_amount","label":"Valor na moeda base","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0.01,"max":1000000000000},{"key":"agreed_rate","label":"Taxa contratada (cotada por base)","type":"number","unit":"quote_per_base","required":true,"decimal_places":8,"min":1e-8,"max":1000000000},{"key":"trade_on","label":"Data de contratação","type":"date","unit":"ISO_date","required":true},{"key":"settles_on","label":"Data de liquidação","type":"date","unit":"ISO_date","required":true},{"key":"side","label":"Direção contratual","type":"enum","unit":"convention","required":true,"options":["buy_base","sell_base"]}],"methodology":null},"fx_forward":{"category":"fx","family":"hedge","fields":[{"key":"source_reference","label":"Referência da fonte","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"base_currency","label":"Moeda base","type":"currency","unit":"ISO_4217","required":true},{"key":"quote_currency","label":"Moeda cotada","type":"currency","unit":"ISO_4217","required":true},{"key":"base_amount","label":"Valor na moeda base","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0.01,"max":1000000000000},{"key":"agreed_rate","label":"Taxa contratada (cotada por base)","type":"number","unit":"quote_per_base","required":true,"decimal_places":8,"min":1e-8,"max":1000000000},{"key":"trade_on","label":"Data de contratação","type":"date","unit":"ISO_date","required":true},{"key":"settles_on","label":"Data de liquidação","type":"date","unit":"ISO_date","required":true},{"key":"side","label":"Direção contratual","type":"enum","unit":"convention","required":true,"options":["buy_base","sell_base"]}],"methodology":null},"ndf":{"category":"fx","family":"hedge","fields":[{"key":"source_reference","label":"Referência da fonte","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"base_currency","label":"Moeda base","type":"currency","unit":"ISO_4217","required":true},{"key":"quote_currency","label":"Moeda cotada","type":"currency","unit":"ISO_4217","required":true},{"key":"base_amount","label":"Valor na moeda base","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0.01,"max":1000000000000},{"key":"agreed_rate","label":"Taxa contratada (cotada por base)","type":"number","unit":"quote_per_base","required":true,"decimal_places":8,"min":1e-8,"max":1000000000},{"key":"trade_on","label":"Data de contratação","type":"date","unit":"ISO_date","required":true},{"key":"settles_on","label":"Data de liquidação","type":"date","unit":"ISO_date","required":true},{"key":"side","label":"Direção contratual","type":"enum","unit":"convention","required":true,"options":["buy_base","sell_base"]},{"key":"fixing_on","label":"Data de fixação","type":"date","unit":"ISO_date","required":true},{"key":"settlement_currency","label":"Moeda de liquidação","type":"currency","unit":"ISO_4217","required":true},{"key":"fixing_source","label":"Fonte de fixação","type":"text","unit":"declared_text","required":true,"maxLength":200}],"methodology":null},"swap":{"category":"fx","family":"hedge","fields":[{"key":"source_reference","label":"Referência da fonte","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"currency","label":"Moeda","type":"currency","unit":"ISO_4217","required":true},{"key":"notional","label":"Valor nocional","type":"number","unit":"currency_amount","required":true,"decimal_places":2,"min":0.01,"max":1000000000000},{"key":"starts_on","label":"Início","type":"date","unit":"ISO_date","required":true},{"key":"ends_on","label":"Fim","type":"date","unit":"ISO_date","required":true},{"key":"pay_index","label":"Indexador da perna pagadora","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"receive_index","label":"Indexador da perna recebedora","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"pay_spread_pct_year","label":"Spread pagador (% a.a.)","type":"number","unit":"percent_per_year","required":true,"decimal_places":8,"min":0,"max":1000},{"key":"receive_spread_pct_year","label":"Spread recebedor (% a.a.)","type":"number","unit":"percent_per_year","required":true,"decimal_places":8,"min":0,"max":1000},{"key":"day_count","label":"Convenção de dias","type":"enum","unit":"convention","required":true,"options":["ACT/365F","ACT/360","30E/360"]},{"key":"payment_frequency","label":"Periodicidade contratual","type":"text","unit":"declared_text","required":true,"maxLength":200},{"key":"notional_exchange","label":"Troca de principal","type":"enum","unit":"convention","required":true,"options":["none","initial_final","final"]}],"methodology":null}}$schema$::jsonb; s jsonb; f jsonb; v jsonb; k text; vals jsonb; d date;
begin
 if jsonb_typeof(p_terms) is distinct from 'object' or length(p_terms::text)>16000 or p_terms->>'schema_version' is distinct from 'financial-product-terms-1' or p_terms::text ~ '[<>]' then return false; end if;
 if exists(select 1 from jsonb_object_keys(p_terms) x where x not in ('schema_version','modality','values')) then return false; end if;
 s:=catalog->(p_terms->>'modality');
 if s is null or s->>'category' is distinct from p_category or jsonb_typeof(p_terms->'values') is distinct from 'object' then return false; end if;
 vals:=p_terms->'values';
 for k in select jsonb_object_keys(vals) loop
  if not exists(select 1 from jsonb_array_elements(s->'fields') x where x->>'key'=k) then return false; end if;
 end loop;
 for f in select * from jsonb_array_elements(s->'fields') loop
  k:=f->>'key'; v:=vals->k;
  if v is null then if (f->>'required')::boolean then return false; else continue; end if; end if;
  if f->>'type'='number' then
   if jsonb_typeof(v) is distinct from 'number' then return false; end if;
   if (v#>>'{}')::numeric<>round((v#>>'{}')::numeric,(f->>'decimal_places')::int) then return false; end if;
   if (v#>>'{}')::numeric<(f->>'min')::numeric or (v#>>'{}')::numeric>(f->>'max')::numeric then return false; end if;
  else
   if jsonb_typeof(v) is distinct from 'string' then return false; end if;
   if f->>'type'='text' and (length(trim(v#>>'{}'))<2 or length(v#>>'{}')>(f->>'maxLength')::int or (v#>>'{}') ~ '[[:cntrl:]]') then return false; end if;
   if f->>'type'='currency' and (v#>>'{}') !~ '^[A-Z]{3}$' then return false; end if;
   if f->>'type'='enum' and not (f->'options' @> jsonb_build_array(v)) then return false; end if;
   if f->>'type'='date' then
    if (v#>>'{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
    d:=(v#>>'{}')::date;
    if d<'1950-01-01'::date or d>'2150-12-31'::date or to_char(d,'YYYY-MM-DD')<>v#>>'{}' then return false; end if;
   end if;
  end if;
 end loop;
 if vals->>'valid_from'>vals->>'valid_until' or vals->>'trade_on'>vals->>'settles_on' or vals->>'starts_on'>vals->>'ends_on' or vals->>'trade_on'>vals->>'fixing_on' or vals->>'fixing_on'>vals->>'settles_on' then return false; end if;
 if vals->>'base_currency'=vals->>'quote_currency' then return false; end if;
 if p_terms->>'modality'='ndf' and vals->>'settlement_currency' not in (vals->>'base_currency',vals->>'quote_currency') then return false; end if;
 return true;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then return false;
end $_$;


ALTER FUNCTION public.fin_valid_product_terms(p_category text, p_terms jsonb) OWNER TO postgres;

--
-- Name: fin_valid_webhook_url(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_valid_webhook_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  -- Só https público: sem credencial, sem porta diferente de 443, sem IP literal
  -- privado/loopback e sem localhost. A resolução DNS é reconferida na entrega.
  select p_url ~ '^https://[^/@:?#\s]+(:443)?(/[^\s]*)?$'
     and length(p_url) between 12 and 500
     and lower(split_part(split_part(substr(p_url, 9), '/', 1), ':', 1)) !~ '^(localhost|.*\.localhost|.*\.local|.*\.internal|0\.0\.0\.0|127\.[0-9.]+|10\.[0-9.]+|192\.168\.[0-9.]+|172\.(1[6-9]|2[0-9]|3[01])\.[0-9.]+|169\.254\.[0-9.]+|100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.[0-9.]+|\[.*\]|[0-9]+)$';
$_$;


ALTER FUNCTION public.fin_valid_webhook_url(p_url text) OWNER TO postgres;

--
-- Name: fin_value_record_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_value_record_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (to_jsonb(new)-array['status','invalidation_reason','invalidated_by','invalidated_at'])
      is distinct from (to_jsonb(old)-array['status','invalidation_reason','invalidated_by','invalidated_at'])
     or old.status<>'active' or new.status<>'invalidated'
     or length(trim(coalesce(new.invalidation_reason,''))) not between 3 and 1000
     or new.invalidation_reason ~ '[<>]' or new.invalidated_by is null or new.invalidated_at is null then
    raise exception 'immutable record';
  end if;
  return new;
end $$;


ALTER FUNCTION public.fin_value_record_guard() OWNER TO postgres;

--
-- Name: fin_value_totals(uuid, date, date, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_value_totals(p_org uuid, p_start date, p_end date, p_kind text DEFAULT NULL::text, p_currency text DEFAULT NULL::text, p_entity uuid DEFAULT NULL::uuid, p_provider uuid DEFAULT NULL::uuid, p_product text DEFAULT NULL::text) RETURNS TABLE(kind text, currency text, records bigint, comparable bigint, value_amount numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_org is null or auth.uid() is null or not public.fin_has_role(p_org,array['admin','finance_manager','analyst','viewer']) then raise exception 'forbidden'; end if;
  if p_start is null or p_end is null or p_end<p_start or p_end-p_start>366*5 then raise exception 'invalid value filters'; end if;
  if p_product is not null and p_product not in ('credit','acquiring') then raise exception 'invalid value filters'; end if;
  return query select r.kind,r.currency,count(*),count(r.value_amount),sum(r.value_amount) from public.fin_value_records r
   where r.organization_id=p_org and r.status='active' and r.period_start>=p_start and r.period_end<=p_end
   and (p_kind is null or r.kind=p_kind) and (p_currency is null or r.currency=p_currency) and (p_entity is null or r.legal_entity_id=p_entity)
   and (p_product is null or r.product=p_product) and (p_provider is null or r.provider_id=p_provider) group by r.kind,r.currency;
end $$;


ALTER FUNCTION public.fin_value_totals(p_org uuid, p_start date, p_end date, p_kind text, p_currency text, p_entity uuid, p_provider uuid, p_product text) OWNER TO postgres;

--
-- Name: fin_verify_fee_observation(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_verify_fee_observation(p_observation uuid, p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare x public.fin_fee_observations%rowtype;
begin
  select * into x from public.fin_fee_observations where id = p_observation for update;
  if x.id is null or auth.uid() is null or not public.fin_entity_allows(x.organization_id, x.legal_entity_id, array['admin','finance_manager'])
     or not exists (select 1 from public.fin_contracts c where c.organization_id = x.organization_id and c.id = x.contract_id and public.fin_entity_allows(c.organization_id, c.legal_entity_id, array['admin','finance_manager'])) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(x.organization_id) then raise exception 'organization offboarding'; end if;
  if x.verification_status <> 'unverified' then raise exception 'fee observation already verified'; end if;
  if p_input->>'status' is null or p_input->>'status' not in ('verified','rejected') or length(trim(coalesce(p_input->>'reason', ''))) not between 3 and 1000 or p_input->>'reason' ~ '[<>]' then raise exception 'invalid fee verification'; end if;
  update public.fin_fee_observations set verification_status = p_input->>'status', verified_by = auth.uid(), verified_at = now(), verification_reason = trim(p_input->>'reason') where id = x.id;
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (x.organization_id, 'contract', x.contract_id, 'fee_observation_verified', auth.uid(), jsonb_build_object('observation_id', x.id, 'status', p_input->>'status'));
  return x.id;
end $$;


ALTER FUNCTION public.fin_verify_fee_observation(p_observation uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_version_fee_schedule(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_version_fee_schedule(p_schedule uuid, p_expected integer, p_input jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.fin_fee_schedules%rowtype;
begin
  select * into s from public.fin_fee_schedules where id = p_schedule for update;
  if s.id is null or auth.uid() is null or not public.fin_entity_allows(s.organization_id, s.legal_entity_id, array['admin','finance_manager'])
     or not exists (select 1 from public.fin_contracts c where c.organization_id = s.organization_id and c.id = s.contract_id and public.fin_entity_allows(c.organization_id, c.legal_entity_id, array['admin','finance_manager'])) then raise exception 'forbidden'; end if;
  if public.fin_governance_org_locked(s.organization_id) then raise exception 'organization offboarding'; end if;
  if p_expected is distinct from s.current_version then raise exception 'fee schedule version conflict'; end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or length(p_input::text) > 6000 then raise exception 'invalid fee schedule'; end if;
  perform public.fin_insert_fee_version(s, p_input, s.current_version + 1);
  insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
    values (s.organization_id, 'contract', s.contract_id, 'fee_schedule_versioned', auth.uid(), jsonb_build_object('schedule_id', s.id, 'version', s.current_version + 1));
  return s.current_version + 1;
end $$;


ALTER FUNCTION public.fin_version_fee_schedule(p_schedule uuid, p_expected integer, p_input jsonb) OWNER TO postgres;

--
-- Name: fin_webhook_capture(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_webhook_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_type text; v_object text; v_data jsonb; v_event uuid; v_status text; v_entity uuid;
begin
  if not exists (select 1 from public.fin_webhook_endpoints e where e.organization_id = new.organization_id and e.status = 'active') then return new; end if;
  v_type := case
    when new.event_type in ('rfq_created','rfq_created_from_contract') then 'rfq.created'
    when new.entity_type = 'rfq' and new.event_type ~ '^rfq_(draft|open|collecting|comparing|decided|contracted|cancelled|closed)$' then 'rfq.status_changed'
    when new.event_type in ('proposal_submitted','proposal_revised') then 'proposal.submitted'
    when new.event_type = 'decision_recorded' then 'decision.recorded'
    when new.event_type = 'approval_requested' then 'approval.required'
    when new.event_type in ('approval_completed','approval_rejected','approval_changes_requested','approval_expired') then 'approval.completed'
    when new.event_type = 'approval_approved' and exists (select 1 from public.fin_approval_requests a where a.id = (new.metadata->>'request_id')::uuid
         and a.status = 'approved' and a.policy_snapshot is null) then 'approval.completed'
    when new.event_type in ('contract_registered','contract_imported') then 'contract.created'
    when new.event_type in ('renewal_milestone_reached','renewal_task_created') then 'contract.renewal_due'
    else null end;
  if v_type is null then return new; end if;
  v_object := case when v_type like 'rfq.%' or v_type = 'decision.recorded' then 'rfq' when v_type like 'proposal.%' then 'proposal'
                   when v_type like 'approval.%' then 'approval' else 'contract' end;
  v_entity := new.legal_entity_id;
  v_data := case v_object
    when 'rfq' then jsonb_build_object('rfq_id', new.entity_id, 'status', (select r.status from public.fin_rfqs r where r.id = new.entity_id))
    when 'proposal' then (select jsonb_build_object('proposal_id', p.id, 'rfq_id', p.rfq_id, 'version', p.current_version, 'revision', new.event_type = 'proposal_revised')
                            from public.fin_proposals p where p.id = new.entity_id)
    when 'approval' then (select jsonb_build_object('approval_id', a.id, 'rfq_id', a.rfq_id, 'status', a.status, 'policy_driven', a.policy_snapshot is not null)
                            from public.fin_approval_requests a where a.id = (new.metadata->>'request_id')::uuid)
    else (select jsonb_build_object('contract_id', c.id, 'status', c.status, 'ends_on', c.ends_on) from public.fin_contracts c where c.id = new.entity_id) end;
  if v_data is null then return new; end if;
  insert into public.fin_webhook_events(organization_id, legal_entity_id, event_type, source_event_id, payload, occurred_at)
    values (new.organization_id, v_entity, v_type, new.id, jsonb_build_object('object', v_object, 'data', v_data), new.happened_at)
    on conflict (source_event_id) do nothing
    returning id into v_event;
  if v_event is null then return new; end if;
  insert into public.fin_webhook_deliveries(organization_id, endpoint_id, event_id)
    select new.organization_id, e.id, v_event from public.fin_webhook_endpoints e
     where e.organization_id = new.organization_id and e.status = 'active' and v_type = any(e.events)
       and (e.entity_ids is null or (v_entity is not null and (v_entity = any(e.entity_ids)
            or exists (select 1 from public.fin_legal_entities le where le.id = v_entity and le.parent_id = any(e.entity_ids)))))
  on conflict do nothing;
  return new;
exception when others then
  -- Modo degradado: integração nunca derruba a ação de negócio que gerou o
  -- evento. O aviso fica no log do banco; o evento de origem continua em
  -- fin_events e pode ser reprocessado (docs/FINANCIAL_PUBLIC_API.md).
  raise warning 'fin_webhook_capture skipped event %: %', new.id, sqlstate;
  return new;
end $_$;


ALTER FUNCTION public.fin_webhook_capture() OWNER TO postgres;

--
-- Name: fin_webhook_claim(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_webhook_claim(p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 60, p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(delivery_id uuid, lease_token uuid, endpoint_id uuid, url text, secret_ciphertext text, event_id uuid, event_type text, organization_id uuid, legal_entity_id uuid, occurred_at timestamp with time zone, payload jsonb, attempt integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  update public.fin_webhook_deliveries set status = 'failed', lease_token = null, lease_expires_at = null, last_error_code = 'lease_expired'
   where status = 'delivering' and lease_expires_at < now();
  return query
  with due as (
    select d.id from public.fin_webhook_deliveries d join public.fin_webhook_endpoints e on e.id = d.endpoint_id and e.status = 'active'
     where d.status in ('pending','failed') and d.next_attempt_at <= now() and (p_org is null or d.organization_id = p_org)
     order by d.next_attempt_at, d.id limit least(greatest(coalesce(p_limit, 20), 1), 100)
     for update of d skip locked
  ), claimed as (
    update public.fin_webhook_deliveries d set status = 'delivering', lease_token = gen_random_uuid(),
           lease_expires_at = now() + make_interval(secs => least(greatest(coalesce(p_lease_seconds, 60), 10), 300)), attempts = d.attempts + 1, last_attempt_at = now()
      from due where d.id = due.id
    returning d.id, d.lease_token, d.endpoint_id, d.event_id, d.attempts
  )
  select c.id, c.lease_token, c.endpoint_id, e.url, e.secret_ciphertext, c.event_id, w.event_type, w.organization_id, w.legal_entity_id, w.occurred_at, w.payload, c.attempts
    from claimed c join public.fin_webhook_endpoints e on e.id = c.endpoint_id join public.fin_webhook_events w on w.id = c.event_id;
end $$;


ALTER FUNCTION public.fin_webhook_claim(p_limit integer, p_lease_seconds integer, p_org uuid) OWNER TO postgres;

--
-- Name: fin_webhook_complete(uuid, uuid, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fin_webhook_complete(p_delivery uuid, p_lease uuid, p_success boolean, p_status_code integer, p_error_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d public.fin_webhook_deliveries%rowtype; v_status text; v_delays integer[] := array[60, 300, 1800, 7200, 21600, 43200, 86400];
begin
  if auth.uid() is not null then raise exception 'forbidden'; end if;
  select * into d from public.fin_webhook_deliveries where id = p_delivery for update;
  if not found or d.status <> 'delivering' or d.lease_token is distinct from p_lease or d.lease_expires_at is null or d.lease_expires_at <= clock_timestamp() then raise exception 'stale lease'; end if;
  if p_success then
    update public.fin_webhook_deliveries set status = 'succeeded', lease_token = null, lease_expires_at = null, last_status_code = p_status_code,
           last_error_code = null, delivered_at = now() where id = p_delivery;
    update public.fin_webhook_endpoints set consecutive_failures = 0 where id = d.endpoint_id and consecutive_failures <> 0;
    return 'succeeded';
  end if;
  v_status := case when d.attempts >= 8 or p_status_code between 400 and 499 and p_status_code not in (408,429) then 'dead' else 'failed' end;
  update public.fin_webhook_deliveries set status = v_status, lease_token = null, lease_expires_at = null,
         last_status_code = case when p_status_code between 100 and 599 then p_status_code end,
         last_error_code = case when coalesce(p_error_code, '') ~ '^[a-z0-9_]{1,60}$' then p_error_code else 'delivery_failed' end,
         next_attempt_at = now() + make_interval(secs => v_delays[least(d.attempts, 7)] + floor(random() * greatest(1, v_delays[least(d.attempts, 7)] / 5))::integer)
   where id = p_delivery;
  update public.fin_webhook_endpoints set consecutive_failures = consecutive_failures + 1, updated_at = now() where id = d.endpoint_id;
  if (select consecutive_failures from public.fin_webhook_endpoints where id = d.endpoint_id) >= 20 then
    update public.fin_webhook_endpoints set status = 'disabled_failing', disabled_at = now(), disabled_reason = 'consecutive_failures', updated_at = now()
     where id = d.endpoint_id and status = 'active';
    update public.fin_webhook_deliveries set status = 'cancelled' where endpoint_id = d.endpoint_id and status in ('pending','failed');
    insert into public.fin_events(organization_id, entity_type, entity_id, event_type, actor_id, metadata)
      values (d.organization_id, 'webhook_endpoint', d.endpoint_id, 'webhook_endpoint_auto_disabled', null, '{}'::jsonb);
  end if;
  return v_status;
end $_$;


ALTER FUNCTION public.fin_webhook_complete(p_delivery uuid, p_lease uuid, p_success boolean, p_status_code integer, p_error_code text) OWNER TO postgres;

