    proposal_version integer NOT NULL,
    rfq_updated_at timestamp with time zone NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    rationale text NOT NULL,
    snapshot jsonb NOT NULL,
    resolved_at timestamp with time zone,
    policy_snapshot jsonb,
    policy_version_ids uuid[],
    evaluated_at timestamp with time zone,
    justification text,
    declared_facts jsonb,
    expires_at timestamp with time zone,
    resolution_note text,
    external_proposal_id uuid,
    external_rfq_revision integer,
    external_request_key text,
    external_request_hash text,
    CONSTRAINT approval_typed_source CHECK ((((proposal_id IS NOT NULL) AND (external_proposal_id IS NULL) AND (external_rfq_revision IS NULL) AND (external_request_key IS NULL) AND (external_request_hash IS NULL)) OR ((proposal_id IS NULL) AND (external_proposal_id IS NOT NULL) AND (external_rfq_revision IS NOT NULL) AND (external_rfq_revision > 0) AND (external_request_key IS NOT NULL) AND (external_request_hash IS NOT NULL)))),
    CONSTRAINT fin_approval_requests_policy_shape CHECK ((((policy_snapshot IS NULL) OR (jsonb_typeof(policy_snapshot) = 'object'::text)) AND ((declared_facts IS NULL) OR (jsonb_typeof(declared_facts) = 'object'::text)) AND ((justification IS NULL) OR (((length(TRIM(BOTH FROM justification)) >= 10) AND (length(TRIM(BOTH FROM justification)) <= 2000)) AND (justification !~ '[<>]'::text))) AND ((resolution_note IS NULL) OR (length(resolution_note) <= 1000)) AND ((policy_snapshot IS NULL) = (evaluated_at IS NULL)))),
    CONSTRAINT fin_approval_requests_proposal_version_check CHECK ((proposal_version > 0)),
    CONSTRAINT fin_approval_requests_rationale_check CHECK (((length(rationale) >= 1) AND (length(rationale) <= 4000))),
    CONSTRAINT fin_approval_requests_snapshot_check CHECK ((jsonb_typeof(snapshot) = 'object'::text)),
    CONSTRAINT fin_approval_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'changes_requested'::text, 'cancelled'::text, 'expired'::text, 'superseded'::text])))
);

