--
-- Name: fin_crm_institution_records; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_crm_institution_records WITH (security_invoker='true') AS
 WITH records AS (
         SELECT 'activity'::text AS record_type,
            a.id,
            a.organization_id,
            a.legal_entity_id,
            a.subject AS title,
            a.kind,
            NULL::text AS stage,
            a.status,
            a.owner_id,
            a.due_on,
            NULL::text AS next_action,
            a.version,
            a.source_reference,
            a.contact_id,
            a.process_id,
            a.related_type,
            a.related_id
           FROM public.fin_crm_activities a
        UNION ALL
         SELECT 'process'::text AS record_type,
            p_1.id,
            p_1.organization_id,
            p_1.legal_entity_id,
            p_1.title,
            NULL::text AS kind,
            p_1.stage,
            p_1.status,
            p_1.owner_id,
            p_1.due_on,
            p_1.next_action,
            p_1.version,
            p_1.source_reference,
            p_1.contact_id,
            NULL::uuid AS process_id,
            p_1.related_type,
            p_1.related_id
           FROM public.fin_crm_processes p_1
        )
 SELECT r.record_type,
    r.id,
    r.organization_id,
    r.legal_entity_id,
    r.title,
    r.kind,
    r.stage,
    r.status,
    r.owner_id,
    r.due_on,
    r.next_action,
    r.version,
    r.source_reference,
    array_remove(ARRAY[direct.id, ct.provider_id, c.provider_id, pdirect.id, pct.provider_id, pc.provider_id], NULL::uuid) AS provider_ids
   FROM (((((((records r
     LEFT JOIN public.fin_providers direct ON (((r.related_type = 'provider'::text) AND (direct.id = r.related_id) AND (direct.organization_id = r.organization_id))))
     LEFT JOIN public.fin_provider_contacts ct ON (((ct.id = r.contact_id) AND (ct.organization_id = r.organization_id) AND ((ct.legal_entity_id IS NULL) OR (NOT (ct.legal_entity_id IS DISTINCT FROM r.legal_entity_id))))))
     LEFT JOIN public.fin_contracts c ON (((r.related_type = 'contract'::text) AND (c.id = r.related_id) AND (c.organization_id = r.organization_id) AND (NOT (c.legal_entity_id IS DISTINCT FROM r.legal_entity_id)))))
     LEFT JOIN public.fin_crm_processes p ON (((p.id = r.process_id) AND (p.organization_id = r.organization_id) AND (NOT (p.legal_entity_id IS DISTINCT FROM r.legal_entity_id)))))
     LEFT JOIN public.fin_providers pdirect ON (((p.related_type = 'provider'::text) AND (pdirect.id = p.related_id) AND (pdirect.organization_id = r.organization_id))))
     LEFT JOIN public.fin_provider_contacts pct ON (((pct.id = p.contact_id) AND (pct.organization_id = r.organization_id) AND ((pct.legal_entity_id IS NULL) OR (NOT (pct.legal_entity_id IS DISTINCT FROM r.legal_entity_id))))))
     LEFT JOIN public.fin_contracts pc ON (((p.related_type = 'contract'::text) AND (pc.id = p.related_id) AND (pc.organization_id = r.organization_id) AND (NOT (pc.legal_entity_id IS DISTINCT FROM r.legal_entity_id)))));


ALTER VIEW public.fin_crm_institution_records OWNER TO postgres;

