CREATE VIEW public.fin_decision_source_versions WITH (security_invoker='true') AS
 SELECT v.proposal_id,
    v.version,
    v.terms,
    v.submitted_at,
    v.rfq_revision
   FROM public.fin_proposal_versions v
UNION ALL
 SELECT v.proposal_id,
    v.version,
    v.terms,
    NULL::timestamp with time zone AS submitted_at,
    v.rfq_revision
   FROM public.fin_external_proposal_versions v
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.fin_proposals p
          WHERE (p.id = v.proposal_id))));


