--
-- Name: fin_external_proposal_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_external_proposal_current WITH (security_invoker='true') AS
 SELECT p.id,
    p.organization_id,
    p.legal_entity_id,
    p.rfq_id,
    p.provider_id,
    p.product,
    p.state,
    p.current_version,
    v.terms,
    v.channel,
    v.received_at,
    v.source_reference,
    v.currency,
    v.rfq_revision,
    v.recorded_by,
    v.recorded_at,
    v.document_id,
    v.document_version,
    v.document_sha256,
    v.document_mime,
    v.document_size,
    q.reviewed_by,
    q.reviewed_at,
    q.document_read,
    ((v.document_id IS NOT NULL) AND (d.id IS NOT NULL) AND (d.removed_at IS NULL) AND COALESCE((f.status = 'available'::text), false)) AS document_available,
    (v.rfq_revision = r.revision) AS rfq_revision_matches,
    b.name AS provider_name,
    'buyer_recorded_external'::text AS origin,
    'buyer_attribution'::text AS issuer_identity,
    'transcription_correspondence_only'::text AS review_scope,
    'not_recorded'::text AS external_validation,
    'not_recorded'::text AS institution_acceptance,
    ((p.state = 'reviewed'::text) AND (q.reviewed_by IS NOT NULL) AND (v.rfq_revision = r.revision) AND (r.status = ANY (ARRAY['open'::text, 'collecting'::text, 'comparing'::text])) AND ((v.document_id IS NULL) OR ((d.id IS NOT NULL) AND (d.removed_at IS NULL) AND (f.status = 'available'::text)))) AS decision_allowed,
    'version_metadata_unverified'::text AS document_hash_source,
        CASE
            WHEN (v.document_id IS NULL) THEN 'not_presented'::text
            WHEN ((d.id IS NOT NULL) AND (d.removed_at IS NULL) AND (f.status = 'available'::text)) THEN 'metadata_available'::text
            ELSE 'unavailable'::text
        END AS document_state
   FROM ((((((public.fin_external_proposals p
     JOIN public.fin_external_proposal_versions v ON (((v.proposal_id = p.id) AND (v.version = p.current_version))))
     JOIN public.fin_rfqs r ON ((r.id = p.rfq_id)))
     JOIN public.fin_providers b ON (((b.id = p.provider_id) AND (b.organization_id = p.organization_id))))
     LEFT JOIN public.fin_external_proposal_reviews q ON (((q.proposal_id = p.id) AND (q.version = p.current_version) AND (q.action = 'confirm'::text))))
     LEFT JOIN public.fin_private_documents d ON ((d.id = v.document_id)))
     LEFT JOIN public.fin_document_versions f ON (((f.document_id = v.document_id) AND (f.version = v.document_version))));


ALTER VIEW public.fin_external_proposal_current OWNER TO postgres;

--
-- Name: fin_decision_sources; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_decision_sources WITH (security_invoker='true') AS
 SELECT p.id,
    p.rfq_id,
    p.buyer_organization_id,
    p.provider_id,
    p.product,
    p.status,
    p.current_version,
    p.created_at,
    'institution_authenticated'::text AS source_kind
   FROM public.fin_proposals p
UNION ALL
 SELECT e.id,
    e.rfq_id,
    e.organization_id AS buyer_organization_id,
    e.provider_id,
    e.product,
    e.state AS status,
    e.current_version,
    e.recorded_at AS created_at,
    'buyer_recorded_external'::text AS source_kind
   FROM public.fin_external_proposal_current e
  WHERE ((e.state = 'reviewed'::text) AND e.rfq_revision_matches AND ((e.document_id IS NULL) OR e.document_available) AND (NOT (EXISTS ( SELECT 1
           FROM public.fin_proposals p
          WHERE (p.id = e.id)))));


ALTER VIEW public.fin_decision_sources OWNER TO postgres;

