--
-- Name: fin_provider_contract_tasks; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_provider_contract_tasks WITH (security_invoker='true', security_barrier='true') AS
 SELECT t.id,
    t.organization_id,
    c.provider_id,
    c.legal_entity_id,
    t.title,
    t.due_on,
    t.status,
    t.related_type,
    t.related_id,
    t.created_at,
    t.assignee_id
   FROM ((public.fin_tasks t
     JOIN public.fin_contracts c ON (((c.id = t.related_id) AND (c.organization_id = t.organization_id))))
     JOIN public.fin_organizations o ON (((o.id = t.organization_id) AND (o.kind = 'BUYER'::text))))
  WHERE (t.related_type = 'contract'::text);


