--
-- Name: fin_provider_performance_monitor; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.fin_provider_performance_monitor WITH (security_invoker='true') AS
 SELECT p.id AS period_id,
    p.organization_id,
    p.legal_entity_id,
    p.provider_id,
    p.contract_id,
    p.product,
    p.period_start,
    p.period_end,
    p.review_due_on,
    p.owner_id,
    p.status,
    p.version,
    p.title,
    d.id AS dimension_id,
    d.title AS dimension_title,
    d.metric,
    d.unit,
    d.methodology,
    d.version AS dimension_version,
    t.operator,
    (t.threshold)::text AS threshold,
    t.source_reference AS target_source,
    o.id AS observation_id,
    o.revision,
    (o.value)::text AS actual,
    o.availability,
    o.source_type,
    o.source_reference,
    o.provenance,
    o.formula_version,
    o.source_facts,
    o.coverage_numerator,
    o.coverage_denominator,
    o.observed_on,
    o.recorded_at,
    o.recorded_by,
    r.status AS verification_status,
    r.id AS review_id,
    r.reviewed_by,
    r.reviewed_at,
        CASE
            WHEN ((r.status = 'confirmed'::text) AND (t.threshold IS NOT NULL)) THEN
            CASE t.operator
                WHEN 'le'::text THEN (o.value <= t.threshold)
                WHEN 'ge'::text THEN (o.value >= t.threshold)
                WHEN 'eq'::text THEN (o.value = t.threshold)
                ELSE NULL::boolean
            END
            ELSE NULL::boolean
        END AS target_met
   FROM ((((public.fin_provider_performance_periods p
     JOIN public.fin_provider_performance_targets t ON ((t.period_id = p.id)))
     JOIN public.fin_provider_performance_dimensions d ON ((d.id = t.dimension_id)))
     LEFT JOIN LATERAL ( SELECT x.id,
            x.organization_id,
            x.period_id,
            x.dimension_id,
            x.revision,
            x.supersedes_id,
            x.value,
            x.availability,
            x.source_type,
            x.source_reference,
            x.provenance,
            x.formula_version,
            x.source_facts,
            x.coverage_numerator,
            x.coverage_denominator,
            x.observed_on,
            x.recorded_by,
            x.recorded_at,
            x.correction_reason
           FROM public.fin_provider_performance_observations x
          WHERE ((x.period_id = p.id) AND (x.dimension_id = d.id))
          ORDER BY x.revision DESC
         LIMIT 1) o ON (true))
     LEFT JOIN public.fin_provider_performance_reviews r ON ((r.observation_id = o.id)));


ALTER VIEW public.fin_provider_performance_monitor OWNER TO postgres;

