    CONSTRAINT fin_sso_connections_check1 CHECK (((NOT enforce_sso) OR (status = 'active'::text))),
    CONSTRAINT fin_sso_connections_display_name_check CHECK ((((length(TRIM(BOTH FROM display_name)) >= 2) AND (length(TRIM(BOTH FROM display_name)) <= 120)) AND (display_name !~ '[<>]'::text))),
    CONSTRAINT fin_sso_connections_issuer_check CHECK (((issuer IS NULL) OR (((length(issuer) >= 8) AND (length(issuer) <= 300)) AND (issuer ~ '^https://[^\s<>]+$'::text)))),
    CONSTRAINT fin_sso_connections_max_session_hours_check CHECK (((max_session_hours >= 1) AND (max_session_hours <= 168))),
    CONSTRAINT fin_sso_connections_metadata_url_check CHECK (((metadata_url IS NULL) OR (((length(metadata_url) >= 12) AND (length(metadata_url) <= 500)) AND (metadata_url ~ '^https://[^\s<>]+$'::text)))),
    CONSTRAINT fin_sso_connections_mfa_policy_check CHECK ((mfa_policy = 'arandu_totp'::text)),
    CONSTRAINT fin_sso_connections_protocol_check CHECK ((protocol = ANY (ARRAY['saml'::text, 'oidc'::text]))),
